insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'bank', 0, $official_bank_source${"code":"PUL101","courseId":"4df568c2-4a68-52ab-80d6-380e5921d119","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":632,"shell":{"contentKey":"legal-methods-1","titles":["Legal Methods I"],"level":"100-level","semesters":["first-semester"]},"rows":{"audited":0,"keep":0,"retire":0,"add":632}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 1, $official_bank_source${"itemId":"1f6d959c-53e3-5e45-be28-fed0ca3fd521","questionId":"6a16b774-0085-5a4f-ac78-550122c93a81","sourceKey":"bank:PUL101:PQ-001-01","payload":{"prompt":"John Austin defined law as \"a command set by a superior being to inferior beings and enforced by sanctions.\" Which school of thought does this definition represent?","options":["The Historical School","The Natural Law School","The Positivist (Analytical) School","The Sociological School"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"This is Austin's command theory, the classic positivist view: law is whatever the sovereign lays down and backs with a sanction, whether or not it is moral. Option B is wrong because natural lawyers test law against morality and right reason. Option A looks to the customs and spirit of the people, and Option D looks to how law actually works in society."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 2, $official_bank_source${"itemId":"f78b0372-8889-51ed-8718-24a976d264bc","questionId":"33492848-9cc0-5e41-a906-0122d8b397ab","sourceKey":"bank:PUL101:PQ-001-02","payload":{"prompt":"Which of the following is NOT an element of Austin's definition of law?","options":["The subjects are in the habit of obeying the sovereign because of his power to impose sanctions","A law is valid only if it agrees with morality","There must be a definite sovereign","The sovereign is not under any legal limitation"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Austin deliberately separated law from morality, so a moral test of validity is no part of his definition. His elements are a definite sovereign (Option C), a sovereign who is legally unlimited, the 'uncommanded commander' (Option D), and habitual obedience by subjects backed by sanctions (Option A)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 3, $official_bank_source${"itemId":"3c849c7b-2a49-5f08-baf4-a6f357015ccd","questionId":"023593ee-aca6-56c7-a45d-65b1bb165f31","sourceKey":"bank:PUL101:PQ-001-03","payload":{"prompt":"Which jurist propounded the Pure Theory of Law, which sees law as a hierarchy of norms whose validity is traced back to a basic norm called the grundnorm?","options":["Hans Kelsen","Friedrich Carl von Savigny","Jeremy Bentham","Eugen Ehrlich"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Kelsen described law as a system of norms, each valid because a higher norm created it, until you reach the grundnorm, which is not itself created by any norm. Option B founded the Historical School, Option D is known for the sociological idea of 'living law', and Option C founded the Utilitarian School."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 4, $official_bank_source${"itemId":"0d0d1cac-e4cb-582e-91d5-a8f885b2f239","questionId":"cebe6cd6-c293-54ff-aa87-d91847af7fd4","sourceKey":"bank:PUL101:PQ-001-04","payload":{"prompt":"According to the Historical School associated with Savigny, for a law to be valid it must accord with","options":["the command of a sovereign backed by sanctions","the volksgeist, that is, the spirit, history and customs of the people","principles of right reason that are the same everywhere","what the courts will actually decide in a given case"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Savigny taught that every people has a national spirit (volksgeist) and that law should grow out of their history and customs, so laws imposed against it will be ignored or evaded. Option A is the positivist command theory. Option C is the natural law view, which the Historical School was developed to counter, and Option D is the realist view."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 5, $official_bank_source${"itemId":"d76bcc4a-bb9c-50c7-b059-55479c1d159e","questionId":"4af6a09f-148c-5816-9bdb-764e53d5aeb1","sourceKey":"bank:PUL101:PQ-001-05","payload":{"prompt":"Which jurist said that \"the centre of gravity of legal development lies not in legislation nor juristic science nor in judicial decisions but the society itself\"?","options":["Eugen Ehrlich","Hans Kelsen","John Austin","Thomas Aquinas"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Ehrlich, a leading European sociological jurist, argued that the 'living law' is found in how people actually behave, so you cannot know a society's law just by reading statutes and cases. Option C and Option B both focus on formally laid down rules, and Option D is a natural law thinker."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 6, $official_bank_source${"itemId":"f2a47a8f-0cd1-5674-bfde-83979b322355","questionId":"21d42400-6d50-5559-8c0f-8ff0ec64b6e8","sourceKey":"bank:PUL101:PQ-001-06","payload":{"prompt":"Roscoe Pound's sociological theory of law is built mainly on the idea that law should","options":["be understood as a system of norms traceable to a grundnorm","restate the customs that have evolved in a society over time","balance competing claims and interests in society in a way that causes the least friction or harm","be obeyed only if it agrees with divine or moral principles"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Pound started from the premise that people make competing claims on limited resources, and saw the task of law, especially the courts, as balancing those interests with the least disruption. Option B describes the Historical School, Option D the Natural Law School and Option A Kelsen's Pure Theory."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 7, $official_bank_source${"itemId":"91443b3b-a764-5439-9373-0cfefc54d7c2","questionId":"b49c8d3b-e3cd-5814-a002-e5d33cbd319a","sourceKey":"bank:PUL101:PQ-001-07","payload":{"prompt":"The Utilitarian School founded by Jeremy Bentham judges a law mainly by whether it","options":["was made by a sovereign who is habitually obeyed","reflects the spirit and customs of the people","promotes the greatest happiness or good of the greatest number of people","agrees with the eternal law of God"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"For Bentham, the task of law is to promote utility, meaning people's happiness, so a good law produces the greatest good for the greatest number. Option A is Austin's positivist test. Option B is the Historical School's test and Option D reflects the Natural Law School."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 8, $official_bank_source${"itemId":"b9aa4337-58a5-5e7d-9e25-fabd353cc736","questionId":"da16866d-0c72-504b-84c6-cd2fcb97040a","sourceKey":"bank:PUL101:PQ-001-08","payload":{"prompt":"The view that law is simply a prediction of what the courts will do in fact is most closely associated with which school of thought?","options":["The Historical School","The Pure Theory of Law","The Natural Law School","The Realist School"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"American realists such as Oliver Wendell Holmes looked at law from the standpoint of what judges actually decide, not what rules say in books. Option C measures law against morality, Option A looks to custom and the spirit of the people, and Option B looks to a formal hierarchy of norms."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 9, $official_bank_source${"itemId":"cc97c72e-fd3c-5b54-9167-ecc2ffd5770d","questionId":"6df2ed50-6757-5884-9274-0c84992bf89a","sourceKey":"bank:PUL101:PQ-001-09","payload":{"prompt":"Legal realists such as Jerome Frank argued that judicial decisions are often influenced by","options":["the volksgeist of the people alone","eternal principles discoverable only through divine revelation","a grundnorm that cannot be questioned","extralegal factors such as the judge's background, personal likes and dislikes and prejudices"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The realists said too much attention was paid to bare legal rules and too little to the human factors in deciding cases, so they wanted judges to become aware of their hidden prejudices. Option A belongs to the Historical School, Option C to Kelsen's Pure Theory, and Option B to religious ideas of law, not realism."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 10, $official_bank_source${"itemId":"d319256f-d7d5-5452-8cff-b2ed9ea4b1aa","questionId":"c1d00955-6fe6-50e8-97b5-1f1fd68441b3","sourceKey":"bank:PUL101:PQ-001-10","payload":{"prompt":"Which modern idea has been built most directly on the philosophy of the Natural Law School?","options":["The grundnorm as the basis of a legal order","Law as the prediction of court decisions","The volksgeist as the basis of valid law","Fundamental human rights and equality of all persons"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Natural law holds that some principles of right and justice exist above man-made law, and this thinking supported human rights, democracy and struggles for independence. Option A comes from Kelsen's Pure Theory, Option C from the Historical School and Option B from the Realist School."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 11, $official_bank_source${"itemId":"623318e3-9b5d-57e7-8690-d15b4730cea7","questionId":"c62b564b-cb1a-52a2-a4a0-37e99ff2c526","sourceKey":"bank:PUL101:PQ-001-11","payload":{"prompt":"A major criticism of the Natural Law School, known as the \"multiple conscience problem\", is that","options":["different people may hold opposite ideas of what is fair, right or just on the same issue","it treats any law made by the sovereign as valid however unjust it is","it focuses only on trial courts and ignores the legislature","it ignores the customs and history of a people"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Because what is 'right' depends on each person's reason and conscience, two equally sincere people can both claim natural law while acting in opposite ways, which is why the theory has been used to defend very different ideologies. Option B is a criticism of positivism, not natural law. Option D and Option C are not what the multiple conscience problem refers to."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 12, $official_bank_source${"itemId":"ea99bc2f-773a-50ce-9975-0f895fb3af45","questionId":"e911335f-744b-545e-9e20-6d2f19169dfe","sourceKey":"bank:PUL101:PQ-001-12","payload":{"prompt":"In Nigeria, a rule of customary law will NOT be applied by the courts if it is","options":["not separately approved by the National Assembly","observed by only one ethnic group","different from the rules of English common law","repugnant to natural justice, equity and good conscience"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Nigerian courts apply customary law only if it passes certain tests: it must not be repugnant to natural justice, equity and good conscience, not contrary to public policy, and not incompatible with any law in force. Customary law is by nature local, so Option B is no ground for rejection, and Option C and Option A are not tests the courts apply."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 13, $official_bank_source${"itemId":"0b057939-e5a7-5420-89ad-ffbde53c0507","questionId":"288fc3ab-8566-5a89-a854-4e41b8087efe","sourceKey":"bank:PUL101:LAW-001","payload":{"prompt":"Which jurist defined law as \"a command set by a superior being to inferior beings and enforced by sanctions\"?","options":["Friedrich Carl von Savigny","Hans Kelsen","Eugen Ehrlich","John Austin"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"This is the classic command theory of law, in which the superior is the sovereign and the inferiors are the subjects. Austin set it out in The Province of Jurisprudence Determined. Kelsen (B) saw law as a hierarchy of norms, Savigny (A) tied law to the spirit of the people, and Ehrlich (C) located law in the actual conduct of society."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 14, $official_bank_source${"itemId":"73854e8f-0197-5786-8f8f-7c5d2b9ec276","questionId":"334c943b-15d4-54ee-bab4-d71c57dc5bb8","sourceKey":"bank:PUL101:LAW-002","payload":{"prompt":"Which of the following is NOT one of the elements of the Austinian definition of law?","options":["The subjects are in the habit of obeying the sovereign because of his power to impose sanctions","The sovereign's commands must agree with the principles of natural justice","The sovereign is without legal limitation in the exercise of power","There must be a definite sovereign"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Austin's theory has nothing to say about the moral quality of the sovereign's commands; a command is law simply because the sovereign issued it. The three real elements are a definite sovereign (D), a sovereign who is above the law (C), and habitual obedience by the subjects backed by sanctions (A)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 15, $official_bank_source${"itemId":"4c4280c5-e666-5371-826e-3d94ca03cc1c","questionId":"cc6da4f7-0f90-5b78-95ca-46c2f87d9f6a","sourceKey":"bank:PUL101:LAW-003","payload":{"prompt":"In Austin's theory, the phrase \"the uncommanded commander\" describes","options":["the basic norm that is presupposed rather than enacted","a sovereign who is the highest authority and is not subject to the command of anyone else","the people, from whom every government derives its powers","a judge who is bound to follow the decisions of higher courts"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"For Austin, the sovereign issues commands but receives none; he is above the law and not subject to another's command. Option C reflects popular sovereignty, which is a modern constitutional idea, not Austin's, while A describes Kelsen's grundnorm."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 16, $official_bank_source${"itemId":"d32f175d-7f73-5d11-9d27-60482c03228a","questionId":"d4632f0d-18d7-5317-8261-53c55aa6e9a6","sourceKey":"bank:PUL101:LAW-004","payload":{"prompt":"The fact that the law on wills does not compel anyone to make a will is used to criticise which theory of law?","options":["The sociological school","Austin's command theory","The natural law school","The historical school"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Austin treated all law as commands couched in 'shall' or 'shall not'. Rules on wills, and the freedom to marry under the Marriage Act or customary law, show that many laws give choices rather than commands. The other schools do not claim that every law is a command, so the example does not attack them."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 17, $official_bank_source${"itemId":"91194d32-9ce4-5d6f-8227-6c6be9cb1773","questionId":"7f7565d4-8ec3-56ca-b71f-31991740f04f","sourceKey":"bank:PUL101:LAW-005","payload":{"prompt":"Which Nigerian case is cited to show that even a military government is not above the law, contrary to Austin's idea of a sovereign without legal limitation?","options":["Holman v Johnson","Lakanmi v A.G. (Western State)","Josiah v The State","Shaw v Director of Public Prosecutions"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"In Lakanmi, the Supreme Court declared the Forfeiture of Assets (Validation) Decree No. 45 of 1968 null and void, showing that governmental power must be exercised according to law. Holman v Johnson (A) concerns the territorial limits of law, Shaw v DPP (D) concerns law and public morality, and Josiah v The State (C) concerns justice in criminal trials."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 18, $official_bank_source${"itemId":"eb615c17-91bf-58ab-8293-d26ddb1edaa7","questionId":"cffdf3c3-33dc-50d4-95f9-79666670e0e9","sourceKey":"bank:PUL101:LAW-006","payload":{"prompt":"During a radio phone-in, Kunle says: \"The President has the power to introduce a fuel tax, and once he does, nobody can question it.\" Kunle's statement implicitly reflects which theory of law?","options":["Austin's command theory","The natural law school","The historical school","The sociological school"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Treating whatever the authorised ruler lays down as binding, without asking whether it is fair, reflects the Austinian command theory. Such philosophies are often implicit: the speaker may never name Austin. A natural lawyer (B) would test the tax against what is just, and the historical school (C) would ask whether it fits the people's customs."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 19, $official_bank_source${"itemId":"382a1f24-34d4-53f2-9c8e-b5aea8265af2","questionId":"e656802c-32b9-5c5a-bb4c-e043971aa436","sourceKey":"bank:PUL101:LAW-007","payload":{"prompt":"\"Many people do not smoke in public, not because a law forbids it, but because it is not their way of life.\" Which claim does this observation challenge?","options":["That the conduct of society determines what the law is","That every legal norm draws its validity from a higher norm","That law must reflect the customs and history of the people","That people obey the law mainly because they fear the sovereign's sanction"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Austin assumed that people obey law because of fear of sanction, but many obey because the law agrees with their beliefs or normal way of life. The other options are the central ideas of the historical school (C), Kelsen's pure theory (B) and Ehrlich's sociological view (A), which the smoking example does not attack."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 20, $official_bank_source${"itemId":"0ee4e978-241c-59c5-9529-ccd61dff05dd","questionId":"ad659acb-71b8-502e-a202-9359ef08d994","sourceKey":"bank:PUL101:LAW-008","payload":{"prompt":"Which jurist defined law as the union of primary rules of obligation and secondary rules of recognition?","options":["John Austin","H.L.A. Hart","Roscoe Pound","Jeremy Bentham"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Hart moved beyond Austin's commands by showing that law is a system of two kinds of rules: primary rules that tell people what to do, and secondary rules that govern how laws are made, changed or recognised. Austin (A) relied on commands and sanctions alone, Pound (C) saw law as social engineering, and Bentham (D) judged law by utility."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 21, $official_bank_source${"itemId":"dea09043-f5f9-50a1-af13-53ccba261171","questionId":"4111afa4-9118-5246-b4f2-010e50f33e6f","sourceKey":"bank:PUL101:LAW-009","payload":{"prompt":"The constitutional rules that set out how a bill passes through the National Assembly and becomes an Act would, in Hart's terms, be classified as","options":["the grundnorm","living law","secondary rules","primary rules of obligation"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Secondary rules tell us how laws are made, changed or recognised, such as a constitution or legislative process. Primary rules (D) directly tell people what they must or must not do, such as 'do not steal'. The grundnorm (A) belongs to Kelsen's theory and living law (B) to Ehrlich's."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 22, $official_bank_source${"itemId":"ce4555d4-4bcf-5f7b-bb58-52e754634f2b","questionId":"6dad240a-8ff7-567a-b28a-02b2ca586006","sourceKey":"bank:PUL101:LAW-010","payload":{"prompt":"In Kelsen's pure theory of law, the ultimate norm from which all other norms derive their validity, but whose own validity cannot be traced to any other norm, is called the","options":["rule of recognition","living law","volksgeist","grundnorm"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Kelsen saw law as a hierarchy of norms in which each norm is valid because a higher norm authorised it, until we reach the grundnorm, which is presupposed rather than enacted. The volksgeist (C) is Savigny's spirit of the people, the rule of recognition (A) is Hart's idea, and living law (B) is Ehrlich's."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 23, $official_bank_source${"itemId":"bec1ca41-a510-5010-8aa8-4fcd98c45131","questionId":"66451c28-1303-568b-a4d2-bba3b89f15e7","sourceKey":"bank:PUL101:LAW-011","payload":{"prompt":"A student argues: \"The rule against murder is valid because it is in the Criminal Code; the Code is valid because the legislature enacted it; the legislature is valid because the Constitution set it up.\" This chain of reasoning reflects","options":["the utilitarian school","the realist school","the historical school","Kelsen's pure theory of law"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Tracing the validity of each rule to a higher norm, step by step up to the Constitution, is the hierarchy of norms at the heart of the pure theory. The historical school (C) tests law against custom, realists (B) look at what courts actually do, and utilitarians (A) judge law by its consequences for happiness."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 24, $official_bank_source${"itemId":"0ace7e75-4264-51de-b420-06db0c734f8c","questionId":"0f0924a1-e14e-50d1-9986-051f48340370","sourceKey":"bank:PUL101:LAW-012","payload":{"prompt":"Which of the following is a criticism directed specifically at Kelsen's pure theory of law?","options":["It stresses the formal validity of law rather than its content and effects in society","Different people have different consciences about what is just","It focuses on the courts and neglects the legislature","It assumes that customary rules are always rational and fair"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Because the pure theory asks only whether a rule was created by a higher norm, it ignores whether the rule is just, moral or useful, and may serve dictators. The multiple conscience problem (B) is a weakness of natural law, neglect of the legislature (C) is a weakness of the functional school, and assuming customs are fair (D) is a weakness of the historical school."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 25, $official_bank_source${"itemId":"fa79dc22-dcfb-5c8a-b797-755cc5b3ba88","questionId":"245402de-49f9-59b8-80cb-205e698a0454","sourceKey":"bank:PUL101:LAW-013","payload":{"prompt":"Soldiers overthrow an elected government, suspend parts of the Constitution and rule by decree, and the coup succeeds. Which criticism of the pure theory of law does this illustrate?","options":["Law should be a restatement of the people's customs","Judges are influenced by their social background","Validity then depends on the effectiveness of the new legal order","Law is not always couched in commanding language"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Once the old grundnorm stops commanding effectiveness, it is no longer the basis of the legal order, so validity follows whoever is effectively in control. Had the coup failed, the plotters could have faced trial for treason. Option D attacks Austin, B is a realist insight, and A is the historical school's view."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 26, $official_bank_source${"itemId":"773247be-7766-5e5a-8933-76e363b75a7f","questionId":"ffcf4e40-073a-5cdb-81b2-d39541b0daed","sourceKey":"bank:PUL101:LAW-014","payload":{"prompt":"Which of the following is NOT a claim of Kelsen's pure theory of law?","options":["The moral quality of a legal rule is irrelevant to its validity","A grossly unjust rule is not law at all and need not be obeyed","Law should be studied as a self-contained system separate from morality and politics","Each norm derives its validity from a superior norm"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The idea that an unjust rule is not true law belongs to the natural law school, which Kelsen rejected. Kelsen wanted a 'pure' study of law free from morality (C), held that a rule's moral quality does not affect its validity (A), and arranged norms in a hierarchy (D)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 27, $official_bank_source${"itemId":"5e9f5e4a-27d6-5977-92bd-317c84d1631d","questionId":"b7359388-eb5f-57f1-aebc-52e22ee36855","sourceKey":"bank:PUL101:LAW-015","payload":{"prompt":"Which of the following thinkers is named as a chief protagonist of the natural law school?","options":["Eugen Ehrlich","Savigny","Karl Llewellyn","Grotius"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Zeno, Thomas Aquinas and Grotius are the chief protagonists of natural law, which holds that there are objective principles of what is fair, just or right. Savigny (B) led the historical school, Ehrlich (A) was a sociological jurist, and Llewellyn (C) was an American realist."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 28, $official_bank_source${"itemId":"ee94d610-9764-535f-b19c-fb5ba54aef7d","questionId":"7b8a5d48-1488-5a74-87e4-ea195eaa0bab","sourceKey":"bank:PUL101:LAW-016","payload":{"prompt":"The school of thought which holds that there are objective principles in every person, whatever their race or colour, telling them what is fair, just or right, and against which man-made laws can be tested, is the","options":["natural law school","realist school","historical school","positivist school"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Reduced to its simplest terms, natural law means what is fair, just or right, and it serves as a test for the validity of man-made law. Positivists (D) separate law from morality, the historical school (C) roots law in custom, and realists (B) look at what courts actually do."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 29, $official_bank_source${"itemId":"926b4c96-3cf1-5a19-80c0-465494b20947","questionId":"059bb0bc-2f54-5c33-af0c-cfa52ff07fef","sourceKey":"bank:PUL101:LAW-017","payload":{"prompt":"Ten people from different countries are placed in separate rooms and each is asked, in a language he understands, whether stealing is good. Most say no. This illustration is used to support","options":["the realist school","the consensus model of law","the natural law school","Kelsen's pure theory of law"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The point is that people everywhere share certain principles of right and wrong that exist apart from any human enactment, which is the natural law position. The pure theory (D) ignores morality, realists (A) focus on judicial behaviour, and the consensus model (B) is a theory of the functions of law, not of what law is."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 30, $official_bank_source${"itemId":"c383cc93-4c56-5426-a091-a75eded703de","questionId":"a535c192-e17a-5f2e-a96f-dc5f42af0e41","sourceKey":"bank:PUL101:LAW-018","payload":{"prompt":"Youth groups in an oil-producing community demand a fairer share of oil revenue, arguing that it is simply unjust for the area that produces the wealth to remain poor, whatever the current law says. Their argument draws mainly on","options":["natural law","the functional school","the pure theory of law","the command theory"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Appealing to what is just or right as a standard above existing law is natural law reasoning; it has been invoked in independence struggles and in the Niger Delta's call for resource control. The command theory (D) and pure theory (C) would accept the current law as valid, and the functional school (B) would wait to see what the courts decide."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 31, $official_bank_source${"itemId":"c3f777d7-b514-58ae-af33-c13ed7755706","questionId":"577e0bef-b9c9-591e-bd17-2f1c436b52ee","sourceKey":"bank:PUL101:LAW-019","payload":{"prompt":"The \"multiple conscience problem\" is a weakness of the natural law school. It refers to the fact that","options":["a sovereign can never be found who is above the law","judges are unconsciously prejudiced by their backgrounds","customs differ from one ethnic group to another","people may hold different ideas of what is just on the same issue"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Two equally devout people can both claim to act according to natural law while acting in opposite ways, so natural law has been used to defend almost every ideology. Option A is a criticism of Austin, C relates to the historical school, and B is the realists' observation about judges."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 32, $official_bank_source${"itemId":"ad76761f-083f-5223-b83d-701ec62212a5","questionId":"bc402674-7c45-5c16-a1d2-02a046ee657b","sourceKey":"bank:PUL101:LAW-020","payload":{"prompt":"Which of the following statements about natural law is correct?","options":["It focuses mainly on what is actually done rather than what ought to be done","It holds that law is valid only if it reflects the people's customs","Courts in practice enforce natural law in preference to statutes","Unless its principles are enacted into law, their violation cannot be legally penalised"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Natural law stresses what ought to be done; in practice, courts interpret and the executive enforces the law found in recognised sources, so a natural law principle carries legal sanction only once enacted. C is the reverse of the position, A inverts natural law's 'ought' focus, and B states the historical school's view."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 33, $official_bank_source${"itemId":"2aa52d12-dd24-53c8-9a06-76a7e7fe12c4","questionId":"8bf7cbae-71e6-51b1-850e-586d35609ed7","sourceKey":"bank:PUL101:LAW-021","payload":{"prompt":"Which thinker defined law as the highest reason, rooted in nature, which commands what must be done and forbids the opposite?","options":["Cicero","Aristotle","John Austin","Roscoe Pound"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Cicero saw law as universal and moral, rooted in nature and reason rather than created by man, and binding even on rulers. Aristotle (B) described law as 'reason without desire', Austin (C) saw law as the sovereign's command, and Pound (D) saw law as a social institution for satisfying human wants."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 34, $official_bank_source${"itemId":"5198b0ac-4275-5597-bd8e-3ec99a695009","questionId":"2912d26c-28ef-5f42-accf-1402ec598336","sourceKey":"bank:PUL101:LAW-022","payload":{"prompt":"\"An ordinance of reason for the common good, made by him who has care of the community.\" This definition of law is associated with","options":["Thomas Aquinas","Eugen Ehrlich","Oliver Wendell Holmes","John Austin"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Aquinas, a natural lawyer, held that for a law to be valid it must be just and in line with moral or divine principles. Holmes (C) defined law as a prediction of what courts will do, Austin (D) as a sovereign's command backed by sanctions, and Ehrlich (B) located law in social conduct."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 35, $official_bank_source${"itemId":"7232b51f-304e-53db-833d-c5aef3b5435e","questionId":"f7923478-de59-5cd0-b838-48e46a28b44c","sourceKey":"bank:PUL101:LAW-023","payload":{"prompt":"According to the historical school, the \"spirit of the people\" that binds a society together and from which its law should flow is called the","options":["volksgeist","rule of recognition","living law","grundnorm"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Savigny taught that each people has a national spirit, the volksgeist, so a law is valid only if it accords with the people's history and customs. The grundnorm (D) is Kelsen's basic norm, living law (C) is Ehrlich's idea, and the rule of recognition (B) is Hart's."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 36, $official_bank_source${"itemId":"e07980f8-735f-5443-aa6e-b81e212671c4","questionId":"fe7a4993-42f9-55f5-87f2-b55fb12083b1","sourceKey":"bank:PUL101:LAW-024","payload":{"prompt":"The historical school, led by Friedrich Carl von Savigny, was developed mainly to","options":["support the codification of law by revolutionary governments","reform trial courts by exposing judges' prejudices","promote the greatest happiness of the greatest number","counter natural law ideas used to overthrow European monarchs"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Natural law ideas fuelled the overthrow of monarchs in 17th and 18th century Europe; Savigny, an aristocrat with an interest in the status quo, stressed slow evolution of law through custom instead. Reforming trial courts (B) was the realists' aim, and greatest happiness (C) is the utilitarian goal."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 37, $official_bank_source${"itemId":"c93497e6-68f3-50e3-af01-7399de5a4b03","questionId":"8f4675d5-587b-5e82-b9fc-0bd59280034f","sourceKey":"bank:PUL101:LAW-025","payload":{"prompt":"A state government suddenly bans a burial custom that its people have practised for centuries. Most people ignore the ban or find clever ways around it. Which school would say this outcome was predictable because the law was not in tune with the people's customs?","options":["The historical school","The utilitarian school","Kelsen's pure theory of law","The positivist school"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The historical school holds that law should be a formal restatement of prevailing customs, and that customs cannot be changed unless the people are in tune with the change; otherwise they circumvent or disregard the law. Positivists (D) and Kelsen (C) would treat the ban as valid simply because it was properly made."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 38, $official_bank_source${"itemId":"6b73b53c-0c40-5040-bbdc-74a29d5cf74a","questionId":"dfed0504-dba0-5959-ac22-06375c4c68c5","sourceKey":"bank:PUL101:LAW-026","payload":{"prompt":"Which of the following is a criticism of the historical school?","options":["It looks only at what courts do and ignores the legislature","It cannot identify the basic norm of a modern state","It treats the sovereign as above the law","It assumes customs are fair, though some prejudice women"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The historical school builds law on custom, but some customary rules have subjected people to servitude or prejudiced women, and following custom dogmatically can block desirable reforms. C criticises Austin, B criticises Kelsen, and A criticises the functional school."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 39, $official_bank_source${"itemId":"717bc409-a40f-5e72-b194-e59c0fe48cdd","questionId":"0df155e4-9020-58b7-9f32-4f213bd06741","sourceKey":"bank:PUL101:LAW-027","payload":{"prompt":"Which of the following is NOT one of the tests that a rule of customary law must pass to be applied in Nigeria?","options":["It must not be incompatible with any law for the time being in force","It must not be repugnant to natural justice, equity and good conscience","It must have been written down and published by a court","It must not be contrary to public policy"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Customary law is largely unwritten, and there is no requirement that a court has written it down before it can apply. The three real tests are the repugnancy test (B), the public policy test (D) and the incompatibility test (A)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 40, $official_bank_source${"itemId":"5813a04e-45c7-55d3-b0ba-cec58ffd9ce9","questionId":"95d23903-fd79-5196-9b53-e20625ba8a38","sourceKey":"bank:PUL101:LAW-029","payload":{"prompt":"By the \"facts of law\", Eugen Ehrlich meant","options":["the facts that a court finds proved at trial","how people actually behave in society","the rules set out in statutes and decided cases","the presupposed norm at the top of the legal order"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Ehrlich taught that law is based on how people act, and that society's conduct determines the rules laid down in formal sources. To know a society's law, you must go into the society and see how it is obeyed, ignored or modified. Statutes and cases (C) are the formal sources he said were not enough."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 41, $official_bank_source${"itemId":"7cc748bc-5800-5954-a68f-c08b9a90b023","questionId":"9d6ff50d-531f-5603-af12-b88c672297f6","sourceKey":"bank:PUL101:LAW-030","payload":{"prompt":"A statute forbids extortion, yet some officers at highway checkpoints still openly collect N100 from motorists, and many motorists simply pay. A jurist who says \"the real law here is what people actually do, not what the statute says\" is applying the ideas of","options":["Kelsen's pure theory of law","the natural law school","Eugen Ehrlich's sociological school","John Austin's command theory"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Ehrlich used the gap between formal law and conduct to show that society's conduct, the living law, determines what the law really is; if law is at variance with popular conduct, it is doomed as an instrument of social control. Austin (D) and Kelsen (A) would focus on the valid statute, and natural law (B) would ask whether the conduct is just."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 42, $official_bank_source${"itemId":"238e4606-2223-58e0-bfe3-5753053064fd","questionId":"eaa5a770-1a11-5dff-aee7-c87337679267","sourceKey":"bank:PUL101:LAW-031","payload":{"prompt":"Car owners in Abuja register their vehicles and stop at roadblocks only because the law requires them to. This is used to criticise which school?","options":["The pure theory of law","The sociological school","The natural law school","The positivist school"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Ehrlich claimed that conduct determines law, but here the law is shaping conduct; sometimes the law moves ahead of society to educate it and change behaviour. This weakens the sociological claim. Positivists (D) and Kelsen (A) would happily accept that a valid law changes behaviour, so the example does not attack them."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 43, $official_bank_source${"itemId":"fa00fc02-bde6-5eef-b490-44ac07496a56","questionId":"7447831c-c8e2-5450-ad46-4162f065ffaa","sourceKey":"bank:PUL101:LAW-032","payload":{"prompt":"Which jurist, a former Dean of Harvard Law School, saw law as a way of satisfying human wants by balancing competing claims to limited resources with the least harm to established institutions?","options":["Jerome Frank","Jeremy Bentham","Roscoe Pound","Eugen Ehrlich"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Pound was the greatest exponent of sociological jurisprudence on the western side of the Atlantic, and the courts were the main institutional focus of his balancing theory. Ehrlich (D) was the European sociological jurist of living law, Frank (A) was a realist judge, and Bentham (B) founded utilitarianism."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 44, $official_bank_source${"itemId":"9054b424-238a-5c76-9977-c790ab17c19e","questionId":"faf09090-7461-58c4-9e9f-2330d868020f","sourceKey":"bank:PUL101:LAW-033","payload":{"prompt":"Which of the following is a criticism of Roscoe Pound's balancing theory?","options":["It treats every law as a command of the sovereign","It holds that unjust laws need not be obeyed","It ignores the role of the courts in resolving disputes","It gives no method for identifying and weighing interests"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Pound's core idea was balancing competing claims, but he did not identify the interests or say how to weigh them, so the same claims might balance differently at different times. A and B belong to Austin and natural law, and C is wrong because the court system was the main focus of Pound's theory."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 45, $official_bank_source${"itemId":"b52aed00-9420-5bc7-9e1c-883fbb6fe2dd","questionId":"7f3ce6dd-e58b-5247-93d2-ddb4eb5422d3","sourceKey":"bank:PUL101:LAW-034","payload":{"prompt":"The view that government, by making the proper laws, should seek to promote the greatest good of the greatest number of people is the central idea of the","options":["utilitarian school","historical school","realist school","pure theory of law"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Jeremy Bentham, the chief proponent of utilitarianism, taught that the task of law is to promote communal utility, meaning what affects people's happiness. The historical school (B) looks to custom, realists (C) to judicial behaviour, and the pure theory (D) to the formal validity of norms."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 46, $official_bank_source${"itemId":"cd860349-b97a-59c5-976a-7024a8f8c6f9","questionId":"de895bb1-7918-5a45-9372-ae646966d709","sourceKey":"bank:PUL101:LAW-035","payload":{"prompt":"Which of the following is NOT one of the four main utilities identified by Jeremy Bentham?","options":["Equality","Security","Abundance","Fraternity"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Bentham identified security, equality, liberty and abundance as the main utilities that law should promote. Fraternity is a slogan of the French Revolution, not one of Bentham's utilities. Security (B), equality (A) and abundance (C) are all on his list."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 47, $official_bank_source${"itemId":"195d29ae-87f8-5069-9906-37f8f674cc46","questionId":"fc588a83-df74-5c14-935b-d48f9f365b18","sourceKey":"bank:PUL101:LAW-036","payload":{"prompt":"Among his four main utilities, which one did Bentham give the highest priority?","options":["Abundance","Liberty","Equality","Security"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Bentham ranked security first and liberty second, with equality and abundance last. This explains why utilitarian reasoning accepts limits on individual freedom, such as routine searches, for the sake of the security of the many. Liberty (B) came second, not first."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 48, $official_bank_source${"itemId":"217a5ae8-feb2-58ba-80a8-8a1d0b0a15b9","questionId":"91923edb-380f-5797-8a6b-7be672751057","sourceKey":"bank:PUL101:LAW-037","payload":{"prompt":"At Murtala Muhammed Airport, every passenger is searched before boarding, even without any suspicion. The authorities explain that a little inconvenience to each traveller is worth the greater safety of all. This justification reflects","options":["the historical school","the utilitarian school","the natural law school","the realist school"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Utilitarians balance individual interest against communal interest; the individual's freedom is sacrificed to achieve the greater goal of security for the greater number. The historical school (A) asks about custom, realists (D) about how judges decide, and natural lawyers (C) about universal right and wrong."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 49, $official_bank_source${"itemId":"075dbeb5-7e6e-50cb-86ba-62341d90451f","questionId":"0a723d76-4a49-58a2-b7a3-046ef2659c8a","sourceKey":"bank:PUL101:LAW-038","payload":{"prompt":"A major criticism of the utilitarian school is that it","options":["insists that only customs can become law","ignores the consequences of laws for society","cannot locate the grundnorm of a legal system","does not explain how to balance individual and communal interests"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Utilitarianism requires the law to balance individual interest against the common good, but it does not solve how to strike that balance. B is wrong because utilitarians judge law precisely by its consequences, A describes the historical school, and C is a criticism of Kelsen."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 50, $official_bank_source${"itemId":"a4ef4050-d99f-54f6-80cd-d4faed23dc80","questionId":"3341d916-1751-572b-a6a5-e80db9e0c307","sourceKey":"bank:PUL101:LAW-039","payload":{"prompt":"Which jurist viewed law from the standpoint of the \"bad man\", who cares nothing for legal theory and only wants to know what the courts will do?","options":["Oliver Wendell Holmes Jr.","Eugen Ehrlich","Hans Kelsen","Friedrich Carl von Savigny"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Holmes, the distinguished United States jurist, expressed the pragmatic idea that law is best understood as what courts will actually do in a particular matter. Ehrlich (B) looked to social conduct, Kelsen (C) to a hierarchy of norms, and Savigny (D) to the spirit of the people."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 51, $official_bank_source${"itemId":"d3f1d161-9c19-57df-b3d3-b5e360ecb6eb","questionId":"8fa3cedc-46d3-560e-9b13-6a33699f09fe","sourceKey":"bank:PUL101:LAW-040","payload":{"prompt":"Which of the following is a shortcoming of the functional school?","options":["It assumes all groups in society have equal bargaining power","It ignores the law-making power of the courts","It looks at the courts alone and neglects the legislature","It ties the validity of law to the customs of the people"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The functional school holds that one must wait for a court decision to know the law, which overlooks the legislature and agencies and forgets that courts are themselves created by law. B is the opposite of its view, since it recognises judicial law-making; D is the historical school, and A criticises the pluralist model."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 52, $official_bank_source${"itemId":"bd798b7d-b073-5c04-a0cb-77c3dc693f4a","questionId":"0535904d-2edd-5b38-bb66-d7f9fa7deaf8","sourceKey":"bank:PUL101:LAW-041","payload":{"prompt":"Before his trial at the High Court, a lawyer advises his client, a well-known \"area boy\", to dress responsibly and not wear dark glasses when giving evidence. The lawyer's advice reflects which theory?","options":["The historical school","Kelsen's pure theory of law","The realist school","The natural law school"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Realists argued that judges are unconsciously influenced by extralegal factors such as dress, appearance and the personality of the accused, so the judicial process is less objective than it looks in the books. The other schools say nothing about how a party's appearance might sway a judge."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 53, $official_bank_source${"itemId":"f2f2e27c-bdb5-5894-91c3-5351a8e9069c","questionId":"845b57b2-6f3d-50b1-bed7-669c8a445bbd","sourceKey":"bank:PUL101:LAW-042","payload":{"prompt":"\"Mr. A's case may be weak, but it will make a big difference if a celebrated human rights lawyer defends him and a judge who shares his faith hears it.\" This statement reflects","options":["the utilitarian school","the consensus model","the positivist school","the realist school"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Realists focus on the human factors in deciding cases: the personality of the accused and his lawyer, and the judge's background and likes, can matter more than the bare rules. Utilitarians (A) judge law by its effect on happiness, positivists (C) by its source, and the consensus model (B) assumes the law is applied equally to all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 54, $official_bank_source${"itemId":"10b82c74-c8cd-534d-be76-acfc3fb3d2c0","questionId":"c6442f54-311c-57a2-97a6-9347b26b3864","sourceKey":"bank:PUL101:LAW-043","payload":{"prompt":"Which of the following is NOT named as an exponent of American realism?","options":["Jerome Frank","Karl Llewellyn","Friedrich Carl von Savigny","John Chipman Gray"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Savigny was a German aristocrat who led the historical school. The exponents of American realism include Oliver Wendell Holmes, Justice Jerome Frank (A), John Chipman Gray (D) and Karl Llewellyn (B)."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 55, $official_bank_source${"itemId":"a9d767a6-f730-50c5-b7e1-69b440ce24b6","questionId":"d6c1cfe0-a635-55d4-9955-98cf5e90e400","sourceKey":"bank:PUL101:LAW-044","payload":{"prompt":"One of the main goals of the American realists was to","options":["replace judges with juries in all criminal trials","make judges aware of their hidden prejudices","restore the authority of monarchs over the law","prove that law is a closed system of logical rules"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Realists studied trial courts and wanted judges to become aware of their latent prejudices, so the system would not favour the 'good boys' against the 'bad boys'. They rejected the idea that law is pure logic (D); for them, the life of the law was experience."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 56, $official_bank_source${"itemId":"47f69538-06ac-5c8f-8b80-926921aba737","questionId":"f8468718-cf6a-56aa-b62a-3052b9b6929b","sourceKey":"bank:PUL101:LAW-045","payload":{"prompt":"\"Law is the prediction of what the courts will do in fact.\" This definition reflects which approach to law?","options":["The natural law approach","The realist approach","The historical approach","The pure theory of law"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Holmes's prediction theory treats law as practical outcomes in court rather than moral ideals or abstract rules. The historical approach (C) looks to custom, natural law (A) to what is just, and the pure theory (D) to the formal validity of norms."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 57, $official_bank_source${"itemId":"ac8b15e4-3a7d-52c6-9306-bd8d69fe90ae","questionId":"d5df106e-a31e-578e-83fd-c31e6ad4550c","sourceKey":"bank:PUL101:LAW-046","payload":{"prompt":"The story of the blind men who each touched a different part of an elephant is used to show that","options":["the oldest definition of law is the most accurate","law can only be understood by those trained as lawyers","each definition of law is shaped by the perspective of the person defining it","only judges can give a complete definition of law"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Each blind man described the part he touched, so all were partly correct yet wrong. Jurists do the same: their backgrounds as judges, legislators, academics or clergymen shape their definitions, which is why all definitions are arbitrary and ad hoc. None of the other options draws that lesson."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 58, $official_bank_source${"itemId":"a8cdc24c-f275-570a-97c5-e0a01b45c5de","questionId":"d743746c-3ff9-5d87-b954-608a81878faf","sourceKey":"bank:PUL101:LAW-047","payload":{"prompt":"Which of the following statements about the theories of law is NOT correct?","options":["Each theory applies to one particular legal system to the exclusion of all others","The theories are often implicit rather than explicit","Virtually all legal systems have applied the theories in varying degrees","The ideas of one jurist may embrace more than one theory"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Students are warned against thinking each philosophy belongs to one legal system alone; in fact all have been applied in varying degrees by virtually every legal system. It is also true that one jurist's ideas may cut across theories (D) and that people often hold these philosophies without naming them (B)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 59, $official_bank_source${"itemId":"5da041ec-53d5-58bf-bde7-dad85ece109e","questionId":"44fda89e-0011-5339-9757-8acf6aaa6db7","sourceKey":"bank:PUL101:LAW-048","payload":{"prompt":"Which of the following uses the word \"law\" in its general sense rather than its technical sense?","options":["The law of demand and supply","The Constitution of the Federal Republic of Nigeria, 1999","The Companies and Allied Matters Act","A rule laid down by the Supreme Court in a decided case"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Expressions such as the law of a club, the law of God or the law of demand and supply use 'law' in a general sense. The technical sense covers rules made by bodies with power to make binding rules, such as statutes (C), the Constitution (B) and case law (D)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 60, $official_bank_source${"itemId":"0e96a066-a129-5054-9ab5-70ef8e5eb6af","questionId":"9cf640dd-7903-5efb-8101-b5406baf3801","sourceKey":"bank:PUL101:LAW-049","payload":{"prompt":"Which feature of law is the main factor that distinguishes legal rules from moral or ethical rules?","options":["Its breach is sanctioned through organised institutions like courts","Legal rules are found in more than one source","Legal rules reflect the values of the society","Legal rules guide people on what they ought or ought not to do"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Moral rules are enforced, if at all, through social disapproval, while legal rules are backed by coercion through organised institutions like the police, courts and prisons. Being normative (D) and reflecting social values (C) are things law shares with moral and religious rules, so they cannot be the distinguishing factor."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 61, $official_bank_source${"itemId":"a9c95d87-9a30-55c2-9aa6-71213f4f08ec","questionId":"dd02d38c-b8d8-5e8c-a7a6-dd72ab73ab10","sourceKey":"bank:PUL101:LAW-050","payload":{"prompt":"A church in Ibadan requires its members to fast every Wednesday and suspends those who refuse. In the technical sense, this rule is not law mainly because","options":["it is not traceable to the Constitution, statutes or case law","it has a sanction attached to breaking it","it applies to only some people in the city","it is not written down in any document"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Law in the technical sense is man-made by bodies vested with power to make binding rules for the state; religious or moral rules are not law unless traceable to sources like the Constitution, statutes, case law or delegated legislation. Being unwritten (D) does not stop customary law being law, and having a sanction (B) is a feature law shares."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 62, $official_bank_source${"itemId":"75cf3c11-628f-5027-aa45-cbd069c1e5de","questionId":"93928aee-e753-5df4-ad2a-79e84d579b22","sourceKey":"bank:PUL101:LAW-051","payload":{"prompt":"In an old English case, a seller sold tea in Dunkirk knowing the buyer planned to smuggle it into England. The court allowed the seller to recover the price, because no country takes notice of the revenue laws of another. Which feature of law does this illustrate?","options":["Element of coercion","Territorial limitation","Normative character","Dynamic nature"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"In Holman v Johnson, the seller had not broken any English law, and enforcing the defence would have given English law extraterritorial effect; laws bind only within their own territory. Dynamic nature (D) is about law changing over time, and normative character (C) is about law guiding conduct."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 63, $official_bank_source${"itemId":"3a009c8a-7162-5874-aed9-4bae1dc114a0","questionId":"4c2812f0-b0ed-58cb-8e1c-b90dc033f5f8","sourceKey":"bank:PUL101:LAW-052","payload":{"prompt":"Musa, a Muslim from Kano, travels to Lagos and drinks beer at a party. He cannot be prosecuted under the Penal Code for that act in Lagos. This illustrates that law","options":["is a body of rules","is dynamic in nature","has territorial limitation","is man-made"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The Penal Code applies in the North and the Criminal Code in the South, and each covers offences committed within its own territory only. As a general rule, a Muslim from the North would be safe from prosecution for drinking alcohol in the South. The other options are real features of law but are not what the example shows."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 64, $official_bank_source${"itemId":"bd154f96-fca0-5369-862d-9a4b1a2429f9","questionId":"c10aa966-b2f2-5fac-8cb7-d7d757e74730","sourceKey":"bank:PUL101:LAW-053","payload":{"prompt":"Nigerian law under colonial rule differed from the law after independence in 1960, and military-era law differed again from law under elected governments. This illustrates that law is","options":["territorially limited","normative","dynamic","coercive"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Law changes with prevailing social, political, economic and cultural conditions, so its content shifts from one era to another. Territorial limitation (A) concerns where law applies, not how it changes over time, and normative (B) and coercive (D) describe how law guides and is enforced."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 65, $official_bank_source${"itemId":"1a258a4b-bd6c-53d8-a8d9-1bff4e931837","questionId":"8df7896d-cb8f-557b-8ceb-33ffa7487bf7","sourceKey":"bank:PUL101:LAW-054","payload":{"prompt":"Bisi and Tunde have lived together for ten years and have two children, but they never contracted a valid marriage. The law does not treat them as husband and wife. Which function of law does this illustrate?","options":["Definition and regulation of social relationships","Dispute settlement and remedies","Identification and allocation of official authority","Change of law"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Law defines which relationships it recognises; a relationship must meet certain essential requirements to be a legal marriage, so prolonged cohabitation alone does not make a couple husband and wife. Allocating authority (C) concerns who exercises public power, and dispute settlement (B) concerns resolving conflicts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 66, $official_bank_source${"itemId":"2e8dbd15-75a8-5473-b402-129ab5b869b2","questionId":"96b8eca9-058f-5a48-a5df-9fe19b2b2d2b","sourceKey":"bank:PUL101:LAW-055","payload":{"prompt":"Sections 4, 5 and 6 of the 1999 Constitution vest legislative, executive and judicial powers in three arms of government. Which function of law do these provisions perform?","options":["Crime prevention and control","Dispute settlement and remedies","Definition and regulation of social relationships","Identification and allocation of official authority"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The law establishes institutions and vests them with authority to act for the state; each arm must keep within its powers or its action is ultra vires, null and void. Choosing class representatives in a university is a small-scale example of the same function. The other options are different functions of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 67, $official_bank_source${"itemId":"d0a6da04-7850-5f20-bf27-7102d9870127","questionId":"be173291-014c-55e6-a303-73243bcd0349","sourceKey":"bank:PUL101:LAW-056","payload":{"prompt":"Mr. A is paralysed after being knocked down by a tanker owned by an oil marketing company with which he has no prior relationship. In a modern complex society, his claim is most likely to be settled","options":["by compromise, because the parties expect a continuing relationship","by the village elders through ostracism of the company","on a winner-takes-all basis, aiming to recover as much compensation as possible","by self-help, with Mr. A seizing the company's property"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"In complex societies, many disputes involve parties who have no need to continue their relationship, so settlement tends to be winner-takes-all. Compromise (A) suits small, community-based societies where relations are permanent. Ostracism (B) and self-help (D) belong to early stages of the evolution of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 68, $official_bank_source${"itemId":"84387dc4-fd53-579b-90f8-9d89ea640c63","questionId":"cb39c73a-d9b7-549b-b7bc-47b29ccc66a3","sourceKey":"bank:PUL101:LAW-057","payload":{"prompt":"The model that sees law as protecting social values to which everyone in society subscribes, with Parliament representing all and the law equal and just to all, is the","options":["conflict or pluralist model","Marxist model","consensus model","open model"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Talcott Parsons saw society as basically unitary with a shared value system. Critics reply that no society has a monolithic set of values, and that apparent consensus may be sectional interests presented as everyone's. The pluralist model (A) accepts competing groups, and Marxism (B) sees law as a tool of class domination."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 69, $official_bank_source${"itemId":"884d7405-bade-5bc6-8dad-c84836f3e844","questionId":"9edbe8fc-cebd-5ba9-9dbd-90d04e63ff2d","sourceKey":"bank:PUL101:LAW-058","payload":{"prompt":"The conflict (pluralist) model of law has been criticised because it","options":["denies that any conflict exists in society","regards the state as an instrument of the ruling class","assumes the competing groups have roughly equal bargaining power","insists that only revolution can resolve conflicts"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The pluralist model treats the state as a neutral arbiter between groups of more or less equal power, but dominant groups control economic and political institutions; the Pareto illustration says 10 per cent own 90 per cent of resources. Denying conflict (A) describes the consensus model, and the ruling-class view (B) is Marxist."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 70, $official_bank_source${"itemId":"411f12aa-8433-5337-8b00-ccaaa98b51b2","questionId":"cae7af90-2814-5a8b-8aa1-537822326f40","sourceKey":"bank:PUL101:LAW-059","payload":{"prompt":"Workers and employers in Nigeria keep disagreeing over wages, but they settle their disputes through negotiation, strikes, arbitration, court cases and elections, never by revolution. This picture best matches the","options":["historical school","open model","Marxist model","consensus model"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The open model sits between consensus and conflict: conflict continues, but it is resolved through legitimate processes such as negotiation, arbitration, judicial decision and electoral battle, backed by strikes but without revolution. The consensus model (D) denies real conflict, and Marxism (C) expects revolutionary confrontation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 71, $official_bank_source${"itemId":"a5105b8a-8a38-5f62-a375-1c8caa9a191d","questionId":"c9b88978-9bbe-514d-bc53-ebaf6f3443d5","sourceKey":"bank:PUL101:LAW-060","payload":{"prompt":"According to Karl Marx, why do many members of the working class accept the domination of a few capitalists?","options":["The ruling class controls both coercion and the dominant ideas","The law reflects the spirit of the people","The state acts as a neutral arbiter between equal groups","The working class freely agrees with a shared value system"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Marx said the ruling class controls the army, police and law, and also the dominant ideas, so 'the ideas of the ruling class are in every epoch the ruling ideas'. A shared value system (D) is the consensus model, a neutral state (C) is the pluralist model, and the spirit of the people (B) is Savigny's historical school."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 72, $official_bank_source${"itemId":"95834ad3-d878-580d-b925-6624c1f3418e","questionId":"de034982-9f58-586d-b0b3-1a46447604ac","sourceKey":"bank:PUL101:LAW-061","payload":{"prompt":"\"The suppression of vice is as much the law's business as the suppression of subversive activities.\" This statement was made by","options":["Phil Harris","Viscount Simonds","Lord Devlin","Lord Eldon"],"correctOption":2,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Lord Devlin argued that societies disintegrate when no common morality is observed, so society may protect its moral code as it protects its government. Viscount Simonds (B) gave the leading speech in Shaw v DPP, and Phil Harris (A) defined morality as a code of beliefs and standards of behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 73, $official_bank_source${"itemId":"9c90ae8e-a74a-56e9-8872-82d2ad90254e","questionId":"aacb20dd-4bae-5c44-a209-e6ee12822d9e","sourceKey":"bank:PUL101:LAW-062","payload":{"prompt":"Respect for elders is strictly observed in villages but has become relaxed in big cities like Lagos and Port Harcourt. This contrast illustrates","options":["the element of coercion in law","the multiple conscience problem of positivism","the territorial limitation of law","the relativity of moral ideas"],"correctOption":3,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Morality is relative: individuals and groups hold different ideas of right and wrong, and as society becomes more diffuse, some moral standards are lowered or abandoned. Respect for elders is a moral standard, not a legal rule, so territorial limitation of law (C) does not fit, and the multiple conscience problem (B) is a weakness of natural law, not positivism."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 74, $official_bank_source${"itemId":"1d7a1a27-7809-5467-8cfb-3294b05b489d","questionId":"02ad1bfb-011d-5cdf-997c-f785f77cbe77","sourceKey":"bank:PUL101:LAW-063","payload":{"prompt":"In Shaw v Director of Public Prosecutions, Shaw published \"The Ladies' Directory\" advertising prostitutes. He was convicted of","options":["treasonable felony","conspiracy to corrupt public morals","obtaining by false pretences","contempt of court"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"The House of Lords upheld the conviction, with Viscount Simonds saying the court had a residual power to conserve the moral welfare of the state. What the court objected to was not prostitution itself but its public advertisement. The case shows law being used to protect public morality."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 75, $official_bank_source${"itemId":"f50e367e-a098-5f5e-bc70-6220c164ce99","questionId":"144b19f6-054c-5edd-b398-0a493d8cbbdb","sourceKey":"bank:PUL101:LAW-064","payload":{"prompt":"In Knuller v Director of Public Prosecutions, the House of Lords held that the Sexual Offences Act 1967","options":["made all private conduct between adults immune from the criminal law","gave no licence to publicly encourage what it decriminalised in private","abolished the offence of conspiracy to corrupt public morals","overruled the decision in Shaw v DPP"],"correctOption":1,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"Following Shaw v DPP, the Lords held that although the Act left consenting adults in private alone, it gave no licence to others to encourage the practice through advertisements, so the publishers were convicted. The case applied Shaw (D) rather than overruling it, and the offence (C) survived."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 76, $official_bank_source${"itemId":"983c1463-c20a-50dc-be8c-1269f8068c44","questionId":"896fece6-6797-5d66-abf7-5493f4f87a14","sourceKey":"bank:PUL101:LAW-065","payload":{"prompt":"A properly enacted law requires every resident of a state to pay a levy of N5,000 to fund a project only the rich will use. A strict positivist would most likely say that the levy","options":["is valid law because it was made by the proper authority, even if it is unjust","is law only if it reflects long-standing custom","is not law at all because it offends natural justice","is law only if the courts decide to enforce it"],"correctOption":0,"section":"Law in Social Context: Meaning, Definitions and Schools of Thought","explanation":"For positivists, law's validity depends on its source, not its moral quality, so even unjust laws remain valid if made and enforced by the proper authority. Saying it is not law at all (C) is the natural law view, waiting for the courts (D) is the realist or functional view, and testing it against custom (B) is the historical view."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 77, $official_bank_source${"itemId":"cf758d3b-2657-53ce-b4c0-0b66f2888595","questionId":"f393a88f-5ac1-5b98-b024-163f60122bd3","sourceKey":"bank:PUL101:PQ-002-01","payload":{"prompt":"Louis XIV's famous claim \"I am the state\" best reflects which idea of the relationship between the ruler and the state?","options":["The rule of law, where the ruler is subject to the law","Popular sovereignty, where power belongs to the people","Separation of powers among three arms of government","Absolute rule, where the ruler claims all power, often based on divine right"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"By saying he was the state, Louis XIV merged the state with his own person, the mark of an absolute ruler whose authority rested on divine right, much like traditional kings seen as second to none. Option B, Option C and Option A are all ideas that developed later precisely to limit that kind of power."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 78, $official_bank_source${"itemId":"facd9c6e-7d36-50bf-8e05-732095d26972","questionId":"d9850e1e-36a5-553b-ac3f-6526c721d0dd","sourceKey":"bank:PUL101:PQ-002-02","payload":{"prompt":"Which of the following is NOT one of the four basic elements of a state?","options":["A population","A definite territory","Sovereignty","A written constitution"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"A state is an organised political community made up of a definite territory, a population, a government and sovereignty. A written constitution is common, but it is not one of these elements of statehood. Option B, Option A and Option C are all listed elements."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 79, $official_bank_source${"itemId":"7f29d887-860d-5bf9-ac23-579c85fadb93","questionId":"d2f5787e-edfb-5012-acbf-b90e4f020c17","sourceKey":"bank:PUL101:PQ-002-03","payload":{"prompt":"Under section 14(2)(a) of the 1999 Constitution of the Federal Republic of Nigeria, sovereignty belongs to","options":["the National Assembly","the people of Nigeria, from whom government derives all its powers and authority","the President as Head of State","the Supreme Court of Nigeria"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Section 14(2)(a) states that sovereignty belongs to the people of Nigeria, from whom government through the Constitution derives all its powers and authority. The President (Option C), the legislature (Option A) and the courts (Option D) only exercise powers given to them by the people through the Constitution."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 80, $official_bank_source${"itemId":"e3cbece5-c43a-571c-904d-f67e74714543","questionId":"02c0b67a-5ace-5ac0-b1ad-fbd80fbe0015","sourceKey":"bank:PUL101:PQ-002-04","payload":{"prompt":"Which French writer introduced the doctrine of sovereignty into Western political theory?","options":["Jean Bodin","Jean-Jacques Rousseau","Voltaire","Montesquieu"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Jean Bodin is credited with introducing the idea of sovereignty, the supreme power within a state, into Western political thought. Option D is famous for separation of powers and Option B for the social contract and the general will. Option C was a writer of the Enlightenment, not the originator of sovereignty theory."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 81, $official_bank_source${"itemId":"d7d93bcf-0116-53fd-b12e-cf47ad423224","questionId":"fc520cb2-e7f3-5f84-9470-d9935a919a30","sourceKey":"bank:PUL101:PQ-002-05","payload":{"prompt":"Which of the following theories was NOT developed to curtail the power of rulers?","options":["The rule of law","The social contract theories","Separation of powers","The divine right of kings"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"The divine right of kings justified absolute power by claiming the ruler's authority came from God, so it supported rulers rather than limiting them. Social contract theories (Option B), the rule of law (Option A) and separation of powers (Option C) all grew up to restrain those in authority."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 82, $official_bank_source${"itemId":"82ec49a2-5898-5228-95f3-374f06ec2864","questionId":"aedb209c-0172-5f46-b436-52a6795127ce","sourceKey":"bank:PUL101:PQ-002-06","payload":{"prompt":"Which thinkers are best known as social contract theorists?","options":["Thomas Hobbes, John Locke and Jean-Jacques Rousseau","Savigny, Ehrlich and Roscoe Pound","John Austin, Hans Kelsen and H.L.A. Hart","Oliver Wendell Holmes, Jerome Frank and Karl Llewellyn"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Hobbes, Locke and Rousseau each explained the state as arising from an agreement among people, which shapes how we see the ruler's duties to citizens. Option C are positivist thinkers, Option D are American realists, and Option B are associated with the historical and sociological schools."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 83, $official_bank_source${"itemId":"fde22bdb-713a-5fef-b18f-d3ddad0cd816","questionId":"e56e0147-52f7-57db-b5d4-fb1acd57cfad","sourceKey":"bank:PUL101:PQ-002-07","payload":{"prompt":"A state is an artificial entity and must act through human agents. The structure through which those agents act for the state is called","options":["the territory","the government","the citizenry","sovereignty"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"The government is the machinery for running the state, made up of the legislature, executive and judiciary and their agencies. A state does not stop existing just because its government changes. Option D is the supreme power the state holds, while Option C and Option A are the people and land of the state, not its acting machinery."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 84, $official_bank_source${"itemId":"0ff9f07a-d3a6-5fff-ad30-2750abf2a46e","questionId":"c5bc868a-b24b-58da-b614-26f985c31e96","sourceKey":"bank:PUL101:PQ-002-08","payload":{"prompt":"Section 1(2) of the 1999 Constitution forbids any person or group from taking control of the government of Nigeria except in accordance with the Constitution. This provision mainly deals with","options":["the legitimacy of how power over the state is acquired","the fundamental rights of citizens","the rules for interpreting statutes","the sharing of revenue among the states"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Section 1(2) prescribes the only lawful way of gaining control of government, which is why an unsuccessful coup is treated as treason. It is about legitimate access to power, not Option B, which is in Chapter IV, nor Option D or Option C."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 85, $official_bank_source${"itemId":"a439b8f7-1c22-56d2-8b2e-36ccec39e9ad","questionId":"d0defa2d-b698-5f36-b508-06fa67bdb0b3","sourceKey":"bank:PUL101:PQ-002-09","payload":{"prompt":"The doctrine of separation of powers, which divides government into legislative, executive and judicial arms, is most famously associated with","options":["Jean Bodin","Friedrich Carl von Savigny","Montesquieu","Thomas Hobbes"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Montesquieu developed separation of powers, building on John Locke, as a way to stop any one ruler from holding all power. Option A is linked with the idea of sovereignty, Option D argued for a strong sovereign, and Option B founded the Historical School of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 86, $official_bank_source${"itemId":"0632d2b5-97e5-57fa-bd2f-e8c6eb627be7","questionId":"b3dc7bdd-e673-5246-87e4-89c0e9b5434d","sourceKey":"bank:PUL101:PQ-003-01","payload":{"prompt":"The statement that justice is \"in the eye of the beholder\" is best explained by which observation?","options":["Justice is only relevant in criminal cases and not in civil cases","Justice has one fixed meaning that every person agrees on","Justice is the same thing as whatever the legislature enacts","What counts as justice depends on the person's position, interests and background, so the winner and loser of the same case may see it differently"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Factors such as home background, education, religion and self-interest shape each person's idea of justice, which is why the party who wins a case says justice was done while the loser speaks of a miscarriage of justice. Option B is the opposite of the statement. Option C confuses law with justice, and Option A is simply untrue."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 87, $official_bank_source${"itemId":"e2d8479a-b0af-5753-a36f-d22fbc480ee1","questionId":"16b10cec-470c-5346-82da-f78d51dbc1b5","sourceKey":"bank:PUL101:PQ-003-02","payload":{"prompt":"Who defined justice as \"the constant and perpetual will to render to everyone his due\"?","options":["Ulpian, the Roman jurist","Plato","Jeremy Bentham","John Rawls"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"This classic Roman definition comes from Ulpian and was adopted in Justinian's Institutes; Aquinas later used very similar words. Option B saw justice as each person doing what he is fitted for. Option D spoke of justice as fairness, and Option C focused on utility rather than defining justice this way."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 88, $official_bank_source${"itemId":"90683413-4953-56ba-802d-1eb4603e34b1","questionId":"7e2ec0ec-fa91-502a-be0a-5dbc55d61b95","sourceKey":"bank:PUL101:PQ-003-03","payload":{"prompt":"Which thinker described justice as \"the first virtue of social institutions, as truth is of systems of thought\" and developed the idea of justice as fairness?","options":["Aristotle","John Rawls","Ulpian","John Austin"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Rawls treated justice as fairness in how basic rights, opportunities and advantages are distributed in society. Option A is known for dividing justice into corrective and distributive. Option C gave the 'render to everyone his due' definition, and Option D was a positivist who separated law from justice."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 89, $official_bank_source${"itemId":"c728eb09-393e-5a7a-996d-9d3948741d32","questionId":"d3bb646f-16ce-5489-b13a-31c5beff83cb","sourceKey":"bank:PUL101:PQ-003-04","payload":{"prompt":"The view that justice is when each person does that for which he or she is fitted or suited is associated with","options":["Thomas Aquinas","Plato","Jeremy Bentham","John Rawls"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Plato saw a just society as one where each person performs the role he is suited for. Critics point out that this idea can be used to justify rigid systems such as caste or the Osu system. Option D spoke of fairness, Option A of rendering each his due, and Option C of the greatest happiness of the greatest number."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 90, $official_bank_source${"itemId":"9785ea12-a521-5c4f-a3ad-08188f60fb8f","questionId":"f56ab749-4c48-5583-8b2a-c38928fdf636","sourceKey":"bank:PUL101:PQ-003-05","payload":{"prompt":"Aristotle classified justice into two types. They are","options":["formal justice and substantive justice","corrective justice and distributive justice","commutative justice and retributive justice","procedural justice and technical justice"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Aristotle distinguished corrective justice, which rectifies wrongs between two parties, from distributive justice, which shares honours and rewards in society according to desert. Option A is a different modern pairing about how strictly judges apply law. Option D names what is essentially one type twice, and the commutative label in Option C is linked with Aquinas."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 91, $official_bank_source${"itemId":"ba619408-2413-5897-9710-b9f075d56658","questionId":"d77859ef-b9a2-5464-9d1f-93ffb3b4874b","sourceKey":"bank:PUL101:PQ-003-06","payload":{"prompt":"The Federal Character principle in the Nigerian Constitution, which seeks a fair spread of public appointments across the country, is an example of","options":["commutative justice","procedural justice","corrective justice","distributive justice"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Distributive justice is about how the state shares out benefits, offices and burdens among members of society, which is exactly what Federal Character does. Option C and Option A deal with putting things right or keeping fairness between two individuals, and Option B is about fair process in deciding cases."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 92, $official_bank_source${"itemId":"fd121a2b-7656-543a-906a-3dfab14ccf32","questionId":"98e4185a-4bdf-51bb-86bd-f8efed3fd3c6","sourceKey":"bank:PUL101:PQ-003-07","payload":{"prompt":"The right to fair hearing guaranteed by section 36 of the 1999 Constitution mainly embodies which type of justice?","options":["Distributive justice","Corrective justice","Procedural justice","Poetic justice"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Procedural or technical justice is concerned with how a decision is reached: an impartial hearing, a chance to be heard and a fair trial. That is the heart of section 36. Option A concerns sharing resources in society, Option B concerns repairing a wrong between parties, and Option D is a literary idea, not a legal one."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 93, $official_bank_source${"itemId":"c7801188-c6e6-5a86-8e83-985a7eb1ebd8","questionId":"c146a61b-7b94-5b65-ad2c-7bf381f0e1a5","sourceKey":"bank:PUL101:PQ-003-08","payload":{"prompt":"The theory of justice that requires a judge to apply the law strictly as it is, without regard to extra-legal considerations or the harshness of the result, is called","options":["distributive justice","substantive justice","judicial activism","formal justice"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Under formal justice, justice is done when a case is decided strictly according to law, which is said to promote certainty and impartiality. Option B lets the judge consider wider factors to avoid absurdity or injustice, and Option C is the name for that liberal approach. Option A is about sharing benefits in society."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 94, $official_bank_source${"itemId":"57081cdd-873c-59cb-ba65-eae44d8135a2","questionId":"4485fa9d-40d7-5e55-a189-e10530646a29","sourceKey":"bank:PUL101:PQ-003-09","payload":{"prompt":"When Nigerian courts insist that \"justice should not be sacrificed on the altar of technicalities\", as in Chinwendu v. Mbamali, they are promoting","options":["substantial (substantive) justice","commutative justice","technical justice","formal justice"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Substantial justice looks at whether the outcome is truly fair, so courts prefer to decide cases on their merits rather than dismiss them on a technical slip. Option D and Option C are the strict, rule-bound approaches the courts are warning against, and Option B concerns fairness in dealings between two persons."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 95, $official_bank_source${"itemId":"887e6cd2-6e07-53ae-a5a6-e4ecf5002680","questionId":"9722a56c-105e-518e-a191-1c26e1825a26","sourceKey":"bank:PUL101:PQ-003-10","payload":{"prompt":"In Josiah v. The State, justice in criminal matters was described as a three-way traffic. The three parties to whom justice is owed are","options":["the legislature, the executive and the judiciary","the judge, the prosecutor and defence counsel","the accused person, the victim and the state (society)","the plaintiff, the defendant and the witnesses"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Oputa JSC explained that criminal justice must serve the accused, the victim and the society represented by the state, not just one of them. Option B are the people who administer the trial, Option A are the arms of government, and Option D describes parties in a civil case."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 96, $official_bank_source${"itemId":"a42df78a-c7f3-529e-92a1-254853e05f4c","questionId":"2768b60c-c10a-562b-a760-01fdab52f307","sourceKey":"bank:PUL101:OBJ-001","payload":{"prompt":"The classical function of any government, often described as the foremost justification for modern government, is to","options":["guarantee every citizen paid employment","maintain law and order and protect lives and property","redistribute wealth equally among all citizens","promote one official religion"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Maintaining law and order is the first objective of law; its opposite is anarchy and chaos. The other options describe policies some governments may pursue, but they are not the classical function on which modern government is justified."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 97, $official_bank_source${"itemId":"dd00e4c5-1b8a-5ef0-85d6-92e9fbdbc2cb","questionId":"d567600c-8816-571c-a47f-31c281540ef0","sourceKey":"bank:PUL101:OBJ-002","payload":{"prompt":"During an armed conflict, the warring parties are bound by rules protecting religious houses, children, pregnant women and Red Cross workers. This shows that","options":["law still sets minimum standards of conduct even in war","law ceases to operate once war begins","only domestic law applies during war","justice is in the eye of the beholder"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Even in war, law plays a basic role in keeping certain minimum standards of behaviour, for example through the Geneva Conventions, which protect civilians, vulnerable groups and relief workers. B is the opposite of the point, and C is wrong because these protections come from international law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 98, $official_bank_source${"itemId":"48a99f1e-39fc-59d9-9b20-c60b66390ba6","questionId":"0852eb9a-6a45-58b1-84f8-ffae57f7b0b0","sourceKey":"bank:PUL101:OBJ-003","payload":{"prompt":"As distinct from the everyday view that law and justice mean the same thing, justice has been described as","options":["the punishment of every wrongdoer without trial","the correct application of a law, as opposed to arbitrariness","the law of a club or association","whatever the most powerful person in society decides"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"In ordinary speech, law and justice are treated as synonyms, but justice is better seen as applying the law correctly rather than arbitrarily. Law seeks justice and is a means to it, not an end in itself. D describes arbitrariness, and A ignores fair process."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 99, $official_bank_source${"itemId":"b3ec7eee-6cbb-588d-9cba-69cda572a9b4","questionId":"e82d7fb7-19e7-50cf-a949-d86b9cd20252","sourceKey":"bank:PUL101:OBJ-004","payload":{"prompt":"Which statement best describes the relationship between law and justice?","options":["Law and justice are always identical in content","Law and justice have no connection with each other","Justice is the means, and law is the end it seeks","Law is the means, and justice is the end it seeks"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Law is the instrument or machinery through which justice is realised, and justice gives law its moral force. C reverses the relationship. A is wrong because a law may be legal yet unjust, as with apartheid laws, and B ignores that the primary objective of law is justice."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 100, $official_bank_source${"itemId":"7e7a4b6e-b3b5-5e48-9df9-2cfd15fb30b6","questionId":"1c65f880-792c-598e-a870-1674a0ce12b2","sourceKey":"bank:PUL101:OBJ-005","payload":{"prompt":"Which of the following is NOT listed as a factor that shapes a person's conception of justice?","options":["Socio-political affiliation","Home background","Height and physical build","Religious belief"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Justice means different things to different people because of factors such as home background, education, religious belief, enlightened self-interest, personal idiosyncrasies and socio-political affiliation. Physical build is not one of them, while B, D and A are all on the list."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 101, $official_bank_source${"itemId":"ddf4bc36-b864-588b-8532-f196298d298e","questionId":"0b995b73-5143-5884-951c-bf8455a66a72","sourceKey":"bank:PUL101:OBJ-006","payload":{"prompt":"After a court rules on a wage dispute, the union says \"justice has been done\", while the employers call the ruling \"a miscarriage of justice\". This best illustrates the view that","options":["justice is following laid down rules","justice is the first virtue of social institutions","justice, like beauty, is in the eye of the beholder","justice is a three-way traffic"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"There is no universally accepted definition of justice; it depends on the definer's perspective. Before a court, the winner feels justice has been done while the loser sees a miscarriage of justice. The other options are definitions of justice, but they do not explain why the two sides see the same ruling differently."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 102, $official_bank_source${"itemId":"549cbdbf-e0aa-5e2c-b8e2-15ac4b00fd8d","questionId":"c20cad3b-1168-5b22-9751-174814d18636","sourceKey":"bank:PUL101:OBJ-007","payload":{"prompt":"Who described justice as \"the first condition of humanity\"?","options":["Emily Thorne","Wole Soyinka","Harold Lasswell","John Rawls"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Prof. Wole Soyinka described justice as the first condition of humanity. Rawls (D) called justice the first virtue of social institutions, Emily Thorne (A) said justice is in the eye of the beholder, and Lasswell (C) defined politics as who gets what, when and how."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 103, $official_bank_source${"itemId":"2eac165f-193b-5b67-9540-d5152973d50a","questionId":"951cead4-e0db-520b-8ff8-84a4509d2468","sourceKey":"bank:PUL101:OBJ-008","payload":{"prompt":"The theory of justice which holds that a judge must apply the law strictly, with no discretion to soften its harshness and no regard to extra-legal considerations, is","options":["formal justice","natural justice","distributive justice","substantive justice"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Under formal justice, justice is done when a case is decided strictly according to law. Substantive justice (D) allows the judge to consider extra-legal factors to avoid absurd or unjust results, and distributive justice (C) concerns the fair sharing of resources and burdens in society."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 104, $official_bank_source${"itemId":"d1545fb0-c7ab-5c42-8084-ad25657436c7","questionId":"7853f25b-0809-5977-8d2c-c63dcf44020b","sourceKey":"bank:PUL101:OBJ-009","payload":{"prompt":"At the end of a politically charged treason trial, the judge tells the court: \"Whatever my sympathies for the accused, my hands are tied,\" and convicts him. The judge's approach is an example of","options":["formal justice","judicial activism","substantive justice","corrective justice"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"'My hands are tied' captures formal justice: the judge applies the law as it is, whatever his sympathies. Judicial activism (B) is the liberal interpretation of law to achieve substantive justice (C), which is the opposite approach. Corrective justice (D) concerns rectifying wrongs between individuals."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 105, $official_bank_source${"itemId":"8b58c0ec-2812-5023-b5c7-de2f969d7b5f","questionId":"3afc770d-aa23-5be1-9e30-8fde8e9f4986","sourceKey":"bank:PUL101:OBJ-010","payload":{"prompt":"Which of the following is NOT a justification offered for formal justice?","options":["It lets the judge soften the law's harshness","It promotes impartiality and independence in adjudication","It ensures the certainty of the law","It ensures the clarity of the law"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Formal justice denies the judge any discretion to mitigate the law's harshness; that flexibility belongs to substantive justice. Its supporters say it ensures clarity (D) and certainty (C) and makes for impartial adjudication (B) because the judge cannot favour either party."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 106, $official_bank_source${"itemId":"972918e1-4522-54a7-8f60-4c389dde77e8","questionId":"53b60d95-5700-5ef6-8650-c668a4b7cbae","sourceKey":"bank:PUL101:OBJ-011","payload":{"prompt":"The practice of judges liberally interpreting the provisions of the law in order to advance substantive justice is commonly known as","options":["the literal rule","formal justice","judicial activism","judicial precedent"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Substantive justice allows a judge to consider extra-judicial factors where strict application would produce manifest absurdity or injustice, and this attitude also led to the development of equity. Formal justice (B) is the opposite approach. Judicial precedent (D) is about following earlier decisions, not liberal interpretation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 107, $official_bank_source${"itemId":"12ddf6fe-25ec-5b6f-9d04-f4d3cf783572","questionId":"ae3e5e4c-a10c-5459-b671-ed02cfc92e1a","sourceKey":"bank:PUL101:OBJ-012","payload":{"prompt":"Chika's evidence clearly proves that a supplier owes her N450,000, but the court strikes out her case because her lawyer used the wrong form. Which type of justice has most clearly been denied?","options":["Substantive justice","Distributive justice","Commutative justice","Formal justice"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Substantive justice looks at whether the outcome is fair; dismissing a case on a mere technicality when the evidence supports the claimant denies it. Formal or procedural justice (D) has arguably been followed, since the rules of procedure were strictly applied. Distributive justice (B) concerns the state's allocation of resources."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 108, $official_bank_source${"itemId":"575d8f0d-627c-59f9-92d1-b26e4770ee0f","questionId":"be571870-082e-524b-80cd-d535d41f497c","sourceKey":"bank:PUL101:OBJ-014","payload":{"prompt":"In his book A Theory of Justice (1971), which writer defined justice as fairness and called it \"the first virtue of social institutions\"?","options":["Wole Soyinka","Aristotle","John Rawls","Ulpian"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Rawls saw a just society as one where basic rights, equality of opportunity and advantages are fairly distributed. Ulpian (D) spoke of the constant and perpetual will to render each his due, and Soyinka (A) called justice the first condition of humanity, not the first virtue of institutions."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 109, $official_bank_source${"itemId":"36fd6463-6be9-51b8-93af-3aceb4773d80","questionId":"28827d6b-ac7a-585d-91fb-69401928e94d","sourceKey":"bank:PUL101:OBJ-015","payload":{"prompt":"According to Aristotle, justice is two-fold. It consists of","options":["obedience to the king, and loyalty to the state","charity, and forgiveness","the will of the majority, and the will of the ruler","conduct in agreement with law, and equality"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Aristotle saw justice both as conduct in agreement with an authoritative rule and as equality. That is why justice is also described as treating like cases alike. The other pairs are virtues or political ideas that do not reflect Aristotle's two-fold account."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 110, $official_bank_source${"itemId":"e65ac38d-e49b-58ec-91ca-efde3437fff3","questionId":"58ae3ba6-ae35-584f-81ce-1d5962817a08","sourceKey":"bank:PUL101:OBJ-016","payload":{"prompt":"A society insists that people born into a particular group may only do menial work and must never hold leadership positions, because that is what they are \"fitted for\". This reasoning reflects which writer's view of justice?","options":["Plato","Wole Soyinka","Ulpian","John Rawls"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Plato said justice is when one does that for which one is fitted or suited, an idea linked to the caste system in India and the Osu system in Eastern Nigeria. Rawls (D) would reject it because justice as fairness requires equality of opportunity. Ulpian (C) spoke of rendering each his due."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 111, $official_bank_source${"itemId":"6ecfe4cf-1a97-5392-8e24-7a4b20896513","questionId":"2f438da2-ad7e-5c2c-bedb-2c7ba6ea0f7e","sourceKey":"bank:PUL101:OBJ-018","payload":{"prompt":"When justice is seen as \"equality according to law\", it is mainly expressed through","options":["letting each community make its own criminal law","treating like cases alike, as in universal adult suffrage","giving more votes to those who pay more tax","allowing judges to decide cases on personal sympathy"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Justice as equality means treating like alike, for example equal treatment in legal proceedings and one vote for every adult. Its benefit is that it can reduce discrimination. C would be unequal treatment, and D replaces law with personal sympathy."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 112, $official_bank_source${"itemId":"1ccfc506-01e8-5c02-96f7-73c232a9a1a4","questionId":"c9634c0c-bc4f-5690-aa31-dcc20ecaa175","sourceKey":"bank:PUL101:OBJ-019","payload":{"prompt":"A mother shares food and clothing exactly equally among her three children, although one of them is physically challenged and needs more care. This example is used to show that","options":["justice is following laid down rules","justice is a three-way traffic","strict equality can sometimes work injustice","equality always produces justice"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Treating unequal situations the same can be unfair, so equality may work injustice. That is why the law sometimes treats people unequally on grounds such as infancy, insanity or poverty. D is exactly what the example disproves."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 113, $official_bank_source${"itemId":"14897752-6a49-51ff-9f46-1b9f782431ca","questionId":"3e101d9f-4458-588f-8f8f-ea8ad2020050","sourceKey":"bank:PUL101:OBJ-020","payload":{"prompt":"A state provides free legal aid only to poor litigants and awards scholarships only to the poorest students. Treating these groups differently from others is best explained by the idea that","options":["only commutative justice matters to the state","justice is whatever the ruler says","justice is always strict equality","unequal treatment can itself be a form of justice"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"On the basis of justice, persons may be treated unequally on grounds of insanity, infancy or poverty, for example through legal aid for indigent persons and scholarships for the poorest of the poor. C is the view this practice departs from, and B reflects absolutism."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 114, $official_bank_source${"itemId":"536f1c98-c5c5-5189-bdc2-116590f4c547","questionId":"4bbe594b-269c-515c-9b27-db09f3693734","sourceKey":"bank:PUL101:OBJ-021","payload":{"prompt":"The type of justice concerned with fairness in dealings and exchanges between two individuals, such as enforcing a contract, and described as \"justice of coordination\", is","options":["distributive justice","social justice","commutative justice","procedural justice"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Commutative justice concerns voluntary transactions between persons in private law; it is individual-centred, not societal. Distributive justice (A) concerns how the community shares goods among its members and is called justice of subordination. Procedural justice (D) concerns the fairness of the process."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 115, $official_bank_source${"itemId":"a8d1d3f7-5ba7-53c6-a1c8-1fe94ae5e506","questionId":"2a07c558-e17e-5c35-a150-124120da5aec","sourceKey":"bank:PUL101:OBJ-022","payload":{"prompt":"The Constitution requires that appointments to federal offices reflect the federal character of Nigeria, so that no state or ethnic group dominates. This is an example of","options":["distributive justice","procedural justice","commutative justice","corrective justice"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Distributive justice concerns how the state allocates resources, honours, rights and burdens among members of the community according to need, merit or equality; the Federal Character principle is a standard example. Commutative (C) and corrective (D) justice deal with transactions and wrongs between individuals."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 116, $official_bank_source${"itemId":"5d06917e-0f8f-59b5-a3ff-812410b2c78e","questionId":"c7b45eb4-9747-54d1-8bc8-7a16c931cb63","sourceKey":"bank:PUL101:OBJ-023","payload":{"prompt":"After removing fuel subsidy, the federal government pays N25,000 in palliatives to the poorest households to ease the burden. This policy is best described as an attempt at","options":["distributive justice","procedural justice","commutative justice","corrective justice"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Spreading the benefits and burdens of public policy fairly across society, according to need, is distributive justice; fuel subsidy removal and palliatives are given as examples. There is no private transaction (C) and no individual wrong being rectified (D) here."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 117, $official_bank_source${"itemId":"1207ad26-2342-5d0e-922b-9b756810ab5a","questionId":"e0059302-3d44-5b60-a698-6fe6b9e4471c","sourceKey":"bank:PUL101:OBJ-024","payload":{"prompt":"Tunde steals Ada's generator worth N180,000. The court orders him to return it and pay a penalty to correct the imbalance. Which type of justice, developed by Aristotle to rectify wrongs between individuals, does this reflect?","options":["Social justice","Corrective justice","Procedural justice","Distributive justice"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Corrective justice restores the balance when one party suffers harm or unfair loss at the hands of another, mainly in criminal law and tort; the wrongdoer must make amends or face punishment. Distributive justice (D) is about allocating society's resources, and procedural justice (C) concerns the fairness of the process."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 118, $official_bank_source${"itemId":"e5107f03-9d81-5545-8838-2a08e463284d","questionId":"652d15d6-4639-5984-936e-8fd95c0b7e9c","sourceKey":"bank:PUL101:OBJ-025","payload":{"prompt":"How does corrective justice differ from distributive justice in terms of time?","options":["Both are concerned only with future arrangements","Both are concerned only with past wrongs","Corrective justice is prospective, while distributive justice is retrospective","Corrective justice is retrospective, while distributive justice is prospective"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Corrective justice looks back to fix past wrongs, such as compensating a victim of fraud, while distributive justice looks forward to fair future arrangements, such as economic policies that reduce poverty. C reverses the two, and A and B wrongly treat them as the same."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 119, $official_bank_source${"itemId":"b47c44bb-ee93-58d7-980b-aab36ce5e71b","questionId":"c6be0323-43ec-509b-8bfb-e610096d74b7","sourceKey":"bank:PUL101:OBJ-027","payload":{"prompt":"Thomas Aquinas classified justice into","options":["natural justice and divine justice","formal justice and substantive justice","corrective justice and retributive justice","commutative justice and distributive justice"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Aquinas divided justice into commutative justice, dealing with transactions between persons, and distributive justice, dealing with the community's relation to each person. Aristotle paired corrective justice with distributive justice, and formal and substantive justice (B) are the two theories of judicial approach."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 120, $official_bank_source${"itemId":"2d7afd7d-a5f3-566a-9137-8e2ab8948435","questionId":"a1fc006b-2d59-5b08-9c54-7d44fae08997","sourceKey":"bank:PUL101:OBJ-028","payload":{"prompt":"The type of justice that focuses on fairness in how a decision is reached, through impartial trials and hearings, rather than on the outcome, is","options":["procedural justice","commutative justice","distributive justice","substantive justice"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Procedural or technical justice requires legal procedures to be conducted impartially and transparently; 'justice must not only be done, but must be seen to be done'. Section 36 of the 1999 Constitution, guaranteeing fair hearing, embodies it. Substantive justice (D) looks at the fairness of the result itself."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 121, $official_bank_source${"itemId":"7623a825-4200-5796-b488-332439acead9","questionId":"1a59e4dc-c704-540e-9471-b26259d9641f","sourceKey":"bank:PUL101:OBJ-029","payload":{"prompt":"A customary court convicts Emeka of land trespass without telling him the charge or letting him call witnesses. Which constitutional guarantee, embodying procedural justice, has most clearly been breached?","options":["The right to fair hearing under section 36 of the 1999 Constitution","Freedom of association under section 40","The vesting of legislative powers under section 4","The procedure for amending the Constitution under section 9"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Procedural justice requires that an accused be heard, have access to counsel and be presumed innocent, and section 36 guarantees fair hearing. Section 40 (B) protects freedom of association, section 4 (C) vests legislative power, and section 9 (D) deals with constitutional amendment."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 122, $official_bank_source${"itemId":"3f4724eb-fd3f-5424-b02d-dbce997ff374","questionId":"881640f8-9bf6-5698-acbd-3ef144caef85","sourceKey":"bank:PUL101:OBJ-030","payload":{"prompt":"Dennis Lloyd suggested ways of making law conform to criteria of rightness so as to achieve substantial justice. Which of the following is NOT one of them?","options":["Judicial discretion","Political or affirmative action such as gender mainstreaming","Legislative reforms","Strict literal application regardless of outcome"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Because procedural or formal justice can itself be unjust, Lloyd proposed judicial discretion (A), legislative reforms (C) and political or affirmative action (B) to secure substantial justice. Strict literal application regardless of outcome is formal justice, the very approach that can produce injustice."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 123, $official_bank_source${"itemId":"112befab-0625-58c2-86b6-974e9fb712fc","questionId":"7c67f35e-874a-5a1d-9d27-7222eb88dc4d","sourceKey":"bank:PUL101:OBJ-031","payload":{"prompt":"In judging whether substantial justice has been done, the standard applied by Nigerian courts is that of","options":["a reasonable man","the majority of the community's elders","the most senior lawyer in court","the presiding judge's personal conscience"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"The test is objective: whether a reasonable person observing the proceedings would conclude that justice was done. A judge's personal conscience (D) would make justice subjective, which the reasonable man standard is meant to avoid."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 124, $official_bank_source${"itemId":"8af6d5f4-0301-5042-8cae-f29864b3faab","questionId":"3afa6f7b-071a-596c-9ee5-7048f04f98ac","sourceKey":"bank:PUL101:OBJ-032","payload":{"prompt":"Apartheid laws in South Africa and racial segregation laws in the United States before 1964 are cited to show that","options":["unjust laws are never enforced by states","a law may be legal yet unjust","justice and law always coincide","only customary law can be unjust"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Law and justice are closely linked but can come apart: such laws were validly made yet deeply unjust. This is why scholars debate whether justice should be the ultimate measure of a law's validity. Brown v Board of Education (1954), which declared school segregation unconstitutional, later realigned law with justice."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 125, $official_bank_source${"itemId":"fe9e293b-32c3-55cb-b50e-4d16807cfae1","questionId":"97236983-279d-5ec4-b4e5-182127ab30fe","sourceKey":"bank:PUL101:OBJ-033","payload":{"prompt":"A journalist publishes a false and malicious story about a businessman and argues that freedom of speech protects him. The best response is that","options":["freedom of speech applies only to politicians","fundamental rights are moral ideas the courts cannot enforce","freedom of speech is absolute and cannot be limited","rights are not absolute and must be balanced against others' rights"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Law recognises freedom but regulates its exercise; leaving freedom totally unrestricted would encroach on others' freedom and lead to anarchy. Freedom of speech does not include freedom to publish malicious falsehoods. B is wrong because Chapter IV rights are justiciable in Nigerian courts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 126, $official_bank_source${"itemId":"ef6b1db1-04e0-507a-a6cd-cde6b112dc4f","questionId":"52456413-a579-5542-83bd-4d4d10847399","sourceKey":"bank:PUL101:OBJ-034","payload":{"prompt":"Which of the following is NOT a limitation that the law places on freedom of contract?","options":["The law may control the prices of certain essential goods","Every person must accept any offer a trader makes to him","A contract is void if it contemplates the commission of a crime","A trader may be barred from using a trade name closely resembling an existing one"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Freedom of contract includes the right to refuse to contract, so no rule forces anyone to accept every offer, and Option B is not a real limitation. The real limitations are voiding illegal or anti-public-policy contracts (C), price control for essential goods (A) and preventing confusing trade names or trademarks (D)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 127, $official_bank_source${"itemId":"d134c8c2-2f59-5b64-8757-d37d58e91feb","questionId":"2cf5991f-a6bb-526e-b3aa-0e88f3e0b145","sourceKey":"bank:PUL101:OBJ-035","payload":{"prompt":"Seventeen-year-old Ifeoma tries to register as a voter for a National Assembly election but is turned away. This is an example of","options":["a breach of freedom of contract","a violation of procedural justice","the territorial limitation of law","a lawful limitation on political freedom"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Political freedom includes the right to vote, but the law may disqualify some people, such as those below eighteen, from voting. The Constitution entitles every citizen who has attained eighteen years to register, which by implication excludes those below that age. The other options do not describe this situation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 128, $official_bank_source${"itemId":"3fa42629-abd5-5911-acdb-14e9107c1143","questionId":"e9a62631-9aaf-5d3a-9fac-dc6886c7530b","sourceKey":"bank:PUL101:OBJ-036","payload":{"prompt":"A state is an organised political community with four basic elements. Which of the following is NOT one of them?","options":["Sovereignty","An official state religion","A population","A definite territory"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"The four basic elements of a state are a definite territory, a population, a government and sovereignty. A state religion is not required, and Nigeria, for example, has none. Territory (D), population (C) and sovereignty (A) are all elements."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 129, $official_bank_source${"itemId":"6c6d9d54-40d0-5d87-8cc9-f1435e9a392d","questionId":"316a0a3d-3ef7-548f-9f78-e4da31ff9008","sourceKey":"bank:PUL101:OBJ-037","payload":{"prompt":"A breakaway region controls its territory and population and has an effective government, but no other state recognises it. Which statement best describes its position?","options":["It is a state only if its old parent state's courts approve","It can never be a state because it was once part of another state","Recognition matters politically but is not strictly conclusive","It automatically becomes a full state once it declares independence"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Under the Montevideo criteria, a state needs a permanent population, a defined territory, a government and capacity to enter relations with other states. Recognition affects international standing but is not strictly conclusive, so such a region may operate in practice while lacking full international personality. D ignores the capacity and recognition problem."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 130, $official_bank_source${"itemId":"19c128e9-b130-5d9f-85d8-582a677e4304","questionId":"eebab13b-2d51-5e25-b0eb-5d95c817dff4","sourceKey":"bank:PUL101:OBJ-038","payload":{"prompt":"Section 2(1) of the 1999 Constitution describes Nigeria as","options":["a unitary state with no component states","a union that any state may leave at will","one indivisible and indissoluble sovereign state","a confederation of independent regions"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Section 2(1) provides that Nigeria is one indivisible and indissoluble sovereign state known as the Federal Republic of Nigeria, and section 2(2) makes it a federation of states and a Federal Capital Territory. It is a federation, not a unitary state (A), and the word indissoluble rules out D and B."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 131, $official_bank_source${"itemId":"44d276fb-adc2-5d6c-b3bd-3f4507cf537b","questionId":"46f757e2-a9ff-5ebc-ae10-b300fe071db2","sourceKey":"bank:PUL101:OBJ-040","payload":{"prompt":"A country's government becomes oppressive and racist, but it does not threaten neighbouring states. As a rule, international law treats that country as","options":["a state only if its citizens approve the government","still a state, as an oppressive government does not end its personality","a state only until the United Nations dissolves it","no longer a state, because its government has become unjust"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"International law as a rule pays little attention to a state's internal affairs as long as other states' interests are not affected, so an oppressive government does not end the state's personality. D confuses the state with its government, which is only the machinery through which the state acts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 132, $official_bank_source${"itemId":"1bb718fa-2ff0-574a-b4e0-76247ac8f961","questionId":"6a643a8a-6f94-51ac-9f8d-3594eaa36275","sourceKey":"bank:PUL101:OBJ-041","payload":{"prompt":"Louis XIV's statement \"I am the state\" best reflects a period when","options":["judges could declare the ruler's acts null and void","sovereignty belonged to the people under a written constitution","the powers of government were separated among three arms","rulers wielded absolute power and based their authority on divine right"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Louis XIV interrupted a judge who spoke of 'the king and the state' to declare 'I am the state', reflecting an era when ruler and state were fused, as with African kings regarded as demi-gods. Popular sovereignty (B), separation of powers (C) and judicial review (A) are later ideas that curtailed such power."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 133, $official_bank_source${"itemId":"242154da-c56a-5714-a954-dbc337da61a4","questionId":"824a494c-ae41-5dcb-bcc0-944eca97082c","sourceKey":"bank:PUL101:OBJ-043","payload":{"prompt":"Under section 14(2)(a) of the 1999 Constitution, sovereignty in Nigeria belongs to","options":["the President as head of state","the Supreme Court as the final court","the people of Nigeria","the National Assembly as the law-making body"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Over time, sovereign power was taken from a few individuals and vested in the people collectively, who exercise it through their representatives. Section 14(2)(a) states this plainly. The President (A), the National Assembly (D) and the courts (B) exercise powers derived from the people through the Constitution."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 134, $official_bank_source${"itemId":"6092a4ae-8e80-5ebb-a7d3-7ad0e8cb9480","questionId":"b8f6b133-0c07-5566-8d42-d2765d2af53c","sourceKey":"bank:PUL101:OBJ-045","payload":{"prompt":"The doctrine of separation of powers is most closely associated with which writer?","options":["A.V. Dicey","Jean Bodin","Montesquieu","Talcott Parsons"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Separation of powers, traced back to John Locke, was developed by Montesquieu in The Spirit of the Laws; it divides government into legislature, executive and judiciary to prevent concentration of power. Bodin (B) introduced sovereignty, Dicey (A) is linked with the rule of law, and Parsons (D) with the consensus model."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 135, $official_bank_source${"itemId":"92bfe4ab-403d-579b-a271-bedef9926a4a","questionId":"15c6d5cd-8489-5a1e-9bb4-e93986547daf","sourceKey":"bank:PUL101:OBJ-046","payload":{"prompt":"Bayo is arrested and charged for an act that was not an offence under any law when he did it. Which principle that limits state power protects him?","options":["The principle of legality","The doctrine of sovereignty","The doctrine of judicial precedent","The consensus model of law"],"correctOption":0,"section":"Objectives of Law, Law and Justice, and the State","explanation":"The principle of legality, nullum crimen sine lege (no crime without law), means no one can be punished for conduct that no law made an offence. It is one of the theories that curtail the power of those in authority. Sovereignty (B) concerns supreme authority, not protection from punishment."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 136, $official_bank_source${"itemId":"4d036913-db50-5a73-a764-bb09980865ae","questionId":"2815458e-459c-520a-9e0b-14c4174453ac","sourceKey":"bank:PUL101:OBJ-047","payload":{"prompt":"Police detain a trader for three weeks without charging him or bringing him before a court. Which principle has the state most clearly violated in enforcing the law?","options":["Sovereignty","Separation of powers","Distributive justice","The rule of law"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"The state holds a monopoly of legitimate force, but the rule of law requires that force be used lawfully and proportionately; an arrest needs a legal basis and the detainee must be brought before a court within a specified period. Sovereignty (A) is the state's supreme authority, not a limit on how force is used."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 137, $official_bank_source${"itemId":"39cdeae1-88f4-596d-a541-5626695506b6","questionId":"26298698-e5fd-5e8b-8004-23a2a0297f1b","sourceKey":"bank:PUL101:OBJ-048","payload":{"prompt":"The National Assembly passes a law, and the Supreme Court later declares it void for being inconsistent with the Constitution. This is an example of","options":["the extinction of the state by dissolution","the people changing their elected leaders","the executive exercising legislative power","checks and balances among the arms of government"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Separation of powers divides government into legislature, executive and judiciary, and each arm checks the others; here the judiciary reviews the legislature's action for constitutionality. The other options describe different situations entirely."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 138, $official_bank_source${"itemId":"92d5abe9-ff35-5849-b8a0-ea5b6ed763c4","questionId":"cf6b8089-0294-5e1a-9102-7c986d000915","sourceKey":"bank:PUL101:OBJ-049","payload":{"prompt":"In the modern period, legitimacy is said to rest not on mere legality but on what Farrar and Dugdale called \"impersonal rational authority\". This means","options":["the decrees of whoever holds military power","a rule of law accepted by both officials and the people","the personal charisma of a strong leader","the divine right of traditional rulers"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"In early legal systems, legitimacy rested on the charismatic qualities of leaders and traditional rulers, then on legality. Today it rests on a rule of law accepted by both officials and the people. Charisma (C) and divine right (D) belong to earlier stages, and A confuses force with legitimacy."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 139, $official_bank_source${"itemId":"27c1dd29-bcbf-5ce0-83b8-8bc53b8a081b","questionId":"42b68e87-4f54-5f0d-af83-a79df80ed622","sourceKey":"bank:PUL101:OBJ-050","payload":{"prompt":"A group of officers attempts to seize power by force, but the coup fails and they are arrested. Under Nigerian law, they are most likely to be charged with","options":["a minor public order offence attracting a fine","treason, as no one may take over government except under the Constitution","no offence, because the coup did not succeed","contempt of court, because they ignored judicial orders"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Section 1(2) of the 1999 Constitution forbids anyone from taking control of the government except in accordance with the Constitution, so an unsuccessful coup attempt is treated as treason, punishable with death. Experience shows the provision cannot stop a coup from happening or make a successful one illegal in practice."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 140, $official_bank_source${"itemId":"3f9d1024-b0f9-5949-90dd-e8e5e4fd3be0","questionId":"41825f47-378c-5957-a3a7-792877e0fcfc","sourceKey":"bank:PUL101:OBJ-051","payload":{"prompt":"Under Kelsen's pure theory of law, a law passed by the legislature and assented to by the President, following constitutional procedure, is legitimate","options":["only if it reflects the customs of the people","only after the courts have applied it in a case","because it follows from higher norms, even if many citizens consider it unjust","only if most citizens consider it morally right"],"correctOption":2,"section":"Objectives of Law, Law and Justice, and the State","explanation":"For Kelsen, legitimacy is grounded in legal validity: a norm is legitimate if it follows from higher norms up to the grundnorm, regardless of moral justification. Critics say this ignores the role of morality in public acceptance. D is a moral test, A is the historical school's test, and B is a realist idea."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 141, $official_bank_source${"itemId":"96645c45-dd0a-569b-8bc5-be284b73efc7","questionId":"8e004df3-33f6-57d3-ab77-7a3e59b674d3","sourceKey":"bank:PUL101:OBJ-052","payload":{"prompt":"Residents of a state say they trust their governor's government because it has delivered security, good roads and working hospitals. This is an example of which source of legitimacy?","options":["Constitutionalism","Performance legitimacy","Democratic consent","Charismatic legitimacy"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Performance legitimacy arises when a government provides security, welfare and prosperity, so citizens regard it as legitimate. Democratic consent (C) comes from elections and participation, and constitutionalism (A) from following constitutional procedures. Here the trust is based on results delivered."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 142, $official_bank_source${"itemId":"2bd119c5-5f8b-5df9-8004-5fdd35c4eef6","questionId":"67e3e999-b165-565f-91c6-58e9f11aec5b","sourceKey":"bank:PUL101:OBJ-053","payload":{"prompt":"The Westphalian model of the state, from the treaties of 1648, emphasises","options":["a single world government with authority over all states","sovereign equality of states and non-interference","the right of powerful states to annex weaker ones","the duty of states to adopt one common religion"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"The Westphalian model rests on territorial sovereignty, centralised authority, legal equality of states and non-intervention. Globalisation, human rights obligations and the responsibility to protect have since softened strict non-interference. The other options contradict the model."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 143, $official_bank_source${"itemId":"861d9698-cda5-54db-a84b-9287680c6b64","questionId":"99589cbc-7f64-57c4-8795-5aa7ff2c1f59","sourceKey":"bank:PUL101:OBJ-054","payload":{"prompt":"Country X is absorbed by its larger neighbour and ceases to exist as a separate state. Which mode of extinction of a state is this?","options":["Merger","Recognition","Dissolution","Annexation"],"correctOption":3,"section":"Objectives of Law, Law and Justice, and the State","explanation":"Annexation occurs when a state ceases to exist because another state absorbs it, a mode that is controversial and often unlawful. Merger (A) is when two or more states unite, and dissolution (C) is when a state breaks into successor states. Recognition (B) is not a mode of extinction at all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 144, $official_bank_source${"itemId":"5985ebe9-5c60-5a85-9aaf-0cc53d3bc180","questionId":"4652b3a2-2b40-5753-8283-4c1f39aa736d","sourceKey":"bank:PUL101:OBJ-055","payload":{"prompt":"The State is said to hold a \"monopoly of legitimate use of force\". This means that","options":["any citizen may use force to enforce his own rights","the State alone may ordinarily use or authorise coercion, channelled through law","the State may use force without any legal limits","only international bodies may authorise the use of force"],"correctOption":1,"section":"Objectives of Law, Law and Justice, and the State","explanation":"The State, through the police and military, ordinarily has the exclusive right to use or authorise coercion, and law channels that force through arrest powers, courts and due process. A describes self-help, and C is wrong because the rule of law limits how force may be used."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 145, $official_bank_source${"itemId":"b98d1880-6948-512a-bff6-aae6d25b5941","questionId":"e413f39e-c0a2-579f-802a-2d44b294b5b8","sourceKey":"bank:PUL101:ASP-001","payload":{"prompt":"The aspect of law that governs the relationship between the state and its citizens, in which the state is 'higher' in legal status than the other party, is called","options":["municipal law","public law","procedural law","private law"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"Public law covers relationships where the state, as the superior party, deals with citizens, as in constitutional, administrative and criminal law. Option D concerns relations between private individuals. Option C is about how cases are conducted in court, and option A simply means the internal law of a country, which includes both public and private law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 146, $official_bank_source${"itemId":"01b39e3c-edda-5f17-872e-17f05ffc6437","questionId":"1c7b6b27-4423-54f8-a979-bde05e35bc59","sourceKey":"bank:PUL101:ASP-002","payload":{"prompt":"Which of the following best describes private law?","options":["Law concerned with the protection of the state and its organs","Law laying down the steps for commencing and conducting cases in court","Law concerned with relationships between individuals and the protection of individual rights","Law governing relationships between independent states and international organisations"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Private law deals with dealings between private persons, such as contract, torts, trusts and succession. Option A describes public law, option D describes international law, and option B describes procedural (adjectival) law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 147, $official_bank_source${"itemId":"da7bffd1-8e42-5809-8e94-861c7ada5465","questionId":"c0b8841d-f727-5f45-bbf0-1aee8ccf0289","sourceKey":"bank:PUL101:ASP-003","payload":{"prompt":"Which of the following is NOT an example of public law?","options":["Administrative law","Criminal law","Constitutional law","Law of contract"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"The law of contract governs agreements between private persons, so it is private law. Constitutional law (option C), administrative law (option A) and criminal law (option B) all involve the state acting in its public capacity, which makes them classic examples of public law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 148, $official_bank_source${"itemId":"ef443280-8cb7-5090-ac49-1cff8435fb7d","questionId":"3f65a314-c776-5a9a-b3c8-3f458dca54ae","sourceKey":"bank:PUL101:ASP-004","payload":{"prompt":"Bola lent Emeka N250,000 under a written agreement. Emeka refuses to repay, and Bola sues him in the High Court to recover the money. Which pair of classifications best fits Bola's claim?","options":["Public law and civil law","Private law and civil law","Public law and criminal law","Private law and criminal law"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"A claim by one private person against another to recover money under a contract is both private law (relations between individuals) and civil law (redress for a breached right). Options C and D wrongly call it criminal, since nobody is being prosecuted or punished. Option A wrongly calls it public law, since the state is not a party."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 149, $official_bank_source${"itemId":"9ad41559-ce52-5394-99f1-7097dc7b0ec3","questionId":"04159fce-8834-59b8-bd70-58d9eb42e9e3","sourceKey":"bank:PUL101:ASP-005","payload":{"prompt":"How does the Nigerian legal system treat the public law/private law divide compared with a country like France?","options":["Nigeria has no separate body of rules and courts for state matters, but special procedures apply in some public-duty cases","Nigeria, like France, has a separate system of courts for all cases involving the government","Nigeria applies different substantive rules to the government in every case it is a party to","Nigeria has abolished any distinction between public and private law in all respects"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Unlike France, Nigeria has not developed separate rules and courts for matters affecting the state; litigation between the state and citizens follows the same rules as private litigation. The distinction that has emerged is procedural, for example in fundamental rights enforcement and judicial review. Options B and C describe the French-style system, and option D ignores the special procedures that now exist."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 150, $official_bank_source${"itemId":"b20c4f04-6903-5134-a035-568be8f49243","questionId":"049292bb-1ff3-554e-be11-d4dd4a6c0867","sourceKey":"bank:PUL101:ASP-006","payload":{"prompt":"Kemi wants to challenge a decision of a state agency by an application for judicial review, but her lawyer files it as an ordinary civil claim without following the special procedure for that kind of application. What is the likely consequence?","options":["The case may be struck out for failure to follow the special procedure","The court must hear it because public and private law cases follow identical procedures","The case will be transferred automatically to a separate administrative court","The case becomes a criminal prosecution because a state agency is involved"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Where the aim is to enforce a public duty, such as in judicial review or fundamental rights enforcement, Nigerian law requires special procedures, and a case that ignores them may be struck out. Option C is wrong because Nigeria has no separate administrative courts. Option B ignores the procedural distinction that has emerged. Option D confuses public law with criminal law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 151, $official_bank_source${"itemId":"975202b6-d372-52b6-be38-6813c709d37e","questionId":"28a4f2d8-2a3c-503d-a592-9e6c2af8bbc6","sourceKey":"bank:PUL101:ASP-007","payload":{"prompt":"The branch of law that defines the rights and duties of persons to one another and gives an injured person a way to be compensated for the wrongful act of another is","options":["adjectival law","criminal law","public international law","civil law"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"In this context civil law is the body of rules on rights and duties between persons, with compensation for the injured party as its aim. Option B aims at punishment for conduct harmful to society. Option C governs relations between states, and option A is the procedural law used to enforce rights rather than the rights themselves."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 152, $official_bank_source${"itemId":"de0531cf-30b5-54e8-bc4f-de7a9a0f4e61","questionId":"20b8fd8e-7214-5897-98e1-005b06c7e46a","sourceKey":"bank:PUL101:ASP-008","payload":{"prompt":"Which statement best describes criminal law?","options":["It enables an injured person to recover compensation from the wrongdoer","It sets out the steps for initiating actions and giving evidence in court","It regulates relations between Nigeria and other sovereign states","It protects the public at large by punishing conduct considered harmful to society"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"Criminal law protects society as a whole by punishing harmful conduct, usually by imprisonment, fine or both. Option A describes civil law, whose aim is compensation. Option B describes procedural law, and option C describes international law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 153, $official_bank_source${"itemId":"2191b8ac-1d33-56ed-a6f2-ff878047bcfc","questionId":"9a700401-2890-5943-9a1b-34043fe0b247","sourceKey":"bank:PUL101:ASP-009","payload":{"prompt":"In a criminal trial in Nigeria, the prosecution must prove its case","options":["beyond reasonable doubt, as provided in section 135 of the Evidence Act 2011","beyond reasonable doubt, as provided in section 134 of the Evidence Act 2011","on the balance of probabilities, as provided in section 134 of the Evidence Act 2011","on the balance of probabilities, as provided in section 135 of the Evidence Act 2011"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Section 135 of the Evidence Act 2011 requires proof beyond reasonable doubt in criminal cases. Option C states the civil standard found in section 134. Options B and D mix up the two sections."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 154, $official_bank_source${"itemId":"43436063-9a7f-5b6d-a988-26991437db75","questionId":"6aa7bf74-5adb-5b2d-84a5-05dfad50d754","sourceKey":"bank:PUL101:ASP-010","payload":{"prompt":"The standard of proof under which judgment goes to the party who proves its case more convincingly than the other is","options":["proof on the balance of probabilities","proof beyond all doubt","proof beyond reasonable doubt","prima facie proof"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Civil cases are decided on the balance of probabilities, so judgment goes to whichever side has proved its case more successfully. Option C is the higher criminal standard. Option B is not a legal standard at all, and option D only means enough evidence to call for an answer."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 155, $official_bank_source${"itemId":"a74cdb5e-b75f-5140-9478-f0d6987d7537","questionId":"6bca0225-99fe-5c01-8a8c-91fbc79abd69","sourceKey":"bank:PUL101:ASP-011","payload":{"prompt":"Why does the law demand a higher standard of proof in criminal cases than in civil cases?","options":["To reduce the number of criminal cases that reach the courts","Because criminal cases are always tried in the High Court","To protect the accused from the power of the state and the danger of wrongful conviction","Because the victim of a crime is always entitled to compensation"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"The higher standard protects an accused person from the state's great power and from wrongful conviction, with its loss of liberty and livelihood; this is the presumption of innocence. Option B is false because minor offences are tried summarily in Magistrate Courts. Options D and A give reasons that have nothing to do with the standard of proof."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 156, $official_bank_source${"itemId":"0ec7edfc-d711-50e6-b02f-f21c535c5526","questionId":"3d4aea83-6581-5160-8960-caf54a952fae","sourceKey":"bank:PUL101:ASP-012","payload":{"prompt":"Which statement correctly contrasts the burden of proof in criminal and civil cases?","options":["In criminal cases it shifts to the accused once charged; in civil cases it stays on the plaintiff","In both kinds of case it stays permanently on the defendant","In both kinds of case it shifts freely between the parties","In criminal cases it stays on the prosecution; in civil cases it may shift between the parties"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"In a criminal trial the burden of proof does not shift from the prosecution, while in civil cases it moves between the parties as each tries to establish its case. Option A reverses the position and would undermine the presumption of innocence. Options B and C ignore the difference between the two kinds of case."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 157, $official_bank_source${"itemId":"0a629c36-48b9-5897-976c-aa018c03e08a","questionId":"e35fe0be-5fde-5150-8994-a544f08f4297","sourceKey":"bank:PUL101:ASP-013","payload":{"prompt":"Tunde takes Ngozi's bicycle without her permission and sells it. Which statement best describes Tunde's legal position?","options":["He may be prosecuted for stealing and also sued by Ngozi in the tort of conversion","He may only be sued for conversion, since the bicycle was private property","He may only be prosecuted, since stealing is a crime and cannot also be a civil wrong","He can be neither prosecuted nor sued until Ngozi gets a customary court order"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"The same conduct can be both a crime and a civil wrong: taking B's bicycle is the offence of stealing and also the tort of conversion. Options C and B wrongly assume the two kinds of liability cannot exist together. Option D invents a requirement that does not exist."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 158, $official_bank_source${"itemId":"0a0d4e7e-45b4-5e4a-b0a4-34486250c46a","questionId":"605bedaf-afc4-5b04-b0e2-fbd1a6933d25","sourceKey":"bank:PUL101:ASP-014","payload":{"prompt":"Which of the following is NOT given as an example of a wrong that is both a crime and a tort?","options":["Defamation","Assault","Breach of contract","False imprisonment"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Breach of contract is a purely civil wrong remedied by damages or similar relief; it is not a crime. Assault (option B), false imprisonment (option D) and defamation (option A) are the standard examples of conduct that is both a crime and a tort, which shows how the line between civil and criminal law overlaps."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 159, $official_bank_source${"itemId":"38fae371-e938-531a-8fef-e24de020dc18","questionId":"2e4be51d-d420-53e8-8aca-dcf7cc41ae16","sourceKey":"bank:PUL101:ASP-015","payload":{"prompt":"Chidi's shop in Yaba is burgled, and the suspect is charged to court for burglary. In such a criminal case, who prosecutes?","options":["Chidi's insurer","The State, on behalf of society","The Yaba community leaders","Chidi, as the person who suffered the loss"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"In criminal law the State prosecutes on behalf of society, because the conduct is treated as harmful to the public at large. Option D describes the claimant in a civil action, not a criminal prosecution. Options A and C have no role as prosecutors."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 160, $official_bank_source${"itemId":"df7a9907-fabd-5bdd-b076-76a5145d1554","questionId":"87349826-2a09-5c01-b2d2-4af7f62555ec","sourceKey":"bank:PUL101:ASP-016","payload":{"prompt":"In Nigeria, criminal law has been codified mainly in","options":["a single Criminal Code applicable uniformly in every state","the Criminal Code for the Southern States and the Penal Code for the Northern States","the Penal Code for the Southern States and the Criminal Code for the Northern States","the Evidence Act and the Sheriffs and Civil Process Act"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"The Criminal Code applies in the Southern States and the Penal Code in the Northern States. Option C reverses the two. Option A ignores the North/South split, and option D names procedural statutes that do not define offences."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 161, $official_bank_source${"itemId":"7be9274c-487d-5978-8453-1d7c5801ded6","questionId":"48fad9db-e4b5-5ea9-8b76-4f48a93d1fe5","sourceKey":"bank:PUL101:ASP-017","payload":{"prompt":"Ada is charged with a minor traffic offence, while Femi is charged with armed robbery. Which statement best reflects how such offences are normally tried?","options":["Both offences must be tried in the High Court because both are crimes","Both offences are civil wrongs and go to a customary court","Ada's offence is tried summarily in a Magistrate Court; Femi's serious offence is normally tried in the High Court","Ada's offence is tried in the High Court; Femi's offence goes to a Magistrate Court"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Serious crimes such as robbery, murder and rape are normally tried in the High Court, while lesser offences such as minor traffic offences are tried summarily in the Magistrate Court. Option A ignores this split, option D reverses it, and option B wrongly treats crimes as civil wrongs."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 162, $official_bank_source${"itemId":"fbe5b238-3037-529b-8318-1e2654b528cb","questionId":"f793c6d3-d1d7-538f-821c-b0399363d23e","sourceKey":"bank:PUL101:ASP-018","payload":{"prompt":"To members of the armed forces, the word 'civil' generally means","options":["law that is enacted by the legislature as opposed to case law","the law of a state as opposed to international law","everything that is not peculiar to the military, as in a civil court contrasted with a court martial","only the law of contract and torts"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"The word 'civil' has several meanings; in the military context it means whatever is not peculiar to the armed forces, so a civil court is contrasted with a court martial. Option B states a different meaning (domestic as against international law). Options D and A are not meanings of the word given in this sense."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 163, $official_bank_source${"itemId":"58fe28ea-688d-5bd0-a46a-f0534065f32e","questionId":"68f06c76-64a8-5aef-ae69-a754c92be2fa","sourceKey":"bank:PUL101:ASP-019","payload":{"prompt":"The body of legal rules that states rights, duties and liabilities, defines a code of conduct and prescribes a penalty for its breach is","options":["substantive law","unwritten law","adjectival law","procedural law"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Substantive law is the law itself: the rules stating what people may or may not do and what follows from a breach, as in contract, torts and criminal law. Options D and C are two names for the same thing: the rules on how substantive law is enforced in court. Option B is a different classification, about whether a rule was enacted."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 164, $official_bank_source${"itemId":"e5d16afc-5312-5b0d-9b25-845ff510a1fb","questionId":"38964230-0e71-5cb3-a440-d24381aadf49","sourceKey":"bank:PUL101:ASP-020","payload":{"prompt":"Procedural or adjectival law is best described as the law that","options":["determines whether a contract exists and what its terms are","deals with the methods of proceedings by which substantive rights and duties are enforced in court","governs the relationship between the state and its citizens","defines offences and prescribes their punishment"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"Procedural law covers how a case is started, how evidence is given, how witnesses are examined, how judgment is delivered and how it is enforced. Options D and A describe the content of substantive criminal and contract law. Option C describes public law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 165, $official_bank_source${"itemId":"c6dcc73e-2132-5927-baa4-5be344bc3241","questionId":"3b37c5b1-79a5-50c5-83cf-c50a345b9a61","sourceKey":"bank:PUL101:ASP-021","payload":{"prompt":"Which of the following Nigerian enactments is procedural law in relation to the Criminal Code and the Penal Code?","options":["Criminal Code Act","Land Use Act","Administration of Criminal Justice Act 2015","Companies and Allied Matters Act"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"The Administration of Criminal Justice Act 2015 lays down how criminal cases are conducted, so it is procedural law in relation to the Criminal and Penal Codes. Option D and option B are substantive statutes on companies and land. Option A is itself the substantive criminal law that the procedure serves."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 166, $official_bank_source${"itemId":"7ad1d89a-7bd1-5b84-8db8-0e4ea7c1d1ce","questionId":"4062dc62-62fe-516f-bd9b-38d499498985","sourceKey":"bank:PUL101:ASP-022","payload":{"prompt":"Section 419 of the Criminal Code, which defines the offence of obtaining goods by false pretences and prescribes imprisonment for it, is an example of","options":["procedural law","unwritten law","conflict of laws","substantive law"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"A provision that defines an offence and fixes its punishment is substantive law. Option A would cover rules on how the trial is conducted, not what the offence is. Option C deals with cases that have foreign elements, and option B is wrong because the Criminal Code is an enactment."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 167, $official_bank_source${"itemId":"9feba09c-7245-5475-a06b-e7d358855930","questionId":"23e40279-278a-5347-baee-f370472fb8eb","sourceKey":"bank:PUL101:ASP-023","payload":{"prompt":"Before filing a claim for breach of contract, Barrister Okafor studies the High Court of Lagos State (Civil Procedure) Rules to find out how to begin the action and serve the defendant. Which kind of law is he consulting?","options":["International law","Substantive law","Procedural law","Divine law"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Rules of court that state how an action is begun and how processes are served are procedural (adjectival) law. Option B would be the law of contract itself, which decides whether there was a breach and what remedies are available. Options A and D have nothing to do with how a Lagos court action is conducted."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 168, $official_bank_source${"itemId":"4c09522c-8b76-5a5f-9d0a-2289b5156b1b","questionId":"96770c77-6491-5d24-8609-6f90e4c39adc","sourceKey":"bank:PUL101:ASP-024","payload":{"prompt":"Which of the following is NOT a matter dealt with by procedural law?","options":["The enforcement of the judgment of the court","The way in which an action is to be initiated in court","The examination of witnesses at trial","Whether particular conduct amounts to an offence"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"Whether conduct is an offence is decided by substantive law, such as the Criminal Code or Penal Code. Starting an action (option B), examining witnesses (option C) and enforcing judgment (option A) are all listed as matters governed by procedural law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 169, $official_bank_source${"itemId":"ad8d78ce-fb64-5cb3-9f00-b348c7b49a27","questionId":"bebe933f-b473-5a2c-be5f-f376cb34e958","sourceKey":"bank:PUL101:ASP-025","payload":{"prompt":"The law that denotes the internal law of a particular country, regulating relations between individuals and between individuals and the State, is called","options":["eternal law","international law","conflict of laws","municipal law"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"Municipal law, also called national, domestic or local law, is a country's internal law. Option B governs relations between states. Option C deals with domestic cases that have foreign elements, and option A is a philosophical idea of unchanging universal law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 170, $official_bank_source${"itemId":"5ef7c552-9899-5458-8f0f-cded46c7784d","questionId":"8bbd981f-0e02-5fef-b935-619d569904f4","sourceKey":"bank:PUL101:ASP-026","payload":{"prompt":"International law is best defined as the law that governs","options":["the procedure of courts in hearing cases involving foreigners","relations between States inter se or between States and international organisations","relations between a state government and its local governments","relations between individuals within a particular country"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"International law regulates relations between States themselves and between States and international organisations. Option D describes municipal private law. Option C is a domestic constitutional matter, and option A confuses international law with procedural law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 171, $official_bank_source${"itemId":"a2abd07b-2250-53d3-88e2-0309b58f2445","questionId":"40c9c3e0-6e4c-53c0-8cee-ffa4daaed931","sourceKey":"bank:PUL101:ASP-027","payload":{"prompt":"Which of the following is NOT one of the recognised sources of international law?","options":["Treaties","International custom","Bye-laws made by a Nigerian local government council","General principles of law recognised by civilised nations"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Bye-laws of a local government are domestic law with no international effect. Treaties (option A), international custom (option B) and general principles of law recognised by civilised nations (option D) are listed, together with judicial decisions and the teachings of highly qualified publicists, as the bases of international law."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 172, $official_bank_source${"itemId":"4afa5a3e-eba1-5990-aaff-e1e6171e026d","questionId":"c8e2227a-24e2-515a-b330-32d4d124f05b","sourceKey":"bank:PUL101:ASP-028","payload":{"prompt":"Nigeria has signed and ratified an international treaty on workers' rights, but the National Assembly has not enacted it into law. A worker relies on the treaty alone in a Nigerian court. What is the treaty's status?","options":["It applies only if a state House of Assembly adopts it","It automatically binds Nigerian courts once it is ratified","It overrides the Constitution because it is international law","It does not have the force of law in Nigeria until enacted by the National Assembly"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"Under section 12(1) of the 1999 Constitution, a treaty has the force of law in Nigeria only to the extent that the National Assembly has enacted it into law. Option B ignores this domestication requirement. Option C is wrong because the Constitution is supreme, and option A names the wrong legislature."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 173, $official_bank_source${"itemId":"3e0e8a37-7887-540e-908b-4ca3632e4506","questionId":"54697323-b251-5fcf-8154-d99cca78fec8","sourceKey":"bank:PUL101:ASP-029","payload":{"prompt":"Two Nigerians make a contract in England to sell goods situated in London. A dispute about the contract's validity comes before a Nigerian court, which applies English law. Which branch of law deals with this kind of question?","options":["Criminal law","Private international law (conflict of laws)","Constitutional law","Public international law"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"Private international law, or conflict of laws, deals with cases inside a legal system in which foreign elements arise, raising questions about which country's law or courts apply. Option D is a separate system governing relations between States. Options A and C do not deal with choosing which country's law governs a contract."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 174, $official_bank_source${"itemId":"7e93a894-f458-5d1e-a212-2e260283cf62","questionId":"4e0e327e-6f32-5289-b128-b177da9abb02","sourceKey":"bank:PUL101:ASP-030","payload":{"prompt":"Which statement correctly distinguishes private international law from public international law?","options":["Private international law handles foreign elements in domestic cases; public international law is a separate system altogether","Private international law is unwritten while public international law is always written","Both are parts of the same domestic legal order and differ only in name","Private international law governs relations between States; public international law governs relations between individuals"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Private international law works inside a particular legal system, dealing with cases that involve foreign elements. Public international law is not an attachment to any domestic legal order but a separate system altogether. Option D reverses the roles. Option C ignores the separateness of public international law, and option B states a false contrast."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 175, $official_bank_source${"itemId":"2ed13f23-b5e2-56d5-a3e2-60fac071e301","questionId":"803c42fe-8be5-5b6a-90bd-f1121fd28fdc","sourceKey":"bank:PUL101:ASP-031","payload":{"prompt":"Which of the following is an example of international law?","options":["The Criminal Code Act","The Companies and Allied Matters Act","The Constitution of the Federal Republic of Nigeria 1999","The African Charter on Human and Peoples' Rights"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"The African Charter is an agreement between states, so it is international law. The 1999 Constitution (option C) applies only in Nigeria, which makes it municipal law, and so do CAMA (option B) and the Criminal Code (option A)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 176, $official_bank_source${"itemId":"9c1fb5a3-7869-5d2a-8a8b-de86c0d31e5b","questionId":"fc8c8fa3-12ed-5ae2-b3d3-f4e653805c55","sourceKey":"bank:PUL101:ASP-032","payload":{"prompt":"In the classification of law, the word 'written' has a technical meaning. A written law is","options":["a rule formally enacted into a statute by the legislature","any rule recorded in the law reports by a judge","any customary rule recorded by a chief's secretary","any rule that appears in a document or book"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"'Written' here means formally enacted by the legislature, usually after debate and passage through several stages. Option D is the trap: being in a document is not enough. Options B and C describe rules that are written down but not enacted, and these count as unwritten law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 177, $official_bank_source${"itemId":"38b7b834-67c6-52de-9f03-5079d9a43dde","questionId":"558e315d-900b-591a-a5cd-3acbe7b3757f","sourceKey":"bank:PUL101:ASP-033","payload":{"prompt":"Written laws go by different names in different jurisdictions and at different times. Which of the following is NOT one of those names?","options":["Judicial precedents","Decrees","Edicts","Ordinances"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Judicial precedents are decisions of the courts, which count as unwritten law because they are not enacted. Edicts (option C), Decrees (option B) and Ordinances (option D) are among the names for enacted written law, together with Codes, Statutes, Acts, Laws and Rules."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 178, $official_bank_source${"itemId":"ad95e240-4643-54d1-a350-94750b298a86","questionId":"705223bc-7abe-514b-9b1e-9c083909adf4","sourceKey":"bank:PUL101:ASP-034","payload":{"prompt":"The term 'unwritten law' covers","options":["rules not written down at all, such as customary law and conventions, and unenacted rules even if written, such as case law","statutes that have been repealed by the legislature","only case law reported in the law reports","only rules that have never been written down anywhere"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"'Unwritten law' has two meanings: rules not written down at all, such as customary law and conventions, and rules that are written down but never enacted, such as case law. Options D and C each give only half of the meaning, and option B has nothing to do with the classification."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 179, $official_bank_source${"itemId":"ac436f30-20fb-52ad-8dbe-7def2df70189","questionId":"b7b6fb1f-5689-5997-bcf8-8cbe493fc18a","sourceKey":"bank:PUL101:ASP-035","payload":{"prompt":"A Nigerian court applies the neighbour principle from Donoghue v Stevenson, which is printed in the law reports but is not found in any statute. How is this principle classified?","options":["Unwritten law, because it was not enacted by a legislature","International law, because it came from a foreign court","Written law, because it appears in printed law reports","Written law, because Nigerian courts apply it"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Case law is unwritten law in the technical sense even though it is recorded in documents, because the legislature did not enact it. Option C relies on the everyday meaning of 'written'. Option D confuses being applied with being enacted, and option B confuses a foreign judicial decision with law between States."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 180, $official_bank_source${"itemId":"342f56cc-a2d3-5c8f-aa8c-3bc3585faf6c","questionId":"c45a2312-4b2c-5efc-8960-5c81b32cb65d","sourceKey":"bank:PUL101:ASP-036","payload":{"prompt":"Which of the following is a well-known example of an unwritten constitution?","options":["The Charter of the United Nations","The 1963 Republican Constitution of Nigeria","The 1999 Constitution of Nigeria","The British Constitution"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"The British Constitution is the classic example of unwritten law at constitutional level, because it is not contained in a single enacted document. The Nigerian constitutions (options C and B) were formally enacted, and option A is a treaty, not an unwritten constitution."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 181, $official_bank_source${"itemId":"0bdd1a98-0a16-53d8-896c-900b7d9c5ed2","questionId":"043966cd-babe-5069-8aaf-ec1d201f180a","sourceKey":"bank:PUL101:ASP-037","payload":{"prompt":"A woman in a village is convicted of adultery under an unwritten local custom, although no written law defines adultery as an offence or prescribes a penalty for it. Which principle makes the conviction unlawful?","options":["Unwritten law can never be applied by any Nigerian court","Customary courts have no power to try anyone","A person cannot be convicted of an offence unless it is defined and its penalty prescribed in a written law","Adultery can only be tried by a court martial"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Section 36(12) of the 1999 Constitution bars conviction for an offence not defined, with its penalty, in a written law; in Aoko v Fagbemi a conviction for adultery was set aside on this basis. Option B overstates things, since customary courts exist and apply customary law. Option D is irrelevant, and option A is wrong because unwritten customary and case law are applied in civil matters."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 182, $official_bank_source${"itemId":"47923d2f-dca6-54a9-a8d1-6337378948c5","questionId":"39aa7ab0-6ddb-5f45-8747-3d8f0dd5f0be","sourceKey":"bank:PUL101:ASP-038","payload":{"prompt":"As a division of law, 'common law' means","options":["the customary law common to all ethnic groups in Nigeria","the law developed by the Lord Chancellor in the Court of Chancery","statutes enacted by the English Parliament","the law developed by the old common law courts of England: the King's Bench, the Court of Common Pleas and the Court of Exchequer"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"As a division of law, common law means the judge-made law of England's old common law courts: the King's Bench, the Common Pleas and the Exchequer. Option B describes equity. Option A misreads the word 'common', and option C describes legislation rather than judge-made law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 183, $official_bank_source${"itemId":"112ff6ea-3813-5e6a-ac6a-a5f170be1cf9","questionId":"c99a671d-3c44-512d-9247-7400e4dd0ae7","sourceKey":"bank:PUL101:ASP-039","payload":{"prompt":"Which of the following was NOT one of the old common law courts of England?","options":["Court of Exchequer","Court of King's Bench","Court of Chancery","Court of Common Pleas"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"The Court of Chancery was the Lord Chancellor's court, which administered equity and stood apart from the common law courts. The King's Bench (option B), Common Pleas (option D) and Exchequer (option A) were the three old common law courts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 184, $official_bank_source${"itemId":"6cec3af6-d171-59ee-ab70-528601a56d7f","questionId":"675780cf-d7a3-513b-a5f3-77d250b8450d","sourceKey":"bank:PUL101:ASP-040","payload":{"prompt":"How did the English common law first emerge after the Norman Conquest of 1066?","options":["The Church courts adopted the Ten Commandments as the law of England","Royal judges on circuit compared local customs and kept the more sensible ones, producing uniform rules for the whole realm","Parliament enacted a single code to replace all local customs","The Lord Chancellor issued decrees based on conscience and natural law"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"The King's judges first applied local customs, then compared them at Westminster and preferred the more logical ones, until uniform rules emerged as 'the common law of the realm'. This makes common law judge-made law. Option C describes legislation, option D describes the later rise of equity, and option A confuses divine law with common law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 185, $official_bank_source${"itemId":"176a799c-8e6a-51a2-a173-cd2bc71fa714","questionId":"c23df7a7-d266-5626-919c-bfc63bed7d1f","sourceKey":"bank:PUL101:ASP-041","payload":{"prompt":"Which of the following was a major defect of the early common law that led to the rise of equity?","options":["It was enacted by Parliament and could not be changed by judges","A plaintiff had no remedy unless his claim fell within an existing writ, and the main remedy was damages","It granted injunctions too readily","It allowed judges to decide every case purely on conscience"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"The common law was strict, formal and legalistic: with no fitting writ there was no remedy, and even a successful plaintiff usually got only damages. Option D describes the approach of equity, not its cause. Option A wrongly treats common law as statute, and option C is wrong because injunctions were an equitable remedy."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 186, $official_bank_source${"itemId":"e96821d7-0c0a-56e5-a23c-1fe1d4b7b79a","questionId":"e2b640a0-237b-530e-9cfa-de21738293ac","sourceKey":"bank:PUL101:ASP-042","payload":{"prompt":"Plaintiffs who failed to get redress at common law began petitioning the King. The official who dealt with these petitions, and whose court became the Court of Chancery, was","options":["the Archbishop of Canterbury","the Attorney General","the Lord Chancellor","the Chief Justice of the King's Bench"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"The Chancellor, as the King's chief minister, handled the petitions and in time decided them in his own court, which became the Court of Chancery. Option D was the head of a common law court. Option B was the office Bacon held when the dispute was referred to him, and option A had no such role."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 187, $official_bank_source${"itemId":"36d57013-4a05-5ca8-bb58-fc53588adb00","questionId":"35bbd84e-b846-5d82-8f33-06af73905af8","sourceKey":"bank:PUL101:ASP-043","payload":{"prompt":"In the Earl of Oxford's case (1615), what did the Chancellor, Lord Ellesmere, do after the common law court gave judgment for the landowner?","options":["He granted an injunction restraining the landowner from ejecting the plaintiff from the house he had built","He confirmed the common law judgment and dismissed the petition","He referred the case to Parliament for legislation","He awarded the plaintiff damages for wrongful ejection"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Relying on equity and good conscience, Lord Ellesmere granted an injunction stopping the owner from ejecting the plaintiff, who had built the house. This led Coke CJ to protest that the Chancellor was frustrating the common law. Option D is wrong because the Chancery could not award damages. Options B and C did not happen."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 188, $official_bank_source${"itemId":"08164f99-ee94-5b92-93a8-03d896ef2280","questionId":"b9ae9133-f064-5722-b64b-7e2175d38fd9","sourceKey":"bank:PUL101:ASP-044","payload":{"prompt":"How was the conflict between the common law courts and the Court of Chancery resolved after the Earl of Oxford's case?","options":["Coke CJ ruled that common law always prevails over equity","It was referred to Lord Bacon and resolved in favour of Chancery: where common law and equity clash directly, equity prevails","The two courts agreed that each would ignore the other's decisions","The Court of Chancery was abolished immediately"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"The dispute was referred to Lord Bacon, who resolved it in favour of Chancery: where common law and equity directly conflict, the rules of equity prevail. Option A reverses the outcome. Option D is wrong because the two courts continued separately until the Judicature Acts, and option C did not happen."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 189, $official_bank_source${"itemId":"03f0270c-0895-5942-a830-489f721ae979","questionId":"3682bc1e-ed28-5c66-9ee8-04ee6e629091","sourceKey":"bank:PUL101:ASP-045","payload":{"prompt":"What was the effect of the Judicature Acts, which came into operation in 1875, on common law and equity?","options":["They made equity subordinate to the common law in every case","They fused the administration of the two systems in the same courts but did not abolish the distinction between legal and equitable rights","They abolished equity entirely and kept only the common law","They merged common law and equity into one identical set of rules"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"The Acts fused the administration of common law and equity so that one court applies both, but legal and equitable rights remain distinct; hence 'the two streams now flow into one, their waters do not mix'. Options C and D wrongly say one system disappeared or that the rules became identical. Option A reverses the rule that equity prevails in a conflict."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 190, $official_bank_source${"itemId":"a519aa95-a41d-591f-a283-1d23550db488","questionId":"d5e7d364-54f3-5817-91be-265fdc85bb72","sourceKey":"bank:PUL101:ASP-046","payload":{"prompt":"Before fusion, the common law courts could not grant certain remedies that were available only in the Court of Chancery. Which of the following was NOT such an equitable remedy?","options":["Injunction","Damages","Specific performance","Rescission"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"Damages were the common law remedy, and the Court of Chancery could not award them. Injunction (option A), specific performance (option C) and rescission (option D) were equitable remedies that the common law courts had no power to grant, which forced litigants to sue in both courts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 191, $official_bank_source${"itemId":"a59e634f-1ab5-5cdc-b800-99df9c70812a","questionId":"a0ab5495-dd92-5916-be7d-f180f7e1f41f","sourceKey":"bank:PUL101:ASP-047","payload":{"prompt":"Uche signs a written agreement transferring his car to Lola for N500,000. Uche later shows that he agreed only because Lola made a misrepresentation about the deal. On what basis may the contract be rescinded?","options":["Criminal law, because every misrepresentation is a crime","The doctrine of equity, which can set aside a contract induced by fraud, mistake or misrepresentation","International law, because the contract involves a sale of goods","The strict common law, which enforces every signed agreement as written"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"A signed agreement creates a legal right enforceable at law, but where fraud, mistake or misrepresentation induced it, equity may rescind it. This is equity softening the strictness of common law. Option D states the common law position that equity corrects. Options A and C apply the wrong branches of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 192, $official_bank_source${"itemId":"4b4b7c41-db46-51e5-a83f-7e4ff85fcfdd","questionId":"06798620-5393-5de7-a5f7-7bda98437eb4","sourceKey":"bank:PUL101:ASP-048","payload":{"prompt":"Before 1875, an English litigant wanted to establish a common law right and also needed an injunction to protect it. What did he usually have to do?","options":["Sue only in Chancery, which could award both damages and injunctions","Petition Parliament directly for an injunction","Sue only in the King's Bench, which could grant injunctions","Sue first in a common law court to establish the right, then in Chancery for the injunction"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"Because the systems were run in separate courts, a litigant often had to establish a legal right in a common law court and then go to Chancery for an equitable remedy, at great cost and inconvenience. Option A is wrong because Chancery could not award damages. Option C is wrong because common law courts could not grant injunctions, and option B was not the route."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 193, $official_bank_source${"itemId":"4f9868cf-7c93-5211-9bf4-dbedeecd3bf3","questionId":"18308248-c8e2-56f5-924d-c5c6fde35b07","sourceKey":"bank:PUL101:ASP-049","payload":{"prompt":"Which statement best illustrates that there is no watertight classification of law?","options":["Much Nigerian land law has become public law since the Land Use Act, and tax law is as much private as public law","Public law and private law are tried in completely separate court systems in Nigeria","Criminal law and civil law never overlap","Every rule of law belongs to exactly one classification"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"The classifications overlap: land law has become largely public law under the Land Use Act, taxation straddles public and private law, and assault is both a crime and a tort. Option B is false for Nigeria. Options D and C contradict the overlap that the classifications actually show."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 194, $official_bank_source${"itemId":"d21941a1-fbeb-50f6-8a3b-60e93e519615","questionId":"60406248-3ffd-56bd-b5cc-01bdde654fec","sourceKey":"bank:PUL101:ASP-050","payload":{"prompt":"Aisha loses her job after an accident at work leaves her unable to perform her duties, and she asks a solicitor to sue her employer. Which approach best reflects how classifications of law work in practice?","options":["The case belongs only to criminal law, because an accident occurred","The solicitor may rely only on the law of contract, because subjects cannot be combined","The solicitor must combine contract law, labour law and the law of tort to build her claim","The solicitor must first decide whether the case is divine or natural law"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Classifications overlap in real life, and a practitioner must combine subjects: here contract, industrial or labour law, and tort. Option B wrongly treats the subjects as sealed off from each other. Options D and A apply categories that do not fit an employment claim."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 195, $official_bank_source${"itemId":"59bafbd4-10c6-5142-a8cc-b60d31cf6e8f","questionId":"80c5e7d3-79d6-5829-91bb-97738a9cac32","sourceKey":"bank:PUL101:ASP-051","payload":{"prompt":"Classified by origin, law has been described as eternal, divine, natural or human (positive) law. Which of the following is NOT one of these types?","options":["Divine law","Eternal law","Natural law","Procedural law"],"correctOption":3,"section":"Aspects and Classifications of Law","explanation":"Procedural law belongs to the classification of law by function (substantive versus procedural), not to the types of law by origin. Eternal law (option B), divine law (option A) and natural law (option C), together with human or positive law, are the four types listed."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 196, $official_bank_source${"itemId":"dccf3ead-a0de-5b14-9e5b-debfe5c9f343","questionId":"f9b85782-5839-5962-bb08-21e7fc279211","sourceKey":"bank:PUL101:ASP-052","payload":{"prompt":"Which of the following is given as a perfect example of divine law?","options":["The Ten Commandments in the Holy Bible","The Criminal Code Act","The Universal Declaration of Human Rights","The Judicature Act 1875"],"correctOption":0,"section":"Aspects and Classifications of Law","explanation":"Divine law means the law of God or law from God, and the Ten Commandments are the standard example. Options B and D are laws made by human legislatures, and option C is an international instrument, so all three are positive law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 197, $official_bank_source${"itemId":"e339198b-89f2-58d5-9e2a-d9b9c00b2914","questionId":"b77f558f-244f-56a3-adf7-4efc921d1065","sourceKey":"bank:PUL101:ASP-053","payload":{"prompt":"A student argues that the Companies and Allied Matters Act is valid law simply because it was enacted by the National Assembly, whatever anyone thinks of its morality. Which type of law, and which view of law, does this reflect?","options":["Eternal law, which governs all creation","Natural law, which requires law to conform to moral principles","Positive (human) law, as understood by legal positivism","Divine law, which comes from God"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Positive law is law laid down by a human authority in society, and legal positivism holds that such law is valid without regard to morality. Option B would test the Act against higher moral principles. Options D and A describe law that does not come from human enactment."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 198, $official_bank_source${"itemId":"0b9f9cf6-39e4-566a-a94f-8e91d0d98a4b","questionId":"8a2c62ca-8934-565e-905d-c8777dbe626a","sourceKey":"bank:PUL101:ASP-054","payload":{"prompt":"What is one practical importance of the classification of law into civil and criminal law for a lawyer?","options":["It decides whether the case will be governed by divine law or natural law","It helps decide whether to bring a civil action, set the criminal process in motion, or wait for a criminal case to end before suing","It determines whether a treaty has been domesticated","It shows whether a law was enacted by the legislature"],"correctOption":1,"section":"Aspects and Classifications of Law","explanation":"The civil/criminal classification separates private injuries from matters of public order and helps a lawyer choose the right way to obtain redress. Option A mixes in types of law by origin. Option D is the job of the written/unwritten classification, and option C belongs to municipal versus international law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 199, $official_bank_source${"itemId":"f2ef448b-e36e-588b-b6a9-0fd171207eec","questionId":"43a38a38-1202-503a-8101-aeeadb8cf5c0","sourceKey":"bank:PUL101:ASP-055","payload":{"prompt":"Which pairing correctly matches a classification of law with its main focus?","options":["Municipal v international: punishment versus compensation","Written v unwritten: law within a country versus law between countries","Substantive v procedural: the rules themselves versus how they are enforced in court","Public v private: enacted law versus case law"],"correctOption":2,"section":"Aspects and Classifications of Law","explanation":"Substantive law is the body of rules on rights and duties, while procedural law governs how those rules are enforced. Option D actually describes written versus unwritten law. Option B describes municipal versus international law, and option A describes criminal versus civil law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 200, $official_bank_source${"itemId":"82a4d49b-51de-5368-9887-67ad5d98a788","questionId":"19d0eaff-52e4-5e83-a39f-3225ab0b08cb","sourceKey":"bank:PUL101:PQ-004-01","payload":{"prompt":"Which of the following is NOT one of the seven techniques of social control through law?","options":["The grievance-remedial technique","The penal technique","The fiscal technique","The judicial precedent technique"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"The seven techniques are the penal, grievance-remedial, private arranging, constitutive, administrative-regulatory, fiscal and conferral of social benefit techniques. Judicial precedent is a doctrine for following earlier court decisions, not a technique of social control. Option B, Option A and Option C are all on the list."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 201, $official_bank_source${"itemId":"7ab83717-73e5-58cc-90af-f2e5598c831e","questionId":"b6022a47-41bd-5418-afda-44e96e295c2a","sourceKey":"bank:PUL101:PQ-004-02","payload":{"prompt":"Robert Summers identified five basic techniques of social control through law. Which two techniques were later added to his list to make seven?","options":["The conferral of social benefit technique and the penal technique","The constitutive technique and the fiscal technique","The penal technique and the grievance-remedial technique","The private arranging technique and the administrative-regulatory technique"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Summers listed the penal, grievance-remedial, private arranging, administrative-regulatory and public-benefit conferral techniques; the constitutive and fiscal techniques were added later. Option C and Option D are all on Summers' original list. In Option A, the social benefit technique is Summers' public-benefit conferral technique renamed, not a new addition."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 202, $official_bank_source${"itemId":"cbdda89a-017e-59c0-b0af-fac660e8dea5","questionId":"2666a89a-f397-55f3-bd64-2f5d0c748a19","sourceKey":"bank:PUL101:PQ-004-03","payload":{"prompt":"The distinctive feature of the constitutive technique of social control is","options":["the payment of damages to a person who has been wronged","the punishment of persons who commit crimes","the use of taxes to discourage harmful conduct","the creation of a new legal person separate from its members, such as an incorporated company"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Through the constitutive technique, the law helps people pool efforts and resources by giving the group its own legal personality, which brings perpetual succession and limited liability. Option B is the penal technique, Option A the grievance-remedial technique and Option C the fiscal technique."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 203, $official_bank_source${"itemId":"ae187a60-630b-59d2-bb3d-c3cc52db8ff6","questionId":"a6e95647-b31b-5f62-9ccd-c23deeacfc81","sourceKey":"bank:PUL101:PQ-004-04","payload":{"prompt":"What principle was established by the House of Lords in Salomon v. Salomon & Co. Ltd?","options":["A company is merely an agent of its majority shareholder","A manufacturer owes a duty of care to the final consumer of its products","A duly incorporated company is a legal person separate and distinct from its members","A statute must be interpreted by looking at the mischief it was meant to cure"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"The House of Lords held that Salomon & Co. Ltd was a different person from Mr Salomon, so as a secured creditor he could be paid first. This separate legal personality is the bedrock of the constitutive technique. Option B is the rule in Donoghue v. Stevenson, Option D is the mischief rule, and Option A is the argument the House of Lords rejected."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 204, $official_bank_source${"itemId":"96879970-9bd9-5b11-a3e7-ae686e138c1f","questionId":"7180773d-73b4-5e87-8a16-1d9721af236e","sourceKey":"bank:PUL101:PQ-004-05","payload":{"prompt":"A food manufacturer must obtain NAFDAC approval after meeting set standards before starting production. This is an example of which technique of social control?","options":["The penal technique","The conferral of social benefit technique","The administrative-regulatory technique","The private arranging technique"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"Under the administrative-regulatory technique, government agencies set minimum standards and enforce them through licensing, inspection, warnings and revocation, as NAFDAC and the NCC do. Option A prohibits and punishes anti-social conduct, Option D leaves people to arrange their own affairs within a legal framework, and Option B provides amenities like roads and health care."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 205, $official_bank_source${"itemId":"f52d216b-1412-5e03-94dc-8adb224f568c","questionId":"ba3eae1f-cbad-50e5-842e-40c1b69ed400","sourceKey":"bank:PUL101:PQ-004-06","payload":{"prompt":"How does the administrative-regulatory technique mainly differ from the grievance-remedial technique?","options":["It creates new legal persons, while the grievance-remedial technique punishes offenders","It applies only to criminal offences, while the grievance-remedial technique applies only to taxation","It is used only by private individuals, while the grievance-remedial technique is used only by government","It works preventively, before a grievance arises, while the grievance-remedial technique gives a remedy after a wrong has occurred"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Regulation tries to stop harm before it happens, for example by making sure food is produced in safe conditions, while the grievance-remedial technique compensates a consumer who has already been harmed. Option B, Option A and Option C misdescribe both techniques."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 206, $official_bank_source${"itemId":"c07f374f-faf9-5c9b-a8b1-efd0478b7e3b","questionId":"d774264d-ec48-54ba-80b1-63f7d6892d42","sourceKey":"bank:PUL101:PQ-004-07","payload":{"prompt":"Government increases the penalty charged for gas flaring and uses income tax to narrow the gap between the rich and the poor. These measures illustrate","options":["the fiscal technique","the constitutive technique","the private arranging technique","the grievance-remedial technique"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"The fiscal technique uses taxes, levies and charges not only to raise money but also to redistribute income and discourage anti-social conduct such as gas flaring. Option B creates legal persons, Option C gives people a framework for arranging their own affairs, and Option D provides remedies for civil wrongs."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 207, $official_bank_source${"itemId":"04ddcb1b-3e7e-5c2e-92e1-256034f226af","questionId":"3c2248e4-ae14-58f4-a2d3-93c563abd7c5","sourceKey":"bank:PUL101:PQ-004-08","payload":{"prompt":"A person is free to choose whether to make a will, but if he does, it must be in writing, signed and witnessed as the law requires. This illustrates","options":["the fiscal technique","the administrative-regulatory technique","the private arranging technique","the penal technique"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"In the private arranging technique, the law provides a framework of rules for valid private transactions, such as wills, marriages and trusts, and leaves the individual to decide whether to use it. Option D punishes crimes, Option A works through taxation, and Option B involves government agencies licensing and inspecting activities."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 208, $official_bank_source${"itemId":"ed8391e2-db5e-5822-ab02-f4968c9ba21d","questionId":"58a2b8d9-e983-56fc-ae43-736bce2868e4","sourceKey":"bank:PUL101:PQ-004-09","payload":{"prompt":"The grievance-remedial technique, which defines remediable grievances, specifies remedies and provides for their enforcement, operates mainly in the area of","options":["the incorporation of companies","civil law, such as contract, tort and property","criminal law and the prisons","taxation and customs duties"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"This technique gives an aggrieved person remedies such as damages, injunction or specific performance through the courts, which is the domain of civil law. Criminal law and prisons (Option C) belong to the penal technique, taxation (Option D) to the fiscal technique, and incorporation (Option A) to the constitutive technique."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 209, $official_bank_source${"itemId":"30e1bfec-b482-5f48-9252-133a7ff34b52","questionId":"f81baa51-9ded-5029-b67c-16c642b78885","sourceKey":"bank:PUL101:PQ-004-10","payload":{"prompt":"Government programmes that provide roads, education, health care and poverty relief, aiming to improve welfare so as to prevent social strife, illustrate","options":["the constitutive technique","the conferral of social benefit technique","the grievance-remedial technique","the penal technique"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"The conferral of social benefit technique does not directly regulate conduct; it improves people's welfare in the expectation that this will bring order and peace. Option D works by punishing deviant conduct, Option A by creating legal persons, and Option C by giving remedies for civil wrongs."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 210, $official_bank_source${"itemId":"1260d0a1-619e-5ee9-9ffb-edd5ed57aeef","questionId":"3f7b9219-4cc4-5250-bad5-5415585c9b0b","sourceKey":"bank:PUL101:PQ-004-11","payload":{"prompt":"A victim agrees not to press criminal charges against an offender in return for payment of compensation. This alternative to the penal system is called","options":["compounding","caution","self-help","insurance"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Compounding is receiving property or some other consideration in return for an agreement not to prosecute someone who has committed a crime. Option B is a warning given instead of full punishment, Option C is the victim taking the law into his own hands, and Option D is an alternative to the grievance-remedial technique for civil losses."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 211, $official_bank_source${"itemId":"a1b8cda4-fca1-55e1-85a4-71cb717a601a","questionId":"4d97a099-d956-5612-8f74-99483647eb7b","sourceKey":"bank:PUL101:PQ-004-12","payload":{"prompt":"In Aoko v. Fagbemi, adultery was held not to be a criminal offence because","options":["the accused had already been punished under customary law","it was not defined as an offence, with its penalty prescribed, in any written law","the parties had settled the matter privately","the High Court has no jurisdiction over matrimonial matters"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Under the Nigerian Constitution, now section 36(12) of the 1999 Constitution, a person cannot be convicted of an offence unless it is defined and its penalty prescribed in a written law. Since adultery was not so defined, it could not be punished. Option A, Option C and Option D were not the basis of the decision."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 212, $official_bank_source${"itemId":"a67dce08-b44c-51d3-8ca2-48e975b049ab","questionId":"b4840b1f-06b4-5955-98c5-8d96cbae7070","sourceKey":"bank:PUL101:SOC-001","payload":{"prompt":"The control of social behaviour, that is, behaviour that affects others, is loosely described as","options":["social order","social control","social engineering","non-intervention"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Social control is loosely the control of behaviour that affects other people. Option C is Pound's idea of law as a tool for balancing competing interests. Option D is an alternative to the penal technique, and option A is a wider idea than social control."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 213, $official_bank_source${"itemId":"452c3100-6189-58fc-ab6b-d513d262e5e3","questionId":"1d6294ff-443d-575b-8061-44f93e0cdf10","sourceKey":"bank:PUL101:SOC-002","payload":{"prompt":"The term 'social control' was coined by sociologists. Who first used it, to refer to institutions that keep individual behaviour in line with group demands?","options":["William G. Sumner","Edward A. Ross","Richard Quinney","Robert S. Summers"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Edward A. Ross, one of the fathers of American sociology, first used 'social control' for regulative institutions such as public opinion, morals, education and law. Option A, a contemporary of Ross, used the term to show how folkways control conduct. Option D classified legal techniques, and option C wrote later about law as the most explicit form of control."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 214, $official_bank_source${"itemId":"145fbb85-bed8-5bf4-91b3-d464594f30a2","questionId":"4aaa3fa8-060d-5849-8058-1db86bf4561e","sourceKey":"bank:PUL101:SOC-003","payload":{"prompt":"Roscoe Pound described law as","options":["social control through the systematic application of the force of politically organised society","the body of rules regulating human conduct regarded as binding by members of a community","the most specialised and highly finished engine of control employed by society","the command of a sovereign backed by sanction"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Pound, a leading figure of the sociological school, described law as social control through the systematic application of the force of politically organised society. Option D is the positivist command theory. Option B is Elias's definition, and option C is Ross's description of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 215, $official_bank_source${"itemId":"ede8cb66-e209-58cf-aab9-0a91b889583e","questionId":"df8c7352-7ec6-5a7b-864e-9fc00d48c529","sourceKey":"bank:PUL101:SOC-004","payload":{"prompt":"In his work on social control through law, Roscoe Pound wrote that in the modern world law has become","options":["the paramount agent of social control","a minor agent compared with religion","less important as societies grow more complex","an agency of control only in criminal matters"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Pound accepted that the household, church, school and voluntary bodies share the task, but held that 'the brunt of the task falls on the legal order' and that law has become the paramount agent of social control. Options B and D understate his view. Option C contradicts the view that complex societies rely more on law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 216, $official_bank_source${"itemId":"804f8c4e-1b04-5b51-936c-233d20abfd12","questionId":"bfc0648f-2e95-5538-8e36-c7d095e636b6","sourceKey":"bank:PUL101:SOC-005","payload":{"prompt":"Roscoe Pound's idea of law as 'social engineering' sees law mainly as a tool for","options":["keeping law completely separate from society","punishing every immoral act in society","enforcing the command of the sovereign without regard to society","balancing and harmonising competing social interests"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Pound saw law as social engineering: a means of balancing competing claims and interests in society so that the most wants are met with the least friction or disruption. Option B is not his aim and is impossible anyway. Option C reflects the command theory, and option A reflects the pure theory, which Pound's sociological approach rejected."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 217, $official_bank_source${"itemId":"c3aa0e01-a351-50d8-b7e0-91ff82ea8bfc","questionId":"fd66bec4-8c0c-5eb0-9d2e-8ca57e253a2f","sourceKey":"bank:PUL101:SOC-006","payload":{"prompt":"Which of the following is NOT an informal means of social control?","options":["Imprisonment after a criminal trial","Ridicule","Ostracism","Gossip"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Imprisonment after trial is a formal legal sanction applied through the criminal justice system. Ridicule (option B), gossip (option D) and ostracism (option C), together with censure, are informal means that societies usually use spontaneously."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 218, $official_bank_source${"itemId":"9ba6eaa7-1b6e-5fb8-adfc-81d3c5065a19","questionId":"6ebb4e3d-a861-50ff-92ed-eb5fdde5d139","sourceKey":"bank:PUL101:SOC-007","payload":{"prompt":"After a scandal, the people of a village refuse to buy from or sell to a family and stop their children from mixing with the family's children, in line with local custom. What kind of social control is this?","options":["Informal social control through ostracism","The administrative-regulatory technique","The fiscal technique","Formal social control through the penal technique"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Shunning a family by refusing to trade or mix with them is ostracism, an informal and spontaneous means of social control. Option D would need the State to define an offence and prosecute it in court. Options C and B are legal techniques that use taxes and licensing, which play no part here."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 219, $official_bank_source${"itemId":"507b01f4-731f-598a-83e7-fbac9d40ec99","questionId":"7ddd32fe-d068-575f-9d9d-601353d148d6","sourceKey":"bank:PUL101:SOC-008","payload":{"prompt":"Law has advantages that no other instrument of social control can match. Which of the following is NOT one of them?","options":["A wealth of detailed rules","Explicit sanctions","Organised institutions and machinery for enforcement","Rules that are never broken"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Law is often broken, and some laws are seen in breach more than in enforcement, so 'rules that are never broken' is not an advantage it can claim. A wealth of detailed rules (option A), explicit sanctions (option B) and organised enforcement machinery (option C), together with regularised procedure, are its distinctive strengths."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 220, $official_bank_source${"itemId":"157debdf-3f85-55fd-b002-fdbbcde90833","questionId":"e5e2e181-cbfe-5dac-ae2d-67710c85917a","sourceKey":"bank:PUL101:SOC-009","payload":{"prompt":"Some sociologists deny that law is the paramount instrument of social control. Which of the following is NOT one of the factors behind their view?","options":["Some laws are seen in breach more than in enforcement","Law has explicit sanctions backed by organised enforcement machinery","Enforcement agencies exercise discretion in enforcing laws","There are dead-letter laws in the statute books"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Explicit sanctions and organised enforcement are strengths of law, not reasons to doubt it. Frequent breach (option A), dead-letter laws (option D) and the discretion of enforcement agencies (option C) are the factors that weaken law's hold, along with the fact that enforcement does not always prevent the evil aimed at."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 221, $official_bank_source${"itemId":"8821afa5-7288-5d88-952e-7cc477d4bb46","questionId":"48133055-40a6-5bef-8538-5b1b2ce223e7","sourceKey":"bank:PUL101:SOC-010","payload":{"prompt":"Explaining why the legal system is the most explicit form of social control, Quinney said law consists of three elements. Which of the following is NOT one of them?","options":["Planned use of sanctions to support the rules","Specific rules of conduct","Designated officials to interpret and enforce the rules","Spontaneous public ridicule of offenders"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Spontaneous ridicule is an informal means of control, not an element of law. Quinney's three elements are specific rules of conduct (option B), planned use of sanctions (option A) and designated officials to interpret and enforce the rules (option C)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 222, $official_bank_source${"itemId":"8bd2d7d3-df1e-5131-ae4b-753d8b4c89f2","questionId":"f9c01dae-9c83-5844-872f-5d528aa962d2","sourceKey":"bank:PUL101:SOC-011","payload":{"prompt":"Which of the following is NOT one of the functions of law as an instrument of social control?","options":["Facilitating co-operative action","Constituting and regulating the principal organs of power","Maintaining public order and suppressing deviant behaviour","Guaranteeing that no crime will ever be committed"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"No legal system can guarantee that crime will never happen; deviants exist in every society. Law does maintain public order and suppress deviance (option C), facilitate co-operative action (option A), constitute and regulate the organs of power (option B), and communicate and reinforce social values."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 223, $official_bank_source${"itemId":"2c2292c9-7acf-5d5b-85c4-fdba50a00f9b","questionId":"02a1c6fd-5875-51df-b779-03e8f81c8b67","sourceKey":"bank:PUL101:SOC-012","payload":{"prompt":"Robert S. Summers identified five basic techniques used in modern law. Which of the following was NOT on his original list?","options":["The penal technique","The grievance-remedial technique","The administrative-regulatory technique","The constitutive technique"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Summers' five were penal, grievance-remedial, private arranging, administrative-regulatory and public-benefit conferral. The constitutive technique was one of the two that Farrar and Dugdale later added, together with the fiscal technique. Options A, B and C were all on Summers' original list."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 224, $official_bank_source${"itemId":"775cd4d6-db92-5dad-9786-1bc195de6fc1","questionId":"51b6172c-ab44-555d-a1c9-e110d742d63b","sourceKey":"bank:PUL101:SOC-013","payload":{"prompt":"Farrar and Dugdale added two techniques to Summers' list. These were","options":["the private arranging and administrative-regulatory techniques","the constitutive and fiscal techniques","the warning and compounding techniques","the penal and grievance-remedial techniques"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Farrar and Dugdale added the constitutive and fiscal techniques, bringing the total to seven. Options D and A were already among Summers' five. Option C names alternatives to the penal technique, not techniques of social control in their own right."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 225, $official_bank_source${"itemId":"4f2798d7-f17e-5e49-ab0b-e7166cb4d7fd","questionId":"afe42910-dfd1-5121-9d5a-715871879dcb","sourceKey":"bank:PUL101:SOC-014","payload":{"prompt":"Farrar and Dugdale renamed the last technique on Summers' list, the 'public-benefit conferral' technique, as","options":["the conferral of social benefits technique","the fiscal technique","the private arranging technique","the constitutive technique"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Summers' 'public-benefit conferral' was renamed 'conferral of social benefits' by Farrar and Dugdale. Options B and D are the two new techniques they added, not a renaming. Option C was already a separate technique on Summers' list."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 226, $official_bank_source${"itemId":"b808b74e-544a-59cb-acf8-e521dc5a99d8","questionId":"d170718c-b549-59f8-8e97-5b30a54b8f98","sourceKey":"bank:PUL101:SOC-015","payload":{"prompt":"The legal techniques of social control are found","options":["only in international treaties","only in statutes enacted by the legislature","both in legislation and in rules developed by the courts (judge-made law)","only in customary law"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"Law here is not limited to rules made by the legislature: some techniques are firmly rooted in judge-made law, and the techniques show both main elements of modern law, legislation and judge-made law. Options B, D and A each wrongly limit the techniques to a single kind of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 227, $official_bank_source${"itemId":"3b889117-2629-5399-a470-cb9d31da098d","questionId":"34b30c1b-2ab6-55a0-ab46-26e87b639eb9","sourceKey":"bank:PUL101:SOC-016","payload":{"prompt":"The penal technique of social control works mainly by","options":["spelling out prohibited conduct, the penalty for breach, the procedure for determining guilt and the appropriate punishment","setting minimum standards and licensing lawful activities in advance","granting compensation to persons whose private rights have been breached","providing social amenities such as roads, schools and health care"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"The penal technique discourages deviance by stating what is forbidden, what the penalty is, how guilt is decided and what punishment follows. Option C describes the grievance-remedial technique. Option B describes the administrative-regulatory technique, and option D describes conferral of social benefits."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 228, $official_bank_source${"itemId":"d59a9a6c-d311-5e37-b692-ea37fca2e57e","questionId":"8051354c-f67d-53fb-9749-13e7ba99c4f1","sourceKey":"bank:PUL101:SOC-017","payload":{"prompt":"The criminal justice system is created to apply the penal technique. Which of the following is NOT part of it?","options":["Rules setting out acts and omissions that violate the criminal law","Insurance companies settling motor accident claims","The Police Force and other enforcement agencies","Prisons and other approved detention centres"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Insurance settlement is an alternative to the grievance-remedial technique, not part of the criminal justice system. That system is made up of the rules defining crimes (option A), the police and other enforcement agencies (option C), and prisons and detention centres (option D)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 229, $official_bank_source${"itemId":"528a3489-6b4e-5193-8c08-e4588042e989","questionId":"26383d84-0f1d-53fd-9fdc-cb0bb33aa2c8","sourceKey":"bank:PUL101:SOC-018","payload":{"prompt":"Ifeoma's phone is snatched in Ikeja. Instead of hunting the thief down herself, she reports to the police, who investigate. The decision whether to prosecute is then taken by the police or the Attorney-General, based on the evidence. This process illustrates","options":["the private arranging technique","how the penal technique brings about social control","reciprocity and self-help","the conferral of social benefits technique"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Under the penal technique the victim reports to the police instead of resorting to vengeance, the State investigates and decides whether to prosecute, and guilt must be proved beyond reasonable doubt. Option A concerns individuals arranging their own affairs, and option D concerns welfare provision. Option C is exactly what Ifeoma avoided."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 230, $official_bank_source${"itemId":"0e208a64-e4d2-5233-9fa0-126177c62e56","questionId":"8333c4bc-6bd9-54b7-bec9-a73d2c19f1ba","sourceKey":"bank:PUL101:SOC-019","payload":{"prompt":"Evidence emerges that Mr. Okon committed a fraud twelve years ago. Under the general rule, can he still be prosecuted?","options":["Yes, but only if the victim first sues him in a civil court","No, because crimes become statute-barred after ten years","Yes, because as a general rule limitation periods do not run against crimes","No, because all criminal prosecutions must begin within six years"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"As a general rule the statute of limitation does not run against a crime, so an offender can be prosecuted however long ago the offence was committed. Options D and B borrow the five, six or ten year limitation periods that apply to civil actions. Option A invents a requirement."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 231, $official_bank_source${"itemId":"270a8691-3336-51f3-83f6-e519f5cff015","questionId":"1c7cdab9-b2fc-5bf1-b099-62d1bc6b0d29","sourceKey":"bank:PUL101:SOC-020","payload":{"prompt":"The alternative to the penal system under which society deliberately chooses not to criminalise certain socially disapproved or immoral conduct is called","options":["non-intervention","reciprocity","warning or caution","compounding"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Non-intervention reflects that society cannot, and sometimes should not, penalise every immoral act, as when adultery was held not to be a crime in Aoko v Fagbemi. Option D is an agreement not to prosecute in return for some benefit. Option C still involves the system acting on an offender, and option B is private vengeance."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 232, $official_bank_source${"itemId":"69cc3e2f-face-56d5-bcf3-b534cc8402a8","questionId":"19a50320-ec85-5894-98d9-91ff50aaf370","sourceKey":"bank:PUL101:SOC-021","payload":{"prompt":"Two brothers living in the same house have a minor scuffle over a borrowed shirt. The police at the station they visit encourage them to settle the matter within the family instead of charging either of them. Which alternative to the penal system does this reflect?","options":["Reciprocity and self-help","Compounding for money","Non-intervention","Administrative regulation"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"Where members of the same household are involved in less serious matters, there may be good reason not to intervene, and the police encourage private settlement; this is non-intervention. Option A means private vengeance. Option B involves receiving property in return for not prosecuting, and option D concerns licensing and standards."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 233, $official_bank_source${"itemId":"ef7385d2-6e98-5721-9714-9a20bece1f50","questionId":"41dbb410-31c3-5687-b9f4-e0b056be7f3f","sourceKey":"bank:PUL101:SOC-022","payload":{"prompt":"During a High Court sitting, a spectator's phone rings loudly and disturbs proceedings. Instead of committing him for contempt of court, the judge warns him and lets him go. This is an example of","options":["the grievance-remedial technique","warning or caution","compounding","non-intervention"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"A judge warning someone who disturbs court proceedings, instead of committing him for contempt, is the standard example of warning or caution as an alternative to full punishment. Option C needs an agreement with a victim. Option D is wrong because the judge did act, and option A is a civil-law technique."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 234, $official_bank_source${"itemId":"497a491f-4832-573f-b936-411f52e76526","questionId":"3f1e6f11-6968-5381-9f7c-63672a6e486d","sourceKey":"bank:PUL101:SOC-023","payload":{"prompt":"A man suspected of stealing a phone at a market is stripped, beaten and set on fire by a mob without any trial. Which alternative to the penal system does this represent, and how is it regarded?","options":["Reciprocity and self-help; it is dangerous and a symptom of an underdeveloped system","Compounding; it is a lawful private settlement","Warning or caution; it is suitable for petty offenders","Non-intervention; the State has chosen not to act"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Mob 'jungle justice' is reciprocity and self-help, the 'eye for an eye' approach, which is described as a symptom of an underdeveloped system and is unfit for modern times. Option B needs an agreement in return for not prosecuting. Option C is a mild official response, and option D misdescribes a violent private act."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 235, $official_bank_source${"itemId":"b661efce-e5b0-500c-8fd8-9fae35f3f63a","questionId":"cb113e6f-6b89-5b3f-9b17-87f3979ea894","sourceKey":"bank:PUL101:SOC-024","payload":{"prompt":"Which of the following is a key danger of self-help ('jungle justice')?","options":["The offender always receives a lighter sentence than in court","It is too slow compared with court proceedings","It protects the perpetrators from civil and criminal liability","An innocent person may be punished without a fair hearing"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Self-help risks punishing an innocent person without a fair hearing, and those who take part are themselves liable to civil and criminal sanctions. Options A and B are not the dangers identified. Option C is false, since the perpetrators expose themselves to liability."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 236, $official_bank_source${"itemId":"519b7f08-b80d-5740-89c6-a343d9bab51f","questionId":"35159356-9f93-5ef0-aa51-1344e7e19ff2","sourceKey":"bank:PUL101:SOC-025","payload":{"prompt":"The receipt of property or other consideration in return for an agreement not to prosecute someone who has committed a crime is called","options":["compounding","non-intervention","restitutio in integrum","arbitration"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Compounding is an arrangement under which the victim agrees not to press criminal charges once certain conditions, usually compensation, are met. Option B is a policy choice not to criminalise conduct at all. Option D is a way of settling civil disputes, and option C is a civil remedy restoring the original position."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 237, $official_bank_source${"itemId":"b45a42f0-8905-5d2e-aea2-197abf600048","questionId":"2ef2b60d-3385-5641-b977-d8b9d8e558c8","sourceKey":"bank:PUL101:SOC-026","payload":{"prompt":"A driver negligently knocks down a pedestrian in Ibadan, causing minor injuries. The pedestrian's relatives agree not to insist on prosecution after the driver promises to pay N150,000 as compensation. This arrangement is an example of","options":["the fiscal technique","the constitutive technique","warning or caution","compounding"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"An agreement by the victim's side not to press charges in return for compensation is compounding, and a minor accident is the classic example. Option A uses taxes and levies. Option C is a warning by an official such as a judge, and option B concerns creating legal persons."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 238, $official_bank_source${"itemId":"79766b7c-1458-5ff9-a01b-97a8908b5691","questionId":"8fa17d20-a1bb-5fc4-9d46-96344d464382","sourceKey":"bank:PUL101:SOC-027","payload":{"prompt":"In Federal Civil Service Commission v Laoye, Oputa JSC criticised dismissing a civil servant accused of conspiracy and stealing a large sum of hard currency without first prosecuting him. What point did he make?","options":["Summary dismissal is always a better remedy than prosecution","Compounding is the preferred way of dealing with serious fraud","Justice is reached through finding the truth, and the means of finding the truth of a criminal charge is trial in open court","Civil servants can never be dismissed for misconduct"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"Oputa JSC held that justice is reached through finding the truth, and that the truth of a criminal charge is tested by trial in open court; the employer could dismiss after conviction. This casts doubt on private alternatives such as dismissal in place of prosecution. Options A and B contradict his reasoning, and option D overstates it."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 239, $official_bank_source${"itemId":"0a983563-50d7-5d44-b61d-b78111757ac4","questionId":"93415a87-e3a5-5440-9474-ef77b786afe9","sourceKey":"bank:PUL101:SOC-028","payload":{"prompt":"Professor Summers explained the grievance-remedial technique as one that","options":["creates new legal persons separate from their members","uses taxation to discourage anti-social behaviour","spells out prohibited conduct and prescribes punishment","defines remediable grievances, specifies remedies and provides for enforcement of remedial awards"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"The grievance-remedial technique, used mainly in civil law, defines which grievances can be remedied, states the remedies and provides for their enforcement. Option C is the penal technique. Option A is the constitutive technique, and option B is the fiscal technique."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 240, $official_bank_source${"itemId":"1ebbd150-0835-5ef7-be9d-8c373b42a852","questionId":"8dbda59b-16be-54e2-88b4-7f39ff87d13f","sourceKey":"bank:PUL101:SOC-029","payload":{"prompt":"The grievance-remedial technique is used mainly in civil law. Which of the following areas does NOT mainly employ it?","options":["Law of contract","Criminal law","Family law","Law of torts"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Criminal law employs the penal technique, which punishes rather than remedies. Contract (option A), torts (option D) and family law (option C), along with commercial law, property, equity and trusts, and labour law, are the areas that use the grievance-remedial technique."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 241, $official_bank_source${"itemId":"56b87531-2b7c-5556-a5ff-e62367a2303d","questionId":"cffbefeb-9f04-59b4-bbf8-ae857659aa18","sourceKey":"bank:PUL101:SOC-030","payload":{"prompt":"Which of the following is NOT a remedy available under the grievance-remedial technique?","options":["Special damages","Injunction","Specific performance","Imprisonment"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Imprisonment is a penal sanction, not a civil remedy. Special damages (option A), specific performance (option C) and injunction (option B), together with general damages and restitutio in integrum, are remedies for an aggrieved person under this technique."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 242, $official_bank_source${"itemId":"2d850807-de42-59be-bf1d-a8116150ca61","questionId":"528cdb80-eb27-57b6-b306-e9d58bee99d0","sourceKey":"bank:PUL101:SOC-031","payload":{"prompt":"What is the logical basis of the grievance-remedial technique as a means of social control?","options":["Punishing offenders deters others from committing crimes","Licensing prevents harm before it occurs","An adequately remedied person is pacified, which discourages injustice and stops people taking the law into their own hands","High taxes discourage harmful activities"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"If an aggrieved person gets an adequate remedy, he is likely to be truly pacified, so the law discourages injustice and self-help. Option A is the logic of the penal technique, option D of the fiscal technique, and option B of the administrative-regulatory technique."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 243, $official_bank_source${"itemId":"6b79406c-0ad3-5f09-959c-d5be122ed111","questionId":"ba06a364-22b7-5072-a511-3a8c6f4a863a","sourceKey":"bank:PUL101:SOC-032","payload":{"prompt":"Under the rule in Smith v Selwyn, where a wrongful act is a felony,","options":["the victim may sue in tort but the State can never prosecute","the victim loses any right to sue once a complaint is made to the police","the civil action and the prosecution must always be heard together","no action in tort can be brought until the defendant has been prosecuted or a reasonable excuse is shown for not prosecuting"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"The rule in Smith v Selwyn holds back a tort action for a felony until the defendant has been prosecuted or a reasonable excuse for not prosecuting is shown. Its application in Nigeria is disputed, and it has been called archaic. Options A, C and B misstate the rule."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 244, $official_bank_source${"itemId":"a82e877a-2b6b-5bca-b8b8-2474a01654b2","questionId":"5bd36e66-94a4-550a-aa3a-8335b14f5f5b","sourceKey":"bank:PUL101:SOC-033","payload":{"prompt":"A supply contract between Adeola Foods Ltd and a transporter states that the transporter will pay N50,000 for each day of late delivery. When a delivery is three days late, the transporter pays N150,000 without going to court. Which alternative to the grievance-remedial technique does this illustrate?","options":["Compounding","The penal technique","Private settlement through a liquidated damages clause","The fiscal technique"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"Parties may agree in advance exactly how much a defaulting party will pay, and if they carry it out there is no need for litigation; this is private settlement. Option A concerns crimes, not contract breaches. Option B involves prosecution, and option D involves the government's financial policy."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 245, $official_bank_source${"itemId":"4c0a062d-4ca2-5ef1-bd1f-ff11f850559d","questionId":"eec5d518-bd9e-5e51-a70e-29b413239839","sourceKey":"bank:PUL101:SOC-034","payload":{"prompt":"Two cars collide on the Third Mainland Bridge. Both drivers have comprehensive cover, so they exchange details and refer the matter to their insurance companies instead of suing each other. Which alternative to the grievance-remedial technique is this?","options":["Non-intervention","Insurance","Compounding","Arbitration"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Handling a motor crash through the parties' insurers instead of the courts is the insurance alternative, and it depends on the type of cover taken. Option D involves an arbitrator making an award. Option C concerns criminal charges, and option A is an alternative to the penal system."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 246, $official_bank_source${"itemId":"06f6a8ee-475b-56e9-b3d2-ab685e1c2945","questionId":"e943821e-87b3-5113-b748-886c43f4f525","sourceKey":"bank:PUL101:SOC-035","payload":{"prompt":"Which of the following is NOT a recognised advantage of arbitration over litigation?","options":["The dispute is usually disposed of much more quickly","An arbitrator familiar with the technical background of the dispute can be chosen","It is always cheaper than going to court","Proceedings can be kept secret and informal"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"Experience shows that arbitration is not necessarily cheaper, and it can cost more if a party goes to court to set aside the award. Speed (option A), expert arbitrators (option B) and secrecy and informality (option D) are recognised advantages."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 247, $official_bank_source${"itemId":"97ad5d59-660d-5ab6-9dfd-9569e151d9ba","questionId":"ecaf96c1-bcdb-52f6-9629-4039f62cb09b","sourceKey":"bank:PUL101:SOC-036","payload":{"prompt":"A construction contract contains a clause requiring disputes to be referred to arbitration. Before any arbitration, one party rushes to the High Court with a claim. What is the position?","options":["The arbitration clause makes the matter a criminal offence","The court must hear the case because arbitration clauses are void","The court can freely rehear any later arbitral award on its merits","Going to court is premature; the dispute should first be submitted to arbitration"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Where a contract has an arbitration clause, it is premature to go to court without first submitting the dispute to arbitration, and courts can set aside an award only within narrow limits. Option B wrongly treats the clause as void. Option A confuses civil and criminal matters, and option C ignores the narrow scope of court intervention."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 248, $official_bank_source${"itemId":"201485b7-f376-5fa3-9659-140c10009d23","questionId":"c65eae08-1424-57bb-90f9-bca1ee5bb205","sourceKey":"bank:PUL101:SOC-037","payload":{"prompt":"The private arranging technique is best described as a system whereby","options":["the law provides a framework of rules for the validity of private transactions, leaving individuals to arrange their affairs within it","the state prosecutes persons who break the criminal law","the state directly provides social amenities to citizens","government agencies license and inspect private operators"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Under the private arranging technique, the law sets the rules that determine whether private transactions such as marriages, trusts and wills are valid, and individuals choose whether and how to act within them. Option C is conferral of social benefits. Option D is the administrative-regulatory technique, and option B is the penal technique."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 249, $official_bank_source${"itemId":"6d150285-8dfc-5995-96ef-d1f1cb09b52f","questionId":"1e9a09c8-7ee5-58b3-a96f-6b454e1264da","sourceKey":"bank:PUL101:SOC-038","payload":{"prompt":"Alhaji Musa writes and signs his will, but only one witness is present when he signs. Assuming the general rule applies, what is the consequence under the private arranging technique?","options":["The will is invalid and his property will be distributed under the rules of intestacy","The will is valid because no special form is required for a will","The will is valid because he signed it himself","The will is invalid and the state confiscates his property"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"A person is free to make a will or not, but if he does, it must meet the legal requirements: generally it must be in writing and signed by the testator in the presence of at least two witnesses present at the same time, who attest it. Otherwise it is invalid and intestacy rules apply. Options B and C ignore the witness requirement, and option D invents confiscation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 250, $official_bank_source${"itemId":"6664f886-4894-58d0-ab67-09a6c715948b","questionId":"e7ca39a2-6516-5b18-b741-95060fd050c1","sourceKey":"bank:PUL101:SOC-039","payload":{"prompt":"Segun married Funmi under the Marriage Act. While that marriage subsists, he goes through a customary marriage with Halima. How does the private arranging technique treat the second marriage?","options":["It is valid if Segun pays tax on it","It is valid, because each person may choose the form of marriage freely at any time","It is invalid, because a person in a subsisting statutory marriage cannot validly contract another marriage under any system","It is valid, because customary law permits more than one wife"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"A person may choose to marry under the Marriage Act, customary law or Islamic law, but once he chooses one system he must comply with its rules. A person in a subsisting statutory marriage cannot validly marry anyone else under any of the systems. Options D and B ignore the binding effect of the first choice, and option A is absurd."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 251, $official_bank_source${"itemId":"66675294-644d-5e12-b5f4-de0a9866b312","questionId":"e129ac7e-ce6a-552c-bc59-7262164186d6","sourceKey":"bank:PUL101:SOC-040","payload":{"prompt":"Mrs. Eze holds a statutory right of occupancy in Lagos and agrees to sell her interest to a buyer. Although this is a private transaction, she must first obtain the Governor's consent. This shows that","options":["areas once left to private arranging are moving towards direct government intervention","private arrangements no longer need to comply with any legal framework","land transactions are governed only by the penal technique","the constitutive technique has replaced private arranging"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Under the Land Use Act a holder must obtain the Governor's consent before assigning, mortgaging or otherwise alienating an interest in land, which is an example of law stepping into an area once left to private arranging. Option C is wrong because no crime is involved. Option D concerns creating legal persons, and option B contradicts the point."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 252, $official_bank_source${"itemId":"eaeec251-f951-5063-925d-88535bcd77ad","questionId":"e3ddbae8-bad6-5430-b892-f4997e4899e6","sourceKey":"bank:PUL101:SOC-041","payload":{"prompt":"Kola buys a car on hire purchase for a total hire-purchase price of N4,000,000 and has paid N2,600,000 when he falls behind with his instalments. Under section 9 of the Hire Purchase Act, which bars an owner of a motor vehicle from recovering it except by court action once three-fifths of the price has been paid, what may the owner do?","options":["Seize the car without a court action, because Kola has not paid the full price","Recover the car only by court action, because Kola has paid more than three-quarters of the price","Recover the car only by an action in court, because Kola has paid more than three-fifths of the price","Seize the car at once without going to court, because instalments are in arrears"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"Kola has paid 2,600,000/4,000,000 = 0.65, or 65 percent, which is more than three-fifths (60 percent), so the owner can recover the car only by court action. Options D and A state the old position before the Act, as in Atere v Amao, where owners could seize goods even when nearly all the instalments had been paid. Option B uses the wrong threshold, and 65 percent is below three-quarters anyway."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 253, $official_bank_source${"itemId":"87e34786-a39f-551b-89fd-9cd81bd1df56","questionId":"b6756ddf-bc1f-51c7-a23a-f8e5954a45f0","sourceKey":"bank:PUL101:SOC-043","payload":{"prompt":"How is the constitutive technique related to the private arranging technique?","options":["It is identical to private arranging and was not separately recognised","It is an offshoot of private arranging: nobody must form a company, but those who do must meet the legal requirements, so it takes off where private arranging stops","It replaces private arranging by banning private contracts","It is the opposite of private arranging because it compels everyone to form a company"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Individuals are free to choose whether to form a company, as with other private arrangements, but those who do must comply with the law so that the company comes into existence. In that sense the constitutive technique takes off where private arranging stops. Option D is false because nobody is compelled. Option A ignores its separate recognition by Farrar and Dugdale, and option C is false."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 254, $official_bank_source${"itemId":"217f5200-7766-5315-a6a3-c5f6018e781d","questionId":"cf3f6022-0363-522e-8c76-a390c4ad6018","sourceKey":"bank:PUL101:SOC-044","payload":{"prompt":"Ada and two friends incorporate AdaTech Ltd. The company borrows N20,000,000 and later fails, and the bank seeks to make the three shareholders personally liable for the company's debt. Which principle supports the shareholders' defence?","options":["The rule in Smith v Selwyn bars all claims against shareholders","A duly incorporated company is a legal person separate from its members, as held in Salomon v Salomon","Debts of a company are cancelled once it is incorporated","Shareholders are always personally liable for company debts"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Salomon v Salomon established that an incorporated company is a separate legal person, which brings limited liability for its members. This principle is the bedrock of company law, though it may not be used as a tool for fraud. Option A concerns tort claims arising from felonies. Option D denies separate personality, and option C is absurd."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 255, $official_bank_source${"itemId":"6a7bfdfd-ce1c-593c-b54a-b39893a8dec5","questionId":"39a7371d-1976-50a7-9a2e-f72cb27730b3","sourceKey":"bank:PUL101:SOC-045","payload":{"prompt":"In Salomon v Salomon, why was Mr. Salomon entitled to be paid before the company's unsecured creditors?","options":["Salomon was the managing director and so had priority","The court found that the company was a sham","The company was a separate legal person, and Salomon was a secured debenture holder","Salomon held all the shares and therefore owned the company's assets"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"The House of Lords held that Salomon and Co. Ltd. was a separate person, so it could owe Salomon money, and as a secured creditor holding debentures he was paid first. Option A confuses office with priority. Option B states the liquidator's argument, which was rejected, and option D contradicts the company's separate ownership of its assets."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 256, $official_bank_source${"itemId":"dbe3be41-8523-5274-9b4c-8f22b71b7463","questionId":"100ba402-67b4-5038-83a2-98ae47ac69e7","sourceKey":"bank:PUL101:SOC-046","payload":{"prompt":"The constitutive technique is used to create many kinds of bodies. Which of the following is given as an example of a group the law recognises WITHOUT giving it legal personality?","options":["A political party","A religious body registered as incorporated trustees","A university established by statute","A statutory corporation"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"The law gives a framework to some collective groups, such as partnerships, labour unions, political parties and professional bodies, without vesting legal personality in them. Statutory universities (option C), statutory corporations (option D) and incorporated trustees (option B) are created as legal persons through the constitutive technique."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 257, $official_bank_source${"itemId":"163e31fb-ddea-57c5-bf8b-45ec1fbb0283","questionId":"4c88795c-8c04-55a8-95cc-65e75e3a8ec3","sourceKey":"bank:PUL101:SOC-047","payload":{"prompt":"Under the administrative-regulatory technique, government agencies","options":["adopt regulatory standards, communicate them to private operators and take steps to ensure compliance","compensate victims of breach of contract","punish offenders after a crime has been committed","distribute social amenities such as low-cost housing"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"The administrative-regulatory technique sets minimum standards in the public interest, makes them known to operators and enforces compliance through licensing, inspection and similar steps. Option C is the reactive penal technique. Option B is grievance-remedial, and option D is conferral of social benefits."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 258, $official_bank_source${"itemId":"49a1248d-dc7a-5945-a3db-d896d2924ae4","questionId":"06be2328-925b-5e44-b08a-acfd14a7f697","sourceKey":"bank:PUL101:SOC-048","payload":{"prompt":"In enforcing the administrative-regulatory technique, which step is normally the last resort?","options":["Writing warning letters","Civil litigation or criminal prosecution","Licensing","Inspection"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Agencies usually rely first on licensing, inspection, warning letters or revoking a licence, and turn to administrative proceedings, civil litigation or criminal prosecution only as a last resort. Options C, D and A are the earlier, preventive steps."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 259, $official_bank_source${"itemId":"de51065c-9e1b-54c3-b90f-a167f17b949f","questionId":"3d258f40-c2e8-5313-94f9-b2e8dcc0827f","sourceKey":"bank:PUL101:SOC-049","payload":{"prompt":"Mrs. Adeyemi plans to open a private nursery and primary school in Surulere. Before admitting pupils, she must apply to the Ministry of Education for a permit, which is granted only if the school meets set standards. Which technique of social control is at work?","options":["The penal technique","The fiscal technique","The private arranging technique","The administrative-regulatory technique"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Requiring a permit from the Ministry of Education before a private school opens, with standards checked in advance, is the administrative-regulatory technique. Option A would apply only after an offence. Option C concerns the validity of private transactions, and option B uses taxes."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 260, $official_bank_source${"itemId":"0d56d2af-9d5e-5c33-abf9-9fc4975ea036","questionId":"0e9c73dc-78ae-59a5-8e62-ac1b73909d2e","sourceKey":"bank:PUL101:SOC-050","payload":{"prompt":"A new company wants to provide mobile telephone services in Nigeria and must first obtain a licence from the Nigerian Communications Commission and comply with its standards. This is an example of","options":["the conferral of social benefits technique","the grievance-remedial technique","the administrative-regulatory technique","compounding"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"The Federal Government regulates mobile and wireless service providers through the NCC, which is an administrative-regulatory technique. Option B would come into play only after a customer suffered a wrong. Option A is government provision of welfare, and option D is an alternative to prosecution."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 261, $official_bank_source${"itemId":"7833c13a-48ce-5a43-a10d-79b87377447b","questionId":"974d4188-36da-5ece-b7fd-c0e959880b4f","sourceKey":"bank:PUL101:SOC-051","payload":{"prompt":"How does the administrative-regulatory technique differ from the penal technique?","options":["It applies only after harm has occurred, while the penal technique is preventive","It punishes offenders more severely than the penal technique","It regulates wholesome activities, while the penal technique prohibits and sanctions anti-social behaviour","It is enforced only by private individuals"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"The administrative-regulatory technique regulates lawful, wholesome activities such as food production and schooling, while the penal technique prohibits and punishes anti-social conduct. Option B is false because punishment is a last resort under regulation. Option A reverses the preventive nature of regulation, and option D ignores the role of government agencies."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 262, $official_bank_source${"itemId":"a726fb40-e0c2-58d4-91b6-f09a8b41d526","questionId":"ff3af406-5f4b-569e-9130-1906923ec544","sourceKey":"bank:PUL101:SOC-052","payload":{"prompt":"A food regulator inspects factories to ensure that drinks are produced hygienically, while a consumer made ill by a contaminated drink sues the manufacturer for compensation. Which pairing is correct?","options":["Inspection is fiscal; the lawsuit is constitutive","Both are examples of the penal technique","Inspection is grievance-remedial; the lawsuit is administrative-regulatory","Inspection is administrative-regulatory (preventive); the lawsuit is grievance-remedial"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Regulation works before any harm, aiming to stop a manufacturer from breaching its duty to consumers, while the grievance-remedial technique compensates a consumer after harm has happened. Option C reverses the two. Options B and A apply techniques that do not fit either activity."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 263, $official_bank_source${"itemId":"0d48ef9a-89d1-5209-ac67-8b43fc39e8bf","questionId":"f459610f-ac46-5a37-8e25-5df9937181a9","sourceKey":"bank:PUL101:SOC-053","payload":{"prompt":"Although the classical aim of taxation is to raise money, the fiscal technique is also used in modern times to","options":["redistribute income, stimulate economic growth and discourage anti-social behaviour","punish crimes through imprisonment","license schools and telecom operators","create new legal persons"],"correctOption":0,"section":"Methods of Social Control through Law","explanation":"Beyond raising revenue, taxation and related financial measures are used to redistribute income, stimulate growth and discourage harmful conduct. Option D is the constitutive technique, option B the penal technique, and option C the administrative-regulatory technique."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 264, $official_bank_source${"itemId":"de48194f-7030-573d-a911-0b60bda91333","questionId":"c0ff800f-60d6-54ad-ab59-5ac2325ee6c9","sourceKey":"bank:PUL101:SOC-054","payload":{"prompt":"To discourage oil companies from flaring gas, the Federal Government sharply increases the financial penalty payable for each unit of gas flared, so that flaring becomes more expensive than using the gas. Which technique of social control is this?","options":["The private arranging technique","The constitutive technique","Warning or caution","The fiscal technique"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"Using government financial measures, here a heavier charge on gas flaring, to discourage environmentally harmful conduct is the fiscal technique; the 1998 budget increased the gas-flaring penalty for this purpose. Option B concerns creating legal persons. Option A concerns private transactions, and option C is an alternative to penal punishment."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 265, $official_bank_source${"itemId":"0e892b30-ce4a-5aae-8c7b-f4503845fd85","questionId":"34171390-7411-59e0-bab1-403c8b1c0ce2","sourceKey":"bank:PUL101:SOC-055","payload":{"prompt":"The conferral of social benefits technique is best described as one that","options":["directly regulates conduct by prescribing punishments","creates companies with separate legal personality","provides social amenities and welfare to improve citizens' well-being, without directly regulating their conduct","sets licensing standards for private businesses"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"This technique has government provide roads, education, electricity, housing, health care and social security. It does not directly regulate behaviour; it expects better welfare to bring order and peace. Option A is the penal technique, option D the administrative-regulatory technique, and option B the constitutive technique."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 266, $official_bank_source${"itemId":"80238933-4774-5ffd-8a88-7092c7e41b8c","questionId":"81c7a1b3-0dc3-5474-bd25-9bdad8c8e417","sourceKey":"bank:PUL101:SOC-056","payload":{"prompt":"To reduce unrest in an oil-producing area, the government sets up a development commission to build roads, schools and health centres, and funds a poverty eradication programme for young people there. Which technique of social control does this mainly use?","options":["The penal technique","Conferral of social benefits","The grievance-remedial technique","Compounding"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Providing amenities and welfare programmes, as with the NDDC or NAPEP, to improve living standards and so promote order is the conferral of social benefits technique. Option A would punish offenders. Option C compensates individual civil wrongs, and option D is a private alternative to prosecution."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 267, $official_bank_source${"itemId":"74eab57c-69b6-5a1b-84cf-0644eb638fd4","questionId":"f9b5b8a6-4d17-5cdf-9a4d-e7f19cc1ad10","sourceKey":"bank:PUL101:SOC-057","payload":{"prompt":"What has been identified as a major weakness of the conferral of social benefits technique in Nigeria?","options":["It cannot be supported by any law","Programmes have often been poorly implemented and hijacked by elites, so only crumbs reach the target group","The technique has been used so effectively that poverty has disappeared","It relies entirely on imprisonment, which is costly"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Despite many welfare programmes, poverty and welfare remain dismal because most programmes were poorly implemented and hijacked by elites. Option C contradicts the poor outcomes. Option D confuses this technique with the penal one, and option A is wrong because laws on social security, education, health and industry fall within it."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 268, $official_bank_source${"itemId":"a76f6787-ecb9-58b5-86a6-597a436701a5","questionId":"e585898c-b59a-5650-ac6f-9e23165b3b92","sourceKey":"bank:PUL101:SOC-058","payload":{"prompt":"Which statement best reflects the relationship between the different techniques of social control?","options":["Each technique operates in complete isolation and can never be combined","The penal technique has replaced all the other techniques","Only one technique may be used in any area of law","They often overlap and complement each other, and government may combine more than one technique to achieve an objective"],"correctOption":3,"section":"Methods of Social Control through Law","explanation":"There are many similarities and overlaps between the techniques; they can complement each other, and when legislating, government must choose which technique or combination will best achieve its goals. Options A and C deny that they can be combined, and option B is false."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 269, $official_bank_source${"itemId":"b678db43-69bb-54f3-9335-2a3f9e32e9d2","questionId":"6c715e89-ca0d-5671-9230-3f30a6437a77","sourceKey":"bank:PUL101:SOC-059","payload":{"prompt":"Two promoters form a company that sells a baby drug without NAFDAC approval, and several children who used it die. Sued, the promoters argue that they cannot be personally responsible because the company is a separate person. Which two techniques are mainly involved in analysing this problem?","options":["The fiscal technique and the conferral of social benefits technique","The administrative-regulatory technique and the constitutive technique","Compounding and warning or caution","The private arranging technique and non-intervention"],"correctOption":1,"section":"Methods of Social Control through Law","explanation":"Failing to obtain NAFDAC approval raises the administrative-regulatory technique, and the promoters' reliance on separate legal personality raises the constitutive technique and Salomon v Salomon. That principle was not meant to shield fraud or harm to the public. Options A, D and C do not address regulation of drugs or corporate personality."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 270, $official_bank_source${"itemId":"b9e95df9-4dfa-5c65-82ed-b2a37f7c6bc2","questionId":"ac798133-3966-5ca7-84ec-387126601a84","sourceKey":"bank:PUL101:SOC-060","payload":{"prompt":"Bisi, a cashier of a co-operative society, steals society funds, then refunds everything at the police station and begs for forgiveness. The prosecutor suggests dropping the charges, but the society's executive committee resolves to press the case to the end. Why is compounding unavailable here?","options":["Compounding is available only when the accused has not refunded the money","Compounding applies only to offences committed by children","Compounding needs a compromise between the accused and the complainant, and the society refuses to compromise","Compounding can be ordered by the prosecutor against the victim's wishes"],"correctOption":2,"section":"Methods of Social Control through Law","explanation":"Compounding rests on an agreement by the victim not to prosecute in return for some satisfaction, so it fails where the complainant, here the society, insists on prosecution. Option B confuses compounding with warning or caution for child offenders. Option A reverses the facts, and option D ignores that the victim must agree."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 271, $official_bank_source${"itemId":"43c461bf-792c-526d-a073-e2f8af83593f","questionId":"5517396a-981c-5f87-a1cb-bca389c4106d","sourceKey":"bank:PUL101:FAC-001","payload":{"prompt":"A process in which only the disputing parties themselves confer with each other and agree on how to restore cordiality and harmony in their relationship, without any third party, is called","options":["conciliation","arbitration","mediation","reconciliation"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"Reconciliation is the act of harmonising differences where the only parties involved are the disputants themselves. Options A and C both bring in a neutral third party to help the parties settle, and option B involves a third party who actually decides the dispute."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 272, $official_bank_source${"itemId":"c58adf85-a300-55c1-a14a-2c79c97432b8","questionId":"afe02f10-2825-503b-b49b-d225d96f344d","sourceKey":"bank:PUL101:FAC-002","payload":{"prompt":"Which of the following best describes arbitration?","options":["A process whereby the disputants alone confer with each other to restore harmony in their relationship","A process whereby a neutral third party offers suggestions for settlement which the parties are free to accept or reject","A process whereby the parties agree to have their dispute settled by an independent third party and to be bound by his decision","A process whereby a judge appointed by the state hears the parties in a court of law and gives a self-executing judgment"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"Arbitration rests on the parties' agreement to submit the dispute to an independent third party whose decision, called an award, binds them. Option B describes mediation, option D describes litigation in court, and option A describes reconciliation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 273, $official_bank_source${"itemId":"7c894d00-4c03-5765-b1ba-63bbf13cb4a6","questionId":"ab1eb32c-6797-5009-8c96-955e0f449bba","sourceKey":"bank:PUL101:FAC-003","payload":{"prompt":"Among reconciliation, conciliation, mediation and arbitration, in which method does the third party actually decide the dispute on its merits?","options":["Arbitration","Mediation","Conciliation","Reconciliation"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"The arbitrator probes into the facts in fair detail and renders a decision on the merits, so he determines who is right and who is wrong. A conciliator or mediator (options C and B) only helps the parties reach their own settlement, and reconciliation (option D) has no third party at all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 274, $official_bank_source${"itemId":"6a55ccf2-d5d3-56f1-a7df-0e898c87ca78","questionId":"5d213079-d3ad-5d2c-9bf4-aa69a6c2d7ba","sourceKey":"bank:PUL101:FAC-004","payload":{"prompt":"What is the main distinguishing factor between conciliation and reconciliation?","options":["The number of parties involved, since conciliation brings in a third party as intermediary","Conciliation always produces an award that is enforceable like a court judgment","Reconciliation can only take place inside a court of law","Conciliation is used only for criminal matters while reconciliation is used for civil matters"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"Reconciliation involves only the disputants, while conciliation adds a third person who acts as intermediary, so the difference lies in the number of parties. Option B is wrong because a conciliator's proposal is generally only a guide, option C is wrong because reconciliation is an informal, out-of-court process, and option D invents a division that does not exist."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 275, $official_bank_source${"itemId":"63d56d5d-5108-5928-a269-dfc419b70ef6","questionId":"e23b5a94-04af-59cb-8f11-977af36d3e77","sourceKey":"bank:PUL101:FAC-005","payload":{"prompt":"A neutral third party who rarely inquires into the facts of a dispute, does not attempt to apportion blame, and merely offers suggestions on terms of settlement which the disputants may accept or reject is","options":["an arbitrator","a prosecutor","a judge","a mediator"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"A mediator facilitates an amicable settlement and has no authority to make decisions that bind the parties. An arbitrator (option A) and a judge (option C) both find facts and decide who is right, while a prosecutor (option B) is a party who brings a criminal charge, not a neutral helper."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 276, $official_bank_source${"itemId":"3cf7c638-2635-513c-9155-200c12d7ba3e","questionId":"752d4c77-8b58-5c4b-9eba-bc6dec278756","sourceKey":"bank:PUL101:FAC-006","payload":{"prompt":"Which of the following statements about negotiation as a method of dispute resolution is correct?","options":["Negotiation requires a conciliator appointed by the Minister of Labour","Once a third party such as a mediator is brought in, it is no longer negotiation","Negotiation ends with a binding award that the parties cannot later challenge","Negotiation can only begin after a suit has been filed and served in court"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"Negotiation is the informal process in which the parties meet and settle their dispute themselves, so bringing in any third party changes its character. Option D is wrong because negotiation is usually the first attempt at resolving a conflict, option C describes arbitration, and option A describes statutory conciliation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 277, $official_bank_source${"itemId":"077e4877-d02d-5fea-b8f3-e2ea285d0d28","questionId":"dbc9166f-e4e6-50e7-bcb6-cfb47c1d6c18","sourceKey":"bank:PUL101:FAC-007","payload":{"prompt":"Which feature distinguishes the decision of a court in the adjudicatory method from the outcome of most non-adjudicatory methods?","options":["It is binding and self-executing without another tribunal","It depends entirely on the parties' later acceptance of it","It is reached without the court ascertaining any facts","It is kept confidential and can never be taken on appeal"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"A court judgment binds the parties and is self-executing, unlike most ADR outcomes. Option B describes mediation or reconciliation, whose terms the parties may accept or reject, option C is wrong because a court must first ascertain the facts before applying the law, and option D is wrong because court judgments may be reversed on appeal."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 278, $official_bank_source${"itemId":"f3206a72-2139-57c9-8384-a05f5ebb25e0","questionId":"f3170e49-b817-5abe-9e32-bbd99f48bb96","sourceKey":"bank:PUL101:FAC-008","payload":{"prompt":"The two main methods a judge or adjudicator may adopt in finding the facts of a dispute are the","options":["deductive and inductive methods","conciliation and arbitration methods","adjudicatory and non-adjudicatory methods","adversarial and inquisitorial methods"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"Once a dispute is before a court or tribunal, the adjudicator ascertains the facts either by the adversarial method or by the inquisitorial method. Option C names the two broad methods of dispute resolution, not of fact-finding, option A names forms of legal logic, and option B names forms of ADR."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 279, $official_bank_source${"itemId":"8667a37e-88cd-5a4e-b22a-1075d95f994f","questionId":"8b1a2b2a-edad-5a26-b9ca-779271197940","sourceKey":"bank:PUL101:FAC-009","payload":{"prompt":"In a trial, the process by which a party calls his own witness and tries to establish, through that witness, the evidence needed for the success of his case is known as","options":["examination-in-chief","cross-examination","address of counsel","re-examination"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"Examination-in-chief is the questioning of a witness by the party who called him. Cross-examination (option B) is done by the opposing counsel, re-examination (option D) only clears up matters arising from cross-examination, and the address (option C) is counsel's final argument, not the questioning of a witness."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 280, $official_bank_source${"itemId":"4c04775b-ca2d-58c6-bb5f-aa1fe534969b","questionId":"d74c2d12-6322-5891-92e7-dd54448be9e0","sourceKey":"bank:PUL101:FAC-010","payload":{"prompt":"What is the main object of cross-examination in the adversarial method?","options":["To allow the witness to explain any seeming inconsistency in his earlier answers","To weaken, neutralise or demolish the case of the party who called the witness","To enable the judge to investigate facts on his own initiative","To introduce the witness to the court before his evidence is taken"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"Cross-examination is conducted by counsel for the opposite party to test and break down the other side's case. Option A is the purpose of re-examination, option C describes the inquisitorial judge, and option D is not a purpose recognised for cross-examination."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 281, $official_bank_source${"itemId":"aa16b94b-4853-5727-8bc8-d60c3ce1f7ef","questionId":"dfd138de-73e3-51bf-912c-1de2637b2a4f","sourceKey":"bank:PUL101:FAC-011","payload":{"prompt":"In the adversarial method, the role of the judge is best likened to that of","options":["an umpire who ensures evidence is presented according to the ground rules","a prosecutor who presents and argues the case on behalf of the state","an investigator who gathers and tests evidence on behalf of both parties","a mediator who suggests terms of compromise acceptable to both parties"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"The adversarial judge is a neutral umpire who enforces the ground rules and decides on the evidence the parties choose to present. Option C describes the inquisitorial judge, option D describes ADR, and option B confuses the judge with a party."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 282, $official_bank_source${"itemId":"7501d2ba-8c65-59f9-a601-257ed5b3aa64","questionId":"d4f36fbb-e751-5dfe-9bf4-29e8a8d19522","sourceKey":"bank:PUL101:FAC-012","payload":{"prompt":"In a civil suit at the Lagos High Court for N2,500,000 owed on a supply contract, the judge privately knows of a witness whose evidence would decide the case, but neither counsel calls that witness. Under the adversarial method, what should the judge do?","options":["Decide on the evidence presented, without descending into the arena","Summon the witness himself and question him fully in open court","Adjourn the case until the plaintiff agrees to call that witness","Rely on his private knowledge of what the witness would have said"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"An adversarial judge must make up his mind on the evidence presented and must not search for evidence for the parties, even if the facts are known to him. Options B and C would make the judge take over the parties' role, and option D would mean deciding on evidence that was never tested in court."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 283, $official_bank_source${"itemId":"eca46d2b-0333-50ea-90fd-6b75d3ca8df8","questionId":"20c51196-05ae-56d3-ac34-20c2357540c9","sourceKey":"bank:PUL101:FAC-013","payload":{"prompt":"Which of the following is NOT one of the ground rules a judge enforces in an adversarial trial?","options":["A party must not take the other side by surprise at trial","A lawyer must not ask his own witness a leading question","Hearsay evidence is generally inadmissible at the trial","The judge may call his own witnesses to fill gaps in a case"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"In the adversarial method the judge may not call his own witnesses; he may question a witness only to clear an ambiguity. Options C, B and A are the ground rules of evidence and procedure that the umpire-judge enforces."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 284, $official_bank_source${"itemId":"6f9d0b42-59ee-5d1a-90d0-391a28add02c","questionId":"880db084-e76f-5e81-9611-7ba692f8615a","sourceKey":"bank:PUL101:FAC-014","payload":{"prompt":"In a civil trial, if the imaginary scale of justice tilts even 51% in favour of one party, judgment will be given in his favour. This describes proof","options":["beyond reasonable doubt","by res ipsa loquitur alone","on the balance of probabilities","beyond all possible doubt"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"Civil cases are decided on the balance of probabilities, so the party whose version is more probable wins, however narrowly. Option A is the higher criminal standard, option D is a standard the law does not require, and option B is a rule of evidence for accident cases, not a standard of proof."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 285, $official_bank_source${"itemId":"3924d1b4-dd71-5f80-8212-08f4f6723cf2","questionId":"fde434c2-04ee-5bbf-a3c7-99ceab64b815","sourceKey":"bank:PUL101:FAC-015","payload":{"prompt":"Kunle is charged with stealing N450,000 from his employer's shop in Yaba. The prosecution proves only that he was the last person seen near the till and that he had argued with the employer. On this evidence, what should the court do?","options":["Require Kunle to prove that he did not take the money","Convict him, because he failed to explain where the money went","Convict him, because the evidence makes his guilt more probable than not","Acquit him, because suspicion, no matter how grave, can never ground a conviction"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"In criminal cases the prosecution must prove guilt beyond reasonable doubt, and mere suspicion cannot ground a conviction. Option C applies the civil standard, while options A and B wrongly place on the accused a burden to prove his innocence, which the law does not impose."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 286, $official_bank_source${"itemId":"9b4b54ba-19b9-5a4b-afaa-56f565f7e26e","questionId":"402f6cdf-a6ac-5158-a053-37637aa060e0","sourceKey":"bank:PUL101:FAC-016","payload":{"prompt":"Which provision of the 1999 Constitution of the Federal Republic of Nigeria states that every person charged with a criminal offence shall be presumed innocent until he is proved guilty?","options":["Section 4(1)","Section 35(2)","Section 6(5)","Section 36(5)"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"Section 36(5) of the 1999 Constitution contains the presumption of innocence, which keeps the burden of proof on the prosecution. Section 35(2) (option B) gives an arrested person the right to remain silent, section 6(5) (option C) lists the superior courts, and section 4(1) (option A) vests legislative powers in the National Assembly."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 287, $official_bank_source${"itemId":"c9aa949b-d421-5a6a-a747-f5ec2665c9da","questionId":"47837283-f9bc-54ea-bbb7-9ee7d8a49c5d","sourceKey":"bank:PUL101:FAC-017","payload":{"prompt":"Ngozi is arrested in Onitsha on suspicion of fraud. At the police station she refuses to answer any question until she has spoken with a lawyer of her choice. Which constitutional right is she exercising?","options":["The right to be tried before an inquisitorial tribunal instead of a court","The right to have the complaint heard first by an independent arbitrator","The right to remain silent until she has consulted a lawyer of her choice","The presumption that an accused person is innocent until proved guilty"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"An arrested or detained person may remain silent or avoid answering any question until after consulting a legal practitioner of his choice. Option D is a related but different protection about who bears the burden at trial, while options A and B are not rights given to an arrested person."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 288, $official_bank_source${"itemId":"d91ea771-39ec-532a-91bf-2297bebb5295","questionId":"2fbe1ef4-ef91-5d96-9251-054f1792fd34","sourceKey":"bank:PUL101:FAC-018","payload":{"prompt":"The Latin expression res ipsa loquitur means","options":["the reason for the decision","the facts speak for themselves","it is for the court to know the law","let the decision stand"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"Res ipsa loquitur is a rule of evidence for accident victims: where the accident would not normally happen without someone's carelessness, the facts themselves suggest negligence. Option D translates stare decisis, option A translates ratio decidendi, and option C translates jura novit curia."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 289, $official_bank_source${"itemId":"b569b55a-c557-58bd-88ea-8a5c574ed894","questionId":"03e8933c-5ed4-5325-8658-dea37ff687b5","sourceKey":"bank:PUL101:FAC-019","payload":{"prompt":"After an abdominal operation at a private hospital in Ibadan, Mrs. Olu discovers that a surgical swab was left inside her. She sues the hospital. If she successfully relies on res ipsa loquitur, what is the effect?","options":["Mrs. Olu must first name the exact staff member who left the swab","The hospital must show a specific cause or that it used reasonable care","The case must be transferred to an arbitral tribunal for expert findings","The hospital becomes liable automatically and may offer no explanation"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"When res ipsa loquitur applies, the plaintiff need only show the accident and that she was its victim; the defendant must then explain it or show it used reasonable care. Option A is exactly what the rule relieves her of, option C has no basis, and option D is wrong because the defendant can still rebut the presumption."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 290, $official_bank_source${"itemId":"c721b3ed-0c64-56fd-8056-f3651faab4f0","questionId":"af2503b5-2ae4-50c6-86c0-1498aec40e31","sourceKey":"bank:PUL101:FAC-020","payload":{"prompt":"Which of the following is NOT an advantage of the adversarial method of fact-finding?","options":["It can enhance the development of the law through ingenious arguments by lawyers","It reduces the element of bias in the adjudicator","It gives each party the chance to present his case and discredit the other side's case","It ensures speedy disposal of cases because a time limit is usually prescribed for concluding them"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"Speed and prescribed time limits are advantages of the inquisitorial method; the adversarial method is in fact criticised for delay. Options B, C and A are recognised advantages of the adversarial method."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 291, $official_bank_source${"itemId":"76ef924d-0e14-538c-8fe0-43f4e9f6fe5b","questionId":"44d3b7ec-eb5b-576e-8c92-22769da0daa5","sourceKey":"bank:PUL101:FAC-021","payload":{"prompt":"The criticism that, under the adversarial method, those with the best lawyers (often the rich) are the most likely to win is described as the","options":["doctrine of res ipsa loquitur","presumption of innocence","sporting theory of justice","win-lose theory of ADR"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"The 'sporting theory' of justice is the complaint that the adversarial trial becomes a contest won by the side with the better lawyer. Option D refers to a different point about litigation's winner-takes-all character, and options B and A are rules of evidence and proof, not criticisms."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 292, $official_bank_source${"itemId":"4579c6e2-0c15-5f4d-8daf-1b2688f73574","questionId":"564da0f8-c9ce-5573-b65d-a26012d3f553","sourceKey":"bank:PUL101:FAC-022","payload":{"prompt":"A land dispute in Abeokuta has been in court for many years. Two key witnesses have died, another has relocated abroad, and the remaining witnesses can no longer recall events clearly. Which disadvantage of the adversarial method does this illustrate?","options":["Long delay may impair the fact-finding efficiency of the system","Multi-party disputes cannot be consolidated and heard together","Trials held in camera escape the scrutiny of the public and press","Hasty trials may lead to a miscarriage of justice for the parties"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"Because the parties control the pace of an adversarial case, long delays can occur, and over time witnesses die, relocate or forget, and evidence is lost. Options C and D are disadvantages of the inquisitorial method, and option B is a disadvantage of non-adjudicatory methods."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 293, $official_bank_source${"itemId":"23f5336a-c51a-511a-8684-5c728d5c2238","questionId":"e564947b-fa23-5c40-a56a-a14dff3d32e0","sourceKey":"bank:PUL101:FAC-023","payload":{"prompt":"What is the main distinguishing feature of the inquisitorial method of fact-finding?","options":["The adjudicator has considerable control over how evidence is collected and presented","The judge acts only as an umpire and may never question any of the witnesses","No facts are found and no blame is apportioned between the disputing parties","The parties and their lawyers alone decide which witnesses are called and when"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"In the inquisitorial method the adjudicator can enter the arena, investigate facts, question parties and witnesses and even appoint expert assessors. Options D and B describe the adversarial method, and option C describes non-adjudicatory methods."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 294, $official_bank_source${"itemId":"f4359127-d51c-56eb-8cf9-c9bd9d5c5237","questionId":"718391af-b84f-55d3-a14e-4233c2a4f6e7","sourceKey":"bank:PUL101:FAC-024","payload":{"prompt":"A statutory benefits tribunal relied partly on the written opinions of two doctors who never appeared before it, so the claimant could not cross-examine them. The court held this was not a breach of natural justice. What principle does this illustrate?","options":["A tribunal must act purely as a neutral umpire between the two parties","Any evidence not tested by cross-examination is always inadmissible anywhere","An inquisitorial body may rely on expert opinions of persons not before it","Expert medical opinions can only ever be received by arbitral tribunals"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"This reflects the inquisitorial character of such tribunals, which may form their own view and rely on experts not personally before them, as in the Ex parte Moore case. Option B states an adversarial rule too absolutely, option A describes the adversarial judge, and option D has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 295, $official_bank_source${"itemId":"f2e4cef6-2d04-5469-a5c4-62c09bbdec96","questionId":"02e3be86-4994-5486-9af2-dab8235ddec0","sourceKey":"bank:PUL101:FAC-025","payload":{"prompt":"Titi was caught cheating in an examination. The invigilator recorded the facts on the official irregularity form, which Titi countersigned as true, and then travelled abroad. An Examination Malpractices Panel found her guilty on the form alone. Titi argues the panel erred because the invigilator was not present to be cross-examined. Her argument is likely to","options":["fail, because the inquisitorial panel may rely on the signed report","fail, because students have no right to be heard by any panel at all","succeed, because only an arbitrator may ever rely on written reports","succeed, because every tribunal must follow the full adversarial procedure"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"An examination panel is not a regular court and adopts an inquisitorial approach, so the absence of cross-examination does not by itself vitiate a report she countersigned. Option D wrongly assumes all tribunals are adversarial, option C has no basis, and option B overstates the position because she is still entitled to a fair opportunity to defend herself."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 296, $official_bank_source${"itemId":"d1d63f04-4387-53cb-8f81-7f2833513d0e","questionId":"bc10ada5-3167-5182-ac26-5597a4e1ecf7","sourceKey":"bank:PUL101:FAC-026","payload":{"prompt":"The saying 'justice rushed is justice crushed' is used to describe which disadvantage of the inquisitorial method?","options":["Parties may use delay tactics to frustrate the other side","Lawyers may procure witnesses to lie on oath","Miscarriage of justice may result from a hasty trial","The decision is not binding on the parties"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"An investigative body working to a deadline may ignore important details, so a hasty trial can produce injustice. Options A and B are disadvantages of the adversarial method, and option D is wrong because inquisitorial decisions bind the parties."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 297, $official_bank_source${"itemId":"bd68ba0a-0cae-5659-bcea-0fd147aacd41","questionId":"1613deac-f819-5e66-bbef-eae026cb0a52","sourceKey":"bank:PUL101:FAC-027","payload":{"prompt":"A special tribunal tried and convicted several officers for an alleged coup plot in closed sessions, with no members of the public or press allowed. Critics later argued the coup never existed. Which disadvantage of the inquisitorial method does this illustrate?","options":["Delay that impairs fact-finding as witnesses die or forget","The sporting theory of justice, which favours the richer party","Inquisitions held in camera are not open to public scrutiny","Inability to consolidate multi-party disputes in one hearing"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"Many inquisitions are conducted in camera, so mistakes or abuses escape public scrutiny; the convictions of officers for phantom coups are given as an example. Options B and A are criticisms of the adversarial method, and option D is a disadvantage of ADR."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 298, $official_bank_source${"itemId":"9ede35b2-2c0e-5778-a295-0cad752c189f","questionId":"7f25e056-4e65-507c-bbab-d798117e1cd2","sourceKey":"bank:PUL101:FAC-028","payload":{"prompt":"Which of the following correctly distinguishes the adjudicatory method from the non-adjudicatory method of dispute resolution?","options":["Adjudication involves fact-finding and apportioning blame; ADR generally does not","ADR is unknown to law and has no rules, while adjudication is regulated by statute","ADR always takes place in a formal court, while adjudication takes place outside it","Adjudication relies only on reconciliation, while ADR relies on state-appointed judges"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"Adjudication finds facts by adversarial or inquisitorial procedure and apportions blame; ADR generally does neither. Option C reverses the formal and informal settings, option D reverses the methods, and option B is wrong because the law recognises ADR and lays down rules for it."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 299, $official_bank_source${"itemId":"2c844b57-bfcc-5a95-95bd-a0864f14e9b2","questionId":"fcb1bf76-c320-5f98-bd55-25bdacfc0d8d","sourceKey":"bank:PUL101:FAC-029","payload":{"prompt":"How does the task of a judge in the adjudicatory method generally differ from that of a non-adjudicator such as a mediator?","options":["The judge suggests compromise terms, while the non-adjudicator applies the law strictly to past events","The judge applies the law to past events, while the non-adjudicator suggests solutions for future harmony","The judge's task is mainly to reconcile the parties, while the non-adjudicator punishes the wrongdoer","Both of them are bound to apply the rules of evidence strictly before reaching any decision"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"A judge's task is generally not to reconcile the parties but to examine past events and apply the law, whereas a non-adjudicator tries to reconcile them by suggesting solutions. Options A and C reverse the two roles, and option D is wrong because ADR is free from the strict rules of evidence."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 300, $official_bank_source${"itemId":"3b6417b8-58ef-5097-83ae-c907c3d5c650","questionId":"4ea7cc64-05fb-5932-b6ca-c8beec842a51","sourceKey":"bank:PUL101:FAC-030","payload":{"prompt":"Which of the following is NOT an advantage of the non-adjudicatory method of dispute resolution?","options":["It enables the parties to control their own fate instead of a judge","It saves time and avoids the delays and uncertainties of court trials","It allows multi-party disputes to be consolidated and heard together","Proceedings are free from the formalities of the rules of evidence"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"ADR does not allow consolidation of actions, because it depends on voluntary agreement and parties cannot be compelled to join; this is a disadvantage. Options B, A and D are recognised advantages of ADR."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 301, $official_bank_source${"itemId":"1a8d1476-39c6-51cc-84b0-ec416615326b","questionId":"9a177f11-09e1-5464-aa2f-7855fcfc6757","sourceKey":"bank:PUL101:FAC-031","payload":{"prompt":"A Kano textile company and a foreign supplier settle a N40,000,000 dispute by arbitration. They must hire a hall for the hearings and jointly pay the arbitrators' fees and administrative expenses. Which feature of the non-adjudicatory method does this reflect?","options":["It requires the parties to prove their facts beyond reasonable doubt","It is self-executing like a court judgment without any agreement","It is not financed by the state, so the parties bear its costs","It is conducted by a state-appointed judge in a public courtroom"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"ADR is not funded by the state: the parties hire venues and pay the arbitrators' fees and expenses, which can be substantial in international commercial cases. Option B misstates the basis of arbitration, which rests on agreement, option D describes litigation, and option A is the criminal standard of proof."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 302, $official_bank_source${"itemId":"d64cb2a5-631b-5a4a-b97e-705f5115f096","questionId":"2abfc348-3940-5895-aa90-9f5fb822b5fc","sourceKey":"bank:PUL101:FAC-032","payload":{"prompt":"Which of the following is NOT an essential element of arbitration?","options":["The arbitrator must be a serving judge of a High Court","The arbitrator's decision (award) must be binding on the parties","There must be an existing dispute, or one the parties envisage arising in future","The parties must have voluntarily agreed to refer the dispute to arbitration"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"An arbitrator is an independent third party chosen by the parties, often a professional with technical knowledge, not a serving judge. Options C, D and B are the three essential elements before a process can be called arbitration."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 303, $official_bank_source${"itemId":"fadd91b0-d359-5f09-9888-5302c3b2b319","questionId":"88fcd33b-f9e3-52df-b2e1-33872956ecb3","sourceKey":"bank:PUL101:FAC-033","payload":{"prompt":"A charter contract between a Lagos shipping firm and a foreign ship owner contains a clause referring all disputes to arbitration. When a dispute arises, the Lagos firm goes straight to the Federal High Court. How is the court likely to respond?","options":["It will refer the dispute to reconciliation between the two firms instead of arbitration","It will hold the firm to the clause, as it cannot approbate and reprobate the contract","It will ignore the clause, because only the regular courts can resolve shipping disputes","It will hear the case and treat the arbitration clause as no more than a suggestion"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"Where parties have agreed to arbitrate, courts have a prima facie duty to act on that agreement, and going to court in breach of it is reprobating the contract (M.V. Lupex case). Options C and D contradict the courts' attitude to valid arbitration clauses, and option A has no basis in the clause."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 304, $official_bank_source${"itemId":"71116deb-5bf4-56e8-9206-6a09357bbca1","questionId":"1900c2cc-e539-5e39-ade9-b07664eee95a","sourceKey":"bank:PUL101:FAC-034","payload":{"prompt":"A dispute between an Abuja estate developer and a contractor turns on whether concrete used in a building met engineering specifications. The parties appoint a structural engineer as arbitrator. Which advantage of arbitration does this choice illustrate?","options":["The arbitrator's decision is never binding on the parties who appointed him","The arbitrator is often a specialist with technical knowledge, unlike a judge","The process allows many unrelated parties to be joined and heard together","The state pays the arbitrator's fees and the cost of the hearing venue"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"An arbitrator is often an independent professional with technical knowledge and experience of the subject, which improves fact-finding. Option A is wrong because an award binds the parties, option C is wrong because ADR does not allow consolidation, and option D is wrong because the parties pay the fees."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 305, $official_bank_source${"itemId":"45b13a8b-37cd-5bd6-927d-61fcea4e1ee0","questionId":"a5c64d8d-028f-5348-9df2-7e25f3a7360d","sourceKey":"bank:PUL101:FAC-035","payload":{"prompt":"The decision of a conciliator is generally only a guide. In which situation can the terms reached through conciliation become binding by law in Nigeria?","options":["In a trade dispute, once the signed memorandum of settlement is reported to the Minister","In any family dispute, once the elders of the family publicly announce the agreed terms","Never, because the outcome of a conciliation can never be binding on anyone by law","In any commercial dispute, once the conciliator writes and signs his own final report"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"Under the Trade Disputes Act, a conciliator appointed for a trade dispute who achieves a settlement reports it to the Minister, and the signed memorandum of terms binds the employers and workers; breach is an offence. Options B and D have no such legal backing, and option C ignores this statutory exception."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 306, $official_bank_source${"itemId":"b0e82e5e-f64f-5587-bc89-544d1f694b3c","questionId":"08c03e04-ef04-564c-b071-8e284603ed93","sourceKey":"bank:PUL101:FAC-036","payload":{"prompt":"Which statement about the decision reached through mediation is correct?","options":["It binds the parties only if it apportions the blame","It can be enforced as a court judgment without agreement","It does not bind the parties, even in a trade dispute","It binds the parties once the mediator signs it"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"A mediator has no authority to make binding decisions; he only helps the parties negotiate, and his decision does not bind them even in a trade dispute. Options D and B wrongly give the mediator a decision-making power, and option A is wrong because a mediator does not apportion blame at all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 307, $official_bank_source${"itemId":"5ffee546-5ab7-5eeb-a9c3-75f0f81338f6","questionId":"b40a6478-8bb9-5c4a-889f-4f56629977d9","sourceKey":"bank:PUL101:FAC-037","payload":{"prompt":"In the Middle Ages, disputes were often 'resolved' by subjecting disputants to terrible ordeals, and survival was taken as proof of innocence. What is the position of trial by ordeal in Nigeria today?","options":["It is a recognised form of alternative dispute resolution","It is permitted in customary courts only","It is prohibited by the Criminal Code","It is allowed if both parties consent in writing"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"Trial by ordeal, a method of 'proof' rather than trial, is now prohibited by the Criminal Code; modern dispute resolution relies on objective standards and procedures. Options A, D and B wrongly suggest that such crude methods still have legal recognition."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 308, $official_bank_source${"itemId":"f542b931-0f5f-5884-882f-813ab17a34fd","questionId":"db4f7b03-9db3-548d-a721-0e8bd6c8dda7","sourceKey":"bank:PUL101:FAC-038","payload":{"prompt":"Four co-tenants in a 'face-me-I-face-you' house in Ajegunle suspect one another after Mrs. A's jewellery box goes missing. Mrs. A wants to find the thief by 'tying the Holy Book with a key' and calling each name. Mrs. C refuses to take part, and the others conclude she is the thief. Which advice is correct?","options":["The method is a valid form of mediation because the other co-tenants agreed","The method is outlawed, and Mrs. C's refusal is not proof of her guilt","Mrs. A must first prove her own innocence before she can report to the police","Mrs. C's refusal is sufficient evidence for a court to convict her of theft"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"Methods like the Holy Book and key are similar to the old ordeals; they are no longer acceptable and have been criminalised, so refusing to take part is not evidence of guilt. If the matter goes to court, guilt must be proved beyond reasonable doubt, which rules out option D; option A misdescribes mediation, and option C has no basis in law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 309, $official_bank_source${"itemId":"97a1e0a9-9554-5bbe-9c02-1ec7d02c719e","questionId":"e3322d01-3edc-54d3-a8f2-5ab56ba649b8","sourceKey":"bank:PUL101:FAC-039","payload":{"prompt":"Under the Evidence Act 2011, which of the following falls within the definition of a 'fact'?","options":["A rule of law contained in a statute","An opinion expressed by a judge in passing","A decision of the Supreme Court on a point of law","Any mental condition of which a person is conscious"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"A fact includes anything, state of things or relation of things capable of being perceived by the senses, and any mental condition of which a person is conscious. Options A, C and B are matters of law or legal opinion, not facts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 310, $official_bank_source${"itemId":"06e78d13-4d8f-58d0-a3a7-77bf56886da0","questionId":"241b27de-3022-533d-a00e-991d547c67af","sourceKey":"bank:PUL101:FAC-040","payload":{"prompt":"In a civil case, 'facts in issue' are best described as","options":["all the facts mentioned by any of the witnesses at any stage of the trial","the facts the judge discovers through his own investigation of the dispute","the rules of law which the court must apply in deciding the case before it","the facts a plaintiff must prove to establish his claim, unless admitted"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"Facts in issue are those facts the plaintiff must prove to establish his claim unless the defendant admits them expressly or by implication, and only these need to be proved. Option A is too wide, option C confuses facts with law, and option B describes inquisitorial investigation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 311, $official_bank_source${"itemId":"e958f996-17ad-5bff-863a-2c72bc7af04a","questionId":"8bc5c69c-577e-5ad0-9ffb-2e4e7704834d","sourceKey":"bank:PUL101:FAC-041","payload":{"prompt":"The term 'burden of proof' is used in two senses. In which sense is 'shifting of fact' a shifting of the burden of proof?","options":["The legal burden to persuade the court that the whole case is established","The evidential burden: the duty to adduce evidence on a particular fact","The duty of the judge to know and apply the law relevant to the case","The obligation of the prosecution to prove guilt beyond reasonable doubt"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"Burden of proof means either the obligation to establish one's whole case (the legal burden) or the obligation to adduce evidence on a particular fact (the evidential burden); shifting of fact refers to the evidential burden. Option A is the burden that does not shift in this way, option C relates to shift of law, and option D is the prosecution's overall burden in criminal cases."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 312, $official_bank_source${"itemId":"a43291f7-a3e8-53b2-bcea-10a4ef903487","questionId":"3fac3aa0-372d-5ebd-8323-17b6151b9872","sourceKey":"bank:PUL101:FAC-042","payload":{"prompt":"The Latin maxim affirmanti non neganti incumbit probatio means that","options":["it is for the court, not the parties, to know the law","the burden of proof lies on the one who affirms, not the one who denies","ignorance of the law is no excuse for anyone who breaks it","the decision of a higher court must be followed by lower courts"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"The maxim places the burden of proving a fact on the party who asserts it, so when a defendant denies the plaintiff's claim, the plaintiff must prove it. Option C translates ignorantia juris non excusat, option A translates jura novit curia, and option D describes stare decisis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 313, $official_bank_source${"itemId":"299938e7-a7de-5634-8d3f-2ffd05729f37","questionId":"31ad0970-e2c2-5c92-b2a2-26ce90e99276","sourceKey":"bank:PUL101:FAC-043","payload":{"prompt":"Emeka sues Bayo for N60,000, the balance of the N150,000 price of a laptop. Bayo denies that he ever promised to pay any balance. Emeka then produces a memorandum of the payment terms signed by Bayo. On whom does the evidential burden now lie?","options":["On neither party, because the case must go to mediation","On Bayo, to prove that the signed memorandum is not genuine","On the judge, who must investigate the memorandum himself","On Emeka, who must now prove the case beyond reasonable doubt"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"Emeka first bore the burden because he affirmed the promise, but once he produced the signed memorandum, the evidential burden shifted to Bayo to disprove it. Option D applies the criminal standard to a civil case, option C describes inquisitorial investigation, and option A has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 314, $official_bank_source${"itemId":"374428ca-3e4a-5471-bc5b-580949bdb144","questionId":"709096e8-4966-53d5-8726-d0df2f8d2c99","sourceKey":"bank:PUL101:FAC-044","payload":{"prompt":"A landlord sues his tenant for N300,000 unpaid rent. In his defence, the tenant admits that the rent was due but states that he had already paid it to the landlord's agent. What is this type of defence called, and who must prove the payment?","options":["Per incuriam; the court must summon the agent to testify","Res ipsa loquitur; the landlord must now prove non-payment","Stare decisis; the agent must prove that he received payment","Confessing and avoiding; the tenant must prove the payment"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"When a defendant admits the allegation but supplies new facts that put a different complexion on the case, he is confessing and avoiding, and the burden of proving those new facts lies on him. Option B is a rule for accident cases, while options A and C are doctrines of judicial precedent."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 315, $official_bank_source${"itemId":"cf7bc44a-c4c9-5bb4-9df0-84bb5da02f3b","questionId":"c76e7f91-22e5-5c21-8e30-dda487041287","sourceKey":"bank:PUL101:FAC-045","payload":{"prompt":"Aisha sues Tunde for N80,000 owed on a sale of goods. In his statement of defence, Tunde expressly admits that he promised to pay the N80,000 within two weeks and failed to do so. What is the effect on Aisha's burden regarding these facts?","options":["The admission must be ignored unless Tunde gives oral evidence","She must still prove the admitted facts beyond reasonable doubt","The burden shifts to the judge to prove the facts","She is discharged of the burden of proving the admitted facts"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"Only facts in issue, those not admitted, need to be proved; once Tunde admits the promise and the failure to pay, Aisha no longer has to prove them. Option B applies the criminal standard and ignores the admission, option C confuses shift of fact with shift of law, and option A has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 316, $official_bank_source${"itemId":"dc79261c-6974-5132-b50d-9369e9b7b2b8","questionId":"92eb73d2-85ec-5d30-b66f-979c093bdf09","sourceKey":"bank:PUL101:FAC-046","payload":{"prompt":"In criminal cases the burden of proving facts generally rests on the prosecution. Which of the following is NOT an exception where the burden of proving certain facts shifts to the accused?","options":["Where special facts are within the knowledge of the accused","Where the accused raises the defence of insanity or intoxication","Where the accused simply pleads not guilty and denies the charge","Where a statute specifically places the onus of proving certain facts on the accused"],"correctOption":2,"section":"Fact Finding and Dispute Resolution","explanation":"A plain denial does not shift any burden; the prosecution must still prove every element of the offence. Options B, A and D are recognised exceptions, together with the case where the accused claims an exemption or qualification under the law creating the offence."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 317, $official_bank_source${"itemId":"e960175f-0dc9-5d66-be27-1298b274ae2c","questionId":"bf9ddd24-d48a-5a5f-ba2d-1e7285999c6c","sourceKey":"bank:PUL101:FAC-047","payload":{"prompt":"The maxim ignorantia facti excusat, ignorantia juris non excusat means","options":["the facts speak for themselves, but the law must be proved","the ignorance of the judge is the calamity of the innocent","the burden of proof lies on the one who affirms a fact","ignorance of fact excuses, but ignorance of law does not"],"correctOption":3,"section":"Fact Finding and Dispute Resolution","explanation":"This maxim separates fact from law: a genuine mistake of fact may excuse, but no one can rely on not knowing the law. Option A mixes res ipsa loquitur with an invented clause, option C translates affirmanti non neganti incumbit probatio, and option B translates ignorantia judicis est calamitas innocentis."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 318, $official_bank_source${"itemId":"326b5a0d-688c-52f7-89be-9e05f0c5b57c","questionId":"a6f5b7e7-97c6-59f4-a821-1e44c771991e","sourceKey":"bank:PUL101:FAC-048","payload":{"prompt":"In a contract case at the Ikeja High Court, neither counsel cites a statutory provision that clearly governs the dispute. Under the principle jura novit curia, what is the position?","options":["The burden of applying the law shifts to the judge, who must know it","The judge must decide only on the facts and leave the statute aside","The case must be struck out because the parties failed to prove the law","The plaintiff loses automatically because he bears the burden of proof"],"correctOption":0,"section":"Fact Finding and Dispute Resolution","explanation":"Jura novit curia means it is for the court to know the law, so where counsel fail to cite a relevant law, the burden of applying it rests on the judge. Options C and D treat law as if it were a fact the parties must prove, and option B would mean ignoring the applicable law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 319, $official_bank_source${"itemId":"6d998210-3ab6-5769-8899-dc074a5843eb","questionId":"b5fe78f9-cb7a-568b-a895-cbd7ab65b0fb","sourceKey":"bank:PUL101:FAC-049","payload":{"prompt":"In a debt recovery suit, the defendant's counsel relies on a section of a state law, unaware that it was repealed last year. The plaintiff's counsel knows of the repeal. On whom does the burden of informing the court of the repeal fall?","options":["On no one, since repealed laws apply until the court discovers the repeal","On the plaintiff's counsel, who has knowledge of the repeal","On the court registrar","On the defendant's counsel, since he cited the law"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"Shifting of law arises where a party relies on a law not knowing it has been amended or repealed; the burden of informing the court then shifts to the person who knows of the change. Option D puts the burden on the party who does not know, option C has no basis, and option A is wrong because a repealed law is no longer in force."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 320, $official_bank_source${"itemId":"dace29c9-4e65-5fd2-9a94-b735aaaa7534","questionId":"b25551a0-a665-579d-b94b-e1f7fb137020","sourceKey":"bank:PUL101:FAC-050","payload":{"prompt":"Bassef is charged with murder after being found with human remains; he claims they came from accident victims. The prosecution fails to cross-examine him on this defence and does not call a vital witness, and the judge notices this. Which conclusion is most consistent with the adversarial method?","options":["The case should be sent to mediation because the evidence before the court is incomplete","The judge cannot call the witness; the unchallenged defence stands and doubt favours Bassef","Bassef must now prove beyond reasonable doubt that he did not kill anyone at all","The judge should call the vital witness himself to complete the prosecution's case"],"correctOption":1,"section":"Fact Finding and Dispute Resolution","explanation":"An adversarial judge must not descend into the arena, evidence not challenged in cross-examination is taken as admitted, and the prosecution must prove guilt beyond reasonable doubt with doubts going to the accused. Option D makes the judge take over the prosecution, option C reverses the burden, and option A is not open in a murder trial."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 321, $official_bank_source${"itemId":"4909fa40-dabe-5740-a0a2-2b61aac42da6","questionId":"7787d5d9-2fbd-51fa-97f8-a892f647b632","sourceKey":"bank:PUL101:PQ-007-01","payload":{"prompt":"A principle of law can best be described as","options":["a comment made by a judge in passing that does not bind later courts","a prediction of how a particular judge will decide a case","an established legal truth or proposition that cannot be contradicted except by a clearer proposition, and from which rules are developed","a specific instruction that applies to one fixed set of facts only"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Principles such as the rule of law, separation of powers and supremacy of the Constitution are broad guideposts by which laws, decisions and arguments are judged, and specific rules grow out of them. Option D describes a rule rather than a principle, Option A describes an obiter dictum, and Option B is the realist view of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 322, $official_bank_source${"itemId":"b3935436-51fb-53f1-b49b-5921f3063c0e","questionId":"aae53008-7fea-59c4-8bd7-34c2f47f55ab","sourceKey":"bank:PUL101:PQ-007-02","payload":{"prompt":"The two rules developed from the principle of natural justice are","options":["ejusdem generis and noscitur a sociis","audi alteram partem (hear the other side) and nemo judex in causa sua (no one should be a judge in his own cause)","stare decisis and ratio decidendi","actus reus and mens rea"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Natural justice is a principle, and these two specific rules apply it: a party must not be condemned unheard, and a judge must not decide his own case. Option A are maxims of statutory interpretation, Option C relate to judicial precedent, and Option D are elements of a crime."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 323, $official_bank_source${"itemId":"61f18882-caf6-5237-885f-9dd711d51e99","questionId":"7015877b-fa48-56f0-b9fc-24c8417ea709","sourceKey":"bank:PUL101:PQ-007-03","payload":{"prompt":"In the law of negligence, a defendant's conduct is measured against what a reasonable man would have done in the circumstances. This measure is best described as a legal","options":["maxim of statutory interpretation","ratio decidendi","standard","syllogism"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A legal standard is a flexible measure of conduct, like the reasonable man test, that the judge applies according to the circumstances of each case instead of a fixed, detailed rule. Option B is the binding reason for a particular decision, Option A is a guide for reading statutes, and Option D is a form of deductive argument."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 324, $official_bank_source${"itemId":"d0e78123-057f-5a22-b98d-93bbea4606b0","questionId":"72755b85-070f-5b0f-8d52-cb0b7164328b","sourceKey":"bank:PUL101:PQ-007-04","payload":{"prompt":"Rhetoric, as used in law, is","options":["the strict deduction of a conclusion from a major and a minor premise","the process by which a bill becomes law","the study of the customs of a people","the art of persuading another, in speech or writing, to accept one's position or view"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Legal rhetoric is the art of persuasion, which is why lawyers must master language and the use of authorities. Option A describes deductive logic (syllogism), Option C relates to the Historical School, and Option B is the legislative process."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 325, $official_bank_source${"itemId":"66a052a3-9484-5fc3-bd53-4ba083b93fdc","questionId":"56f796fb-8445-50b7-8fac-f57e35bd6069","sourceKey":"bank:PUL101:PQ-007-05","payload":{"prompt":"Aristotle distinguished forensic rhetoric from deliberative rhetoric. Broadly, which form do lawyers use when arguing for their clients?","options":["Deliberative rhetoric","Forensic rhetoric","Analogical rhetoric","Inductive rhetoric"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Lawyers represent their clients' interests and seek to persuade the court, which is forensic rhetoric, while judges broadly use deliberative rhetoric because they must reach a reasoned decision justifiable to the parties and society. Option A is therefore the judges' form, and Option D and Option C are not Aristotle's categories of rhetoric."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 326, $official_bank_source${"itemId":"cb685772-d83d-5851-9e08-511c57026252","questionId":"ed9af712-2a08-58f0-a05e-47f283856481","sourceKey":"bank:PUL101:PQ-007-06","payload":{"prompt":"The principal rhetorical device used in law is","options":["the use of Latin phrases","personal attacks on the opposing counsel","the appeal to authority, that is, citing statutes and decided cases to support a position","appeal to the emotions of the judge"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Lawyers persuade mainly by showing that statutes and judicial decisions support their argument; writers' opinions and foreign decisions are only persuasive. Option D and Option B are not proper legal persuasion, and Option A is a feature of legal language, not the main rhetorical device."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 327, $official_bank_source${"itemId":"c1a6bf8f-ef49-5bd7-9219-f040ed3e58d5","questionId":"84482e15-0fd5-5bc2-bed8-247ea3f11313","sourceKey":"bank:PUL101:PQ-007-07","payload":{"prompt":"Consider this argument: \"Any person under 18 cannot join in forming a company. Seyi is under 18. Therefore Seyi cannot join in forming a company.\" The statement \"Seyi is under 18\" is the","options":["major premise","ratio decidendi","conclusion","minor premise"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"In a syllogism, the major premise is the general rule (here, the statutory provision), the minor premise states the facts of the case (Seyi's age), and the conclusion follows from both. So Option A is the age rule, Option C is the final statement, and Option B is a term for the binding reason in a court decision, not a part of a syllogism."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 328, $official_bank_source${"itemId":"aac3b5d0-113c-5cd1-8d2e-043fe87e4afe","questionId":"b4a3d950-0d85-5eee-a6be-fb0d9bc0f857","sourceKey":"bank:PUL101:PQ-007-08","payload":{"prompt":"Deductive and inductive logic differ in that","options":["deductive logic relies on case law, while inductive logic relies only on statutes","deductive logic reasons from particular cases to a general principle, while inductive logic reasons from the general to the particular","deductive logic is used only by judges, while inductive logic is used only by legislators","deductive logic reasons from the general to the particular, while inductive logic reasons from particular cases to a general principle"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Deduction applies a general rule, often a statute, to the facts to reach a conclusion, while induction studies several decided cases to build up a general principle. Option B reverses the two. Option C is wrong because lawyers and judges use both, and Option A is backwards because reasoning from case law is typically inductive."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 329, $official_bank_source${"itemId":"061525ce-47f8-5efd-b009-71cce61a74b1","questionId":"506abb84-34f1-53f2-b2a2-9cfff4b109c8","sourceKey":"bank:PUL101:PQ-007-09","payload":{"prompt":"A syllogism can be logically valid even though its conclusion is false. This is because","options":["a valid syllogism always has a true conclusion","validity and truth mean exactly the same thing","a syllogism can never contain a false premise","validity only means the conclusion follows from the premises, while truth depends on whether the premises match the facts"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Logic tests whether a conclusion follows from the premises, not whether the premises are true, so a wrong premise accepted as true will give a valid but false conclusion. This is why a lawyer must spot a witness who is logical but lying. Option A, Option B and Option C all ignore this difference between truth and validity."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 330, $official_bank_source${"itemId":"40610ac5-20ba-5e82-bfe2-a764d68188dd","questionId":"6f9ad492-d794-5e32-81a4-1fd3d9bbe105","sourceKey":"bank:PUL101:PQ-007-10","payload":{"prompt":"How does practical reasoning differ from formal legal logic?","options":["It is not tied to deduction or induction; it weighs various considerations, often uses analogy, and its conclusions are judged by society's values","It ignores the values of society and focuses only on formal validity","It relies strictly on a major premise, a minor premise and a conclusion","It can only be used by legislators when drafting bills"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Practical reasoning balances many factors to reach a justifiable conclusion, and whether that conclusion is good or bad depends on the society's prevailing values, which can change over time. Option C describes a syllogism, Option B is the opposite of practical reasoning, and Option D is too narrow because judges and lawyers use it daily."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 331, $official_bank_source${"itemId":"a31454a1-640b-5261-9d1c-5cb2b8c3b5dd","questionId":"1e0311a2-b4b0-5b9a-850f-5effbe6256cb","sourceKey":"bank:PUL101:PQ-007-11","payload":{"prompt":"The statement \"The life of the law has not been logic but experience\" is attributed to","options":["Hans Kelsen","Jeremy Bentham","Oliver Wendell Holmes","John Austin"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Holmes made this point to show that law develops by constantly testing rules against real-life needs and dropping those that can no longer be supported, not by logic alone. Option D, Option A and Option B are known for more formal or utility-based accounts of law."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 332, $official_bank_source${"itemId":"9bcb16f3-a861-52d9-bf28-42803aaa551a","questionId":"9662ac67-6ee1-55c8-9855-df0ffabed69d","sourceKey":"bank:PUL101:PQ-007-12","payload":{"prompt":"Apart from appeal to authority, which of the following is NOT a factor judges properly use to justify their decisions?","options":["Public policy and the view of a reasonable man","The judge's personal likes and dislikes about the parties","Whether the consequences of the decision are acceptable in terms of justice","Coherence of the decision with existing principles and authorities"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A judge must give a reasoned justification, drawing on coherence with existing law (Option D), the justice of the consequences (Option C), and common sense, the reasonable man and public policy (Option A). Personal prejudices are exactly what proper justification is meant to keep out."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 333, $official_bank_source${"itemId":"f8d5c9d8-aa47-5f81-b840-ee7dedcc2992","questionId":"d44d9e06-bfc9-5f36-8f53-db60b458c992","sourceKey":"bank:PUL101:REA-001","payload":{"prompt":"Legal reasoning is best defined as","options":["the memorisation of statutes and decided cases for the purpose of examinations","systematic, logical, coordinated and persuasive thinking or argument on legal issues","the personal opinion of a judge about what is fair, without giving reasons","the use of Latin, French and archaic English words in court proceedings"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Legal reasoning combines 'reasoning' (thinking in a coordinated, orderly and logical way) with 'legal' (connected with law). Option A is mere recall, option D is a feature of legal language, and option C ignores the need for logic and justification."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 334, $official_bank_source${"itemId":"d23bc59e-710c-5c1e-b9db-352f68ac95bd","questionId":"41a9a357-0129-5e45-96cb-f0fb06a3224b","sourceKey":"bank:PUL101:REA-002","payload":{"prompt":"Section 316 of the Criminal Code makes a person guilty of murder if he unlawfully kills another under listed circumstances, without naming any weapon, so it covers shooting, stabbing, poisoning or strangling. Which feature of legal language does this illustrate?","options":["Law is always expressed in highly specific language","Law is usually expressed in general terms","Law uses argot or jargon","Law uses archaic English words"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Laws are drafted generally because they must apply to many people in different circumstances, so one provision can cover every method of intentional unlawful killing. Options D and C are other features of legal language not shown here, and option A is the opposite of what the provision does."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 335, $official_bank_source${"itemId":"41c5f8f4-8ec8-5501-8e45-96a33e941769","questionId":"54326545-cf28-520b-bc5e-5fcb16769fa4","sourceKey":"bank:PUL101:REA-003","payload":{"prompt":"Donoghue v Stevenson concerned a snail in a bottle of ginger beer, yet its principle is stated as 'a manufacturer of consumer goods owes a duty of care to the final consumer'. Why is the principle expressed at this higher level of generality?","options":["Because principles must always be stated as widely as possible, without limits","Stating it only as snails in ginger beer would hinder the growth of case law","Because ginger beer is not regarded in law as a consumer good at all","Because the House of Lords was not sure of the actual facts of the case"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"If the case were limited to its exact facts, it could only be a precedent for snails in ginger beer, which would not help future cases such as germs in canned milk. Option D has no basis, option A is wrong because the principle is kept within limits (for example consumable goods and proven health problems), and option C is untrue."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 336, $official_bank_source${"itemId":"a58ca7eb-7a77-58e4-8bcd-95b843117c1c","questionId":"fac92186-b588-558b-810c-c8ff80bda851","sourceKey":"bank:PUL101:REA-004","payload":{"prompt":"Section 6(5) of the 1999 Constitution does not speak generally of 'superior courts' but lists them one by one: the Supreme Court, the Court of Appeal, the Federal High Court, a State High Court, a Sharia Court of Appeal and a Customary Court of Appeal. This shows that","options":["law can never be expressed in general terms in a written constitution","the list is an obiter dictum of the legislature with no binding force","law can be expressed in highly specific language when no doubt is intended","the Constitution here uses abstract concepts in order to save words"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Although law is usually general, it can be made highly specific where the lawmaker wants no doubt about its application, as with this list of courts. Option A overstates the point, option D describes a different feature, and option B misuses a term that belongs to judgments."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 337, $official_bank_source${"itemId":"1b674f50-6467-5085-b694-e70df8239120","questionId":"c534e0e2-9167-53da-9992-b235420d6a8e","sourceKey":"bank:PUL101:REA-005","payload":{"prompt":"What is the main advantage of using abstract legal concepts such as 'rule of law', 'legal personality' or 'possession'?","options":["They make the law easily understandable to every layman in society","They allow lawyers to invent any meaning they like for ordinary words","They achieve economy of words by avoiding a full list of details","They remove the need for legal reasoning in the interpretation of law"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A single concept, such as 'rule of law' with its components of supremacy of law, equality before the law and fundamental rights, carries a whole set of ideas, saving words. Option A is doubtful because such terms often confuse laymen, option B is wrong because lawyers are not free to use words anyhow, and option D is untrue."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 338, $official_bank_source${"itemId":"8333d42e-5ab5-5fb9-9aac-451b0fdd164d","questionId":"00156aa3-23eb-5352-b92a-4b8945f83891","sourceKey":"bank:PUL101:REA-006","payload":{"prompt":"A lawyer who says 'my brief has not been perfected', meaning 'I have not been paid my professional fee', is using which feature of legal language?","options":["Argot or jargon meant for those within the profession","Resonant formal expressions used during court oaths","Archaic English words such as hereinafter and aforesaid","Latin and French phrases such as consensus ad idem"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Argot is a special vocabulary not meant to be understood by those outside the legal profession; 'my brief has not been perfected' and 'I am speaking from the bar' are examples. Option B refers to phrases like 'the truth, the whole truth and nothing but the truth', option D to terms like ultra vires, and option C to words like 'hereinafter'."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 339, $official_bank_source${"itemId":"3e296f67-d6b3-5e2f-acd8-aa855eae93a2","questionId":"e6b7635a-878e-5128-b437-82184e2d4158","sourceKey":"bank:PUL101:REA-008","payload":{"prompt":"What is the relationship between legal principles and legal rules?","options":["Rules furnish the basis for principles; principles are specific applications of rules","Rules are binding on courts, while principles are mere opinions with no legal value","Principles and rules are exactly the same thing described in different words","Principles furnish the basis for rules; rules are specific applications of principles"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A principle is a comprehensive legal proposition from which rules develop; for example, the principle of natural justice gives rise to the rules audi alteram partem and nemo judex in causa sua. Option A reverses the relationship, option C ignores the difference in generality, and option B is wrong because arguments against principles are open to attack."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 340, $official_bank_source${"itemId":"5bd6d9e4-51f9-5e32-b921-4b6a9c381348","questionId":"7cc8a749-3d6f-5d73-bc9d-ea7cde649125","sourceKey":"bank:PUL101:REA-009","payload":{"prompt":"The rule audi alteram partem, developed from the principle of natural justice, means that","options":["ignorance of the law is no excuse","the facts speak for themselves","no one should be a judge in his own cause","a party must not be condemned unheard"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Audi alteram partem means 'hear the other side': a judge must hear both parties before reaching a conclusion. Option C is nemo judex in causa sua, the other component of natural justice, option B is res ipsa loquitur, and option A is ignorantia juris non excusat."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 341, $official_bank_source${"itemId":"4020e770-2aa4-5e8a-a225-d564ac798b37","questionId":"f8bc107f-92ab-570f-bc69-7bb43be75004","sourceKey":"bank:PUL101:REA-010","payload":{"prompt":"A magistrate in Enugu is assigned a case in which the company being sued for N1,200,000 is owned largely by the magistrate himself. If he hears and decides the case, which rule of natural justice is breached?","options":["Res ipsa loquitur: the facts speak for themselves","Nemo judex in causa sua: no one should be a judge in his own cause","Audi alteram partem: a party must not be condemned unheard","Stare decisis: let the decision stand"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A magistrate who decides a case in which he has a personal interest is a judge in his own cause, contrary to nemo judex in causa sua. Option C concerns hearing both sides, which is not the problem here, while options D and A are not rules of natural justice."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 342, $official_bank_source${"itemId":"003348ce-04f7-5a28-8a8c-73556d60936e","questionId":"bfae5ffc-90a3-59da-979c-8f73fb684004","sourceKey":"bank:PUL101:REA-011","payload":{"prompt":"Which of the following is an example of a well-established principle of constitutional law?","options":["A particular judge's remark made in passing","Separation of powers","The short title of a bill","A N25,000 fine for failing to renew a vehicle licence"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Rule of law, separation of powers and supremacy of the Constitution are well-established constitutional principles by which legislation, decisions and arguments are judged. Option D is a specific rule, option A is an obiter dictum, and option C is merely part of a bill's form."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 343, $official_bank_source${"itemId":"a983352b-c26a-584e-aab5-2a8a4e178c68","questionId":"188e2181-3bdc-5261-bafc-b86f78617fd8","sourceKey":"bank:PUL101:REA-012","payload":{"prompt":"What happens to a line of legal argument that is contrary to an established legal principle?","options":["It becomes binding on all lower courts in the hierarchy","It immediately becomes suspect and open to legal attack","It automatically becomes a new principle of the law","It must be accepted if it produces a good result in the case"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Principles are guideposts by which arguments and decisions are judged, so an argument against an established principle is suspect even if it seems to produce a good result. Option A confuses it with precedent, option C has no basis, and option D contradicts the role of principles."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 344, $official_bank_source${"itemId":"ea46c60e-1041-50bc-be8a-8b4212bf666c","questionId":"8ad77f65-e4ac-50c6-84e3-bc65c6d008c3","sourceKey":"bank:PUL101:REA-014","payload":{"prompt":"Which statement best describes a legal standard such as 'reasonable care' or 'the reasonable man'?","options":["A rule of evidence that applies only in criminal cases, never in civil cases","A general measure applied to the circumstances of each case, leaving discretion","A remark by a judge made in passing that has no legal effect on later cases","A fixed, detailed rule that gives exactly the same answer in every case"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Standards are flexible: they are applied liberally to the circumstances of each case, and attempts to replace them with hard and fast rules tend to fail. Option D describes a rule rather than a standard, option C describes an obiter dictum, and option A is wrong because the reasonable man standard is central to negligence, a civil wrong."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 345, $official_bank_source${"itemId":"95d54598-a57f-5ced-8f1a-fcfe48cc46cc","questionId":"fe88b782-a6d1-54e2-a010-fa4c72749240","sourceKey":"bank:PUL101:REA-015","payload":{"prompt":"A state traffic law contains two provisions: (1) 'No vehicle shall be driven within a school zone at more than 30 km/h', and (2) 'Every driver shall drive with reasonable care for other road users'. Which statement is correct?","options":["Provision (1) is a rule and provision (2) is a standard","Provision (1) is a standard and provision (2) is a rule","Both provisions are principles of constitutional law","Both provisions are obiter dicta"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Provision (1) fixes a precise limit that applies the same way every time, which makes it a rule; provision (2) requires the court to judge what reasonable care means in each situation, which makes it a standard. Option B reverses them, option C confuses them with principles such as separation of powers, and option D misuses a term for judicial remarks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 346, $official_bank_source${"itemId":"54fd5689-2da6-542f-970d-3a395589b101","questionId":"53dbc672-3352-51b0-b3e5-d3bd15fa2996","sourceKey":"bank:PUL101:REA-017","payload":{"prompt":"Who defined rhetoric as 'the art of winning men's minds with words'?","options":["Aristotle","Roscoe Pound","Plato","John Austin"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Plato described rhetoric as the art of winning men's minds with words. Aristotle (option A) is associated with the distinction between forensic and deliberative rhetoric, while Austin (option D) and Pound (option B) are jurists known for theories about the nature and functions of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 347, $official_bank_source${"itemId":"edaffad6-f93f-53ba-a50f-d7cd5f467333","questionId":"6452462d-c477-5a37-9ff8-edd7736e35d8","sourceKey":"bank:PUL101:REA-018","payload":{"prompt":"Following Aristotle's distinction, what type of rhetoric do lawyers and judges broadly use?","options":["Lawyers use forensic rhetoric, while judges use deliberative rhetoric","Both lawyers and judges use only forensic rhetoric","Lawyers use deliberative rhetoric, while judges use forensic rhetoric","Neither lawyers nor judges use rhetoric"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Lawyers represent their clients and try to persuade the court to accept their view, which is forensic rhetoric; judges aim at a reasoned decision justifiable in the interests of the parties and society, which is deliberative rhetoric. Option C reverses them, option B ignores the judge's different goal, and option D is wrong."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 348, $official_bank_source${"itemId":"6ee43b33-bc00-5722-b830-0b4f13c5f824","questionId":"cdf6cd72-b4d2-5510-b593-cbc05a771543","sourceKey":"bank:PUL101:REA-019","payload":{"prompt":"What is the principal rhetorical device used in law?","options":["An emotional appeal to the sympathy and feelings of the trial judge","Questioning the character and competence of the opposing counsel","The use of archaic English words to impress the court and the public","The appeal to authority by citing judicial or statutory authorities"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Although legal argument is made in words, its main persuasive tool is appeal to authority: citing statutes and decided cases. Option A and option B are not recognised legal techniques of persuasion, and option C is merely a feature of legal language."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 349, $official_bank_source${"itemId":"3c31386c-03a9-56b5-aa1c-06e74fbd596b","questionId":"f01a94e0-d73f-521c-b7b7-abe27bfdc3be","sourceKey":"bank:PUL101:REA-020","payload":{"prompt":"In a Nigerian High Court, counsel supports his argument by citing (i) a section of a Nigerian statute, (ii) a decision of the Nigerian Supreme Court and (iii) a passage from a respected textbook writer together with a decision of a Ghanaian court. How should the court treat item (iii)?","options":["As binding in the same way as the Supreme Court decision","As having only persuasive effect","As overriding the Nigerian statute","As inadmissible in any Nigerian court"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Statutes and decisions of Nigerian courts are primary authorities, while the writings of learned authorities and decisions of other jurisdictions have only persuasive effect. Options A and C give item (iii) far too much weight, and option D is wrong because such writings and foreign decisions may be referred to."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 350, $official_bank_source${"itemId":"21c7b0a3-24f7-5255-b5a8-12d610e3e373","questionId":"7af4a7b6-7bc5-5d66-b67a-d7ad5eb41339","sourceKey":"bank:PUL101:REA-021","payload":{"prompt":"The statement 'There is nothing like a born lawyer' expresses the view that","options":["only the children of lawyers can grow up to become good courtroom advocates","lawyers do not need to master language since judges decide on facts alone","legal rhetoric is an acquired skill developed through training and practice","persuasion is a natural gift at birth and cannot be learned by anyone"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Skill in legal persuasion is acquired through academic and professional training and practical experience; lawyers are made by diligence, patience and application. Options A and D treat it as inborn, and option B contradicts the importance of words to a lawyer."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 351, $official_bank_source${"itemId":"69245ec7-d2d7-5ff6-9f1d-0f6e064a1c51","questionId":"37bdeedc-61b1-5d60-911a-181f189dbbda","sourceKey":"bank:PUL101:REA-022","payload":{"prompt":"Which of the following is a stated value of logic to the lawyer?","options":["It replaces the need for him to know the statutes and decided cases","It guarantees that every conclusion he reaches is factually true and correct","It allows him to ignore the facts of the case and argue on law alone","It helps him reason clearly, express himself precisely and spot bad arguments"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Logic helps a lawyer think clearly, state his position firmly and spot defective arguments that might mislead the court. Option B is wrong because logic deals with validity, not truth, and options A and C are wrong because the lawyer must still master both the facts and the authorities."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 352, $official_bank_source${"itemId":"bdd2c2f5-5bab-58e4-b045-953c5de3504d","questionId":"f1802a7d-6f45-5377-91b3-be7fec742bcb","sourceKey":"bank:PUL101:REA-023","payload":{"prompt":"A syllogism is best described as","options":["an inductive argument that builds a general principle from several decided cases","a comparison of two cases based on their points of resemblance to each other","a remark made by a judge in passing that does not bind any later court","a deductive argument whose conclusion follows from a major and a minor premise"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A syllogism is a set of three connected propositions in which the conclusion necessarily follows from the major and minor premises. Option A describes inductive reasoning, option C describes an obiter dictum, and option B describes analogical reasoning."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 353, $official_bank_source${"itemId":"f714ed43-4f12-5429-bf4f-9634017d6854","questionId":"9aeae54a-2508-55dd-b170-9d5cb6cf43f1","sourceKey":"bank:PUL101:REA-024","payload":{"prompt":"Which statement correctly contrasts deductive and inductive reasoning?","options":["Deductive reasoning moves from the particular to the general, while inductive reasoning moves from the general to the particular","Deductive reasoning moves from the general to the particular, while inductive reasoning moves from the particular to the general","Both move from the general to the particular","Deductive reasoning is used only by judges, while inductive reasoning is used only by lawyers"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Deduction starts from a general proposition, such as a statute, and applies it to particular facts; induction examines particular decisions to arrive at a general principle. Option A reverses them, option C ignores the difference, and option D is wrong because both lawyers and judges use both forms."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 354, $official_bank_source${"itemId":"0f1ef5ae-c6da-5a2b-accb-a585ea6879ad","questionId":"d93e06cc-fc14-51c1-8d24-53cf35bfc70f","sourceKey":"bank:PUL101:REA-025","payload":{"prompt":"Consider this argument: 'Any trader who sells in Oyingbo market without a permit shall pay a fine of N20,000. Mama Bisi sold in Oyingbo market without a permit. Therefore Mama Bisi shall pay a fine of N20,000.' Which part is the minor premise?","options":["Mama Bisi sold in Oyingbo market without a permit","Any trader who sells in Oyingbo market without a permit shall pay a fine of N20,000","The permit system of Oyingbo market","Therefore Mama Bisi shall pay a fine of N20,000"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"In a legal syllogism the minor premise states the facts of the particular case, here what Mama Bisi did. Option B is the major premise, the general rule taken from the law, option D is the conclusion, and option C is not one of the three propositions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 355, $official_bank_source${"itemId":"f1176d9e-f7ac-5b01-bdbe-066731f6b62a","questionId":"dc68cb3c-0d65-5798-b05d-271a5a0eda38","sourceKey":"bank:PUL101:REA-026","payload":{"prompt":"A client asks his lawyer whether a new Lagos tenancy law applies to his N900,000 rent dispute. The lawyer reads the relevant section, finds that the client's facts fall within it, and concludes how the section applies to him. Which form of reasoning has the lawyer used?","options":["Rhetoric based on appeal to emotion","Inductive reasoning, building a principle from several cases","Deductive reasoning, with the statute as the major premise","Analogical reasoning between two unrelated statutes"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"When advising on a detailed statutory provision, the lawyer treats the statute as the major premise, fits the client's facts in as the minor premise and deduces the conclusion. Option B applies when the authority is case law rather than a clear statute, option D does not describe what he did, and option A is not legal logic."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 356, $official_bank_source${"itemId":"0ad8ddfe-10c6-5a55-adc9-3bb824f45b72","questionId":"f6885ead-7c38-584d-bc45-a43f2ef226f9","sourceKey":"bank:PUL101:REA-027","payload":{"prompt":"A key limitation of syllogism as a method of legal reasoning is that","options":["it is concerned with validity rather than with the truth of the premises","it can be used only in criminal cases and never in civil disputes","it always requires a jury to decide whether the premises are correct","it can never produce a firm conclusion from the premises given to it"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A syllogism is valid when the conclusion necessarily follows from the premises, but that says nothing about whether the premises are true; for example, 'Every good man goes to heaven; John died a good man; therefore John is in heaven' is valid but its truth cannot be verified. Options D, B and C are not limitations of syllogism at all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 357, $official_bank_source${"itemId":"c6fa7a9f-45cd-53a0-bdc0-482d9ec3779c","questionId":"1b33f15b-47a1-542a-ae5d-7291103966d9","sourceKey":"bank:PUL101:REA-028","payload":{"prompt":"Counsel argues: 'Section 12 of the State Revenue Law imposes a N50,000 penalty on late filers; my client filed late; so my client must pay N50,000.' In fact, section 12 was repealed before the client filed. What does this show about syllogistic reasoning?","options":["A repealed law remains a valid major premise until the court formally rules on it","Deductive reasoning cannot be used at all when the major premise is a statute","A wrong premise accepted as true leads to a wrong conclusion, though the form is valid","A syllogism is invalid whenever it involves money penalties or fines of any amount"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"The argument is logically valid in form, but its major premise is false because the section no longer exists, so the conclusion is wrong. Option D has no basis, option A is wrong because a repealed provision is no longer law, and option B contradicts the fact that statutes are the usual major premise in deduction."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 358, $official_bank_source${"itemId":"6013c6c2-e073-5dfb-b93f-960d05f1d94a","questionId":"c39635d7-6ae5-514c-8057-46dd863331a2","sourceKey":"bank:PUL101:REA-029","payload":{"prompt":"Why must a lawyer carefully distinguish between truth and validity when dealing with witnesses?","options":["A witness may be logical but untruthful, and counsel must expose it","Because only valid testimony is admissible in a Nigerian court of law","Because witnesses are not allowed to reason logically while testifying","Because testimony that is logical is always true and must be believed"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A witness can be perfectly logical while lying; if counsel or the judge does not see the difference between truth and validity, undeserved weight may be given to such evidence. Option D confuses validity with truth, option B invents an admissibility rule, and option C is untrue."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 359, $official_bank_source${"itemId":"9451fb2e-69cf-5597-a4c2-124e0f4401a4","questionId":"f94532e0-be75-5bc2-b3d8-65119d2e4c2d","sourceKey":"bank:PUL101:REA-030","payload":{"prompt":"The argument 'A man is a human being; a woman is a human being; therefore a man is a woman' illustrates which limitation of logic?","options":["Inductive reasoning can never be used by judges in deciding any case","A statement may be logical in one context and illogical in another","Analogy is a perfect form of induction that always gives a true result","Rhetoric in law depends mainly on appeal to judicial or statutory authority"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"The pattern 'things equal to the same thing are equal to one another' works in mathematics but produces nonsense when transferred to men and women, showing that logic valid in one context may fail in another. Options A, D and C are unrelated or false statements."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 360, $official_bank_source${"itemId":"708cdab4-ee0b-5a67-bafd-10085b859b47","questionId":"feeae71b-a488-5544-986d-a20e1895acb3","sourceKey":"bank:PUL101:REA-031","payload":{"prompt":"When the conclusion of an argument does not necessarily follow from its premises, the fallacy committed is called","options":["non sequitur","per incuriam","obiter dictum","stare decisis"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Non sequitur ('it does not follow') is the fallacy where the conclusion does not follow from the premises, making the argument invalid. Option B describes a decision given through carelessness, option C a remark made in passing, and option D the doctrine of precedent."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 361, $official_bank_source${"itemId":"34fe508b-9438-52e4-9e39-38e50edfe6dd","questionId":"52e96de9-086c-55a7-8f57-cde6cfeda60c","sourceKey":"bank:PUL101:REA-032","payload":{"prompt":"Why is inductive reasoning usually needed when a lawyer bases his argument on case law rather than on a statute?","options":["Statutes are always too vague to support deductive reasoning by a lawyer","Case law cannot be used as legal authority in any Nigerian court or tribunal","Judges are not allowed to use deductive reasoning when case law is cited","One decision may not yield a clear major premise, so several cases must be examined"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Deduction requires a clear major premise; with case law, the lawyer must reason from particular decisions to the general principle they establish, which then serves as the major premise. Option B is false, option A overstates the problem of vagueness, and option C is false because judges use both forms."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 362, $official_bank_source${"itemId":"ca44394c-d9d6-5519-8e5a-bd08164295b8","questionId":"7cecf15d-4ce8-5cee-aa60-204736181dde","sourceKey":"bank:PUL101:REA-033","payload":{"prompt":"To show that a negligent driver must pay damages to her client, counsel cites three earlier cases in which negligent defendants were held liable, shows that they share common features with her client's case, and argues that they establish a general rule that applies. Which form of reasoning is this?","options":["Inductive reasoning","Forensic rhetoric based on emotion","Deductive reasoning from a statute","Reasoning per incuriam"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Building a general proposition from several particular decisions with common features is inductive reasoning, moving from the particular to the general. Option C would start from a statute as the major premise, option B is not what counsel did, and option D refers to a decision given in ignorance of a binding authority."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 363, $official_bank_source${"itemId":"a06ab0c6-a514-5cf6-859d-228f3c2a7d73","questionId":"9d8465e2-0712-55df-84e5-ecd6a4a58a56","sourceKey":"bank:PUL101:REA-034","payload":{"prompt":"Lord Diplock in the Dorset Yacht case described how a court decides whether a duty of care exists. How did he describe the two stages of the process?","options":["The first stage is analytical and inductive; the second is deductive and analytical","The first stage is mediation between the parties; the second stage is arbitration","Both stages are purely inductive, moving from particular cases to a general rule","The first stage is deductive and analytical; the second is rhetorical and persuasive"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"The court first analyses previous decisions to find the characteristics common to cases where a duty of care was held to exist (induction), then applies that proposition to the facts before it (deduction). Options D, C and B misdescribe the two stages."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 364, $official_bank_source${"itemId":"99d27942-74ed-59c2-ac3a-eeea7f077947","questionId":"b4523998-5d55-55ac-bfa7-7d25825206ef","sourceKey":"bank:PUL101:REA-035","payload":{"prompt":"Analogical reasoning in law is best described as","options":["comparing the issue with closely similar earlier decisions; a loose, not strictly logical, form of reasoning","a strictly formal argument whose conclusion follows necessarily from a major and a minor premise","the rule that a lower court must always follow the decision of a higher court on the same point","reasoning that ignores all previous decisions and relies only on the judge's own sense of fairness"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Analogical reasoning categorises the issue and compares it with closely similar earlier decisions; it is regarded as not strictly logical but a looser form of reasoning. Option B describes syllogism, option C describes binding precedent, and option D is the opposite of reasoning by analogy."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 365, $official_bank_source${"itemId":"a5c8f98c-feea-574d-9b09-dcef365621d0","questionId":"047378b0-1c9d-5127-a0c1-16a15a131fd2","sourceKey":"bank:PUL101:REA-036","payload":{"prompt":"Farrar described English case law as the product of practical reasoning emerging from decision-making. Which attributes does it combine?","options":["Legislation and the codification of custom","Syllogism and the old trial by ordeal","Reasoning by analogy and reasoning by rules","Forensic rhetoric and mediation by the judge"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Case law combines reasoning by analogy, comparing points of resemblance between cases, with reasoning by rules, classifying categories and stating principles. Options D, B and A pair terms that do not describe how case law is built."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 366, $official_bank_source${"itemId":"5b811d2e-052e-5a6f-8d50-36ba8ec51a29","questionId":"b22d4681-e811-5027-8d06-9de03357e87b","sourceKey":"bank:PUL101:REA-038","payload":{"prompt":"What is meant by the statement 'The life of the law has not been logic but experience'?","options":["Only old precedents should ever be followed, since they represent the experience of the law","Logic is only part of legal reasoning; rules are reshaped by experience and changing values","Logic has no place at all in legal reasoning and should be avoided by judges and lawyers","Judges should decide cases on experience alone without giving any reasons for decisions"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"The statement means that logic is only part of the story; the common law has stayed relevant by constantly supporting rules with reasons and modifying or discarding them when they no longer fit. Option C overstates the point, option D contradicts the need for justification, and option A ignores how rules are changed."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 367, $official_bank_source${"itemId":"efbbccfa-e607-5867-9835-c9f9cc6987dd","questionId":"6353b0cd-f356-5f0f-89bb-c67cb629af42","sourceKey":"bank:PUL101:REA-040","payload":{"prompt":"Why is litigation sometimes described as 'a gamble'?","options":["Because judges weigh factors beyond authority, so outcomes can be hard to predict","Because the burden of proof shifts randomly from one party to the other during trial","Because courts never follow precedent, so earlier decisions give no guidance at all","Because judgments are decided by casting lots when the evidence is evenly balanced"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Since decisions involve logic, authority, justice, public policy and common sense, it can be difficult to predict how a court will resolve some cases. Option D is false, option B is wrong because the burden shifts with the pleadings and the evidence, and option C ignores stare decisis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 368, $official_bank_source${"itemId":"c8403245-c5fb-52aa-9290-b58757567032","questionId":"ede2ffb0-73bc-564b-bac0-2493c758bd44","sourceKey":"bank:PUL101:REA-041","payload":{"prompt":"Which principle is associated with the case of Chinwendu v Mbamali?","options":["A lower court must follow a higher court even if the decision was per incuriam","Justice delayed is justice denied","Justice should not be sacrificed on the altar of technicalities","The burden of proof lies on the one who affirms"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"In Chinwendu v Mbamali the court warned that justice must not be sacrificed on the altar of technicalities and that disputes should be decided on their merits. Option B is a general saying about delay, option A is a rule of precedent, and option D is a rule on the burden of proof."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 369, $official_bank_source${"itemId":"8fcdba2b-8651-5a24-ab9b-8a03f43dfad3","questionId":"6ecf3970-de18-5ee4-bc37-0978aee227cd","sourceKey":"bank:PUL101:REA-042","payload":{"prompt":"On appeal, a party asks the court to set aside a judgment for N3,000,000 only because the respondent's counsel misnumbered two paragraphs of his brief, although the case was fully argued on its merits. Which approach is most consistent with modern legal reasoning?","options":["Allow the appeal, because strict technical rules always override the demands of justice","Refer the whole matter to mediation, because the brief contains technical errors","Decide on the merits, since technicality must not cause a miscarriage of justice","Decide according to its personal sympathy for whichever party seems more deserving"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Rhetoric and logic are the technical parts of adjudication, but courts may depart from strict technicality where the interest of justice demands. Option A is the very approach the courts have rejected, option B has no basis, and option D would replace reasoned justification with personal feeling."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 370, $official_bank_source${"itemId":"d93f424b-f3b9-5f5a-b627-6e84ea8886d0","questionId":"75de3db5-58f8-586d-a812-8856bd460eb6","sourceKey":"bank:PUL101:REA-043","payload":{"prompt":"A judge is trying an officer under a law that prescribes death for coup plotting. Pardons have been granted only once before, and international bodies are urging mercy. The judge reasons that a lighter sentence would better serve justice, public policy and what a reasonable man would do. Which aspect of legal reasoning is the judge relying on?","options":["Strict syllogism, ignoring every factor except the exact wording of the statute","The rule that the opinions of foreign bodies are binding on Nigerian courts","Shifting of the burden of proof to the accused to show that there was no coup","Justifying the decision by justice, public policy and common sense, beyond authority"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Modern judges justify decisions not only by citing authority but by considering justice, public policy, common sense and the reasonable man. Option A describes the strictly technical approach the judge is moving away from, option B is wrong because foreign views are at most persuasive, and option C is unrelated."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 371, $official_bank_source${"itemId":"d1cedaab-1029-5c0a-a02d-2c8944268622","questionId":"b3d3d073-b304-599f-a8f5-00e7f7dd8a3e","sourceKey":"bank:PUL101:REA-044","payload":{"prompt":"The doctrine of judicial precedent, also known as stare decisis, means that","options":["a court may ignore the decisions of higher courts whenever it disagrees with them","the legislature must approve every judgment before it can bind any other court","every remark made by any judge binds all other courts in the country in later cases","a decision on a point of law binds the same court and lower courts in similar cases"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Stare decisis requires the same question of law to be decided the same way by the court and the courts below it. Option C is wrong because only the ratio decidendi binds, not passing remarks, option A contradicts the doctrine, and option B has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 372, $official_bank_source${"itemId":"b492c187-b5e8-570f-9600-697af2e34dc8","questionId":"227c881e-8b47-5aa1-9b28-fbbc810c8b56","sourceKey":"bank:PUL101:REA-045","payload":{"prompt":"In an earlier case with facts A, B, C and D, the court treated A, B and C as the material facts, discarded D, and gave decision Y. A later case in a lower court has material facts A, B and C, plus a different fact E that the court considers immaterial. Under the doctrine of precedent, the lower court should","options":["give a decision opposite to Y","treat the earlier case as overruled","refuse to decide until fact D is proved","give decision Y"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Precedent binds through the essential facts and the decision based on them: where the essential facts are again A, B and C, the decision must also be Y. Option A contradicts the doctrine, option C is wrong because D was discarded as irrelevant, and option B is wrong because a lower court cannot overrule a higher court."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 373, $official_bank_source${"itemId":"d9f84fa1-cfd2-53d8-be8c-b0bb4bcba0df","questionId":"53424819-3035-54d6-8728-c64c51781929","sourceKey":"bank:PUL101:REA-046","payload":{"prompt":"Counsel before the Oyo State High Court relies on a decision of the Lagos State High Court on the same point of law. How should the Oyo State High Court treat that decision?","options":["As binding only if the Lagos judge was more senior than the Oyo judge","As persuasive only, since the courts are of coordinate jurisdiction","As irrelevant, since High Court decisions are never cited in other states","As binding, since every State High Court binds every other High Court"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Decisions of courts of coordinate or concurrent jurisdiction are only persuasive, so one State High Court is not bound by another. Option D overstates their effect, option C is wrong because such decisions may be cited and can persuade, and option A is wrong because seniority of judges does not make a decision binding."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 374, $official_bank_source${"itemId":"7901f36c-f7e7-5282-8574-0d4ae64fc207","questionId":"5d94b394-4e3e-59be-9c18-2477fbe266ad","sourceKey":"bank:PUL101:REA-047","payload":{"prompt":"A judge of the Osun State High Court refuses to follow a Supreme Court decision because he thinks it was wrongly decided, and instead treats a contrary House of Lords decision as binding on him. Which statement is correct?","options":["He erred twice: the Supreme Court decision binds him, and a House of Lords decision is at most persuasive in Nigeria","He was right on both points, since a High Court may choose which authority to follow","He was right to follow the House of Lords, since English decisions bind Nigerian courts","He was right to reject the Supreme Court decision, since the Supreme Court cannot bind State High Courts"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Supreme Court decisions bind all lower courts, and since foreign courts are outside the Nigerian court hierarchy, their decisions are only persuasive. Options B, C and D each misstate how binding and persuasive precedent work in Nigeria."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 375, $official_bank_source${"itemId":"768704be-52f4-5ab3-8137-7dda4ac82a7e","questionId":"12790d05-cf7e-54f9-9a0a-e79f9794f9ea","sourceKey":"bank:PUL101:REA-048","payload":{"prompt":"The ratio decidendi of a case means","options":["the final order of the court, such as the amount of damages awarded","a decision reached through ignorance or neglect of a binding statute","a statement of opinion made by the judge in passing, by the way","the reason for the decision: the legal rule on which the decision rests"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Only the ratio decidendi of a case, its essential legal reason, constitutes a binding precedent for later cases. Option C is an obiter dictum, option A is the order or outcome rather than its legal basis, and option B describes a per incuriam decision."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 376, $official_bank_source${"itemId":"196cb30a-e222-5d80-80a1-d58ccbfe56b7","questionId":"66f4bb3d-f459-5460-a0ce-b34758f1a518","sourceKey":"bank:PUL101:REA-049","payload":{"prompt":"According to Goodhart, how is the principle (ratio) of a case found?","options":["From the reasons given in the opinion, considered without the facts","From the rule of law stated in the judgment, read on its own terms","By choosing among many possible levels of generality of the facts","From the facts the judge treated as material and his decision on them"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Goodhart held that the ratio is found in the facts the judge treated as essential, together with his decision on them, and also in what he held to be irrelevant. Options B and A are approaches Goodhart expressly rejected, and option C is Stone's approach, which criticised Goodhart."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 377, $official_bank_source${"itemId":"df98c7a6-11d2-57ba-9bea-c42cf25e720b","questionId":"a797c652-0156-502b-bf59-77d4e04147f6","sourceKey":"bank:PUL101:REA-050","payload":{"prompt":"Julius Stone, disagreeing with Goodhart, saw the process of finding the ratio decidendi as basically one of","options":["reading the headnote prepared by the editor of the law report for the case","choosing an appropriate level of generality among many potential rationes","counting the number of judges who agreed with the leading judgment delivered","applying the rule that ignorance of the law is no excuse to the parties"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Stone argued that facts can be stated at different levels of generality, so a case holds several possible rationes and a later court must choose among them. Option A is not a method of finding the ratio, option C relates to appellate courts with several judges, and option D is unrelated."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 378, $official_bank_source${"itemId":"c4018ab1-cb4a-5bf9-9592-cf4589851d31","questionId":"61a46118-24ec-51bb-bf80-bb786b43ccb5","sourceKey":"bank:PUL101:REA-051","payload":{"prompt":"An obiter dictum is","options":["the binding legal reason on which the decision of the case rests","a final and binding order made by an arbitrator after a hearing","a remark made by a judge 'by the way' that is not binding","a decision given in ignorance of a relevant and binding statute"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Obiter dictum means 'something said in passing': words of an opinion not necessary for deciding the case, which do not bind later courts. Option A is the ratio decidendi, option D is per incuriam, and option B is an award."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 379, $official_bank_source${"itemId":"25469296-bd16-5e43-a58e-3ea427af8a40","questionId":"61665fff-9c0d-5f0a-92ce-5efa49e3caaa","sourceKey":"bank:PUL101:REA-052","payload":{"prompt":"In deciding a breach of contract case over the supply of bags of cement worth N700,000, the judge adds: 'Had the goods been perishable foodstuffs, I would have applied a different rule.' The goods were not perishable. That additional statement is","options":["a standard of proof","the ratio decidendi","a per incuriam decision","an obiter dictum"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"The statement concerns facts that were not before the court, so it was not necessary for the decision and is a remark made in passing. Option B is wrong because the ratio rests on the facts actually found, option C refers to decisions that overlook binding authority, and option A is unrelated."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 380, $official_bank_source${"itemId":"9271d951-bee8-548c-85b6-a667989d9a83","questionId":"17cfda23-17df-58bf-aa38-f43a4074d92a","sourceKey":"bank:PUL101:REA-053","payload":{"prompt":"On what does the weight given to an obiter dictum mainly depend?","options":["The level of the court and the learning of the judge who made it","Whether both parties to the case agreed with it at the time","The amount of money involved in the case in which it was made","The total length of the judgment in which the remark appears"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Obiter dicta do not bind, but their persuasive weight depends on the court's place in the hierarchy and the eruditeness of the judge; statements of the Supreme Court made after asking counsel to address it on the law are likely to be followed. Options C, B and D are not the factors that give obiter weight."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 381, $official_bank_source${"itemId":"09aa5bb1-3f00-557f-b106-b25ca0f5a1bb","questionId":"429fb991-dc2a-5172-9477-ddd30a2faac9","sourceKey":"bank:PUL101:REA-054","payload":{"prompt":"A decision described as reached per incuriam is one that","options":["was reached by the parties themselves through mediation outside the regular courts","was made by a judge in passing on facts that were not actually before the court","was given through carelessness, overlooking a relevant statute or binding precedent","was given by the highest court in the land and therefore binds every other court"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Per incuriam literally means 'through carelessness'; it applies where a relevant statute or binding precedent was not brought to the court's attention and was overlooked. Option D describes a binding Supreme Court decision, option B an obiter dictum, and option A an ADR settlement."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 382, $official_bank_source${"itemId":"041e087d-49c7-52b5-bcde-e7287098b3da","questionId":"cae69834-5e90-5881-b8f1-12637a0ef6e2","sourceKey":"bank:PUL101:REA-055","payload":{"prompt":"A Chief Magistrate in Ilorin believes that a High Court decision binding on her was given per incuriam because it overlooked a statute. What should she do?","options":["Declare the High Court decision overruled and apply the statute directly","Follow the High Court decision, though she may express doubt as obiter","Refer the question of law to an arbitrator for a binding determination","Refuse to follow it, since per incuriam decisions bind no court at all"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"No court is bound by its own per incuriam decision, but a lower court remains bound by a higher court's decision even if it was reached per incuriam. Option D states the rule too widely, option A is beyond a magistrate's jurisdiction, and option C has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 383, $official_bank_source${"itemId":"49b15603-6996-5f8d-80bd-01ca63147b4e","questionId":"2ac646f5-8055-5630-80c3-ef1908dffab3","sourceKey":"bank:PUL101:REA-056","payload":{"prompt":"'Distinguishing' a case means","options":["transferring the case to a higher court because the earlier decision appears to be inconsistent","following the earlier case exactly in every detail, even where the facts are clearly different","showing an essential factual difference, so the earlier case is not followed but remains good law","declaring that the earlier case was wrongly decided and is therefore no longer good law at all"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"A court distinguishes a precedent when it finds a significant factual difference that justifies not applying it, while accepting that it is still good law. Option D describes overruling, which is open only to a court not bound by the earlier decision, option B is following, and option A is a transfer."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 384, $official_bank_source${"itemId":"28fbbdff-1328-59dc-94d4-f902f272e247","questionId":"8c4b8738-69e1-5f12-827c-332927768e55","sourceKey":"bank:PUL101:REA-057","payload":{"prompt":"Glanville Williams classified distinguishing into restrictive and non-restrictive. What is non-restrictive distinguishing?","options":["The court cuts down the ratio of the earlier case by treating extra facts as essential","The court leaves the earlier ratio intact but finds the facts materially different","The court follows the earlier case automatically without examining the facts","The court declares the earlier case wrongly decided and overrules it completely"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"In non-restrictive distinguishing the earlier ratio is left intact and the present case is simply shown to be different on its facts. Option A describes restrictive distinguishing, which narrows the earlier ratio, option D is overruling, and option C is not distinguishing at all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 385, $official_bank_source${"itemId":"41eae7e7-5133-5953-9fff-a4f0ac53afd3","questionId":"c935d5a5-e978-5e66-95d5-1739f5098f0b","sourceKey":"bank:PUL101:REA-058","payload":{"prompt":"Which of the following is NOT a factor affecting the weight of a precedent?","options":["The status and composition of the court that decided it","Whether the decision was unanimous or had a dissent","The number of pages in the judgment","The age of the precedent"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"The weight of a precedent depends on its age, the status of the court, the adequacy of its law report, its history in later cases, and whether the court was unanimous; the length of the judgment is not one of them. Options D, A and B are recognised factors."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 386, $official_bank_source${"itemId":"6e2b7d7a-5555-5e69-9cf1-db7d29575b23","questionId":"49242020-95fa-5371-bf5f-5dcfc269bb63","sourceKey":"bank:PUL101:REA-059","payload":{"prompt":"Which statement correctly describes the attitude of the Supreme Court of Nigeria to its own previous decisions?","options":["It respects them but may overrule one reached on a wrong principle","It is absolutely bound by all its previous decisions without any exception","It must follow decisions of State High Courts that conflict with its own","It treats its previous decisions as merely persuasive obiter dicta"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"As the court of last resort, the Supreme Court respects its precedents but, as held in cases such as Bronik Motors v Wema Bank, may depart from them on grounds such as injustice and public policy. Option B overstates the binding effect, option D understates it, and option C reverses the hierarchy."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 387, $official_bank_source${"itemId":"1d40e08d-969b-51cf-b2c5-c4865023bd57","questionId":"b194ef53-55d4-5e36-8889-2f0d795bf16f","sourceKey":"bank:PUL101:REA-060","payload":{"prompt":"Under the rule in Young v Bristol Aeroplane Co., followed by the Court of Appeal, the court is bound by its own previous decisions subject to exceptions. Which of the following is NOT one of those exceptions?","options":["Where the court considers its earlier decision unpopular with the public","Where its earlier decision was given per incuriam","Where its earlier decision cannot stand with a decision of a higher court","Where there are two conflicting decisions of its own, it may choose which to follow"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"The three exceptions are conflicting decisions of its own, a decision that cannot stand with a decision of a higher court, and a decision given per incuriam. Unpopularity of a decision is not an exception, while options D, C and B are the recognised exceptions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 388, $official_bank_source${"itemId":"9953c455-4927-59d4-b7cb-efdc0d9d376d","questionId":"48fa0c54-be3f-58c7-ae1f-5b52f2ee4d11","sourceKey":"bank:PUL101:REA-062","payload":{"prompt":"Where an appellate court is equally divided, the practice is to dismiss the appeal on the principle semper praesumitur pro negante. What does this mean?","options":["Let the earlier decision of the court stand","The facts of the accident speak for themselves","Justice must not only be done but be seen to be done","The presumption is always in favour of the negative"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Semper praesumitur pro negante means the presumption is always in favour of the negative, so an equally divided court dismisses the appeal and the decision below stands. Option C restates the dictum that justice must be seen to be done, option B paraphrases res ipsa loquitur, and option A translates stare decisis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 389, $official_bank_source${"itemId":"4e3d8fa7-9670-50ce-aa02-f92e450e78fa","questionId":"c4501859-adc1-5a39-9551-90ee302dba7b","sourceKey":"bank:PUL101:REA-063","payload":{"prompt":"On the old controversy whether judges make law, what is now the settled position?","options":["Judges make law only in criminal matters and never in civil or equitable matters","Judges never make law; they only declare law that already existed before the case","Judges do make law, though retrospectively, where no statute or precedent applies","Only the legislature can create any rule of law, so case law does not really exist"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Judges must decide cases even where no statute or precedent clearly applies, so they make new law; it has been said that the rules of equity and nine-tenths of the common law were made by judges. Option B is the old declaratory view now set aside, option D ignores case law, and option A has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 390, $official_bank_source${"itemId":"02278749-bfd1-5e16-9f81-3f3513321e6e","questionId":"810ddc0b-00ed-5fa9-a1f8-0ae70b0ad3b3","sourceKey":"bank:PUL101:REA-065","payload":{"prompt":"To curb the crime of obtaining money by false pretences, popularly called '419', the government enacted the Advance Fee Fraud law. Which reason for new legislation does this best illustrate?","options":["Arrest of anti-social behaviour","Global shifts in value systems","Scientific and technological breakthroughs","Change from a military to a civilian regime"],"correctOption":0,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Governments legislate to arrest reckless or anti-social practices that harm the public or the country's image; the Advance Fee Fraud law is given as an example. Option B concerns changing values such as women's and children's rights, option D concerns a change of regime, and option C concerns new technology."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 391, $official_bank_source${"itemId":"eee4763b-5037-5cbc-9fa0-200531d64031","questionId":"65cdbe13-4058-5c4e-9298-bb14362912a8","sourceKey":"bank:PUL101:REA-066","payload":{"prompt":"Following a transition from military to civilian rule, the new government abolished an agency the previous regime had created and made new laws to pursue its own programmes. Which reason for new legislation does this illustrate?","options":["Scientific and technological breakthroughs in the country","Global shifts in value systems on rights and the environment","Arrest of anti-social behaviour such as fraud and cultism","Change in the political and economic ideologies of government"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"When the baton of governance changes, political goals change and changes in the law become inevitable; the abolition of the Petroleum Trust Fund at the start of civilian rule is an example. Options A, C and B are other reasons for legislation that do not fit these facts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 392, $official_bank_source${"itemId":"8d05fcf1-b37f-5677-a2e8-9a8469cb7d4f","questionId":"febb415f-03d2-50bb-bc95-bae2a2fb2523","sourceKey":"bank:PUL101:REA-067","payload":{"prompt":"How does a vague statutory provision differ from an ambiguous one?","options":["Vagueness is always less serious than ambiguity, because context easily resolves a vague provision","An ambiguous provision has no meaning at all, while a vague provision has exactly two meanings","Ambiguity offers two or more meanings; vagueness leaves a cloudy meaning context can hardly cure","There is no difference, because both terms describe a provision that has been badly punctuated"],"correctOption":2,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"Ambiguity offers two or more mutually exclusive meanings, often resolvable by context; vagueness leaves the meaning indeterminate and is worse because context rarely cures it. Option B misdescribes both, option A reverses their seriousness, and option D ignores the distinction."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 393, $official_bank_source${"itemId":"639162d1-827c-5d5f-8881-4c8f00099fb0","questionId":"970302a8-99c8-54c7-84a8-be3e1cc4688c","sourceKey":"bank:PUL101:REA-069","payload":{"prompt":"In answering law problem questions, the acronym IRAC stands for","options":["Issue, Ratio, Argument, Citation","Introduction, Rule, Analysis, Comment","Introduction, Definition, Body, Conclusion","Issue, Rule, Application, Conclusion"],"correctOption":3,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"IRAC means identify the Issue, state the Rule (or Principle, in the IPAC variant), Apply it to the facts and reach a Conclusion. Options B and A are invented versions, and option C is IDBC, the structure used for essay questions."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 394, $official_bank_source${"itemId":"61f6665e-69a0-5da2-b342-2f320dd30e90","questionId":"27c80123-ad67-5ef1-b54c-93ef8594f8b9","sourceKey":"bank:PUL101:REA-070","payload":{"prompt":"A student is given this question: 'Mr. Ade sued Mr. Ola in the Ibadan High Court and cited only an English House of Lords decision. Advise Mr. Ola.' Which approach is most suitable for answering it?","options":["Listing all the Latin maxims and English cases known to the student","IRAC: identify the issue, state the rule, apply it, and conclude","IDBC: introduction, definition, body and conclusion, as for an essay","Writing a general essay on the history of English law in Nigeria"],"correctOption":1,"section":"Legal Reasoning: Logic, Rhetoric, Principles and Standards","explanation":"This is a problem question, because it gives facts and asks for advice, so it is answered with IRAC (or IPAC). Option C is the structure for essay questions, and options D and A would not address the issue raised by the facts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 395, $official_bank_source${"itemId":"17bca4e1-9ec8-5568-98b8-210964add8a1","questionId":"52ffeac3-a1a7-595c-b88c-d89146796f54","sourceKey":"bank:PUL101:PQ-005-01","payload":{"prompt":"Under which rule of statutory interpretation must the court give the words of a statute their natural, ordinary and plain meaning, as stated by Tindal C.J. in the Sussex Peerage case?","options":["The literal rule","The mischief rule","The ejusdem generis rule","The golden rule"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The literal rule says that where the words are precise and unambiguous, the words themselves best declare the legislature's intention, so the court simply applies their ordinary meaning. Option D allows a departure from that meaning to avoid absurdity, Option B looks at the defect the statute was meant to cure, and Option C narrows general words that follow a list."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 396, $official_bank_source${"itemId":"88e990ec-cdcd-514b-a34b-479519ced9b6","questionId":"a3c02b87-8b53-51cf-8b94-8eaa3edfa2bb","sourceKey":"bank:PUL101:PQ-005-02","payload":{"prompt":"The golden rule of interpretation allows a court to","options":["depart from the ordinary meaning of words where it would lead to absurdity, inconsistency or repugnance, but no further than needed","refuse to apply any statute it considers unjust","apply the ordinary meaning of words even where the result is absurd","look at the debates in the legislature to find what members intended"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The golden rule starts from the ordinary meaning but modifies it just enough to avoid a manifest absurdity or repugnance that the legislature could not have intended. Courts cannot simply refuse to apply a statute (Option B), and the use of legislative debates (Option D) is not part of this rule. Option C describes a strict literal approach."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 397, $official_bank_source${"itemId":"b7dd3c37-95ec-5eb3-bcda-404961f34c83","questionId":"669f92b6-d9e5-56e7-a9a7-0bd6828cabdb","sourceKey":"bank:PUL101:PQ-005-03","payload":{"prompt":"The mischief rule of statutory interpretation was laid down in","options":["the Sussex Peerage case","Donoghue v. Stevenson","Heydon's case","Salomon v. Salomon & Co. Ltd"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Heydon's case (1584) set out the mischief rule, which asks what the law was before the statute and what defect the statute was passed to remedy. Option A is associated with the literal rule, while Option D (company law) and Option B (negligence) are not about statutory interpretation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 398, $official_bank_source${"itemId":"9421e6f1-63c0-5ae0-b866-3ef0a240d89b","questionId":"b9187ddb-76ab-583c-8214-41f2255b2b93","sourceKey":"bank:PUL101:PQ-005-04","payload":{"prompt":"When applying the mischief rule, the court mainly asks","options":["what the words mean in their ordinary dictionary sense alone","what defect or mischief in the earlier law the statute was meant to remedy","how a reasonable man would vote on the statute","whether the statute agrees with natural law"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The mischief rule looks at the state of the law before the enactment and the shortcoming the new law came to cure, then interprets the words to suppress that mischief. Option A describes the literal rule, and Option D and Option C are not tests the court uses to interpret statutes."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 399, $official_bank_source${"itemId":"9eb033d8-4bba-5611-95a4-6d9ca0ebf682","questionId":"bb0a8ce9-0c0d-5f6a-a135-2d05cfc0aac1","sourceKey":"bank:PUL101:PQ-005-05","payload":{"prompt":"Awolowo v. Shagari, which arose from the 1979 presidential election, is often used to show the weakness of the literal rule because","options":["the court refused to interpret the Constitution at all","Supreme Court justices applying the literal rule to the same words reached opposing conclusions","the court relied entirely on the debates of the legislature","the court applied the ejusdem generis rule to reach an absurd result"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The dispute over 'two-thirds of all the States' (the famous 12 two-thirds argument) showed that words do not always have one plain meaning, since judges using the same literal approach disagreed. Option A and Option C did not happen, and Option D names the wrong rule."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 400, $official_bank_source${"itemId":"fa567dd0-74d4-5c67-8b53-001988bcf818","questionId":"70335d5a-c34f-5197-9d36-178c14f7da2a","sourceKey":"bank:PUL101:PQ-005-06","payload":{"prompt":"In Adegbenro v. Akintola, the Privy Council interpreted the provision that the Governor could remove the Premier \"if it appears to him\" that the Premier no longer commanded majority support. The court held that","options":["the Governor could act only after a formal vote in the House of Assembly","the provision was void for vagueness","only the courts could decide whether the Premier had lost support","the Governor could reach that view without any limit on the material he relied on"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Reading the words literally, the Privy Council held that the Governor was not limited in the material on which he formed his view, so it could, as critics put it, even 'appear to him in a dream'. This is often cited to show how the literal rule can give surprising results. Option A, Option B and Option C were not the holding."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 401, $official_bank_source${"itemId":"8560eafa-ca3e-5669-a0ac-a367dbd2813b","questionId":"3db8129f-6f35-554f-a1aa-145dde5b5c07","sourceKey":"bank:PUL101:PQ-005-07","payload":{"prompt":"A statute refers to \"bread, meat pie, cake, doughnut, sausage and other snacks\". Under the ejusdem generis rule, \"other snacks\" will be read to cover","options":["only things of the same class as those listed, such as pastries and confectioneries","only the items specifically named","main meals and drinks but not pastries","any food or drink whatsoever"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Ejusdem generis means that general words following a list of specific items are limited to things of the same kind as the list. So 'other snacks' covers similar pastries but not main food items or drinks (Option D and Option C). Option B would make the general words meaningless."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 402, $official_bank_source${"itemId":"d20e9915-8878-5a59-86f3-d0b8eb8f071d","questionId":"a537e552-a915-5f5c-b4ac-d3e08795a511","sourceKey":"bank:PUL101:PQ-005-08","payload":{"prompt":"A rule states that a Principal or Vice-Principal absent from office without excuse shall be sanctioned. A court holds that it does not apply to ordinary teachers. Which maxim has it applied?","options":["Ut res magis valeat quam pereat","Expressio unius est exclusio alterius","Lex non cogit ad impossibilia","Noscitur a sociis"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Expressio unius est exclusio alterius means that expressly mentioning one thing excludes others, so naming the Principal and Vice-Principal leaves other staff out. Option D means a word takes its meaning from the words around it. Option C means the law does not compel the impossible, and Option A means a provision should be read so that it works rather than fails."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 403, $official_bank_source${"itemId":"1526efa7-c7b2-507d-a7e8-3f9745c4115d","questionId":"5f7ebf93-cf5d-5dcc-8613-028bb155355f","sourceKey":"bank:PUL101:PQ-005-09","payload":{"prompt":"The maxim noscitur a sociis means that","options":["the express mention of one thing excludes others","a provision should be interpreted so that it is effective rather than void","a word takes its meaning from the other words with which it is associated","the law does not compel the doing of impossibilities"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Noscitur a sociis literally means 'it is known by its companions': the meaning of a doubtful word is gathered from its context. Option A is expressio unius est exclusio alterius, Option D is lex non cogit ad impossibilia, and Option B is ut res magis valeat quam pereat."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 404, $official_bank_source${"itemId":"1df9d1c4-5799-5c09-8b3f-15dfc0e48c6b","questionId":"96c35a85-94b9-5f5f-abea-49752c030e4a","sourceKey":"bank:PUL101:PQ-005-10","payload":{"prompt":"Which of the following is a presumption courts use as a guide to legislative intention?","options":["A presumption against ousting the jurisdiction of the courts","A presumption that every new Act silently changes all existing law","A presumption that statutes operate retrospectively","A presumption in favour of criminal liability without fault"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Courts presume that the legislature does not intend to shut people out of the courts, so a clause ousting jurisdiction must be clear and is construed strictly. The real presumptions are the opposite of Option C and Option D: against retrospective operation and against liability without fault. Option B is also wrong, since an Act is presumed not to alter existing law unless it says so."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 405, $official_bank_source${"itemId":"002478ab-ab4c-5612-b264-2c0afead954e","questionId":"17087f34-3331-5421-899f-f7107d038bd1","sourceKey":"bank:PUL101:PQ-005-11","payload":{"prompt":"Which of the following is an intrinsic aid to the interpretation of a statute?","options":["The Interpretation Act","A law dictionary","The preamble or long title of the statute","A textbook by a recognised author"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Intrinsic aids are found inside the statute itself, such as the long title, preamble, definition or interpretation sections and schedules. A dictionary (Option B), a writer's book (Option D) and the Interpretation Act (Option A) all come from outside the statute, so they are extrinsic aids."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 406, $official_bank_source${"itemId":"5632883f-27e2-51fe-9d2c-9da88aa48ed8","questionId":"2aa7872a-6818-554e-bf9c-4bb6235a4bca","sourceKey":"bank:PUL101:PQ-006-01","payload":{"prompt":"A statute that applies to everyone and everywhere within the state, such as the Criminal Code, is","options":["a public general Act","a local Act","a private Act","a consolidating Act"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A public general Act has general application throughout the country to all persons. Option B applies only to a particular area or community, Option C applies to a particular person or body, and Option D describes a re-enactment of earlier statutes, which is about form rather than scope."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 407, $official_bank_source${"itemId":"65ab7d7a-ac98-578d-bcaa-45fc530d8185","questionId":"03bfbc1e-0330-5d7f-b99c-db440b53f6f3","sourceKey":"bank:PUL101:PQ-006-02","payload":{"prompt":"A law imposing a curfew in one part of the federation, or a law establishing a particular university, is best classified as","options":["a public general Act","a consolidating Act","a code","a local Act"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A local Act applies to a particular locality or community, or deals with a particular regional problem or institution. Option A applies everywhere in the state, Option C gathers statute, common law and equity on a subject into one document, and Option B re-enacts earlier statutes as a coherent whole."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 408, $official_bank_source${"itemId":"ebc4f4d1-fada-5ff7-b093-01ab07118426","questionId":"9ecfaa45-6e1d-5b9f-948f-55bdad0b5110","sourceKey":"bank:PUL101:PQ-006-03","payload":{"prompt":"A statute granting a state pardon to a named convicted person, or proscribing a particular union, is","options":["a private Act","a local Act","a code","a public general Act"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A private Act is even narrower than a local Act: it is made in respect of a particular person or body of persons. Option D applies to everyone, Option B applies to a particular place, and Option C brings together all the law on a subject."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 409, $official_bank_source${"itemId":"d6aaee81-5b18-5871-bee5-5cab7672cd69","questionId":"d783a9d8-9620-52a5-a99f-4c33a75f03fc","sourceKey":"bank:PUL101:PQ-006-04","payload":{"prompt":"A newly passed statute that re-enacts the contents of earlier related statutes, with necessary modifications, to produce one coherent whole is","options":["a private Act","a code","subsidiary legislation","a consolidating Act"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A consolidating Act brings scattered statutes on a subject together into a single enactment. It is different from Option B, which goes further by also gathering common law principles and doctrines of equity. Option A applies to a particular person, and Option C is made by a body other than the legislature."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 410, $official_bank_source${"itemId":"be38ae15-b6f0-52bd-ae8d-69e1a96eef65","questionId":"60dca7d2-5ec2-5a9a-a160-2cf7d3b66108","sourceKey":"bank:PUL101:PQ-006-05","payload":{"prompt":"What distinguishes a code from an ordinary consolidating Act?","options":["A code applies only to one locality","A code applies only to a particular named person","A code brings together existing statutes and also the principles of common law and doctrines of equity on a subject","A code is made by a minister under delegated powers"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A code, such as the Criminal Code, aims to state all the law on a subject in one document, including rules that came from common law and equity, while consolidation only re-enacts statutes. Option A describes a local Act, Option D subsidiary legislation, and Option B a private Act."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 411, $official_bank_source${"itemId":"3bf1241a-bcf5-5c36-8e9e-6866a97815e5","questionId":"a3642c64-6280-5771-bceb-5ec077305cdc","sourceKey":"bank:PUL101:PQ-006-06","payload":{"prompt":"Bye-laws of local governments, regulations of public corporations and statutory instruments made by ministers are examples of","options":["subsidiary (delegated) legislation","Acts of the National Assembly","codes","judicial precedents"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Subsidiary or delegated legislation is law made by persons or bodies other than the legislature, under powers conferred by a statute. Option B are made by the legislature itself, Option C are comprehensive statutes, and Option D are court decisions, not legislation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 412, $official_bank_source${"itemId":"917b5856-2c8d-53ff-8a8d-abd5a6d6d6db","questionId":"20d4f1db-e175-5ab3-ac29-4d612387adc9","sourceKey":"bank:PUL101:PQ-006-07","payload":{"prompt":"The statute under which a subsidiary legislation is made is known as","options":["the private statute","the consolidating statute","the enabling statute","the interpretation statute"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The enabling statute (or parent Act) confers the power to make the subsidiary legislation and sets its limits. Option B re-enacts earlier statutes, Option A applies to a particular person, and Option D refers to the Interpretation Act, which defines common words used in legislation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 413, $official_bank_source${"itemId":"592747ab-a884-5c82-bb95-5769cb197647","questionId":"ad5ede20-100a-5ec0-bcb3-b5a64e7ef0dc","sourceKey":"bank:PUL101:PQ-006-08","payload":{"prompt":"Subsidiary legislation that goes beyond the limits of the power conferred by its enabling statute is","options":["valid until the legislature expressly repeals it","ultra vires, null and void","automatically converted into an Act of the National Assembly","valid if it was published in the Gazette"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Delegated power must be exercised within its limits; anything beyond them is ultra vires (beyond power) and void. Option A and Option D are wrong because publication or the absence of repeal cannot cure a lack of power, and Option C is simply not how delegated legislation works."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 414, $official_bank_source${"itemId":"b910331f-96fc-543e-985e-3354ac72fab5","questionId":"3e8c8bdf-3c2c-5581-82f9-02ee1983e9c8","sourceKey":"bank:PUL101:PQ-006-09","payload":{"prompt":"Which of the following is a main reason for the use of delegated legislation?","options":["It allows the courts to make laws without any statutory authority","The Constitution forbids the legislature from making detailed laws","The legislature cannot make detailed rules for every aspect of life, and many areas need technical expertise","Delegated legislation is always superior to statutes"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The legislature usually sets out the general framework and leaves specialists and agencies to fill in technical details and respond to changing circumstances. Option B is false, Option D is the reverse of the truth because delegated legislation is inferior to its enabling statute, and Option A misdescribes it since it always rests on a statute."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 415, $official_bank_source${"itemId":"5bb7851f-a58c-5443-a78d-2baaafd1789d","questionId":"0a6e5219-6891-5d41-b7ee-fc288a1b3a57","sourceKey":"bank:PUL101:PQ-006-10","payload":{"prompt":"In Nigerian legislative terminology, an enactment made by a State Military Governor or Administrator during military rule is called","options":["a Decree","a Law","an Act","an Edict"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Under military rule, the Federal Military Government made Decrees while State military governors made Edicts. In civilian times, the National Assembly makes Acts and a State House of Assembly makes Laws. So Option A, Option C and Option B are the names for enactments by other law makers."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 416, $official_bank_source${"itemId":"dc92c1f8-7e70-592e-aee0-2f719fb590e7","questionId":"f0869549-302f-53ca-9d18-7dfe995f0920","sourceKey":"bank:PUL101:LEG-001","payload":{"prompt":"Strictly speaking, legislation as a source of law refers to law made by which of the following?","options":["Superior courts when they lay down principles in decided cases","The legislature, the body whose primary duty is to make law","A community whose customs are accepted by its members as binding","Any ministry, university or public corporation that issues rules"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"In the strict sense, legislation is law made by the legislature, the organ whose main job is law-making, as B states. Option D describes the wider sense in which many agencies make rules, and A describes judicial precedent. Option C is customary law, not legislation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 417, $official_bank_source${"itemId":"58adef30-01b2-55c5-9293-04ff03118a70","questionId":"23b00a65-2c14-50c5-b9c5-05aba578b5d1","sourceKey":"bank:PUL101:LEG-002","payload":{"prompt":"The formal and express promulgation or declaration of legal rules, proscriptions or directions into statutes on the subjects to which they relate best describes:","options":["Judicial precedent","Legislation","Customary law","Doctrines of equity"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Legislation is the formal, express declaration of legal rules into statutes, so B is right. Judicial precedent (A) comes from court decisions, while customary law (C) and equity (D) grew from usage and the Chancery courts rather than from formal enactment."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 418, $official_bank_source${"itemId":"ec52189b-7be0-582d-88fb-62e5fb527775","questionId":"72fe201c-34dd-5f20-816e-ce51875737ab","sourceKey":"bank:PUL101:LEG-003","payload":{"prompt":"Section 4(2) of the 1999 Constitution empowers the National Assembly to make laws for the:","options":["Peace, order and good government of the Federation","Welfare, security and prosperity of the Federation","Unity, faith and progress of the Federation","Justice, equity and good conscience of the Federation"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Section 4(2) gives the National Assembly power to make laws for the peace, order and good government of the Federation, which is A. Option D borrows the wording of the repugnancy test for customary law, and C and B are invented phrases that only sound constitutional."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 419, $official_bank_source${"itemId":"f405fd35-0b69-5062-97cc-338bec87da09","questionId":"57ef28de-9e33-5d36-9faf-12e5ef49cd95","sourceKey":"bank:PUL101:LEG-004","payload":{"prompt":"Which of the following is NOT one of the reasons for making new legislation or changing old laws?","options":["Change in the political and economic ideologies of government","The need to preserve every existing custom whatever the change in values","Scientific and technological breakthroughs","The dynamic nature of society"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"New laws are made because society changes, so a wish to freeze every custom regardless of change (B) is not a reason for legislation; many customs have in fact been set aside as repugnant. Options D, C and A are all recognised reasons, along with global shifts in value and the arrest of anti-social behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 420, $official_bank_source${"itemId":"85d39e17-191b-5b79-99ab-e419b5becc01","questionId":"7920587e-e9e5-54dc-b87f-9ab2d31d8c0b","sourceKey":"bank:PUL101:LEG-005","payload":{"prompt":"The spread of computers and the Internet creates new problems about private information being shared with everyone and about copyright in broadcast music, so the National Assembly begins work on information technology laws. Which reason for new legislation does this illustrate?","options":["Change in the political ideology of a new government","Scientific and technological breakthroughs","Global shifts in value systems","The transition from a military to a civilian regime"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Laws prompted by new inventions such as computers, satellites and the Internet are made to cope with scientific and technological breakthroughs, so B is correct. Option A and D concern changes of government, and C concerns changing ideas of justice such as women's and children's rights, not new technology."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 421, $official_bank_source${"itemId":"f2c5849c-6782-5ebc-8259-550a87b889ee","questionId":"d7d58c65-b95b-58cc-80c1-85bfe382acb8","sourceKey":"bank:PUL101:LEG-006","payload":{"prompt":"After a military regime hands over to an elected government, the new administration repeals several Decrees and abolishes an agency created by the old regime in order to pursue its own policies. Which reason for legislation is at work?","options":["The need to codify customary law","Global shifts in value systems","Change in the political and economic ideologies of government","Scientific and technological breakthroughs"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"When the baton of governance changes, new goals and ideologies make changes in the law inevitable, as in the abolition of the Petroleum Trust Fund after the return to civil rule; that is C. Options D and B are different reasons, and A is about codification rather than a change of government."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 422, $official_bank_source${"itemId":"6061a10c-af2f-50cf-8d60-d9ed3741fef2","questionId":"3a9e5906-3478-5995-84ca-262a6889a4b9","sourceKey":"bank:PUL101:LEG-007","payload":{"prompt":"Nigeria joins several international organisations and, influenced by them, passes laws on the rights of women and children and on the protection of endangered species. Which reason for legislation does this best illustrate?","options":["Global shifts in value systems","Arrest of anti-social behaviour","Change in the political ideology of government","Scientific and technological breakthroughs"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Laws on women's and children's rights and on conservation that reflect international standards come from global shifts in value systems, so A is right. Option D concerns new technology, C concerns a change of government, and B concerns curbing harmful conduct such as fraud."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 423, $official_bank_source${"itemId":"ee826d98-7ba3-5cf6-a0d4-84fddf18e77b","questionId":"053295eb-6cba-5fe3-b427-28fbcb76c284","sourceKey":"bank:PUL101:LEG-009","payload":{"prompt":"As people adopt new attitudes about public health, a State enacts a law forbidding the dumping of refuse in public places and the indiscriminate slaughtering of animals. Which reason for legislation does this best illustrate?","options":["The need to consolidate existing statutes","Scientific and technological breakthroughs","Change in the political ideology of government","The dynamic nature of society"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Because human beings and their values keep changing, the law must also change, and laws on refuse dumping and slaughtering are given as examples of this, so D is right. Option B concerns new inventions, C concerns a change of government, and A describes a type of Act rather than a reason for new law."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 424, $official_bank_source${"itemId":"07215612-03ea-574e-b896-616d89bf7968","questionId":"ba0450e5-bb28-50f0-a6a1-39d795cd1434","sourceKey":"bank:PUL101:LEG-010","payload":{"prompt":"Which of the following statements about who may initiate a proposal for legislation is correct?","options":["Only the President or a State Governor may initiate a proposal","Proposals may come from citizens, interest groups, NGOs, communities, ministries or legislators","Only a serving member of the National Assembly may initiate a proposal","Only the Law Reform Commission may initiate a proposal"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Legislative proposals can be instigated by citizens, interest groups, communities, private persons, NGOs, government ministries or legislators, as B says. Options A, C and D each wrongly limit the right to one body; for example, a private person's idea can be presented through a member of the National Assembly."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 425, $official_bank_source${"itemId":"571e162c-c009-5aea-9da9-e5a7ff53d764","questionId":"94764d76-9085-5f1a-b39c-5a26ea0529b6","sourceKey":"bank:PUL101:LEG-011","payload":{"prompt":"Which statement about the form of a legislative proposal is correct?","options":["It must be a fully drafted bill with long title and enacting clause","It must be written in English, Hausa, Igbo and Yoruba before submission","It must follow a form prescribed in the Second Schedule to the Constitution","It need not take a stereotyped form but should be logically and structurally presented"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A legislative proposal need not assume any fixed form, although it makes sense to present it logically and to state the subject matter it relates to, so D is right. Option A confuses a proposal with a finished bill, which comes later, and C and B invent formal requirements that do not exist."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 426, $official_bank_source${"itemId":"d2873055-ff99-59d3-9247-e9caaaba60d8","questionId":"8745e25f-c35c-5f30-9cfc-2b381487c627","sourceKey":"bank:PUL101:LEG-012","payload":{"prompt":"In what order should a well-structured legislative proposal usually present its contents?","options":["Suggested changes, present position, concrete proposals for the law, anomalies","Present position, anomalies, suggested changes, concrete proposals for the law","Concrete proposals for the law, present position, anomalies, suggested changes","Anomalies, concrete proposals for the law, present position, suggested changes"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A proposal first describes the present position, then the anomalies or problems, then suggestions for change, and lastly concrete proposals and a framework for the law, which is the order in B. The other options put the concrete framework or the suggestions before the problem has been shown, which reverses the logic of the proposal."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 427, $official_bank_source${"itemId":"39235bdb-2907-518f-a529-0c0c59eee30c","questionId":"ead58048-6ee3-5af1-bf5a-f7aa8a958546","sourceKey":"bank:PUL101:LEG-013","payload":{"prompt":"Which of the following is NOT a usual channel through which legislative proposals are expressed or submitted?","options":["Memoranda submitted to the Law Reform Commission","A judgment of the Supreme Court addressed to the parties","Opinions expressed in the print and electronic media","Memoranda submitted to the relevant committee of the legislature"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A court judgment settles a dispute between parties; it is not a channel for proposing new legislation, so B is the odd one out. Proposals are normally expressed in memoranda to government departments, the legislature or its committees (D) or the Law Reform Commission (A), and may also appear in the media (C) or come through pressure groups."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 428, $official_bank_source${"itemId":"067367f9-8d05-5b33-8f62-e0200f9f9581","questionId":"823aa19d-5b04-59e1-b926-7da82a97fba7","sourceKey":"bank:PUL101:LEG-014","payload":{"prompt":"A national teachers' union writes newspaper articles and submits memoranda urging a law to make teaching a regulated profession. In legislative terms, the union is:","options":["Making delegated legislation under an enabling statute","Channelling a legislative proposal as a pressure group","Presenting a bill for its first reading","Promulgating a Decree on behalf of the executive"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Professional, economic and other pressure groups often channel legislative proposals through memoranda and the media, as the Nigerian Union of Teachers did on professionalising teaching, so B is right. A union has no power to make delegated legislation (A) or Decrees (D), and only a bill already before a House can have a first reading (C)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 429, $official_bank_source${"itemId":"a8e36744-3970-5eb9-a1e1-45a5c3e4d29b","questionId":"f76d1d4f-103c-53a5-ac02-912194aae5f0","sourceKey":"bank:PUL101:LEG-015","payload":{"prompt":"A legislative draftsman should receive detailed instructions before drafting. Which of the following is NOT one of the items the instructions should state?","options":["The names of the judges who will later interpret the law","The object of the legislation and background information","The mischief or need the law is meant to cure or meet","The implementation bodies, procedures and possible exemptions"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Drafting instructions should state the object, background, the mischief or need to be met, the implementing bodies, procedures and instruments, and possible exemptions, which covers B, C and D. Who will later interpret the law (A) is not something a draftsman is told or needs; interpretation is for whichever court hears a case."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 430, $official_bank_source${"itemId":"ae05fe2b-6e31-5520-a984-664b64550967","questionId":"61b9aa0c-f269-5dbb-9a4d-d1242333329a","sourceKey":"bank:PUL101:LEG-016","payload":{"prompt":"Which of the following is NOT a quality expected of a good legislative draftsman?","options":["Familiarity with the socio-cultural and political peculiarities of the country","High intellectual competence and an analytical, diagnostic mind","Patience, care and close attention to detail","Firmness in refusing corrections and criticisms of his draft"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A good draftsman must be amenable to corrections, suggestions and criticisms, so refusing them (D) is the opposite of what is expected. Options B, A and C are all listed qualities, because the draftsman writes for legislators, lawyers, judges and ordinary citizens alike."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 431, $official_bank_source${"itemId":"97d0d886-fab1-5655-82a1-0ab34311234a","questionId":"bf580bfb-36e2-5daf-9ae5-2aa4fd5f3949","sourceKey":"bank:PUL101:LEG-017","payload":{"prompt":"The chairman of a local government council plans to appoint any Arts graduate as the council's legislative draftsman because 'drafting is only about good English'. What is the best advice?","options":["Let the councillors draft bills themselves, since they will vote on them","Appoint any Arts graduate, since mastery of English is the only skill needed","Appoint a professional linguist, since bills are judged mainly on grammar","Appoint a lawyer, because knowledge of law is an indispensable quality of a draftsman"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Drafting a bill free of ambiguity, vagueness and textual defects needs legal training, so the council should engage a lawyer with the other qualities of a draftsman, as D says. Good English matters, but B and C ignore the legal technicalities, and A ignores that drafting is a specialist skill separate from voting."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 432, $official_bank_source${"itemId":"0e5f52ea-4410-5e89-916c-9d1e7f54210e","questionId":"56ec712d-9027-54d2-97df-23b231dff4fb","sourceKey":"bank:PUL101:LEG-018","payload":{"prompt":"Section 55 of the 1999 Constitution provides that the business of the National Assembly shall be conducted in:","options":["English only, with no provision for any Nigerian language","English and Nigerian Pidgin, whichever members prefer","English, and in Hausa, Ibo and Yoruba when adequate arrangements have been made","Hausa, Ibo and Yoruba only, with English used for records"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Section 55 names English, and Hausa, Ibo and Yoruba once adequate arrangements are made, which is C; in practice English remains the language of the law in Nigeria. Option A ignores the three indigenous languages the section mentions, while D and B misstate which languages are listed."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 433, $official_bank_source${"itemId":"9b80f4ab-682e-5661-910a-dd3021e35016","questionId":"97693488-19a5-580d-84bf-2aa52369d9b4","sourceKey":"bank:PUL101:LEG-019","payload":{"prompt":"Under the drafting principle of mastery and familiarity of language, which practice should a draftsman follow?","options":["Use expressions peculiar to each ethnic group so all feel included","Prefer Latin phrases such as pari passu because they are more precise","Use technical legal jargon so that only lawyers can apply the law","Use common, familiar English words and avoid tribal or Latin expressions"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The draftsman should stick to common, familiar words so that people do not need a lawyer or a linguist to know what the law says, and should avoid tribal expressions and even assimilated Latin like inter alia or pari passu, so D is right. Options B, A and C each recommend exactly the kind of language the principle warns against."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 434, $official_bank_source${"itemId":"045d7f3d-7d27-51e5-b5a4-fca9a6eb5d7d","questionId":"6b9254f4-6d64-5f2a-8d32-6ab803d77661","sourceKey":"bank:PUL101:LEG-020","payload":{"prompt":"A draft reads: 'where the borrower fails, refuses, neglects, omits or avoids repayment ... in breach of his obligation, undertaking, agreement or promise'. Which drafting principle does it most clearly break?","options":["Economy of language","Consistency of terms","Orderliness","Correct punctuation"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The clause piles up words that do the same work, which is the verbosity that economy of language forbids, so A is right; one word from each list would do. Consistency of terms (B) is about using one word for one idea throughout, orderliness (C) concerns arrangement of sections, and D concerns punctuation marks."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 435, $official_bank_source${"itemId":"e3d8a9ea-0ffd-5f29-8546-dc5e7e784b99","questionId":"4efc531e-355b-59fc-aed3-4af730d263a0","sourceKey":"bank:PUL101:LEG-021","payload":{"prompt":"A draft provides: 'Only courts specified in section 6 above shall exercise the powers hereinafter contained in this section.' Which drafting fault does the use of 'above' and 'hereinafter' show?","options":["Lack of orderliness","Ambiguity","Archaism","Inconsistency of terms"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Words such as 'hereinafter', 'hereinbefore' and 'above mentioned' are archaic and can be removed without any damage to the meaning, so the fault is archaism, C. The sentence has only one meaning, so it is not ambiguous (B), it does not switch terms (D), and its arrangement is not in issue (A)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 436, $official_bank_source${"itemId":"e332db5d-2f48-5462-95ae-d223c6b87ab5","questionId":"8b134816-6f67-5033-983b-490ad7910673","sourceKey":"bank:PUL101:LEG-022","payload":{"prompt":"In a draft Tenancy Law, section 2 refers to 'the lessor' and section 5 refers to 'the landlord', although both mean the same person. Which drafting principle is breached?","options":["Direct and explicit expression","Avoidance of archaism","Consistency of terms","Economy of language"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Once a draftsman picks a word for an idea he must use it throughout, and 'lessor' and 'landlord' should not be used interchangeably for the same person, so C is right. Economy (D) is about cutting redundant words, B is about old-fashioned words, and A is about avoiding winding sentences."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 437, $official_bank_source${"itemId":"2f69a5a9-a41e-5ce9-b7e0-bf9ee5d55103","questionId":"37bc15bf-d507-576d-8c01-87066f307218","sourceKey":"bank:PUL101:LEG-023","payload":{"prompt":"A drafter replaces a long, winding clause on self-defence with the simple sentence 'Every person has a right to defend himself when attacked.' Which drafting principle is being applied?","options":["Consistency of terms","Use of an interpretation clause","Use of schedules","Direct and explicit expression"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Replacing a clumsy, intricate clause with a short sentence that carries the same meaning applies the principle of direct and explicit expression, so D is right. Consistency of terms (A) is about using one word per idea, while schedules (C) and interpretation clauses (B) are separate structural devices."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 438, $official_bank_source${"itemId":"870d37fa-6fff-5453-a4f9-ad1e120d18af","questionId":"5867e306-1dbb-512f-8495-2b14dffd8662","sourceKey":"bank:PUL101:LEG-024","payload":{"prompt":"Why must a draftsman be careful with connective words such as 'from' and 'to' in a time provision?","options":["They are archaic words that should never appear in a statute","They may either include or exclude the stated periods","They are defined in the same way in every Nigerian statute","They always oblige the reader to count only working days"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Connective and definitive words can carry more than their everyday meaning; 'from' and 'to' may include or exclude stated periods, just as 'shall' may signal duty or discretion and 'or' may join or offer alternatives, so B is right. They are not archaic (A), and D and C invent fixed rules that do not exist."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 439, $official_bank_source${"itemId":"e6c00e89-e94c-5d78-bcea-10b3262ec245","questionId":"41bba5ea-7c44-5f62-8b24-8875dad3066f","sourceKey":"bank:PUL101:LEG-025","payload":{"prompt":"Writers and drafters are advised to avoid certain pitfalls of style. Which of the following is NOT such advice?","options":["Use the same word always for the same idea","Be wary of using metaphors in a draft","Avoid repetitions and needless duplications","Vary words for the same idea to add elegance"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The advice is to use the same word for the same idea, because elegant variation is confusing in a statute, so D reverses the rule. Options B, A and C are the three pitfalls a drafter is warned about; a statute is not a literary masterpiece or an experiment in synonyms."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 440, $official_bank_source${"itemId":"ec5ec11b-de49-5a35-8c59-14a9c76f54e4","questionId":"d56dcb13-ecc4-5232-a226-364bdb5bc7c0","sourceKey":"bank:PUL101:LEG-026","payload":{"prompt":"A statute whose language affords two or more mutually exclusive meanings, each of which can be deduced from the text, is said to be:","options":["Ultra vires","Ambiguous","Vague","Archaic"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Ambiguity exists when a provision is capable of two or more mutually exclusive meanings, each deducible from the text, so B is right. Vagueness (C) is a cloudy, indeterminate meaning rather than competing clear ones, A refers to subsidiary law made beyond its powers, and D refers to old-fashioned words."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 441, $official_bank_source${"itemId":"3c776147-953d-56eb-b1c6-4cdda105900a","questionId":"b59c29b3-fba7-5755-8e3d-ca059289103f","sourceKey":"bank:PUL101:LEG-027","payload":{"prompt":"Ambiguity in statutes is often classified into three types. Which of the following is NOT one of them?","options":["Syntactic ambiguity","Lexical ambiguity","Procedural ambiguity","Contextual ambiguity"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The three usual classes are lexical, syntactic and contextual ambiguity, which are B, A and D. 'Procedural ambiguity' (C) is not one of the recognised classes."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 442, $official_bank_source${"itemId":"6384f4a8-b8fb-5041-b9b1-a81bee2992e2","questionId":"912964ad-85d5-5e62-8f02-f4c382d9a98a","sourceKey":"bank:PUL101:LEG-028","payload":{"prompt":"Why is vagueness in a statute regarded as worse than ambiguity?","options":["A vague provision can hardly be resolved by reference to the context of the statute","Vagueness affects only marginal notes, not the operative sections","An ambiguous provision can never be resolved by any court","A vague provision always has exactly two possible meanings"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A vague provision is cloudy and indeterminate, and unlike an ambiguous one it can hardly be cured by looking at the context of the statute, so A is right. Option D actually describes ambiguity, B is invented, and C is wrong because ambiguity can often be resolved from context."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 443, $official_bank_source${"itemId":"f6b2ede7-54e0-5c06-a68d-2f0293385fc3","questionId":"b0f0e3a3-458f-5054-b432-31af88ee5ac2","sourceKey":"bank:PUL101:LEG-029","payload":{"prompt":"A State Law bans 'large gatherings' without a permit but does not say how many people make a gathering 'large'. Officials cannot say whether a meeting of 40 people is covered. This defect is best described as:","options":["Archaism caused by old-fashioned legal words","Vagueness, creating borderline cases with no definite answer","Lexical ambiguity between two clear dictionary meanings","Inconsistency of terms across different sections"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Where a provision creates borderline cases in which there is no definite answer whether it applies, the defect is vagueness, so B is right. The word 'large' does not offer two competing clear meanings, so C does not fit, and there are no archaic words (A) or switched terms (D) in the provision."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 444, $official_bank_source${"itemId":"4c6d775d-23c7-5594-b339-4042cda9866f","questionId":"cf5aa7cd-dc0d-50cf-80b9-41e3e4a74f31","sourceKey":"bank:PUL101:LEG-030","payload":{"prompt":"A statute requires every 'bank' within a river basin to be registered. One party argues it means financial institutions; another argues it means riverbanks. Each reading fits the words. This is an example of:","options":["Ambiguity","Economy of language","Open texture deliberately built in","Vagueness"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The word 'bank' here yields two mutually exclusive meanings, each deducible from the text, which is ambiguity, A; it is lexical ambiguity because it arises from a single word. Vagueness (D) is an indeterminate meaning rather than two clear rivals, C is intended flexibility, and B is a drafting virtue, not a defect."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 445, $official_bank_source${"itemId":"d89db0c4-bbc0-5b62-a473-a68ea9a3e07a","questionId":"fcb03b9d-1ce5-5d14-9201-45f06602c573","sourceKey":"bank:PUL101:LEG-031","payload":{"prompt":"In legislative drafting, 'open texture' refers to:","options":["Built-in generality or flexibility, since no statute can foresee every future case","The rule that all bills must be gazetted before second reading","A drafting error in which two sections contradict each other","The practice of opening each statute with a long title and preamble"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Because a drafter must make a rule general enough to cover unforeseen cases while keeping it clear, and no statute can settle all future situations in advance, flexibility or open texture is built into legislation, so A is right. Option D describes preliminary parts, C describes inconsistency, and B confuses open texture with gazetting."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 446, $official_bank_source${"itemId":"676333c7-6439-520c-b9f5-d489936508a1","questionId":"9bc09606-b6e2-5630-8cb5-7fa43387b40e","sourceKey":"bank:PUL101:LEG-032","payload":{"prompt":"The observation that 'breadth of scope and precision are not always compatible objectives' describes which dilemma of the drafter?","options":["Deciding whether to use marginal notes or schedules","Deciding whether a bill should start in the Senate or the House","Choosing between drafting in English and in an indigenous language","Making a rule general enough to cover all foreseeable cases yet detailed and clear"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The drafter must make a rule broad enough to cover all foreseeable instances within the policy of the statute and also detailed enough to be clear, and these two aims pull against each other, so D is right. Options C, B and A are practical choices, not the generality-versus-precision dilemma behind open texture."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 447, $official_bank_source${"itemId":"e1e2ffa9-d449-5832-909f-bf975fff9927","questionId":"a0cc3806-ee3c-5f8d-96ad-f3ad2f363781","sourceKey":"bank:PUL101:LEG-033","payload":{"prompt":"In what order do the parts of a Commonwealth-style statute usually appear?","options":["Preliminary, final, principal, executive endorsement, miscellaneous","Principal, preliminary, final, miscellaneous, executive endorsement","Executive endorsement, preliminary, principal, miscellaneous, final","Preliminary, principal, miscellaneous, final, executive endorsement"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The usual order is preliminary parts, principal parts, miscellaneous parts, final parts and then the executive endorsement where the bill is signed, as in D. The other options misplace the endorsement, which comes last, or put substantive provisions ahead of the long title and enacting clause."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 448, $official_bank_source${"itemId":"3143c56f-d2e3-53d7-86c8-b1b16d225678","questionId":"29b186f1-d3a5-5223-b158-338ca2a7ee38","sourceKey":"bank:PUL101:LEG-034","payload":{"prompt":"A draftsman is placing a clause that repeals an earlier Act, saves certain rights under it and makes transitional arrangements. In which part of the statute does this clause usually belong?","options":["Preliminary parts","Principal parts","Final parts","Executive endorsement part"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Final parts provide for savings, transitional provisions, repeals, schedules and possibly an interpretation section, so C is right. Preliminary parts (A) hold the long title, preamble, short title, enacting and commencement clauses, principal parts (B) hold the substantive and administrative provisions, and D is where the bill is signed."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 449, $official_bank_source${"itemId":"4324ec3b-05bf-5845-ab09-a129458fba93","questionId":"bef58b95-fcf1-5e02-80c7-e437c49a9af7","sourceKey":"bank:PUL101:LEG-035","payload":{"prompt":"Which of the following belongs to the preliminary parts of a statute?","options":["The offences and other supplementary provisions","The substantive provisions and the administrative provisions","The savings, transitional provisions and repeals","The long title, short title, enacting clause and commencement clause"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Preliminary parts comprise the long title, the preamble (usually but not always), the short title or citation, the enacting clause and the commencement clause, so D is right. Option B describes the principal parts, A the miscellaneous parts, and C the final parts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 450, $official_bank_source${"itemId":"d91a43a0-fd0d-5d76-b84d-eca39e3d6e3a","questionId":"9e7e5f6a-538d-5ec5-bd2c-638fe25900cf","sourceKey":"bank:PUL101:LEG-036","payload":{"prompt":"The part of a statute that contains its substantive provisions and its administrative provisions naming the enforcing agencies is called the:","options":["Final parts","Principal parts","Miscellaneous parts","Preliminary parts"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The principal parts contain the substantive provisions, which are the main business of the law, and the administrative provisions stating the enforcing instruments and agencies, so B is right. Preliminary parts (D) introduce the law, miscellaneous parts (C) hold offences and supplementary provisions, and final parts (A) hold savings, repeals and schedules."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 451, $official_bank_source${"itemId":"86c11a1e-93c6-51be-ba4a-159282c7ffa5","questionId":"ce8932c8-9100-5d5a-be0e-8f2b4a13488d","sourceKey":"bank:PUL101:LEG-037","payload":{"prompt":"In the structure of a statute, 'schedules' are used to:","options":["Record the votes cast at the third reading of the bill","Contain the President's signature and the date of assent","State the long title and the date of commencement","Set out elaborate technical information that cannot conveniently go in the main text"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Schedules carry more elaborate, technical or explicit information that could not conveniently be included in the main text of the legislation, so D is right. Votes (A) are not part of the statute's text, the signature belongs to the executive endorsement (B), and the long title and commencement are preliminary parts (C)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 452, $official_bank_source${"itemId":"539549cf-dc70-5480-a8ba-d425c5ee8685","questionId":"d0f46194-b9c7-5211-a6dc-2bcb2fa55f34","sourceKey":"bank:PUL101:LEG-038","payload":{"prompt":"Why must a legislative draftsman pay particular attention to punctuation?","options":["Punctuation is ignored by courts, so errors in it are harmless","Punctuation decides which House of the legislature must pass the bill","Punctuation marks may only be used in schedules, not in sections","Changing punctuation alone can alter the meaning of a passage without changing a word"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The effect of punctuation is so far-reaching that the meaning of a paragraph can be changed by tinkering with it without altering any word, so D is right. Option A is wrong because courts take punctuation into account when construing an enactment, and C and B are invented rules."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 453, $official_bank_source${"itemId":"3fa26db4-7321-5f47-af2c-d4e0be8eca0b","questionId":"44b313b8-fb44-58d3-b52c-de5db6bfedbe","sourceKey":"bank:PUL101:LEG-039","payload":{"prompt":"Under the 1999 Constitution, the National Assembly is a bicameral legislature made up of:","options":["The Senate and the House of Representatives","The Senate and the State Houses of Assembly","The House of Representatives and the Federal Executive Council","The Senate and the Council of State"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Nigeria's federal legislature is bicameral, with the Senate and the House of Representatives together forming the National Assembly, so A is right. State Houses of Assembly (B) are separate State legislatures, and the Federal Executive Council (C) and Council of State (D) are executive or advisory bodies."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 454, $official_bank_source${"itemId":"e1242f26-7005-5b10-ac4e-15b92ddb51b4","questionId":"28b29d63-498d-5304-83a3-a2147a5c78a3","sourceKey":"bank:PUL101:LEG-040","payload":{"prompt":"What happens at the first reading of a bill in the House where it originates?","options":["The final draft is voted on by a simple or two-thirds majority","The Clerk reads it to inform members of its subject; no questions are asked on it","A committee goes through it clause by clause and word by word","Members debate its general principles and ask questions on it"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The first reading, done by the Clerk or a designated person, merely introduces members to the subject matter, and the bill is not questioned at that stage, so B is right. Debate on general principles (D) happens at second reading, clause-by-clause scrutiny (C) at committee stage, and the final vote (A) at third reading."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 455, $official_bank_source${"itemId":"a594fd10-f763-5f79-a1d6-5c5cdb75e05d","questionId":"45d549e6-4c5c-5bdc-b032-06456639140e","sourceKey":"bank:PUL101:LEG-041","payload":{"prompt":"At which stage of a bill are its general principles and import debated and questions asked on it for the first time?","options":["Report stage","Committee stage","Second reading","First reading"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"After printing and distribution, the second reading is when the general principles of the bill are discussed and questions asked, so C is right. The first reading (D) is only an introduction, the committee stage (B) is detailed clause-by-clause work, and the report stage (A) presents the amended bill back to the House."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 456, $official_bank_source${"itemId":"2166eaf1-a169-5338-b15e-e23e7f6bf609","questionId":"15688e32-de8c-5eed-a792-458a06152f55","sourceKey":"bank:PUL101:LEG-042","payload":{"prompt":"The function of the committee stage of a bill is best described as:","options":["Voting on the final draft by the required majority","Reading the long title aloud so members know the bill exists","Obtaining the President's signature on the passed bill","Going through the text clause by clause, even word by word, to make it more acceptable"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"At committee stage the bill goes through the text clause by clause and, if necessary, word by word, and may undergo drastic amendment, so D is right. Option B describes the first reading, C describes assent, and A describes the third reading."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 457, $official_bank_source${"itemId":"0cfef4b9-4f74-54d0-9ae9-f38fb59a28e1","questionId":"ad361d5e-f535-5434-a19b-79d0d1277dc3","sourceKey":"bank:PUL101:LEG-043","payload":{"prompt":"The House of Representatives sets up a committee to investigate a specific crisis in the aviation sector, and the committee is dissolved once it submits its report. This committee is:","options":["A joint finance committee","A committee of the whole Senate","An ad hoc committee","A standing committee"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Committees set up from time to time to look into specific issues and dissolved after completing their assignment are ad hoc committees, so C is right. Standing committees (D) are permanent committees on subjects such as education, health and aviation, the joint finance committee (A) deals with disputed money bills, and B concerns the other House."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 458, $official_bank_source${"itemId":"801960dd-4176-5446-a4c2-c9dd9ccca7e4","questionId":"50d0b3d2-b599-504a-81c4-703501c8ae53","sourceKey":"bank:PUL101:LEG-044","payload":{"prompt":"The stage at which a bill is put before the House in its amended or revised form after committee work, when its likely success or failure becomes evident, is the:","options":["Second reading","First reading","Assent stage","Report stage"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"After the committee stage comes the report stage, when the amended bill is laid before the House for further consideration, so D is right. The second reading (A) comes before committee work, the first reading (B) is only an introduction, and assent (C) follows passage by both Houses."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 459, $official_bank_source${"itemId":"1f88884b-d289-5c92-931f-bb59ea34292c","questionId":"3a9e20cb-96cd-52ff-8ee5-780e12faa262","sourceKey":"bank:PUL101:LEG-045","payload":{"prompt":"Which sequence correctly shows the stages of a bill in its House of origin?","options":["First reading, second reading, committee stage, report stage, third reading","First reading, committee stage, second reading, third reading, report stage","Second reading, first reading, report stage, committee stage, third reading","First reading, second reading, report stage, committee stage, third reading"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A bill is introduced at first reading, debated in principle at second reading, examined in detail at committee stage, returned to the House at report stage, and then read a third time and voted on, which is A. Option D reverses the committee and report stages, and the other options put debate or reporting in the wrong place."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 460, $official_bank_source${"itemId":"e4901f8e-4c4d-5de7-aba0-113a646dfc46","questionId":"5cb53e86-d63c-5054-b474-843bbde3f0c0","sourceKey":"bank:PUL101:LEG-046","payload":{"prompt":"At the third reading, by what majority is a bill passed?","options":["By a simple majority or a two-thirds majority, depending on its subject matter","By the Speaker or Senate President alone if members are divided","Always by unanimous vote of all members present","Always by a three-quarters majority of the whole House"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"At the third reading the bill in its final draft is voted on and passed by a simple majority or by a two-thirds majority depending on its subject matter, so A is right. No rule requires unanimity (C) or three-quarters (D) for ordinary bills, and a presiding officer cannot pass a bill alone (B)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 461, $official_bank_source${"itemId":"6e7a8e10-82af-59f0-a38a-29fcd66086ed","questionId":"03b5d9c8-fcb7-568f-9f02-9d415115fd5e","sourceKey":"bank:PUL101:LEG-047","payload":{"prompt":"After a bill has been passed by the House in which it originated, what happens next?","options":["It becomes law at once if it was passed by two-thirds","It goes straight to the President for assent","It is sent to the other House and goes through a similar procedure","It is sent to the Supreme Court to confirm its validity"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Because the National Assembly is bicameral, a bill passed in its House of origin is sent to the other House, where it passes through a similar procedure before going to the President, so C is right. It does not go straight to the President (B), courts play no part in passing bills (D), and a two-thirds vote in one House alone does not make law (A)."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 462, $official_bank_source${"itemId":"08cef325-8a4a-54d9-a5a5-70d66ef73a70","questionId":"7878ce28-66cc-5205-b130-55711a1b1725","sourceKey":"bank:PUL101:LEG-048","payload":{"prompt":"Under section 58(5) of the 1999 Constitution, what is the effect when the President withholds assent to a bill?","options":["It becomes law if passed again by a simple majority of a joint sitting","It becomes law without assent if passed again by two-thirds majority in each House","It becomes law automatically after the President's term ends","It is dead and can never be reintroduced in the National Assembly"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Where the President withholds assent and the bill is again passed by each House by a two-thirds majority, it becomes law and his assent is not required, so B is right. A veto does not kill the bill forever (D), there is no automatic law at the end of a term (C), and a simple majority (A) is not enough."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 463, $official_bank_source${"itemId":"965e49be-d102-5c31-b3d3-c94062715786","questionId":"2036806a-cc48-5e80-b013-f9df3faca024","sourceKey":"bank:PUL101:LEG-049","payload":{"prompt":"The President withholds assent to a Road Safety Bill. The Senate passes it again by a two-thirds majority, but the House of Representatives passes it again by only a simple majority. What is the position?","options":["It does not become law, because each House must re-pass it by two-thirds","It becomes law, because a simple majority in both Houses is enough","It becomes law, because the Senate's two-thirds vote is enough","It becomes law once the Clerk reads its long title a third time"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Section 58(5) requires the bill to be passed again by each House by a two-thirds majority before it can become law without assent, so a simple majority in the House of Representatives is not enough, as A says. Options C and B each ignore the requirement in one of the Houses, and D invents a rule."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 464, $official_bank_source${"itemId":"ba4d13e1-131f-510b-814d-0f5099d02186","questionId":"64795cff-83f8-5bfb-8fa2-b785097ed8ea","sourceKey":"bank:PUL101:LEG-050","payload":{"prompt":"What is the effect of the assent of the President or a State Governor on a bill?","options":["It makes the bill a Decree of the National Assembly","It sends the bill to the Senate for its first reading","It sends the bill back to the committee stage for amendment","It turns the passed bill into an Act (federal) or a Law (State)"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Unless the bill is assented to (or the veto is overridden), it cannot become an Act or a Law; assent by the President produces an Act if federal, and by a Governor a Law if State, so D is right. Assent ends the process rather than restarting it (C, B), and Decrees (A) belong to military regimes."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 465, $official_bank_source${"itemId":"ffe6b8b4-a6b9-5110-adbe-a8a2512d0021","questionId":"cc5940bb-84cc-5ecb-a1d7-f3d43835001b","sourceKey":"bank:PUL101:LEG-051","payload":{"prompt":"Why is a bill published in the Gazette after it has been introduced?","options":["To make it binding law immediately on publication","To give the public notice so that people can weigh in for or against it","To show that the President has already assented to it","To obtain the approval of the Chief Justice of Nigeria"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Bills are gazetted to give the public notice that legislation is being considered so that people can make their views known, for or against, so B is right. Gazetting a bill does not make it law (A), the judiciary is not part of the process (D), and assent comes at the end, not at gazetting (C)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 466, $official_bank_source${"itemId":"95354f79-1ff2-57e1-be4b-a272a65e4c16","questionId":"db64928d-f127-5dc4-9f93-9daa440f6e49","sourceKey":"bank:PUL101:LEG-052","payload":{"prompt":"How does law-making under a military regime differ from law-making under a civilian regime in Nigeria?","options":["Military Decrees require a two-thirds vote of the State Houses of Assembly","Military Decrees must pass three readings in both the Senate and the House","Military law-making is slower because each Decree goes to the Supreme Court","Legislative and executive powers are fused, so Decrees are made without readings or debates"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Under military rule the legislature and executive are fused, and a Decree is made by typing and signing a text by the Head of the Federal Military Government without readings, debates or voting, so D is right. This ease explains the many shortcomings and endless amendments in military laws. Options B, A and C describe procedures that did not apply to Decrees."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 467, $official_bank_source${"itemId":"1c8ca27f-644f-5d60-929b-85600e9059af","questionId":"d51053d0-398a-5c29-9ef5-0985539d50be","sourceKey":"bank:PUL101:LEG-053","payload":{"prompt":"During a military regime, the Military Governor of a State signs a short typed text banning street trading in the State capital. That enactment is called:","options":["A Law","A Decree","An Edict","An Act"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"An enactment made by a State Military Governor or Administrator is an Edict, so C is right. A Decree (B) is made by the Federal Military Government, an Act (D) by the National Assembly, and a Law (A) by an elected State House of Assembly."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 468, $official_bank_source${"itemId":"eabbd50c-e60d-5ca1-ac1d-1fcb49afd684","questionId":"6b64510e-891c-5192-9477-40fc42ad3839","sourceKey":"bank:PUL101:LEG-054","payload":{"prompt":"What is a major weakness of legislation made under military regimes?","options":["The involvement of the judiciary, which makes Decrees unconstitutional","The need for a two-thirds vote, which blocks most Decrees","Lack of rigorous scrutiny, which leads to shortcomings and endless amendments","Excessive public consultation, which delays every Decree for years"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Because Decrees and Edicts are made so easily, they escape rigorous criticism and scrutiny, which accounts for their many shortcomings and the endless amendments that follow, so C is right. Options D, B and A describe features of the civilian process or invented rules, not the military process."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 469, $official_bank_source${"itemId":"29e6ec70-6e8e-5c72-aff6-4a6cddc98e08","questionId":"3ba61ebb-1e8a-5509-9996-f8cfce335c72","sourceKey":"bank:PUL101:LEG-056","payload":{"prompt":"The National Assembly passes an Act setting up a commission to tackle environmental and economic problems in one particular region of Nigeria. This Act is best classified as a:","options":["Private Act","Local Act","Public General Act","Code"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A Local Act applies to a particular locality or community, and laws made to combat environmental or economic problems of a particular region, such as the Niger Delta Development Commission Act, are given as examples, so B is right. It is not a Public General Act (C) because it targets one region, not a Private Act (A) because it is not about particular persons, and not a Code (D)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 470, $official_bank_source${"itemId":"dd2179a8-2ec9-5a77-9052-5f81a137cb3b","questionId":"b9be9442-2702-5620-814f-5fd4c89f1ac4","sourceKey":"bank:PUL101:LEG-057","payload":{"prompt":"A statute is passed solely to grant a state pardon to one named convicted person and to return property earlier confiscated from him. This is a:","options":["Local Act","Private Act","Public General Act","Consolidating Act"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A Private Act is made in respect of a particular person or body of persons, for example a statute granting a state pardon to a convicted person or restoring confiscated property, so B is right. A Local Act (A) concerns a place, a Public General Act (C) applies to everyone, and a Consolidating Act (D) re-enacts earlier statutes."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 471, $official_bank_source${"itemId":"b1b7012e-8d43-5bb3-9cfd-d9e90c8dd797","questionId":"d3d319db-d9cb-5d20-ba3e-30927a782412","sourceKey":"bank:PUL101:LEG-058","payload":{"prompt":"A Consolidating Act is best described as a statute that:","options":["Is made by a Minister under powers given by an enabling statute","Applies only to one named person or body of persons","Combines existing statutes, common law and equity on a subject into one document","Re-enacts the contents of earlier related statutes, with necessary changes, as one coherent whole"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A Consolidating Act is a newly passed statute that re-enacts the content of an earlier statute or related statutes, with such modifications as are necessary, to produce a coherent whole, so D is right. Option B describes a Private Act, C describes a Code, which goes further by including common law and equity, and A describes subsidiary legislation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 472, $official_bank_source${"itemId":"ee15092f-cc08-55cf-b79a-36f69ab69f0e","questionId":"b5a654a7-4fef-518d-81da-4e2d16d53603","sourceKey":"bank:PUL101:LEG-059","payload":{"prompt":"A statute that puts together in one document the existing legislation, the principles of common law and the doctrines of equity on a stated subject is a:","options":["Code","Private Act","Local Act","Consolidating Act"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A Code attempts to put existing legislation, common law principles and equitable doctrines on a subject into one comprehensive document, with the Criminal Code, Penal Code and Companies and Allied Matters Act as examples, so A is right. A Consolidating Act (D) re-enacts only earlier statutes, while Local (C) and Private (B) Acts are defined by their limited reach."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 473, $official_bank_source${"itemId":"eb0dac40-0dbf-5d59-867b-c5358a2ab552","questionId":"905f9359-a97a-564f-9973-ef5bf2f4422d","sourceKey":"bank:PUL101:LEG-060","payload":{"prompt":"What is the main difference between a Consolidating Act and a Code?","options":["Consolidation re-enacts statutes only; a Code also takes in common law and equity","Consolidation applies only to States; a Code applies only to the Federation","Consolidation is made by the military; a Code is made by the legislature","Consolidation needs no assent; a Code needs a two-thirds majority"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A Consolidating Act brings together and re-enacts earlier statutes, while a Code sums up the existing legislation together with the principles of common law and doctrines of equity on a subject, so A is right. Options B, C and D invent differences of level, regime and voting that do not define either type."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 474, $official_bank_source${"itemId":"72d7efdb-2e7f-5bbf-a427-e9745144ba3e","questionId":"1f8bf038-85d7-5cd2-9a92-ff6109d79745","sourceKey":"bank:PUL101:LEG-061","payload":{"prompt":"The National Assembly repeals four separate statutes on civil aviation and re-enacts their provisions, with minor changes, in a single new Act. No common law or equitable rules are added. The new Act is a:","options":["Local Act","Consolidating Act","Private Act","Code"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Re-enacting the contents of several related statutes, with necessary modifications, into one coherent statute is consolidation, so B is right. It is not a Code (D) because no common law or equity is being brought in, and it is not limited to particular persons (C) or to one locality (A)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 475, $official_bank_source${"itemId":"75632693-1dbe-57d6-a4c5-b19f60ccfbb4","questionId":"ad5eaafa-a2c5-5a51-8064-c58517e71aba","sourceKey":"bank:PUL101:LEG-062","payload":{"prompt":"Reformers propose a single statute on land in Nigeria that would bring together the Land Use Act, conveyancing statutes, common law rules and customary land tenure. This proposal is an example of:","options":["Delegated legislation","A Private Act","Consolidation of a single statute","Codification"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Pulling scattered statutes, common law and customary rules on land into one comprehensive law that states all the law on the subject is codification, so D is right. Consolidation (C) re-enacts statutes only, delegated legislation (A) is made under an enabling statute, and a Private Act (B) concerns particular persons."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 476, $official_bank_source${"itemId":"541cc2ce-2236-5c1c-b49c-c333298a4fa5","questionId":"9a34aafd-5ae0-51dc-939d-fb943594832f","sourceKey":"bank:PUL101:LEG-063","payload":{"prompt":"Which of the following is NOT an argument in favour of codification?","options":["It simplifies the work of judges and makes the law more accessible","It preserves the flexibility and adaptability of customary law","It reconciles scattered sources of law on a single subject","It eliminates overlapping provisions and encourages reform"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Loss of flexibility is in fact a major objection to codifying customary law, because flexibility and adaptability are its strengths, so B is not an argument in favour. Options C, D and A are the main benefits claimed for codification."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 477, $official_bank_source${"itemId":"34e307e4-e10e-5109-b379-9376d53646d0","questionId":"fae7eee4-3966-5775-831b-4fabb909df0c","sourceKey":"bank:PUL101:LEG-064","payload":{"prompt":"Which jurist opposed codification because he believed in the unconscious, evolutionary growth of law rather than drastic change?","options":["John Austin","Jeremy Bentham","Von Savigny","Hans Kelsen"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Von Savigny, of the historical school, saw law as growing gradually and unconsciously with the people and opposed codification, arguing a code cannot provide in advance for all future cases, so C is right. Bentham (B) was a famous champion of codification, while Austin (A) and Kelsen (D) are known for positivist theories of law, not for this objection."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 478, $official_bank_source${"itemId":"425c7555-c139-5948-bc06-c95dc419db48","questionId":"50dc5aa8-ee0c-5645-a0ea-094d9985e81e","sourceKey":"bank:PUL101:LEG-065","payload":{"prompt":"Which is a reason given against codifying customary law in Nigeria?","options":["Customary law is too rigid to change, so a code adds nothing","Customary law has been fully replaced by received English law","Ethnic diversity and the near irreconcilable differences among customary systems","Customary law already applies uniformly across the whole country"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Codifying customary law is said to be impracticable because of Nigeria's ethnic diversity, the near irreconcilable differences in customary practices, and the threat to flexibility, so C is right. Option D is false since each ethnic group has its own system, A reverses the point that flexibility is customary law's strength, and B is false."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 479, $official_bank_source${"itemId":"a4f7b4a1-fd30-56f2-8d2f-5beb0f8476c5","questionId":"0a1fd381-f249-5fdb-b0e1-6ec2ca7896b0","sourceKey":"bank:PUL101:LEG-066","payload":{"prompt":"To answer the fear that codification fossilises the law, what safeguard is suggested?","options":["A rule that judges may ignore the code where it seems outdated","A standing provision that the code be reviewed every ten or twenty years","A rule that the code can never be amended once enacted","A requirement that each code be re-enacted as a military Decree"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"A standing provision for review of the code, say every ten or twenty years, lets reform keep pace with changing times and answers the fear of fossilisation, so B is right. Option C would cause the very fossilisation feared, A would destroy certainty, and D is unrelated."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 480, $official_bank_source${"itemId":"34ea3171-2a55-598a-8025-45766e4cdaa8","questionId":"1b196628-e90a-53ed-9586-eef708628d0b","sourceKey":"bank:PUL101:LEG-068","payload":{"prompt":"Which of the following is an example of subsidiary (delegated) legislation?","options":["The Constitution of the Federal Republic of Nigeria 1999","An Act passed by the Senate and House of Representatives","Bye-laws made by a local government under powers given by a statute","A Law passed by a State House of Assembly"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Subsidiary or delegated legislation is law made under powers conferred by a statute, such as local government bye-laws, regulations of public corporations and statutory instruments by ministers, so C is right. Options B and D are statutes made by the legislature itself, and A is the supreme law from which other laws derive validity."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 481, $official_bank_source${"itemId":"2618bd75-41c5-50a0-8b5e-799f5553f4bf","questionId":"4e2eb354-fb7a-5ac8-b564-bc78c9cdaba3","sourceKey":"bank:PUL101:LEG-069","payload":{"prompt":"An Act empowers the Minister of Health to make regulations on drug labelling. The Minister makes regulations that also create a new tax on pharmacies, which the Act does not authorise. The tax provision is most likely:","options":["Valid, because any regulation becomes an Act once published","Valid until the President formally assents to it","Ultra vires and void, for exceeding the delegated power","Valid, because ministerial regulations rank above statutes"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Delegated legislation must not exceed the limits of the power granted by the enabling statute, otherwise it is ultra vires, null and void, so C is right. Subsidiary legislation is inferior to statutes, so D is wrong, publication does not turn a regulation into an Act (A), and presidential assent applies to bills, not regulations (B)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 482, $official_bank_source${"itemId":"d1953ae5-d5a7-5cb6-bd78-b4919b8b15c4","questionId":"17718db9-24a0-571d-9ab8-cffd98a7fede","sourceKey":"bank:PUL101:LEG-070","payload":{"prompt":"Which of the following is a reason why delegated legislation has become inevitable in modern governance?","options":["The legislature cannot provide for every detail and lacks technical expertise in many areas","Delegated legislation ranks higher than Acts of the National Assembly","The Constitution forbids the legislature from making detailed rules","Courts refuse to apply statutes that contain technical details"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"It is practically impossible for the legislature to legislate for every aspect of life, and many areas need technical expertise, so it lays down a general framework and leaves details to specialists, as A says. There is no constitutional ban on detail (C), delegated legislation is inferior to statutes (B), and D is invented."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 483, $official_bank_source${"itemId":"1f84279a-069e-52a1-bbd3-07cda7ed67bf","questionId":"88c4c94b-83f3-5dc7-8bd4-edf3a508cf27","sourceKey":"bank:PUL101:LEG-071","payload":{"prompt":"In a classification that divides legislation into municipal, primary, judicial, executive and subordinate legislation, a practice direction issued by the Chief Judge of a State to regulate proceedings in the State High Court is an example of:","options":["Municipal legislation","Primary legislation","Judicial legislation","Executive legislation"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"In this classification, judicial legislation refers to the rule-making role of the courts, and practice directions issued by the Chief Judge of a State or the Chief Justice of Nigeria are its example, so C is right. Executive legislation (D) refers to bills initiated by the executive, such as the EFCC Act, municipal legislation (A) to bye-law powers, and primary legislation (B) to foundational laws like the Constitution."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 484, $official_bank_source${"itemId":"d6a7d86f-0e39-5d5e-8a47-30b8aaea670a","questionId":"b9d5da39-ec81-528a-8d20-7e7895ff7bf0","sourceKey":"bank:PUL101:LEG-072","payload":{"prompt":"Which section of the 1999 Constitution provides interpretations of key words and expressions used in the Constitution?","options":["Section 58","Section 318","Section 4","Section 55"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Section 318 is the interpretation section of the 1999 Constitution, and section 318(4) applies the Interpretation Act to the Constitution, so B is right. Section 4 (C) vests legislative powers, section 55 (D) deals with the language of National Assembly business, and section 58 (A) sets out how bills become law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 485, $official_bank_source${"itemId":"a1a30180-b798-529a-b639-04b695069daf","questionId":"83248147-0e3f-5a43-a546-b88ea57e8d37","sourceKey":"bank:PUL101:LEG-073","payload":{"prompt":"A Lagos State Law provides that 'In this Law, money means paper currency (notes) only'. A trader is charged under the Law for hoarding N50 coins. How does the definition affect the case?","options":["The coins are 'money', because definitions cannot narrow the ordinary meaning of words","The coins are 'money', because the Interpretation Act overrides any definition in a Law","The coins are not 'money' under the Law, because the definition narrows the ordinary meaning","The court must ignore the definition, because definitions belong only in schedules"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Definition sections and interpretation clauses may delimit, extend or narrow the ordinary meaning of words, and here 'money' has been narrowed to paper currency, so coins fall outside it, as C says. Option A denies a power definitions clearly have, the Interpretation Act is a fallback where a statute gives no definition of its own (B), and definitions may sit in the section itself or at the start or end of a statute (D)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 486, $official_bank_source${"itemId":"ec9c494e-8202-59dc-af84-efe8e8771a9c","questionId":"19482d6b-37e9-5e95-8975-e21187f30179","sourceKey":"bank:PUL101:LEG-075","payload":{"prompt":"\"The primary duty of the courts in interpreting statutes ... is to find the intention of the legislature.\" Which statement best reflects how courts approach this task?","options":["Courts ask the legislators who passed the Act what they meant","Courts may replace a statute with their own policy where it is unclear","Courts apply whatever meaning best suits the party with the stronger case","Courts seek the lawmakers' intention as expressed in the statute, though they were not present when it was made"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Judges seek to discover the intention of the legislature as contained in the statute and give effect to it, even though they were not there when the law was made, so D is right. Option C abandons neutrality, A is not how courts work, and B would be usurping the legislative function."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 487, $official_bank_source${"itemId":"197396de-3eb4-5ca4-bbb2-022bb7c7a81e","questionId":"a0b90a28-f470-5142-b523-8f7900b772c1","sourceKey":"bank:PUL101:LEG-076","payload":{"prompt":"The rule that the intention of the law must be found on its face, so that courts apply the natural and ordinary meaning of the words whatever the consequences, is called:","options":["The literal rule","The ejusdem generis rule","The golden rule","The mischief rule"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The literal or plain meaning rule requires courts to apply the natural, ordinary meaning of the words notwithstanding the implications, so A is right. The golden rule (C) allows departure from that meaning to avoid absurdity, the mischief rule (D) looks at the defect the statute was meant to cure, and ejusdem generis (B) concerns general words after a list."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 488, $official_bank_source${"itemId":"7be9eb02-692f-53dc-b49d-d51c47c272f1","questionId":"da8c3b49-5c53-597b-b5ea-880ab07cd595","sourceKey":"bank:PUL101:LEG-077","payload":{"prompt":"In the Sussex Peerage case, Tindal C.J. said that where the words of a statute are precise and unambiguous, nothing more is needed than to expound them in their natural and ordinary sense. This statement is a classic expression of:","options":["The golden rule","The rule in Heydon's case","The literal rule","The mischief rule"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Tindal C.J.'s statement that clear words should be given their natural and ordinary sense, because the words themselves best declare the lawgiver's intention, is the classic statement of the literal rule, C. The golden rule (A) qualifies this to avoid absurdity, and the mischief rule (D) is the same thing as the rule in Heydon's case (B)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 489, $official_bank_source${"itemId":"e36d86ea-e3f8-5b8d-a000-6d0c22901548","questionId":"111afccb-9a56-5335-92de-bb563b01dfc2","sourceKey":"bank:PUL101:LEG-078","payload":{"prompt":"Which of the following is NOT a recognised criticism of the literal rule?","options":["Applying the literal meaning may lead to inconvenient or absurd results","It is ill-suited to modern social legislation in a developing society","It allows judges too much freedom to rewrite statutes to suit their own views","Words have no ordinary meaning except in the context in which they are used"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The literal rule is criticised for being too rigid, not for giving judges too much freedom, so C is not a criticism of it; that charge is usually aimed at gap-filling approaches. Options D, A and B are the standard weaknesses: words take meaning from context, literalism can produce absurdity, and it fits poorly with changing social needs."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 490, $official_bank_source${"itemId":"03e6daf2-010e-58ab-ac0f-db9c558dc08b","questionId":"f7343d94-f367-5059-9051-1f7e0b9ef276","sourceKey":"bank:PUL101:LEG-081","payload":{"prompt":"In Council of the University of Ibadan v Adamolekun (1967), the Supreme Court declared a Western Nigeria Edict void for inconsistency with a Federal Military Government Decree, rejecting a literal reading of an ouster provision that would have left the void Edict standing. Which rule of interpretation does the case illustrate?","options":["The expressio unius rule","The golden rule","The ejusdem generis rule","The literal rule"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The court refused a literal reading that would let a void, inconsistent law coexist with the superior law, because that would be absurd and legally anomalous, which is the golden rule at work, B. The literal rule (D) was the argument rejected, and C and A are maxims about lists and express mention that were not in issue."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 491, $official_bank_source${"itemId":"eb478766-6f70-56db-b825-bbd8d7f68919","questionId":"02b26a76-eccb-5790-921c-94291761cdda","sourceKey":"bank:PUL101:LEG-082","payload":{"prompt":"A State Law provides that 'no person shall hawk goods in the vicinity of the State Secretariat'. A hawker is caught selling goods inside the Secretariat premises and argues that 'in the vicinity of' means only the area near or around the Secretariat, not the premises themselves. The court rejects this argument as absurd and holds that the Law covers the premises too. Which rule has the court applied?","options":["The golden rule","The rule against retrospective laws","The literal rule","The expressio unius rule"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The court departs from a strict literal reading because it would produce an absurd result the lawmakers could not have intended, and modifies the meaning only as far as needed, which is the golden rule, A. The hawker was relying on the literal rule (C), expressio unius (D) concerns things expressly listed, and B concerns laws reaching back in time."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 492, $official_bank_source${"itemId":"e163e502-0366-53d4-bc81-59331875f36e","questionId":"cc4358fa-a042-57c8-ac1e-43c476e58330","sourceKey":"bank:PUL101:LEG-083","payload":{"prompt":"The rule of interpretation that considers the statutory purpose and the history of a statute by looking at the state of the law before it was passed, to find the defect it was meant to cure, is the:","options":["Noscitur a sociis rule","Golden rule","Mischief rule","Literal rule"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The mischief rule, also called interpretation by reference to the statutory purpose, looks at the law before the statute to see what shortcoming the new law came to cure, so C is right. The literal rule (D) applies plain meaning, the golden rule (B) avoids absurdity, and noscitur a sociis (A) reads a word with its neighbours."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 493, $official_bank_source${"itemId":"ffc3517e-05de-521f-8ae3-9e9c4c92bf1a","questionId":"bfafa42e-c4a0-5a20-b695-605cb9ccd549","sourceKey":"bank:PUL101:LEG-085","payload":{"prompt":"Under the rule in Heydon's case, a court considers several matters when interpreting a statute. Which of the following is NOT one of them?","options":["What the judge personally thinks the best policy on the subject would be","What remedy Parliament adopted and the true reason for it","What mischief or defect the earlier law did not provide for","What the law was before the Act was passed"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Heydon's case directs the court to ask what the law was before the Act, what mischief or defect it did not provide for, what remedy Parliament resolved on, and the true reason for that remedy, which covers D, C and B. The judge's own view of good policy (A) is not one of these questions; the inquiry is about Parliament's purpose."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 494, $official_bank_source${"itemId":"b45cc1be-febd-53f2-ba70-052eb169c724","questionId":"b70142d6-f7b3-57bd-a019-6f14007c77e6","sourceKey":"bank:PUL101:LEG-086","payload":{"prompt":"Before 2025, traders in a State evaded a market levy by registering stalls in relatives' names. A 2025 State Law was passed to stop this evasion. A trader now uses a newly formed company to hold his stalls. The court asks what defect the old law had and holds that the Law covers the company scheme because it is the very evil the Law was passed to cure. Which approach has the court used?","options":["The ejusdem generis rule","The literal rule","The presumption against ousting jurisdiction","The mischief rule"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Looking at the law before the statute, identifying the mischief it was meant to cure and interpreting the words to suppress that mischief is the mischief rule, so D is right. The literal rule (B) would look only at the words, ejusdem generis (A) concerns general words after a list, and C concerns statutes that try to shut out the courts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 495, $official_bank_source${"itemId":"9e3d285f-08a2-5779-a4ef-444d8bdfcb42","questionId":"b79e5529-7fa3-566c-8ad5-a6684f7f87c6","sourceKey":"bank:PUL101:LEG-087","payload":{"prompt":"What is a main limitation of the mischief rule?","options":["It requires a two-thirds vote of the legislature before use","It can be used only for constitutions, not ordinary statutes","It forbids the court from looking at anything except the bare words","It assumes statutes cure defects, yet many modern laws meet new social or technological needs"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The mischief rule assumes every statute is made to correct an existing defect, but many modern laws respond to social, economic, political or technological needs rather than curing a defect, and the rule gives no clear test for construing the words used, so D is right. Option C describes the literal rule's narrowness, and B and A are invented limits."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 496, $official_bank_source${"itemId":"d89dfe2a-339d-54a8-ad75-246df2bbbe30","questionId":"029c120e-1ff5-5b86-837a-269d87d3c141","sourceKey":"bank:PUL101:LEG-088","payload":{"prompt":"What is the status of the literal, golden and mischief rules?","options":["They are convenient rules of practice to assist courts, not principles of law","They are customary rules applicable only in customary courts","They are binding rules of law laid down in the Constitution","They are provisions of the Interpretation Act that courts must apply in order"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The canons are not principles of law but convenient rules of practice developed over time to help courts interpret statutes, and their helpfulness is open to doubt, so A is right. They are not laid down in the Constitution (C) or listed in a fixed order in the Interpretation Act (D), and they are not customary rules (B)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 497, $official_bank_source${"itemId":"c55d10ff-b2e2-5725-a1dc-f62ab19f9922","questionId":"c71fac96-a191-51d2-a57d-85256200ec64","sourceKey":"bank:PUL101:LEG-089","payload":{"prompt":"In Awolowo v Shagari, Fatayi-Williams CJN remarked that a common feature of most canons of interpretation is that they:","options":["Are binding only on the Supreme Court and not on lower courts","Always lead to the same answer whichever canon is chosen","Are of little practical assistance in settling doubts in particular cases","Must be applied in a fixed order beginning with the mischief rule"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Fatayi-Williams CJN observed that many canons take the form of broad general principles and so are of little practical help in settling doubts about interpretation in particular cases, so C is right. Option B is contradicted by the opposing conclusions in Awolowo v Shagari itself, and D and A invent rules."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 498, $official_bank_source${"itemId":"f9c7d7ff-20da-5c91-bd66-acf6359824bc","questionId":"43e0cd15-d75d-5105-80e4-49ae680e95af","sourceKey":"bank:PUL101:LEG-090","payload":{"prompt":"\"There is no golden rule nor is there a mischief rule or a literal rule or any other rule at all; instead, there are a thousand and one interpretative criteria.\" What does this statement suggest?","options":["Interpretation draws on many criteria rather than a few fixed rules","The literal rule is the only true rule of statutory interpretation","Courts should never interpret statutes and must leave it to the legislature","The golden rule should always be preferred over the other canons"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The statement denies that there are a few fixed rules and says interpretation in fact uses a great many criteria, so A is right. It rejects the golden rule (D) and the literal rule (B) as rules just as much as the mischief rule, and it does not say courts should stop interpreting statutes (C)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 499, $official_bank_source${"itemId":"97d31eec-c1f6-51f7-ac8d-ba45a6231f5b","questionId":"483a25b0-57e7-56c8-a0d8-47d4d1838dd6","sourceKey":"bank:PUL101:LEG-091","payload":{"prompt":"The principle that 'an Act must be read as a whole' means that:","options":["Every section of an Act must be interpreted literally and separately","Words take their meaning from the context in which they are used, not in isolation","Courts must read all Acts passed in the same year together","Only the long title of an Act may be used to interpret it"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Reading an Act as a whole means that words derive their meaning from their context and must be interpreted by reference to it, not in isolation, so B is right. Option D is too narrow, A is the opposite of reading in context, and C confuses context with date of enactment."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 500, $official_bank_source${"itemId":"33c61bf7-c653-5dc9-bb49-7665bdcd6bb9","questionId":"bcee7f97-ace0-5464-8aba-b57d12ec7677","sourceKey":"bank:PUL101:LEG-092","payload":{"prompt":"Which of the following is NOT an intrinsic (internal) aid to the interpretation of a statute?","options":["A recognised law dictionary such as Black's Law Dictionary","The preamble of the statute","The interpretation section of the statute","The long title of the statute"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Intrinsic aids are found inside the statute itself, such as the preamble, long title, definition and interpretation sections, schedules and appendixes, which covers B, D and C. A dictionary (A) is outside the statute, so it is an extrinsic aid."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 501, $official_bank_source${"itemId":"0ad81fa7-414c-59a0-817c-b7c1b932da00","questionId":"a01c86de-159a-5d33-b305-d1bde84a5dc4","sourceKey":"bank:PUL101:LEG-093","payload":{"prompt":"In interpreting the word 'premises' in a Federal Act, a judge looks first at the Act's long title and preamble, and then consults a leading textbook on property law. Which statement correctly classifies these aids?","options":["All three are extrinsic aids because none is an operative section","The long title and preamble are extrinsic aids; the textbook is an intrinsic aid","The long title and preamble are intrinsic aids; the textbook is an extrinsic aid","All three are intrinsic aids because the judge relies on them"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Intrinsic aids come from within the statute, such as the long title and preamble, while extrinsic aids come from outside it, such as dictionaries, the Interpretation Act and leading works by recognised authors, so C is right. Option B reverses the classes, and D and A ignore the inside-versus-outside test."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 502, $official_bank_source${"itemId":"97fc00c2-816b-5f63-8665-490df9e62dc1","questionId":"96889518-d99b-594e-8eae-cf29bb94b88b","sourceKey":"bank:PUL101:LEG-094","payload":{"prompt":"Section 318(4) of the 1999 Constitution provides that:","options":["English dictionaries shall be binding on courts interpreting the Constitution","The Constitution may be interpreted only by the National Assembly","Customary law shall apply to interpret words not defined in the Constitution","The Interpretation Act shall apply for the purposes of interpreting the Constitution"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Section 318(4) states that the Interpretation Act shall apply for the purposes of interpreting the provisions of the Constitution, which is D; this applies unless the context otherwise requires. Interpretation is a judicial task, not a legislative one (B), and C and A invent rules not in the section."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 503, $official_bank_source${"itemId":"0ad1a8d0-e9ec-5fab-8899-c337bb4c8756","questionId":"674937a9-1283-54db-818c-29d82d9b2f82","sourceKey":"bank:PUL101:LEG-095","payload":{"prompt":"What is one main purpose of an Interpretation Act?","options":["To avoid needless and burdensome repetition of common definitions in every statute","To set out the stages a bill passes through before assent","To transfer the power to interpret statutes from courts to ministers","To list the cases in which the literal rule must be used"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"An Interpretation Act gives general definitions of common words and phrases, so each statute need not repeat them; its main purpose is to avoid needless and burdensome repetition, so A is right. It does not rank the canons (D), does not take interpretation away from courts (C), and the stages of a bill are in the Constitution and House rules (B)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 504, $official_bank_source${"itemId":"a094bd79-e6fa-5211-b333-c1fe9f1e5107","questionId":"ab974cf4-750b-52db-8cc0-460fa60c2e6d","sourceKey":"bank:PUL101:LEG-096","payload":{"prompt":"Which of the following is NOT a presumption courts use as an indicator of legislative intention?","options":["A presumption against ousting the jurisdiction of the courts","In criminal law, a presumption against imposing liability without fault","A presumption in favour of statutes operating retrospectively","A presumption against interference with vested rights"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Courts presume against retrospective operation of statutes, not in favour of it, so C reverses the real presumption. Options D, A and B are recognised presumptions, along with the presumption that a new Act does not alter existing law unless it says so expressly."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 505, $official_bank_source${"itemId":"1f77620d-66c4-5458-a29b-8ce4ef5b95d6","questionId":"b4678e62-8103-5286-92e5-8043af6b623b","sourceKey":"bank:PUL101:LEG-097","payload":{"prompt":"A Federal Act provides that 'no court shall entertain any action' arising from the decisions of a new tax tribunal. The words can reasonably mean either that all court review is barred or only that fresh suits on the merits are barred, leaving judicial review open. How should the court construe the provision?","options":["Strictly, adopting the meaning that preserves the jurisdiction of the courts","Liberally, adopting the meaning that ousts the courts most widely","By applying whichever meaning the tax tribunal prefers","By declining to interpret it until the National Assembly amends it"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"There is a presumption against ousting the jurisdiction of the courts, and a statute that ousts it must be construed strictly, so if it reasonably bears two meanings, the one preserving the courts' jurisdiction is taken, as A says; Fatayi-Williams JSC stated this in Barclays Bank of Nigeria Ltd v CBN. Option B reverses the presumption, and D and C abandon the court's duty to interpret."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 506, $official_bank_source${"itemId":"93a67c14-cd18-5449-ad0f-4a4929c08691","questionId":"dbbe6957-cf0b-5b34-9acb-f1c302b76c6e","sourceKey":"bank:PUL101:LEG-098","payload":{"prompt":"A 2026 Act creates a new offence of failing to register a business name, but says nothing about whether guilty knowledge is required and does not state that the offence is one of strict liability. A trader who honestly could not have known of the duty is charged. Which presumption is most relevant?","options":["The presumption against imposing criminal liability without fault","The presumption that general words follow a list of specific words","The presumption that a new Act does not alter existing law","The presumption against ousting the jurisdiction of the courts"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"In criminal law there is a presumption against imposing liability without fault, although an express provision can make an offence one of strict liability, so where the Act is silent this presumption is the relevant one, A. Option D concerns attempts to shut out courts, C concerns changes to earlier law, and B is the ejusdem generis maxim rather than a presumption about fault."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 507, $official_bank_source${"itemId":"db882c42-56b9-5ce7-9f87-f67328ee8b53","questionId":"4eec5a84-b34d-5d62-9731-6864368e32c2","sourceKey":"bank:PUL101:LEG-099","payload":{"prompt":"A Lagos State Law passed in March 2026 imposes a new levy on hotel bookings. Although the Law is silent on the point, the State revenue service tries to collect the levy on bookings made in 2024. Which presumption works against the revenue service?","options":["The maxim lex non cogit ad impossibilia","The presumption against retrospective operation of statutes","The presumption against ousting the jurisdiction of the courts","The presumption against liability without fault in criminal law"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Courts presume that a statute does not operate retrospectively or interfere with vested rights unless it says so in clear terms, so a silent 2026 Law should not reach 2024 bookings, as B says. Option D concerns criminal fault, C concerns ouster clauses, and A concerns impossible commands."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 508, $official_bank_source${"itemId":"bb997d05-bb70-5ea7-b010-e5cff134c698","questionId":"baa0041d-bb07-512f-856a-cec64d2eca69","sourceKey":"bank:PUL101:LEG-100","payload":{"prompt":"The ejusdem generis rule means that:","options":["The express mention of one thing excludes all others not mentioned","A statute should be read so that it is valid rather than void","The law does not compel a person to do the impossible","General words following a list of specific words are limited to things of the same class"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Under ejusdem generis, where specific words of one class are followed by general words, the general words are restricted to things of the same class as the specific ones, so D is right. Option A is expressio unius est exclusio alterius, B is ut res magis valeat quam pereat, and C is lex non cogit ad impossibilia."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 509, $official_bank_source${"itemId":"f99844b3-464c-5917-ac6b-86f31f55c46c","questionId":"730b3e2b-f0f3-5225-82b6-83cb1415d8c5","sourceKey":"bank:PUL101:LEG-101","payload":{"prompt":"A State Law provides: 'It shall not be lawful for makers of bread, meat pie, cake, doughnut, sausage and other snacks to display such except in places provided.' Applying the ejusdem generis rule, which of the following is most likely covered by 'other snacks'?","options":["Chin-chin, a fried pastry snack","Plates of jollof rice","Fresh fish","Bottled zobo drink"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"The listed items are all confectionery or pastry, so under ejusdem generis 'other snacks' is limited to that class and covers a pastry snack such as chin-chin, A. Jollof rice (B) is a main food item and zobo (D) is a drink, both outside the class, and fresh fish (C) is not a pastry at all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 510, $official_bank_source${"itemId":"5203ce11-3f44-51be-9d70-e131643d4692","questionId":"64f55f0c-8c0c-5be4-8b1d-466081c5a793","sourceKey":"bank:PUL101:LEG-102","payload":{"prompt":"A State Education Law provides that 'the Principal and/or Vice-Principal of any school who is absent from office without due excuse' shall be liable to a penalty. A classroom teacher is absent without excuse. Which maxim shows that the teacher is not caught by this provision?","options":["Expressio unius est exclusio alterius","Ut res magis valeat quam pereat","Lex non cogit ad impossibilia","Ejusdem generis"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Expressio unius est exclusio alterius means the express mention of one thing excludes others, so naming only the Principal and Vice-Principal excludes teachers and other staff, making A right. Ejusdem generis (D) needs general words after a list, which this provision lacks, while C and B concern impossibility and validity."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 511, $official_bank_source${"itemId":"c294150c-756a-5049-8acb-519baaf316eb","questionId":"44db76f1-946a-566b-8807-7f5ef519cf1f","sourceKey":"bank:PUL101:LEG-103","payload":{"prompt":"The maxim that a word takes its meaning from the other words with which it is associated is:","options":["Expressio unius est exclusio alterius","Lex non cogit ad impossibilia","Noscitur a sociis","Stare decisis"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Noscitur a sociis means a word is known by its companions, so it is read in the light of the words around it, which is C. Expressio unius (A) is about express mention excluding others, lex non cogit ad impossibilia (B) is about impossible commands, and stare decisis (D) is the doctrine of judicial precedent."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 512, $official_bank_source${"itemId":"aeb737f7-9018-5b35-88c1-96cea820d88d","questionId":"c2a7be15-9447-547f-af58-f0973cd2fa66","sourceKey":"bank:PUL101:LEG-104","payload":{"prompt":"A provision in an Act is capable of two mutually exclusive interpretations: one makes the provision valid and effective, the other makes it invalid and ineffective. Which maxim tells the court which to adopt?","options":["Expressio unius est exclusio alterius, so the invalid interpretation is adopted","Noscitur a sociis, so the court chooses whichever reading is shorter","Lex non cogit ad impossibilia, so the provision is ignored","Ut res magis valeat quam pereat, so the valid interpretation is adopted"],"correctOption":3,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Under ut res magis valeat quam pereat a statute is construed so that it may have effect rather than be destroyed, so the interpretation that keeps the provision valid is adopted, as D says. Lex non cogit ad impossibilia (C) is about impossible commands, and A and B misapply maxims that concern express mention and context."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 513, $official_bank_source${"itemId":"7175e572-3936-5db2-a7fd-c6553b3caca9","questionId":"d5affec4-4c52-5ccb-8e1a-1285bc1892fd","sourceKey":"bank:PUL101:LEG-105","payload":{"prompt":"The maxim lex non cogit ad impossibilia means that:","options":["A statute is construed to have effect rather than be destroyed","A statute is construed so as not to command what is humanly impossible","A statute must always be construed against the government","General words take their meaning from the specific words before them"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Lex non cogit ad impossibilia means the law does not compel the doing of impossibilities, so a statute is read in a way that does not require what is humanly impossible, which is B. Option A is ut res magis valeat quam pereat, D is ejusdem generis, and C is not a recognised maxim of interpretation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 514, $official_bank_source${"itemId":"d81f61ca-720c-5c15-a84e-834d1afb004f","questionId":"ad5bcbf7-17dc-509e-994e-006a853a3799","sourceKey":"bank:PUL101:LEG-106","payload":{"prompt":"In Carter v Bradbeer, Lord Diplock cautioned that in questions of statutory construction, a ratio decidendi on the meaning of words in one statute:","options":["Binds every court that later interprets the same words in any statute","Has no more than persuasive influence when the same words appear in another statute","Overrides the words of any later statute that uses different language","Has no value at all and must never be cited in another case"],"correctOption":1,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"Lord Diplock said the strict doctrine of precedent has only narrow application in statutory construction, and a ruling on words in one provision can have no more than persuasive influence on the same words in another provision, so B is right. Option A overstates precedent, D understates it, and C would put a judgment above a statute."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 515, $official_bank_source${"itemId":"12a77bc9-75a7-51ed-803b-8d76721ab0a8","questionId":"806013f3-15aa-5fec-9361-1b90c2e43855","sourceKey":"bank:PUL101:LEG-107","payload":{"prompt":"In Magor and St Mellons RDC v Newport Corporation, Lord Simonds criticised the idea that judges should fill gaps in statutes by describing it as:","options":["A naked usurpation of the legislative function under the thin disguise of interpretation","The correct method of applying the ejusdem generis rule","A necessary use of the rule in Heydon's case","The proper application of the literal rule in modern conditions"],"correctOption":0,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"When the case reached the House of Lords, Lord Simonds rejected Lord Denning's view that judges should fill in gaps, calling it 'a naked usurpation of the legislative function under the thin disguise of interpretation', so A is right. Gap-filling is not the literal rule (D), and Lord Simonds was not endorsing it as an application of the mischief rule (C) or ejusdem generis (B)."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 516, $official_bank_source${"itemId":"ccd58d9c-4fbb-5eac-8434-e1712f815e84","questionId":"537c7067-4e59-5597-a7ee-5bb4a07b3566","sourceKey":"bank:PUL101:LEG-108","payload":{"prompt":"Which approach to statutory interpretation is considered most appropriate overall?","options":["Following previous interpretations of similar words in any other statute","Exclusive use of the mischief rule, ignoring the words of the statute","A combination of the canons and aids, read against the legislative purpose","Strict use of the literal rule in every case, whatever the result"],"correctOption":2,"section":"Legislation: Process, Types and Statutory Interpretation","explanation":"No single canon is reliable on its own, so a combination of the canons and aids should be used, giving effect to the ordinary and contextual meaning against the background of the legislative purpose, as C says. Option D can produce absurdity, B ignores the text, and A overstates precedent, which is only persuasive across different statutes."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 517, $official_bank_source${"itemId":"657531ac-ef8e-5097-a7b8-905df8299145","questionId":"b45223cf-bc61-55ff-b9e2-3bee30462b44","sourceKey":"bank:PUL101:SRC-001","payload":{"prompt":"In the study of Nigerian legal method, the expression 'sources of Nigerian law' refers to:","options":["The government agencies responsible for printing and distributing copies of statutes","The moral and religious beliefs that individual judges bring to the cases before them","The historical events that led to the amalgamation of Northern and Southern Nigeria in 1914","The materials through which a lawyer, court or judge finds reliable authorities for a particular legal question"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"The expression refers to where a lawyer or judge goes to find reliable authority on a legal question, such as statutes, case law and customary law. Option C describes history, not where the law is located. Options A and B describe publishers and personal beliefs, neither of which is an authority a court relies on."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 518, $official_bank_source${"itemId":"85419705-d24d-5c27-a9ad-0745b3da6e80","questionId":"cdc9c90d-316e-579a-924d-afde6b35cf6c","sourceKey":"bank:PUL101:SRC-002","payload":{"prompt":"Which of the following is a PRIMARY source of Nigerian law?","options":["Law digests summarising decided cases","Customary law, including Islamic law where applicable","Legal dictionaries such as Stroud's Judicial Dictionary","Legal textbooks written by Nigerian professors"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"The primary category covers the authorities that can bind a Nigerian court: received English law, Nigerian legislation, judicial precedent and customary law (including Islamic law). Options A, C and D are all secondary works, which only help to find or explain the law and can at most persuade a court."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 519, $official_bank_source${"itemId":"90c66233-0292-555b-bf1a-dffe240bb08b","questionId":"f6575e39-8a23-5ea2-8090-22fd3f526550","sourceKey":"bank:PUL101:SRC-003","payload":{"prompt":"Which of the following is NOT a primary source of Nigerian law?","options":["Nigerian case law or judicial precedent","Nigerian legislation and subsidiary enactments","Articles in legal periodicals and journals","Received English law"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Legal periodicals and journals fall in the secondary category: they discuss the law but are not the law itself. Options A, B and D are all in the primary category of Nigerian law, which is capable of binding a court."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 520, $official_bank_source${"itemId":"25a078f1-d4c3-5b3d-b7f7-e65b0473faec","questionId":"6c28c99e-0b2a-572d-b0ac-f8ee0dd9904e","sourceKey":"bank:PUL101:SRC-004","payload":{"prompt":"What is the main difference in legal effect between primary and secondary sources of Nigerian law?","options":["Secondary sources bind lower courts while primary sources bind only the Supreme Court","Only primary sources can bind a Nigerian court; secondary sources are merely persuasive","Primary sources are always written while secondary sources are always unwritten","Both bind the courts equally, but primary sources are older than secondary sources"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Primary authorities such as legislation and case law carry binding force, while secondary works such as law books and periodicals can only persuade, usually where no primary authority exists. Option C is wrong because customary law is primary yet largely unwritten. Options A and D wrongly give binding force to secondary works."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 521, $official_bank_source${"itemId":"da8b8330-76c1-5403-aa86-ac94e98ed532","questionId":"52a3d1a8-0144-5975-9f98-1efeab0988a1","sourceKey":"bank:PUL101:SRC-005","payload":{"prompt":"Gboga, a newly qualified lawyer, must address a Lagos court on a novel point. There is no statute or reported decision on it, only a textbook by a leading professor in the field. What is the correct position on citing the textbook?","options":["He may cite it only if the professor is called to give evidence as an expert witness","He may cite it and the court is bound to follow it, since no primary authority exists","He may cite it as persuasive authority, and its weight will depend on the standing of the author and the significance of the subject","He may not cite it at all, because only primary sources may be mentioned in a Nigerian court"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Where judicial decisions are scanty or absent, reputable law books can be cited as persuasive authority, and their weight depends on who wrote them and the importance of the subject. Option B is wrong because a secondary authority never becomes binding just because nothing else exists. Option D is wrong because courts do accept such works for persuasion."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 522, $official_bank_source${"itemId":"156f0b41-f8f6-5390-bab0-20e6ce137d71","questionId":"d806170a-508d-5a2b-a611-ad80d0c2e47c","sourceKey":"bank:PUL101:SRC-006","payload":{"prompt":"Received English law in Nigeria consists of:","options":["The doctrines of equity and the decisions of English courts given after 1 October 1960","The common law of England and all Acts of the UK Parliament passed before Nigeria's independence in 1960","The common law of England, the doctrines of equity and the statutes of general application in force in England on 1 January 1900","The statutes of general application in force in England on 1 October 1954 and English customary law"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"The reception provisions bring in three things: the common law, the doctrines of equity, and statutes of general application in force in England on 1 January 1900. Option B is wrong because not every pre-independence Act was received, only statutes of general application up to the 1900 date. Option D uses the wrong date, which is the date federalism began, not the reception date."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 523, $official_bank_source${"itemId":"f583d12b-afe0-5643-83fb-e6f93db17aa5","questionId":"a07356b6-df18-5698-86ae-31c4376f40aa","sourceKey":"bank:PUL101:SRC-007","payload":{"prompt":"Statutes of general application are received into Nigeria if they were in force in England on which date?","options":["1 October 1954","1 January 1914","1 January 1900","1 October 1960"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"The cut-off date for statutes of general application is 1 January 1900, as stated in the Interpretation Act and the Supreme Court Ordinance 1914. Option B is the year of amalgamation and of the Supreme Court Ordinance itself, not the reception date. Options A and D are the dates federalism began and Nigeria became independent."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 524, $official_bank_source${"itemId":"b7dadbd1-4255-5451-9434-e8a821ede018","questionId":"def523ca-e2eb-5909-ac6f-c6cc763abe27","sourceKey":"bank:PUL101:SRC-008","payload":{"prompt":"Which of the following is NOT one of the three components of received English law under the reception provisions?","options":["English statutes of general application passed after 1 January 1900","Statutes of general application in force in England on 1 January 1900","The doctrines of equity","The common law of England"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Only statutes of general application that were already in force in England on 1 January 1900 are received; an English statute passed after that date is not part of received English law. Options B, C and D are exactly the three components named in the reception provisions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 525, $official_bank_source${"itemId":"e36a3d1c-6172-5a3f-958d-45565ec380a0","questionId":"e822f00f-9b58-5215-b415-11f283d91e96","sourceKey":"bank:PUL101:SRC-009","payload":{"prompt":"How does the application of the English common law and doctrines of equity in Nigeria differ from that of statutes of general application?","options":["Common law and equity are applied as they stand in England when applied, while statutes of general application are tied to the 1 January 1900 date","Common law and equity apply only in Lagos, while statutes of general application apply in every State","Common law and equity must be re-enacted by the National Assembly each year, while statutes of general application need not","Common law and equity are frozen as at 1 January 1900, while statutes of general application apply as they stand today"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Nigerian courts apply common law and equitable principles as they stand in England on the day of application, so their application is not limited by time. Statutes of general application, by contrast, are received only if in force in England on 1 January 1900. Option D reverses the two rules."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 526, $official_bank_source${"itemId":"586ddbb3-39f6-5ae6-963e-83861cb04f4b","questionId":"d8383c1e-73ff-595b-8cef-c29d3361d721","sourceKey":"bank:PUL101:SRC-010","payload":{"prompt":"An English statute of general application was in force in England on 1 January 1900 and was later repealed in England in 1960. It has never been repealed in Nigeria. What is its status in Nigeria?","options":["It became customary law and must pass the repugnancy test","It applies in Nigeria only if the UK Parliament re-enacts it","It remains in force in Nigeria despite its repeal in England","It ceased to apply in Nigeria automatically on its repeal in England"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Statutes of general application received into Nigeria remain in force here even if they have since been repealed in England, unless a Nigerian legislature removes them. Option D is the common mistake of assuming English repeal carries over to Nigeria. Options B and A have no basis since Nigeria is sovereign and the statute is not customary law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 527, $official_bank_source${"itemId":"fcb2d376-a0e4-58ff-a8a7-a87b6ee364f4","questionId":"f9610932-fa42-5704-82c4-6308e1dd3966","sourceKey":"bank:PUL101:SRC-011","payload":{"prompt":"Which of the following correctly states where the meaning of 'statute of general application' is found?","options":["In section 1 of the 1999 Constitution","In case law, because the reception enactments do not define the phrase","In a schedule to the Interpretation Act listing all such statutes","In the definition section of the Supreme Court Ordinance 1914"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Neither the Supreme Court Ordinance, the Interpretation Act nor other reception enactments define 'statute of general application', so its meaning has been worked out by the courts. Options D and C are wrong because those enactments use the phrase without defining it or listing the statutes. Option A is about constitutional supremacy, not reception."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 528, $official_bank_source${"itemId":"9e2c34d2-c06a-5f13-9185-6d3ecbd2c36d","questionId":"b4ccfa57-21af-5651-b985-3e5cea79df0c","sourceKey":"bank:PUL101:SRC-012","payload":{"prompt":"In Attorney General v John Holt & Co Ltd, Osborne CJ proposed a 'rough but not infallible test' for a statute of general application. The test asks:","options":["By what courts the statute is applied in England, and to what classes of the community in England it applies","Whether the statute is repugnant to natural justice, equity and good conscience, and whether it is contrary to public policy","Whether the statute was expressly extended to Nigeria by name, and whether it was published in the Nigeria Gazette","Whether the statute was passed before or after Nigeria's independence, and whether it is still in force in England"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Osborne CJ asked two preliminary questions: by what courts the statute is applied in England, and to what classes of the community it applies. A statute applied by all courts to all classes is likely to be of general application. Option B is a trap: those are the validity tests for customary law, not for English statutes."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 529, $official_bank_source${"itemId":"91563e20-b592-5a15-8534-220585bf2c2e","questionId":"76ff66fa-6b17-5e06-81f3-6d26855c663d","sourceKey":"bank:PUL101:SRC-013","payload":{"prompt":"Suppose an English Act in force on 1 January 1900 merely regulated procedure in certain English courts. Under the test in Attorney General v John Holt & Co Ltd, it would most likely be:","options":["Held to be a statute of general application, because all English Acts in force in 1900 were received","Held to be a statute of general application, because procedural Acts apply to every litigant","Held not to be a statute of general application, because it was applied only by certain courts","Held to be customary law, because procedure is a matter of local custom"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Under Osborne CJ's test, a statute applied only by certain courts, such as one regulating procedure, is probably not locally applicable. Option A is wrong because only statutes of general application are received, not every Act. Option B misreads the test, which uses a procedural statute as the example of one that would not qualify."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 530, $official_bank_source${"itemId":"f5bbd95b-a683-5293-beb9-84d90713f19d","questionId":"4dbde29a-58b0-5ee9-ab2b-36648ba79262","sourceKey":"bank:PUL101:SRC-014","payload":{"prompt":"An English Act in force on 1 January 1900 was applied by all the civil courts of England to all classes of the community. Applying Osborne CJ's test, what is the likely conclusion?","options":["It is unlikely to apply because it regulated the affairs of ordinary people","There is a strong likelihood that it is a statute of general application in force in Nigeria","It cannot be a statute of general application because it was applied by civil courts only","It is certain to be in force in Nigeria, because the test is conclusive"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Where a statute was applied by all civil or criminal courts, as the case may be, to all classes of the community, there is a strong likelihood it is in force. Option D overstates the test, which Osborne CJ himself called 'rough but not infallible'. Option C is wrong because the test speaks of all civil or criminal courts 'as the case may be'."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 531, $official_bank_source${"itemId":"e0b8e3a3-8496-5708-8288-dd7521a61f19","questionId":"39b1a4bd-3cc5-5416-80bb-f993088fb41c","sourceKey":"bank:PUL101:SRC-015","payload":{"prompt":"In Dede v African Association Ltd, the court took which view of statutes of general application?","options":["That they include only statutes passed after 1 January 1900","That they must be statutes applicable throughout the United Kingdom, not those in force in England only","That they cease to apply in Nigeria once repealed in England","That they must be statutes applied by all courts to all classes of the community in England"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"In Dede, Webber J ruled that statutes of general application must mean those applicable throughout the United Kingdom, a view criticised because the Ordinance itself speaks of statutes 'in force in England'. Option D is the test later proposed by Osborne CJ in Attorney General v John Holt & Co Ltd, a different case."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 532, $official_bank_source${"itemId":"9a8990e4-cc23-59a4-8f2f-beb0a17dff8a","questionId":"940ab0c3-b305-59ce-a164-0cd7e72d8524","sourceKey":"bank:PUL101:SRC-016","payload":{"prompt":"In Lawal v Younan, the Federal Supreme Court held which English statutes to be statutes of general application?","options":["The Land Transfer Act 1897","The Fraudulent Conveyances Act 1571","The Statute of Frauds 1677","The Fatal Accidents Acts of 1846 and 1864"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Lawal v Younan held that the Fatal Accidents Acts 1846 and 1864, which applied to all classes of the community in England, were statutes of general application. Option A was the statute considered in Young v Abina, and option B the one in Braithwaite v Folarin."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 533, $official_bank_source${"itemId":"896b6330-71ac-51e3-95ac-bc29fdeca439","questionId":"f8ed10a6-7d70-55d7-9f07-d159d8bcdc93","sourceKey":"bank:PUL101:SRC-017","payload":{"prompt":"In Young v Abina, the West African Court of Appeal held that which statute was of general application because it applied quite generally to the estates of all persons dying in England after 1 January 1898?","options":["The Land Transfer Act 1897","The Fraudulent Conveyances Act 1571","The Trustees Act 1888","The Fatal Accidents Act 1846"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Young v Abina concerned the Land Transfer Act 1897, which the court said could hardly be of more general application since it applied to the estates of all persons dying after 1 January 1898. Option D was the subject of Lawal v Younan, and option B of Braithwaite v Folarin."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 534, $official_bank_source${"itemId":"2f3122a6-1093-5ef8-a221-5f525834312f","questionId":"4828632c-772f-5f85-990c-ccfe8e3b7dc2","sourceKey":"bank:PUL101:SRC-018","payload":{"prompt":"In Braithwaite v Folarin, which statute was held to be of general application because it applied generally to the ordinary affairs and dealings of men?","options":["The Infant Relief Act 1874","The Fatal Accidents Act 1864","The Fraudulent Conveyances Act 1571","The Land Transfer Act 1897"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Braithwaite v Folarin held the Fraudulent Conveyances Act 1571 to be a statute of general application, since it applied to the ordinary affairs of men without any special restriction. Options D and B were the statutes in Young v Abina and Lawal v Younan respectively."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 535, $official_bank_source${"itemId":"24ca0124-c058-5518-b8dc-a1457ecba7ad","questionId":"d12cfb26-f2d3-5ab2-8009-23b82e0b88bc","sourceKey":"bank:PUL101:SRC-019","payload":{"prompt":"Statutes of general application have NOT been received into some Nigerian States for matters within State legislative competence. In which of the following States do they still apply to such matters?","options":["Edo State","Ogun State","Ondo State","Lagos State"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Statutes of general application apply in all Nigerian jurisdictions except Edo, Delta, Ekiti, Osun, Ondo, Ogun and other States carved from the former Western and Mid-Western regions, for matters within their competence. Lagos is not among the excepted States. Options A, B and C are all named among the States where they have not been received."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 536, $official_bank_source${"itemId":"dffddfaf-54da-5d50-9f6a-c35de73cc437","questionId":"a308267b-bacd-5e7a-a6a9-f7f20404c05e","sourceKey":"bank:PUL101:SRC-020","payload":{"prompt":"Counsel in an Abuja High Court cites an English Court of Appeal decision given in 1995 on a point of contract law. What is the status of that decision before the Nigerian court?","options":["It must be ignored completely, because foreign decisions cannot be cited","It is binding, because English common law is part of received English law","It is binding only if it was decided before 1 January 1900","It is only persuasive, because foreign decisions do not bind Nigerian courts"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"As an independent and sovereign nation, Nigeria is not bound by foreign laws, including English decisions; they serve only as persuasive authority. Option B confuses the reception of common law principles with a duty to follow particular English courts. Option A goes too far, since persuasive foreign decisions are regularly cited."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 537, $official_bank_source${"itemId":"c406d30d-4f67-5a15-a07e-551384da1bd3","questionId":"8e682c33-7eb6-5611-a549-9d176efc8885","sourceKey":"bank:PUL101:SRC-021","payload":{"prompt":"Which local enactments brought the received English law into force in Nigeria?","options":["The African Charter on Human and Peoples' Rights","The Legitimacy Act and the Marriage Act","The Interpretation Act and the Supreme Court Ordinance 1914, among others","The Penal Code and the Criminal Code"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"English law applies in Nigeria because Nigerian enactments, such as the Interpretation Act and section 14 of the Supreme Court Ordinance 1914, received it in general terms. Option A is an international treaty incorporated into Nigerian law and has nothing to do with reception. Options B and D are substantive statutes, not reception provisions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 538, $official_bank_source${"itemId":"71c2cdf8-1bbf-543f-bfc6-d85516756a3a","questionId":"e05d82d5-cdcf-54e5-86c1-90b1b2cdfb44","sourceKey":"bank:PUL101:SRC-022","payload":{"prompt":"Nigerian legislation, as a source of law, consists of:","options":["Customary law and Islamic law","Textbooks and law reports","Statutes and judicial decisions","Statutes and subsidiary legislation"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Nigerian legislation is made up of statutes, which are enacted by the legislature, and subsidiary legislation, which is made under powers given by a statute. Option C adds judicial decisions, which are case law, a separate category. Option A is customary law, and option B lists secondary works that only record or explain the law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 539, $official_bank_source${"itemId":"a0773450-93ec-5e83-bcb9-ae8721a5bbb9","questionId":"6a60437c-4141-51cc-b50f-6ab520119f87","sourceKey":"bank:PUL101:SRC-023","payload":{"prompt":"A law passed by the Nigerian central legislature before 1 October 1954, when federalism became a constitutional feature, is called:","options":["A Decree","An Act","An Edict","An Ordinance"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Ordinances were laws passed by the central legislature before 1 October 1954, when the Lyttleton Constitution introduced federalism. Option B is a law of the elected National Assembly in a civilian regime. Options C and A are military-era enactments of a State military government and the Federal Military Government respectively."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 540, $official_bank_source${"itemId":"c33012cf-bd1a-5300-bb0b-eba09dc4380a","questionId":"51367181-3931-50ed-9e4b-43b7645e01d7","sourceKey":"bank:PUL101:SRC-024","payload":{"prompt":"In Nigerian legislative terminology, a 'Decree' is:","options":["An enactment made by the National Assembly in a civilian regime","An enactment made by the Federal Military Government during military rule","An enactment made by a Military Governor or Administrator of a State","An enactment made by a State House of Assembly in a civilian regime"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"A Decree was the enactment of the Federal Military Government during military rule. Option C describes an Edict, the State-level military counterpart. Options D and A describe a Law and an Act, made by civilian legislatures."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 541, $official_bank_source${"itemId":"61b89d59-a213-58fc-be81-1aa079e6a411","questionId":"f119b900-45c3-506b-8eff-26deebc8a6fc","sourceKey":"bank:PUL101:SRC-025","payload":{"prompt":"In 2015, the Lagos State House of Assembly passed an enactment regulating tenancy in the State. What is such an enactment called?","options":["A Law","An Act","An Edict","An Ordinance"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"An enactment made by an elected State legislature, the House of Assembly, in a civilian regime is called a Law. Option B is the name for an enactment of the National Assembly. Option C applies only to State enactments under military rule, and option D only to central laws made before 1 October 1954."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 542, $official_bank_source${"itemId":"864be8af-6164-5457-994c-56f3df5c6267","questionId":"2eab93ff-1d8d-5de4-9a42-e882cf2aff7d","sourceKey":"bank:PUL101:SRC-026","payload":{"prompt":"In 1976, during military rule, the Military Governor of a Nigerian State made an enactment regulating markets in that State. What is the correct name for it?","options":["A Decree","An Edict","A Law","A bye-law"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"An enactment made by a State Military Governor or Administrator during military rule is an Edict. Option A is wrong because Decrees were made by the Federal Military Government, not by States. Option C is the civilian State equivalent, and option D is subsidiary legislation such as a local government rule."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 543, $official_bank_source${"itemId":"386aba99-aa09-582f-9daf-7b1bbe2684aa","questionId":"e601d0f6-b642-5d35-9eea-311d94ebbda7","sourceKey":"bank:PUL101:SRC-027","payload":{"prompt":"A statute was enacted in 1950 by the Nigerian central legislature. A student describing it correctly would call it:","options":["An Ordinance","A Decree","An Act","A Law"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Laws passed by the central legislature before 1 October 1954 are called Ordinances, and 1950 falls before that date. Option C is the name for National Assembly enactments in a civilian regime, which did not exist in 1950. Options B and D are military federal enactments and civilian State enactments."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 544, $official_bank_source${"itemId":"83457204-9af5-5ea4-b7ac-2b7e42686f6b","questionId":"a3eb78dc-e941-561b-a843-572d2ac6c2d8","sourceKey":"bank:PUL101:SRC-028","payload":{"prompt":"Which of the following pairings of enactment and law-maker is INCORRECT?","options":["Ordinance - central legislature before 1 October 1954","Act - National Assembly","Law - State House of Assembly","Edict - Federal Military Government"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"The Federal Military Government made Decrees; Edicts were made by State Military Governors or Administrators, so pairing an Edict with the Federal Military Government is wrong. Options A, B and C are all correct pairings."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 545, $official_bank_source${"itemId":"9317f172-d4a2-5d3f-885f-71b91f4c7871","questionId":"6ce0f6ed-da43-58a2-ae17-d456f58f23f0","sourceKey":"bank:PUL101:SRC-029","payload":{"prompt":"Why is 1 October 1954 the dividing line between Ordinances and later forms of Nigerian legislation?","options":["It was when Nigeria became independent","It was when federalism was introduced by the Lyttleton Constitution","It was when statutes of general application were received","It was when Nigeria became a republic"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"The Lyttleton Constitution introduced federalism on 1 October 1954, and laws of the central legislature before that date are Ordinances. Options A and D are 1 October 1960 and 1 October 1963 respectively. Option C is wrong because the reception date for statutes of general application is 1 January 1900."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 546, $official_bank_source${"itemId":"fe417b0d-394c-5fe1-9ea1-0faa9156b53a","questionId":"85dc0936-6536-59e1-a2f9-95d806fb91b6","sourceKey":"bank:PUL101:SRC-031","payload":{"prompt":"Which of the following is NOT an example of subsidiary (delegated) legislation?","options":["A bye-law made by a local government","Regulations made by a public corporation","A statutory instrument made by a minister","An Act passed by the National Assembly"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Subsidiary legislation is made by persons or bodies other than the legislature under powers conferred by a statute. An Act of the National Assembly is itself a statute made by the legislature. Options A, B and C are the standard examples of delegated legislation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 547, $official_bank_source${"itemId":"7f6143c5-f434-5f99-b190-16a23382d858","questionId":"b800f0bd-6a7b-572e-b1a6-df88407b52b8","sourceKey":"bank:PUL101:SRC-032","payload":{"prompt":"A State Law empowers a local government to make bye-laws fixing fines of up to N5,000 for illegal dumping. The local government makes a bye-law fixing a fine of N50,000. What is the legal effect of the bye-law's fine?","options":["It becomes customary law and must be tested for repugnancy","It is valid, because the local government is the law-maker for its area","It is valid until the State House of Assembly passes a resolution against it","It is ultra vires and liable to be declared null and void, because it exceeds the power delegated"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Delegated legislation must stay within the limits of the power granted by the enabling statute; exceeding those limits renders it ultra vires, meaning beyond power, and void. Option B ignores that the local government's power comes only from the State Law. Option A confuses written delegated legislation with customary law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 548, $official_bank_source${"itemId":"68c3cb18-9985-59ba-bc64-6f2f9449ae2d","questionId":"a122bb68-4b22-5f50-a97a-09a3266c8083","sourceKey":"bank:PUL101:SRC-033","payload":{"prompt":"Which of the following is NOT a reason given for the use of delegated legislation?","options":["Specialists and those involved in specific activities can deal with particular cases","Many areas of public affairs require technical expertise the legislature may lack","To allow administrative bodies to override the provisions of the enabling statute","It is practically impossible for the legislature to make laws for every aspect of life"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Delegated legislation exists because the legislature cannot foresee every detail and lacks technical expertise, so it lays down the framework and leaves details to specialists. It never permits a body to override its enabling statute; doing so would be ultra vires. Options A, B and D are the genuine reasons."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 549, $official_bank_source${"itemId":"a65184ea-63f4-5dfb-834d-3ad75b4275c8","questionId":"a7d6411c-7ad5-5ff4-8708-fba83465beed","sourceKey":"bank:PUL101:SRC-034","payload":{"prompt":"The Laws of the Federation of Nigeria revised and published in 2004 were printed in loose-leaf format mainly in order to:","options":["Reduce the number of federal statutes in force","Replace the 1999 Constitution as the highest law","Make it easy to incorporate future amendments or revisions","Allow States to remove federal laws they disagree with"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"The loose-leaf format allows new amendments and revisions to be slotted in without reprinting the whole collection. Option A is wrong because the format does not repeal anything. Options D and B are wrong because States cannot remove federal laws and the Constitution remains supreme."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 550, $official_bank_source${"itemId":"e3605cbb-6294-5a16-a012-79e21b366d48","questionId":"1bc49288-4b58-59f2-9e30-a15f25ddd37a","sourceKey":"bank:PUL101:SRC-035","payload":{"prompt":"Which source of law is described as the most important in a modern nation and the 'measuring scale' for the efficacy of other legal sources?","options":["Customary law","Legislation","Received English law","Judicial precedent"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Legislation is the most important form of law in the modern world because it can validate, alter or abolish the content of the others. For example, customary law is applied only as statute directs, and received English law operates through local reception statutes. Options A, C and D are all subject to legislation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 551, $official_bank_source${"itemId":"7441f844-b832-52f6-b2e6-97a427f83433","questionId":"8e28537b-8a65-520f-8a68-74fdc4997ca4","sourceKey":"bank:PUL101:SRC-036","payload":{"prompt":"On what date did the Constitution of the Federal Republic of Nigeria 1999 come into force?","options":["1 January 1999","1 October 1999","29 May 1999","12 June 1999"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"The 1999 Constitution came into force on 29 May 1999, the date civilian rule returned. Option B confuses it with Independence Day, 1 October. Options A and D are not the commencement date."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 552, $official_bank_source${"itemId":"0f4c6600-123c-536f-b499-86eb06b504c2","questionId":"163e3913-092e-5f78-9aa4-0ed507bbce93","sourceKey":"bank:PUL101:SRC-037","payload":{"prompt":"Which section of the 1999 Constitution proclaims its supremacy over all other laws, authorities and persons in Nigeria?","options":["Section 12","Section 1","Section 4","Section 36"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Section 1 of the 1999 Constitution declares the Constitution supreme and makes any other law that is inconsistent with it void to the extent of the inconsistency. Option C deals with legislative powers, option A with the implementation of treaties, and option D with the right to fair hearing."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 553, $official_bank_source${"itemId":"2cf77b15-0ba9-55ed-8145-343796796548","questionId":"7fdbfb7f-8445-53da-9767-8364a32a1cd8","sourceKey":"bank:PUL101:SRC-038","payload":{"prompt":"A State House of Assembly passes a Law that conflicts with a provision of the 1999 Constitution. What is the effect of the conflict?","options":["The Law is void to the extent of its inconsistency with the Constitution","The Law prevails within that State because States are autonomous","The Law prevails because it is more recent than the Constitution","Both remain equally valid and the court chooses the fairer one"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"The Constitution is the highest law of the land, from which all other laws derive their validity, so any inconsistent law is void to the extent of the inconsistency. Option C wrongly applies the idea that a later law prevails; that does not hold against the Constitution. Option B ignores that the Constitution binds every State."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 554, $official_bank_source${"itemId":"3c327e68-ed92-5e74-ad4f-29c1cfde9215","questionId":"8079f9fb-79b5-5ef0-9e80-6ed55bf0b4a9","sourceKey":"bank:PUL101:SRC-039","payload":{"prompt":"Customary law, as a source of Nigerian law, consists of:","options":["The decisions of customary courts that bind all higher courts","English common law principles adapted to Nigerian conditions","Rules made by local governments under an enabling Law","The customs accepted by members of a community as binding among them"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Customary law is made up of customs that the members of a community accept as binding on them, and acceptance as an obligation is one of its main features. Option C describes subsidiary legislation. Option B describes received English law, which is a separate body of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 555, $official_bank_source${"itemId":"00804993-2155-5fcd-92f5-fafd289eefc8","questionId":"3135d62e-0d5d-57f9-ad7d-61fdfe6625f0","sourceKey":"bank:PUL101:SRC-040","payload":{"prompt":"Nigerian customary law is usually classified into:","options":["Ethnic (non-Moslem) customary law and Moslem (Islamic) law","Criminal customary law and constitutional customary law","Written customary law and English customary law","Federal customary law and State customary law"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Customary law in Nigeria is commonly divided into ethnic or non-Moslem customary law and Moslem law, which is Islamic law. Option C is wrong because 'English customary law' is not a category of Nigerian customary law. Options B and D are invented divisions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 556, $official_bank_source${"itemId":"cdae8197-4885-575f-95d0-0c1af95134b0","questionId":"3528d51d-2c26-5b70-9028-4300d842d6e1","sourceKey":"bank:PUL101:SRC-041","payload":{"prompt":"Which statement correctly contrasts ethnic customary law with Islamic law in Nigeria?","options":["Ethnic customary law applies only in the North, while Islamic law applies only in the South","Both are fully written and identical across all ethnic groups","Ethnic customary law is written in the Quran, while Islamic law is unwritten","Ethnic customary law is unwritten and varies between ethnic groups, while Islamic law is largely in written form"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Ethnic customary law is indigenous, unwritten and diverse from one ethnic group to another, while Islamic law is largely written, drawing on the Quran and other recorded authorities. Option C reverses the two. Option B is wrong because the diversity of ethnic customary law is a major obstacle to uniformity."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 557, $official_bank_source${"itemId":"c07879eb-9ee3-508a-9752-d2762b9ebc9f","questionId":"2c4b359c-ffd7-50ee-9365-45e9f6a46f3f","sourceKey":"bank:PUL101:SRC-042","payload":{"prompt":"Which of the following is NOT one of the sources of Islamic law?","options":["The consensus of Islamic scholars","Decisions of the English Court of Chancery","The practice of the Prophet (the Sunna)","The Holy Quran"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Islamic law is derived from the Holy Quran, the Sunna, the consensus of Islamic scholars, and analogical deductions from the holy writ. The English Court of Chancery developed equity, which is part of received English law, not Islamic law. Options A, C and D are genuine foundations of the Sharia."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 558, $official_bank_source${"itemId":"12e551b0-54f3-51c0-a749-c70c2421b2c7","questionId":"5cdf8006-2e25-52a2-b467-0db879a27092","sourceKey":"bank:PUL101:SRC-043","payload":{"prompt":"The predominant version (school) of Islamic law applied in Nigeria is that of the:","options":["Hanbali school","Shafi'i school","Hanafi school","Maliki school"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"The Maliki school is the predominant version of Islamic law in Nigeria. Options A, B and C are other recognised Sunni schools, but they are not the dominant one in Nigeria."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 559, $official_bank_source${"itemId":"4c14acf7-126b-51b9-8839-d8de33692367","questionId":"2107250e-e499-541b-bcdb-4f22b1aad3b4","sourceKey":"bank:PUL101:SRC-044","payload":{"prompt":"In Lewis v Bankole, the court described which feature as one of the most striking features of West African native custom?","options":["Its flexibility and adaptability to altered circumstances without entirely losing its character","Its being written down in codes kept by traditional rulers","Its rigidity and resistance to change over the centuries","Its identity with the rules of English common law"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Lewis v Bankole stressed that native custom is flexible and adapts to changing circumstances without losing its character. Option C is the opposite. Option B is wrong because ethnic customary law is largely unwritten, and option D because customary law is distinct from English law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 560, $official_bank_source${"itemId":"6bd1c522-bd15-5e54-af32-c7e67e40d86c","questionId":"b9ece3e0-8936-55f9-ae0c-d7e7a5c07ad7","sourceKey":"bank:PUL101:SRC-045","payload":{"prompt":"Before a Nigerian court enforces a rule of customary law, the rule must NOT be:","options":["Unwritten; older than 1900; or different from English law","Repugnant to natural justice, equity and good conscience; contrary to public policy; or incompatible with any law for the time being in force","Contrary to Islamic law; unknown outside its community; or more than one hundred years old","Inconsistent with English law; not recorded in a law report; or applied by a customary court"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"The three statutory validity tests are repugnancy to natural justice, equity and good conscience; being contrary to public policy; and incompatibility, directly or by implication, with any law in force. Options A and D wrongly treat difference from English law as a ground of invalidity, which Dawodu v Danmole rejected."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 561, $official_bank_source${"itemId":"258f972e-debe-58ac-a6ac-8eb9764f5394","questionId":"29d578db-259a-51bc-868c-a87759632f56","sourceKey":"bank:PUL101:SRC-046","payload":{"prompt":"Which of the following is NOT one of the statutory tests of validity of customary law in Nigeria?","options":["The rule must not be contrary to public policy","The rule must not be repugnant to natural justice, equity and good conscience","The rule must not be incompatible directly or by implication with any law in force","The rule must be consistent with the principles of English law"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Consistency with English law is not a test; a customary rule does not become invalid merely because it differs from English legal principles. Options A, B and C are the three validity tests laid down by statute."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 562, $official_bank_source${"itemId":"ee9a2063-f861-56ab-acf9-489bd23cde17","questionId":"5e7bab29-6de3-5111-93be-73bcf263c279","sourceKey":"bank:PUL101:SRC-047","payload":{"prompt":"Where are the tests of validity of customary law prescribed?","options":["In the rules of the Maliki school of Islamic law","In statutes, such as the High Court Laws of the States and of the Federal Capital Territory","In the African Charter on Human and Peoples' Rights","Only in the unwritten traditions of each community"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"The validity tests are laid down by statute: the High Court Laws of all the States and the FCT direct courts to enforce customary law only if it passes them. Option D is wrong because communities cannot set the limits on their own custom. Options C and A are not where the tests come from."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 563, $official_bank_source${"itemId":"21c1b209-f243-5a1d-8762-8e88f1d12a37","questionId":"00973722-5840-53de-8bf0-4369bd37ab64","sourceKey":"bank:PUL101:SRC-048","payload":{"prompt":"In Esugbayi Eleko v Officer Administering the Government of Nigeria, Lord Atkin explained the repugnancy test by saying that:","options":["A barbarous custom must be rejected as repugnant to natural justice, equity and good conscience","Any custom differing from English law must be rejected","A custom becomes valid once accepted by a majority of the community","Customary law must give way to statutes of general application"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Lord Atkin held in Eleko that a barbarous custom must be rejected on the ground of repugnancy. Option B is wrong because difference from English law alone does not make a custom invalid. Option C ignores that even widely accepted custom must pass the validity tests."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 564, $official_bank_source${"itemId":"17c971cd-8ea8-5c39-bee9-6695ed083087","questionId":"9c20c208-8dd9-53cd-b8a7-40cc0c1279ba","sourceKey":"bank:PUL101:SRC-049","payload":{"prompt":"In Dawodu v Danmole, the Privy Council held that the Yoruba idi-igi custom of distributing a deceased person's estate:","options":["Was repugnant because it denied equality among the children","Was incompatible with the Marriage Ordinance","Was contrary to public policy and therefore void","Was not repugnant to natural justice, equity and good conscience"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"The Privy Council rejected Jibowu J's view that idi-igi was repugnant, noting that natural justice in a society that accepts polygamy should not be equated with that of a monogamous society. Option A is the trial judge's view, which was overturned. Options C and B were not the grounds considered."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 565, $official_bank_source${"itemId":"e7602e68-a645-5076-87df-1433150a3fbf","questionId":"9e768f4e-c20d-5448-a496-9b167d6eb19c","sourceKey":"bank:PUL101:SRC-050","payload":{"prompt":"Under Yoruba customary law of succession, the idi-igi method distributes the estate of a deceased man:","options":["Per stirpes, according to the branches of the family (each wife's children as a unit)","Per capita, equally among all the children as individuals","Entirely to the eldest son as heir","Entirely to the surviving wives"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Idi-igi is distribution per stirpes, by branches of the family, while ori-ojori is distribution per capita, by the number of children. Option B describes ori-ojori, which the trial judge in Dawodu v Danmole preferred as more equal. Options C and D are not idi-igi."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 566, $official_bank_source${"itemId":"c51b0c99-a8d6-5e05-9614-5630545e2890","questionId":"443da208-2423-5793-95be-c6101cdaa1bf","sourceKey":"bank:PUL101:SRC-051","payload":{"prompt":"Justice Dede of a Kogi State High Court invalidates every customary rule he finds inconsistent with English legal principles. Is his approach correct?","options":["No; customary law can never be declared invalid by a High Court","Yes; the repugnancy test means the same thing as inconsistency with English law","No; inconsistency with English law is not a ground of invalidity, and the custom must be judged only by the statutory validity tests","Yes; customary law is valid only where it agrees with English common law"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"A customary rule is not invalid merely because it differs from English law; Dawodu v Danmole made this clear. The judge should apply only the three statutory tests. Option B wrongly equates repugnancy with difference from English law. Option A goes too far, since High Courts do strike down customs that fail the tests."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 567, $official_bank_source${"itemId":"b7bb6335-32a3-530d-b1fc-c011187812b2","questionId":"b7e5a804-cbb9-51aa-acd4-26f5dd6bc747","sourceKey":"bank:PUL101:SRC-052","payload":{"prompt":"In Re Effiong Okon Atta, the court held which customary rule to be repugnant?","options":["A rule distributing an estate per stirpes among the wives' children","A rule legitimising a child born outside a statutory marriage","A rule entitling the former owner of a slave to administer the slave's personal estate after the slave's death","A rule denying a person accused of highway robbery the right to defend himself"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Re Effiong Okon Atta struck down, as repugnant, a custom allowing a former slave owner to administer the deceased slave's estate. Option D is Guri v Hadejia Native Authority. Option B is Cole v Akinyele, decided on public policy. Option A is the idi-igi rule upheld in Dawodu v Danmole."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 568, $official_bank_source${"itemId":"26bb655f-44eb-50d1-9452-26c5cf254b06","questionId":"de42000c-38d2-594a-9298-23ae5ed29be0","sourceKey":"bank:PUL101:SRC-053","payload":{"prompt":"Afar, a native of Agbor, is tried for robbery in the Delta State High Court. The judge convicts him without letting him present a defence, saying that under Agbor custom a robbery suspect is not entitled to be heard. How should the customary rule be assessed?","options":["It is invalid only because it differs from English criminal procedure","It is valid, because customary law is a primary source of Nigerian law","It is valid, because courts must apply the custom of the accused's community","It is invalid as repugnant to natural justice, equity and good conscience, as in Guri v Hadejia Native Authority"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"A custom denying an accused person the right to defend himself fails the repugnancy test; Guri v Hadejia Native Authority rejected such a rule in a case of highway robbery (hiraba). Options B and C ignore that customary law applies only if it passes the validity tests. Option A gives the wrong reason, since difference from English law is not itself a ground of invalidity."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 569, $official_bank_source${"itemId":"2a630bdb-d0b9-5ce2-8f0f-fc87332e5bb8","questionId":"5269d10a-9e2c-57cc-9bb2-79d1586c5928","sourceKey":"bank:PUL101:SRC-054","payload":{"prompt":"In Cole v Akinyele, the Federal Supreme Court invalidated a customary rule on legitimacy on which ground?","options":["Incompatibility with the Constitution","Inconsistency with English common law","Public policy","Repugnancy to natural justice, equity and good conscience"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"In Cole v Akinyele, Brett FJ held invalid on grounds of public policy a custom that made an acknowledged child born out of wedlock legitimate, sharing equally with children of a marriage under the Marriage Ordinance. Option D is the ground in cases such as Guri and Effiong Okon Atta. Option B is not a ground of invalidity at all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 570, $official_bank_source${"itemId":"58b019b1-afb9-525b-af74-4b21d9ceb074","questionId":"176ac312-0cc9-56d2-a68a-6af9c1641853","sourceKey":"bank:PUL101:SRC-055","payload":{"prompt":"Chief Ade is married under the Marriage Act. He acknowledges paternity of a child born outside that marriage and claims that, under his custom, the child is legitimate and shares equally with the children of the statutory marriage. Following Cole v Akinyele, which validity test is the custom most likely to fail?","options":["Repugnancy to natural justice","Public policy","Incompatibility with the 1999 Constitution","Consistency with English law"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"These facts match Cole v Akinyele, where a custom legitimising an acknowledged child born out of wedlock so that the child shared equally with children of a marriage under the Marriage Ordinance was struck down as contrary to public policy. Option A is the test in Guri and Eleko. Option D is not a validity test."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 571, $official_bank_source${"itemId":"fb626deb-0e4b-5f03-8d2a-69b4380cd60b","questionId":"ab410761-5bfc-51ec-a0e2-e76c051659cf","sourceKey":"bank:PUL101:SRC-056","payload":{"prompt":"A State Law expressly prohibits a practice that a particular customary rule permits. A litigant relies on the customary rule in a State High Court. Which validity test does the rule fail?","options":["Repugnancy to natural justice, equity and good conscience","Incompatibility, directly or by implication, with a law for the time being in force","Inconsistency with English common law","Public policy, because all customs are against public policy"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"A customary rule that conflicts with an existing statute fails the incompatibility test, because customary law yields to written law in force. Option A concerns customs that are inherently barbarous or unjust, which is a different test. Option C is not a test, and option D is false because most customs are valid."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 572, $official_bank_source${"itemId":"d1a464ee-f29c-5417-af8a-92cffe2c1a13","questionId":"afd61c62-bdcc-5dfd-a5e1-f845963ac963","sourceKey":"bank:PUL101:SRC-057","payload":{"prompt":"Which statement best describes the meaning of the repugnancy clause as developed by Nigerian courts?","options":["It applies only to Islamic law and not to ethnic customary law","It has not received a detailed and settled explanation, and its meaning is gathered from decided cases","It has been precisely defined in section 1 of the 1999 Constitution","It means any rule that differs from English law"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Nigerian courts have not given the repugnancy clause a detailed and settled meaning; its content is drawn from cases such as Eleko, Dawodu v Danmole and Guri. Option D is wrong because difference from English law is not repugnancy. Option C is wrong because the clause comes from the High Court Laws, not section 1 of the Constitution."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 573, $official_bank_source${"itemId":"67744c24-ff59-56d3-85b7-1edb66d472fe","questionId":"27f3c908-e0ee-5e67-8bcf-2f6108fb306f","sourceKey":"bank:PUL101:SRC-058","payload":{"prompt":"Why can a person no longer be convicted in Nigeria for an offence known only to unwritten customary law?","options":["Because customary criminal law fails the incompatibility test only in the North","Because customary law was abolished entirely as a source of Nigerian law","Customary criminal law has been displaced, and offences must now be defined in written law such as the Criminal Code and Penal Code","Because customary law applies only in Lagos State"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Customary law today operates in civil matters; customary criminal law has been displaced by written codes such as the Criminal Code and Penal Code. Option B is wrong because customary law remains a primary authority in civil matters such as succession and marriage. Options D and A are invented limits."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 574, $official_bank_source${"itemId":"251b75c9-15ac-5085-9ad7-3ebcaaabb7b7","questionId":"754327c5-71b0-5798-9ef1-c4e21a879267","sourceKey":"bank:PUL101:SRC-059","payload":{"prompt":"The doctrine of judicial precedent means:","options":["The practice whereby the earlier decision of a court is followed in later similar cases, with lower courts bound to follow higher courts","The rule that customary courts must follow the decisions of English courts","The rule that the most recent statute always prevails over an earlier one","The practice whereby each judge decides every case afresh without regard to earlier decisions"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Judicial precedent is the practice of following earlier decisions in later similar cases; where the later court is lower than the earlier one, it must follow the earlier decision. Option D is the opposite of precedent. Option C is a rule about statutes, not case law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 575, $official_bank_source${"itemId":"88fb8a6f-417e-5238-a900-e11713caec77","questionId":"e412632d-1284-51fd-b22c-b59a3e8ecd6f","sourceKey":"bank:PUL101:SRC-060","payload":{"prompt":"The Latin maxim stare decisis, which expresses the rule that lower courts must follow earlier decisions of higher courts, means:","options":["Let the decision stand","Beyond the powers","The thing speaks for itself","Something said in passing"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Stare decisis means 'let the decision stand', the principle behind binding precedent. Option C is res ipsa loquitur, option B is ultra vires, and option D is obiter dictum."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 576, $official_bank_source${"itemId":"0ccc3bc2-e564-5ee2-b474-b5ee08dc656b","questionId":"9262581f-168f-5036-b3af-85f0b0e1e8c9","sourceKey":"bank:PUL101:SRC-062","payload":{"prompt":"A judge of the Kaduna State High Court is faced with facts materially similar to those of a Supreme Court decision. Under the doctrine of judicial precedent, the High Court judge:","options":["May ignore it if he considers it unfair","May follow either it or a contrary decision of another High Court","Must follow the ratio decidendi of the Supreme Court decision","Must follow it only if it was reported in the NWLR"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Decisions of higher courts bind lower courts, so the High Court must follow the Supreme Court's ratio decidendi on facts that are similar in all important respects. Option A would defeat stare decisis. Option B is wrong because a coordinate High Court decision cannot displace a binding Supreme Court decision."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 577, $official_bank_source${"itemId":"b33000c0-daa4-5997-86d6-ca6ee8f69c0b","questionId":"54ca62be-06f2-5d09-a82b-8dcd0406eb5b","sourceKey":"bank:PUL101:SRC-063","payload":{"prompt":"Which statement correctly distinguishes ratio decidendi from obiter dictum?","options":["Both bind later courts equally, but only the ratio is reported","The ratio decidendi is the legal principle necessary for the decision and binds later courts, while an obiter dictum is a remark made in passing that does not bind","The ratio decidendi is a remark made in passing, while an obiter dictum is the binding principle","The ratio decidendi is the judge's summary of the facts, while an obiter dictum is the final order"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"The ratio decidendi, the 'reason for the decision', is the rule of law on which the decision rests and is what binds future cases. An obiter dictum, 'something said in passing', is not binding, though it may persuade and can later be adopted as a ratio. Option C reverses the two terms."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 578, $official_bank_source${"itemId":"a042ef84-1e7d-5770-9ce1-c62239e3abc4","questionId":"e93909f9-23ed-5918-a3af-5f1f4719a528","sourceKey":"bank:PUL101:SRC-064","payload":{"prompt":"Which of the following is NOT an advantage of judicial precedent as a source of Nigerian law?","options":["It enables lawyers and litigants to predict the outcome of disputes","It provides ready solutions to legal problems","It promotes uniformity, consistency and certainty in the law","It allows each judge to depart freely from higher court decisions he dislikes"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Precedent is valued because it gives ready solutions and makes the law uniform, certain and predictable. Allowing judges to depart freely from higher decisions would destroy those benefits. Options A, B and C are the advantages of judicial precedent."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 579, $official_bank_source${"itemId":"308b77bf-7070-5fe3-9fb8-a17c64f563e6","questionId":"394cd690-e0b9-5b9a-97bb-cb31d820cf15","sourceKey":"bank:PUL101:SRC-065","payload":{"prompt":"A Nigerian court extends an existing rule by analogy to cover a new situation that the earlier case did not deal with. This type of precedent is called:","options":["Per incuriam precedent","Declaratory precedent","Derivative precedent","Original precedent"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"A derivative precedent extends an existing rule analogically to a new situation. Option D is a wholly new decision with no similar earlier case. Option B simply restates an existing rule. Option A is not a type of precedent; per incuriam describes a decision reached in ignorance of a binding authority."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 580, $official_bank_source${"itemId":"da40eb7f-661f-5f95-80a0-963bd376b696","questionId":"0ed40466-98ec-5f79-a86c-7430ca374a8e","sourceKey":"bank:PUL101:SRC-066","payload":{"prompt":"A declaratory precedent is one that:","options":["Simply declares or restates an existing rule, giving it added weight and authority","Extends an existing rule by analogy to a new situation","Creates a completely new rule where no earlier similar case exists","Is reached through ignorance of a binding statute"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"A declaratory precedent re-echoes an existing rule, which strengthens it and helps weed out conflicting decisions. Option C describes an original precedent, and option B a derivative precedent. Option D describes a decision given per incuriam."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 581, $official_bank_source${"itemId":"3fbcade6-31a6-52bb-b986-c0c67023cc3c","questionId":"eeff322e-99f8-536b-b79d-e31b913881cb","sourceKey":"bank:PUL101:SRC-067","payload":{"prompt":"Without which two things would the principle of stare decisis be impracticable?","options":["A hierarchy of courts and an efficient system of law reporting","A codified customary law and an Islamic court","A written constitution and a military government","A Law Commission and a loose-leaf statute book"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Stare decisis depends on knowing which courts are higher and binding, and on reliable reports of their decisions. Options B, C and D are not preconditions for binding precedent."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 582, $official_bank_source${"itemId":"e482c49c-4c48-5fcb-8745-0eb66a87ca2e","questionId":"f7d81b28-a2a8-5921-b43d-2abb7a02df78","sourceKey":"bank:PUL101:SRC-068","payload":{"prompt":"The branch of law known historically as jus gentium, which recognises that no nation can exist in isolation, is:","options":["Customary law","Constitutional law","Islamic law","International law (the law of nations)"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Jus gentium means the law of nations, the basis of international law, which governs relations among States through treaties, conventions and similar instruments. Options A, B and C are domestic categories of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 583, $official_bank_source${"itemId":"7d3066f6-81e3-53ad-968b-8a5faeaa6689","questionId":"e5f781a7-2a84-5dc3-b58f-463b052687a5","sourceKey":"bank:PUL101:SRC-069","payload":{"prompt":"Under the Nigerian constitutional system, when does a treaty that Nigeria has signed become operative as law in Nigeria?","options":["When the National Assembly has enacted it into law","When any State High Court applies it in a case","As soon as the President signs it","As soon as it is published in a foreign gazette"],"correctOption":0,"section":"Sources of Nigerian Law","explanation":"Section 12(1) of the 1999 Constitution provides that a treaty has no force of law in Nigeria until the National Assembly enacts it into law. Option C is a common mistake: signature or ratification by the executive alone is not enough. Option B is wrong because courts cannot domesticate a treaty."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 584, $official_bank_source${"itemId":"62a04a18-1dd3-5aaf-a22d-4e33e1e412af","questionId":"41c5ddb2-7983-56b7-afcd-fe866183370a","sourceKey":"bank:PUL101:SRC-070","payload":{"prompt":"In Sani Abacha v Gani Fawehinmi, the Supreme Court held that the African Charter on Human and Peoples' Rights:","options":["Applies only in the States that signed it individually","Is superior to the 1999 Constitution","Having been incorporated into Nigerian law, is enforceable in Nigerian courts","Is not enforceable in Nigeria because it is a foreign document"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"Because the African Charter was enacted into Nigerian law, the Supreme Court in Abacha v Fawehinmi held it enforceable in Nigerian courts. Option D ignores its domestication. Option B is wrong because the Constitution remains supreme over every other law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 585, $official_bank_source${"itemId":"de69e6c2-1bf4-56ba-b676-bd6b2e1cc34a","questionId":"853a452a-79c9-5336-8c56-8b2a76d1c7c5","sourceKey":"bank:PUL101:SRC-071","payload":{"prompt":"Nigeria ratified an international trade convention in 2020, but the National Assembly has not enacted it into law. A Kano trader sues, relying solely on a right granted by the convention. What is the likely outcome?","options":["The convention is enforceable because ratification by the executive is enough","The convention is enforceable because international law binds all courts automatically","The convention is enforceable only in the Kano State High Court","The convention cannot be enforced as law in Nigeria until the National Assembly enacts it"],"correctOption":3,"section":"Sources of Nigerian Law","explanation":"Under section 12(1) of the 1999 Constitution, a treaty becomes operative in Nigeria only after the National Assembly enacts it into law. Option A is the common mistake of treating ratification as domestication. Option B is wrong because Nigeria requires an enactment before a treaty has the force of law."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 586, $official_bank_source${"itemId":"6f8a2d59-8866-5b31-a24d-4dc473bdc03f","questionId":"0fcab8b0-3371-52fd-b500-e7686d7fac91","sourceKey":"bank:PUL101:SRC-072","payload":{"prompt":"A law digest, such as the Digest of Supreme Court Cases, is best described as:","options":["A journal of academic articles on law reform","An abridgement of cases giving summaries of the facts, issues, arguments and decisions","A dictionary of foreign legal terms","A collection of statutes arranged in loose-leaf form"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Digests abridge cases, giving useful summaries of the facts, issues, arguments and decisions in judicial proceedings. Option D describes a statute compilation such as the Laws of the Federation. Options C and A describe legal dictionaries and periodicals."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 587, $official_bank_source${"itemId":"77c3ec6c-b48d-5796-91a4-3521bbde20cc","questionId":"6d9945b2-4eaa-596f-a7fc-5991f43a5c0e","sourceKey":"bank:PUL101:SRC-073","payload":{"prompt":"Why are law reports described as essential in a country such as Nigeria that operates judicial precedent?","options":["Law reports replace the need for legislation","Only by reference to reported cases can courts and lawyers ascertain the position of the law","Law reports record only customary law","Law reports are themselves binding statutes"],"correctOption":1,"section":"Sources of Nigerian Law","explanation":"Where precedent operates, the law is partly contained in decided cases, and lawyers and judges can only know those decisions through reports. Option D is wrong because a law report is a secondary work that records decisions, not a statute. Options A and C misstate its role."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 588, $official_bank_source${"itemId":"db925639-5e82-5fe8-9e07-9131478032ae","questionId":"79d49962-473f-5d49-9ff4-a8d6ed7b92a3","sourceKey":"bank:PUL101:SRC-075","payload":{"prompt":"Under the division of legislative powers in the 1999 Constitution, which statement is correct?","options":["All matters may be legislated on by both levels equally, so there is no division","Matters on the Exclusive List are for the States only, and residual matters are for the federal legislature only","Matters on the Exclusive List are for the federal legislature only, matters on the Concurrent List may be legislated on by both levels, and residual matters are left to the States","The Concurrent List is for local governments, and the Exclusive List for the States"],"correctOption":2,"section":"Sources of Nigerian Law","explanation":"The Exclusive Legislative List is reserved to the National Assembly, the Concurrent List is shared by the National Assembly and State Houses of Assembly, and residual matters, which appear on neither list, fall to the States. Option B reverses the federal and State roles. Option A ignores the constitutional division altogether."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 589, $official_bank_source${"itemId":"632b7aad-f481-58d9-898a-50fc9f3f1c3c","questionId":"c2160839-0519-5018-8938-bf10e7793c99","sourceKey":"bank:PUL101:RES-001","payload":{"prompt":"In the context of legal method, 'research' means:","options":["Interviewing witnesses in order to prove facts in court","The use of library resources to seek recorded information on a legal problem in order to authoritatively determine the rights, duties and liabilities of the parties","Drafting a bill for presentation to the National Assembly","Memorising lecture notes so as to pass law examinations"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"Legal research is the use of library resources to find recorded information that settles the rights, duties and liabilities of the parties to a legal problem. Option D is mere examination preparation, which is not the same as finding the law. Option A is fact-gathering for evidence, and option C is legislative drafting."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 590, $official_bank_source${"itemId":"28fbce07-6e67-55d8-b5c6-6248e8ccc9d6","questionId":"f589f869-749a-5997-9d41-be6cd9b1e36d","sourceKey":"bank:PUL101:RES-002","payload":{"prompt":"Which of the following is NOT a reason why a lawyer needs to carry out legal research?","options":["Research findings may help persuade a court to adopt the lawyer's reasoning","The law is static, so research is needed only once at the start of a career","Diligent research may persuade a court to adopt a new position or even reverse its earlier decision","The law is dynamic and developing, so current rules must be determined"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"Research is needed precisely because law is dynamic, not static, so a lawyer must keep checking the current rules. Options A, C and D are all genuine reasons: law keeps developing, research supports persuasion, and good research can even lead a court to change its position."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 591, $official_bank_source${"itemId":"cfcd2a5d-f1e3-544f-a817-9925c370bae1","questionId":"9fa9e51b-4a9e-5de4-ab6d-9eb9c5733a27","sourceKey":"bank:PUL101:RES-003","payload":{"prompt":"The saying that 'lawyers do not know much more law than other people, but they know better where to find it' emphasises the importance of:","options":["Having a large private collection of novels","Courtroom advocacy skills","Memorising every statute word for word","Legal research and the effective use of the library"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"The saying stresses that a lawyer's real advantage is knowing where and how to find the law, which is the skill of legal research. Option C is wrong because the point is precisely that lawyers need not carry all the law in memory. Option B is a different skill."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 592, $official_bank_source${"itemId":"14f962ce-2101-5a89-8483-218e0f5e87c4","questionId":"f08ffd10-991d-5027-9a6f-37a832fdd56b","sourceKey":"bank:PUL101:RES-004","payload":{"prompt":"What is the great disadvantage of a law student confining himself to lecture notes and law textbooks?","options":["Textbooks are always more up to date than law reports","He takes all his law at second hand, because the law itself is contained in statutes and judicial decisions","He will be unable to read the Constitution","He will learn too many cases to remember"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"The law is contained in statutes and judicial decisions; what a text writer thinks is not itself law and may misread the authorities. Relying only on secondary works means taking the law at second hand. Option A is wrong because books often lag behind the latest reports."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 593, $official_bank_source${"itemId":"8e626e5c-996d-582a-8543-5e44b7868548","questionId":"855c04a4-a452-53d9-b8e6-0e401878153d","sourceKey":"bank:PUL101:RES-005","payload":{"prompt":"Why is a competent law librarian described as an important research aid?","options":["Once the subject area is identified, he can assemble the relevant primary and secondary authorities for the researcher","He writes the legal opinion for the lawyer","He decides which party should win a case","He removes the need for the researcher to know how to use the library"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"A good law librarian specialises in knowing what is relevant to a subject and can assemble both primary and secondary authorities, and it helps if he is legally trained. Option D is wrong because such librarians are rare, so the researcher must still know how to use the library himself."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 594, $official_bank_source${"itemId":"4b882857-4c24-5e7a-9ed6-2c503580dfd2","questionId":"f4f8059b-98ba-5b9a-8086-d63c02be3e9c","sourceKey":"bank:PUL101:RES-006","payload":{"prompt":"Most books are identified by six elements. Which of the following is NOT one of them?","options":["The place and date of publication","The name of the library that owns the book","The author's name","The publisher"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"The six identifying elements are the cover, the author's name, the publisher, the title, the place of publication and the date of publication. The owning library is not one of them. Options A, C and D are among the six, and apart from the cover they all appear on the title page."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 595, $official_bank_source${"itemId":"103883e2-a63d-5dd8-9e00-2cac0e796a5e","questionId":"6c0e7e8e-ac99-509a-b613-67f4a67abad1","sourceKey":"bank:PUL101:RES-007","payload":{"prompt":"Tobi pulls a book from a library shelf and sees the call mark K108.7. Another library's books have call marks such as 642.13. Which classification systems do these indicate?","options":["K108.7 indicates the Dewey Decimal system; 642.13 indicates the Library of Congress system","Both indicate the Dewey Decimal system","Both indicate the Library of Congress system","K108.7 indicates the Library of Congress system; 642.13 indicates the Dewey Decimal system"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"A call mark beginning with a letter shows the Library of Congress classification, while one beginning with numbers shows the Dewey Decimal system. Option A reverses the two, which is the usual slip. Options C and B ignore the difference between letters and numbers."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 596, $official_bank_source${"itemId":"7b8d8834-b7b4-51fa-b1d1-3f10d9838921","questionId":"7a3a1466-1a54-514f-9b4c-6368e5d1d709","sourceKey":"bank:PUL101:RES-008","payload":{"prompt":"Four books in a Library of Congress library have the call numbers B358.C54, B200.C57, K146.O2 and B200.A18. Which of them will be shelved FIRST?","options":["K146.O2","B200.A18","B358.C54","B200.C57"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"Books are shelved alphabetically by the subject letter, then numerically by the subject number, then by the author letter and number. B comes before K, 200 comes before 358, and author letter A comes before C, so B200.A18 is first. Option D has the same subject number but a later author letter."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 597, $official_bank_source${"itemId":"18b4b865-5d47-59db-8b94-4f7ce438c40d","questionId":"50629bd6-b18c-53d4-81a4-3f97c5043cb3","sourceKey":"bank:PUL101:RES-009","payload":{"prompt":"Why is the library catalogue a better approach than browsing the shelves, even in a library with open stacks?","options":["Browsing may miss books that are borrowed, reserved or on the reserve shelf, while the catalogue lists all the library's books","The catalogue contains the full text of every book","The catalogue arranges books by the colour of their covers","Browsing is forbidden in all Nigerian law libraries"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"The catalogue tells the researcher about every book the library holds, including those a browser would miss because they are borrowed or reserved. It is especially important in libraries with closed stacks. Option B overstates what a catalogue contains; it gives entries, not the full text."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 598, $official_bank_source${"itemId":"60282eb0-50ff-5b76-83f0-59110493401a","questionId":"3aedb758-8197-5eb1-acd7-bce44cbc9d5c","sourceKey":"bank:PUL101:RES-010","payload":{"prompt":"Jumar, a visiting law student with little time before the library closes, must find a contract book by a named new author but is unsure of its exact title. What is her best approach?","options":["Search the Words and Phrases section of a law report index","Browse the shelves one by one until she finds it","Check the author's entry in the catalogue, note the call number and go to the shelf","Check the periodical index"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"With limited time, browsing is ill advised; she should use the catalogue, and the author's entry is the main entry and the best route when the author is known. Option B wastes time. Option D is for journal articles, and option A is for judicially defined words."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 599, $official_bank_source${"itemId":"b2070c86-1576-50b1-b6ba-63c50c309c6d","questionId":"1d641125-573c-5d2e-91b3-e222db1fb6e9","sourceKey":"bank:PUL101:RES-011","payload":{"prompt":"A lawyer is applying for bail for an accused person in the Ogun State High Court. Under which law will the application be brought?","options":["The law of whichever State the lawyer practises in most often","The Laws of Lagos State, because Lagos is the former federal capital","English law only, as received in 1900","The relevant law of Ogun State, since each State has its own system of law and courts"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"Each Nigerian State has its own system of law and courts, so an application in a State High Court is brought under that State's law. Options B and A pick the wrong State's law. Option C ignores that local State law governs procedure in that State's courts."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 600, $official_bank_source${"itemId":"9739aeb9-1aef-54a5-8e05-a2ca49dcbc3b","questionId":"82808bc3-a367-5292-81ef-188dc93d93a6","sourceKey":"bank:PUL101:RES-012","payload":{"prompt":"Which of the following is NOT usually contained in a modern law report?","options":["A headnote and an outline of the facts","The reporter's own verdict on which party should have won","The name of the case, its date, the court and the judges","A verbatim copy of the judgment"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"A modern law report gives the case name, date, court and judges, a headnote, an outline of the facts, counsel's names, sometimes a summary of arguments, and always a verbatim copy of the judgment. The reporter does not substitute his own verdict. Options A, C and D are standard contents."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 601, $official_bank_source${"itemId":"be23dabf-0e0d-5cd1-9901-9241992d1b65","questionId":"3dce9ada-6601-514c-884a-4c8a51a4d7df","sourceKey":"bank:PUL101:RES-013","payload":{"prompt":"A reported case is usually cited by stating:","options":["The names of the judges, the counsel and the court registry number","The headnote, the ratio decidendi and the final order","The names of the parties, the year, the volume, the name of the law report and the page","The date of filing, the suit number and the trial judge only"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"A case citation gives the parties' names, the year (or month), the volume, the name of the law report and the page where the case begins. Options A and D describe court records rather than a law report citation. Option B describes parts of a judgment, not a citation."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 602, $official_bank_source${"itemId":"3b26978c-63ae-56ce-896f-4173f0a7698c","questionId":"968a7a83-4922-5da8-b8c6-d4c8e963093e","sourceKey":"bank:PUL101:RES-014","payload":{"prompt":"What is the significance of square brackets, as against round brackets, around the year in a case citation?","options":["Square brackets show that the year is essential for locating the case; round brackets show that it is not","Square brackets show that the case was decided by the Supreme Court; round brackets show a High Court case","Square brackets show that the year is not essential; round brackets show that it is","Square brackets show a foreign case; round brackets show a Nigerian case"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"When the year is in square brackets, it is an essential part of finding the case, because the reports are arranged by year. When it is in round brackets, the volume number is what locates the case and the year is not essential. Option C reverses the rule, which is the common slip."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 603, $official_bank_source${"itemId":"4ecc4473-44f0-5a79-8faa-de8c4ed44679","questionId":"f39f8248-45bb-5bf6-89f0-c80513a12794","sourceKey":"bank:PUL101:RES-015","payload":{"prompt":"In the citation Marina Nominees Ltd v FBIR [1986] 2 NWLR (Pt 20) 40, what does 'Pt 20' refer to?","options":["Page 20 of the judgment","Paragraph 20 of the headnote","Part 20 of the Nigerian Weekly Law Reports, a part number that is never duplicated","The 20th case decided by the Supreme Court in 1986"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"The Nigerian Weekly Law Reports identifies each issue by a part number, and no part number is ever repeated, so the part and the page are the most useful details for tracing the case. Here 2 is the volume, Pt 20 is part 20 and 40 is the page. Option A confuses the part with the page."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 604, $official_bank_source${"itemId":"b70e6226-bd38-580b-b18a-4dfd90b9c6d1","questionId":"e73635fe-ec80-5d2a-bdcc-21b17eb32d31","sourceKey":"bank:PUL101:RES-016","payload":{"prompt":"Jumar's supervisor gives her the citation Adeolu v Mabamiye (1985) 2 NWLR p.5, which omits the part number. What is a sensible way to find the full citation?","options":["Look for it in the periodical index","Look in the Dewey Decimal section of the library","Check the list of cases in a standard book on the subject, or an index, to obtain the full citation including the part","Give up, because a case cannot be traced without the part number"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"Because the NWLR is traced mainly by part and page, a missing part is a problem, but it can be solved by checking the list of cases in a standard book on the subject or an index, or by going through the volumes. Option D is too pessimistic. Option A is for journal articles, not law reports."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 605, $official_bank_source${"itemId":"bd11920e-2278-56cf-9d3b-4fdf94756520","questionId":"7ffbe274-a782-50e5-8446-1817cfc454dd","sourceKey":"bank:PUL101:RES-017","payload":{"prompt":"A researcher wants to see all the reported cases on locus standi, and also how the courts have judicially defined the phrase 'reasonable cause'. Where should she look?","options":["In the periodical index under both headings","In a case index: under L for locus standi, and in the 'Words and phrases' section for 'reasonable cause'","In the catalogue's author entries","In a general dictionary of the English language"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"A case index, arranged alphabetically by subject, is the best tool for finding all the authorities on an issue, so locus standi appears under L. Judicially defined expressions are listed under 'Words and phrases'. Option A finds journal articles, not cases. Option D gives ordinary meanings, not judicial definitions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 606, $official_bank_source${"itemId":"19bff8c9-3e05-57d4-85a6-43c3822dbf32","questionId":"0810e8da-1d64-5bb3-be7c-dc999dd86b9f","sourceKey":"bank:PUL101:RES-018","payload":{"prompt":"How do the Nigerian Weekly Law Reports (NWLR) and the Supreme Court of Nigeria Judgments (SCNJ) differ in coverage?","options":["The SCNJ is published weekly, while the NWLR appears once a year","The NWLR reports only High Court cases, while the SCNJ reports Court of Appeal cases","The NWLR reports decisions of both the Court of Appeal and the Supreme Court, while the SCNJ reports only Supreme Court cases","Both report only customary court decisions"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"The NWLR comes out weekly and reports cases of the Court of Appeal and the Supreme Court, while the SCNJ reports only Supreme Court cases and usually appears every month or two. Option A reverses their frequency. Options B and D misstate which courts they cover."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 607, $official_bank_source${"itemId":"6914d353-a0ec-557f-b27f-2c208b93b37b","questionId":"2e503f9c-e14b-520d-8a0e-88149d817bdd","sourceKey":"bank:PUL101:RES-019","payload":{"prompt":"Which of the following is a Nigerian law report?","options":["Weekly Law Reports (WLR)","Nigerian Weekly Law Reports (NWLR)","Appeal Cases (AC)","All England Law Reports (All ER)"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"The Nigerian Weekly Law Reports, published since 1985, is one of the main Nigerian law reports. Options A, C and D are United Kingdom reports, although Nigerian lawyers may cite them as persuasive authority."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 608, $official_bank_source${"itemId":"1c7cfc69-3d42-539b-b5fe-c07bc0a86b8c","questionId":"de121ac4-9021-5cc1-805e-85aab03e92cb","sourceKey":"bank:PUL101:RES-020","payload":{"prompt":"Which of the following is a way in which periodicals (journals) differ from books?","options":["Periodicals appear at intervals and contain briefer articles by different writers","Periodicals are always written by a single author","Periodicals contain longer treatments than books","Periodicals always discuss one subject completely in a single edition"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"Periodicals appear at intervals (weekly, monthly, quarterly and so on), their articles are briefer so the essentials are reached quicker, and they contain contributions by different writers. Option D describes a book, whose author treats the subject in one complete edition. Options B and C are the opposite of the true position."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 609, $official_bank_source${"itemId":"e43be06b-2833-5c2e-bc56-d0ab40df2f1f","questionId":"700dba49-b87c-551b-aad5-c3156c7bcc42","sourceKey":"bank:PUL101:RES-021","payload":{"prompt":"Amaka is researching recent developments in Nigerian banking law. She has no particular article in mind and no citation. What is the best tool for finding relevant journal articles?","options":["The library's card catalogue of books","A periodical index","A case index under 'Words and phrases'","Browsing the journal section one journal at a time"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"A periodical index does for journal articles what the catalogue does for books: it lists published articles by subject and author so the citation can be noted. Option D is slow and may prove futile. Options A and C are for books and cases respectively."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 610, $official_bank_source${"itemId":"f78ba78b-13a6-53f0-b28b-f333fd8e8c5a","questionId":"2d841485-53f3-5bdd-b822-db156ae0b684","sourceKey":"bank:PUL101:RES-022","payload":{"prompt":"Reference books in a library are distinguished from regular books in that they:","options":["Can be borrowed for longer periods than other books","Contain only primary legislation","Do not circulate and are marked with 'R' or 'REF' above the call number","Have no call number at all"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"Reference books, such as dictionaries and encyclopedias, give quick, brief information, do not circulate, and can only be used in the reference section. They are marked with R or REF above the call number. Option A is the opposite of the rule, and option D is wrong because they do carry call numbers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 611, $official_bank_source${"itemId":"f1b1ef91-eef2-51df-8f90-f7ee9fc2a98c","questionId":"47c2949b-08c4-5133-b0c7-1481d571c809","sourceKey":"bank:PUL101:RES-023","payload":{"prompt":"A student needs only the meaning of the legal term 'locus standi' and the date of a historical event for his assignment. What is the most efficient resource?","options":["The Dewey Decimal classification table","The periodical index","A full treatise read from cover to cover","A reference book, such as a law dictionary, used in the reference section"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"Reference books exist for brief, concise information such as the meaning of a word or the date of an event, and can be consulted without reading a whole book. A subject reference book such as Black's Law Dictionary suits a legal term. Option C is inefficient. Option B locates articles, not definitions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 612, $official_bank_source${"itemId":"9957eadb-e284-504a-9397-d2a18341fe1a","questionId":"0e61f8d0-6f84-5728-9a5d-04096503d830","sourceKey":"bank:PUL101:RES-024","payload":{"prompt":"Which work is described as the most comprehensive legal encyclopedia, covering all areas of English law and serving as the take-off point for legal research?","options":["Stroud's Judicial Dictionary","Black's Law Dictionary","Halsbury's Laws of England","The Digest of Supreme Court Cases"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"Halsbury's Laws of England is the most comprehensive legal encyclopedia, covering all areas of English law, and is a natural starting point for research. Legal encyclopedias are also more current than ordinary law books. Options B and A are law dictionaries, and option D is a digest of cases."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 613, $official_bank_source${"itemId":"760aa167-cd4c-54c7-84b9-2c1c14aa7c56","questionId":"b1f64ff9-7929-5d4a-bb65-5db4ead4b5e9","sourceKey":"bank:PUL101:RES-025","payload":{"prompt":"Lexis and Westlaw are examples of:","options":["Legal databases making recent judicial decisions and legislation available electronically","Library classification systems","Types of argumentative essay","Nigerian law reports published weekly"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"Lexis and Westlaw are electronic legal databases giving access to recent decisions and legislation from the Commonwealth, Europe and the United States. Information technology lets a computer find in seconds what a manual search might take days to find. Option B describes systems like Dewey and Library of Congress."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 614, $official_bank_source${"itemId":"1d8f0770-9435-529f-aeb8-b678e0ea530d","questionId":"cae4075a-62df-5265-9290-935ce9c1ab32","sourceKey":"bank:PUL101:RES-027","payload":{"prompt":"An essay titled 'Constitutional Development in Nigeria' traces events in order from 1914 to the present day. Which type of essay is it most likely to be?","options":["A narrative essay","An argumentative essay","A descriptive essay","An expository essay"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"A narrative essay presents details about events in the order in which they occurred, so a chronological account of constitutional development from 1914 is narrative. Option B would require taking and defending a position. Option C would focus on how something looks or feels."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 615, $official_bank_source${"itemId":"561cf011-2e94-560e-8456-0f2b12698732","questionId":"41318bfa-ca53-52ae-89f2-7e7c463dc43a","sourceKey":"bank:PUL101:RES-028","payload":{"prompt":"A student is asked to write on 'The Abolition of the Death Penalty: To Be or Not to Be?' and must take a stand, persuade the reader and demolish the opposing arguments. This calls for:","options":["A descriptive essay","A narrative essay","An expository essay","An argumentative essay"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"An argumentative essay requires the writer to support or oppose a position, give reasons for his claims and demolish the arguments for the opposing view. Option C explains and clarifies without necessarily taking sides. Options B and A recount or describe."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 616, $official_bank_source${"itemId":"7fc2d873-aea4-51fe-b0b2-f022cf511006","questionId":"70ab29ab-6151-56a0-a341-1ba0c4c1cb70","sourceKey":"bank:PUL101:RES-029","payload":{"prompt":"A good essay topic is said to possess which three attributes?","options":["It is correct, complete and concise","It is long, technical and controversial","It is popular, foreign and historical","It is vague, broad and open-ended"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"A good topic is correct because it gives adequate information about the subject, complete because it is clearly understandable to everyone in the field, and concise because it states the content in the shortest efficient way. Options B and D describe topics that are hard to manage."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 617, $official_bank_source${"itemId":"97359a75-6a36-54fe-8d74-b6200a6707c3","questionId":"a987e9d4-4a44-58a8-988d-5d70c658657a","sourceKey":"bank:PUL101:RES-030","payload":{"prompt":"When rethinking a chosen topic, a writer who has difficulty raising questions on it is advised to use which words?","options":["Correct, complete and concise","Issue, rule, application and conclusion","Introduction, definition, body and conclusion","What, who, where, when, how and why"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"Questioning the topic with what, who, where, when, how and why throws light on it and opens up new ideas. Option C is the IDBC structure for answering essay questions, and option B is IRAC for problem questions. Option A lists the attributes of a good topic."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 618, $official_bank_source${"itemId":"21b8a9ba-7b24-5a73-93e4-dc0efab132a0","questionId":"bad95dd8-6d3e-5241-925e-ec03998b57bd","sourceKey":"bank:PUL101:RES-031","payload":{"prompt":"A writer is deemed to have made a definite choice of thesis when it:","options":["Avoids taking any position on the topic","Repeats the title of the essay word for word","Lists every question that can possibly be asked about the topic","Makes a restricted and organised assertion about the topic and clearly reveals the writer's attitude towards it"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"The thesis turns the basic question into a basic answer: a restricted, organised assertion that announces the major points and the writer's attitude. Option C describes the earlier questioning stage, not the thesis. Option A is the opposite of a thesis."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 619, $official_bank_source${"itemId":"7f3c1f1f-386f-519b-8761-7c4b5c6b09af","questionId":"86375f8c-3209-5abe-845c-088e94671f2b","sourceKey":"bank:PUL101:RES-032","payload":{"prompt":"Before writing, Kunle gives his essay idea to a classmate who has researched the same topic and asks her to criticise it as ruthlessly as possible. Which test of the idea is he applying?","options":["The writing test","The possibility test","The credibility test","The friendly colleague test"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"The friendly colleague test involves getting someone, preferably a person who has researched the topic, to critique the idea so it is thoroughly 'sieved' before writing. Option C asks whether the idea is current and plausible. Option B asks whether the task can be completed in the time available. Option A involves trying the idea out on paper."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 620, $official_bank_source${"itemId":"c60cffbb-2fc2-5660-9e34-4eecf80a1c5b","questionId":"0d234dea-abcc-551a-b01c-c24222221af6","sourceKey":"bank:PUL101:RES-033","payload":{"prompt":"Which of the following is NOT one of the preliminary tests for an essay idea?","options":["The repugnancy test","The writing test","The credibility test","The possibility test"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"The preliminary tests of an essay idea are the writing test, the credibility test, the friendly colleague test and the possibility test. The repugnancy test belongs to the validity of customary law, not essay writing. Options B, C and D are genuine idea tests."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 621, $official_bank_source${"itemId":"ee8a6e94-bf41-58d2-b3e6-47420196547a","questionId":"0fddaa2f-066d-5015-9f9d-bd4db3433990","sourceKey":"bank:PUL101:RES-034","payload":{"prompt":"When choosing works to rely on, why may a writer still cite an old work such as Obilade's The Nigerian Legal System?","options":["Recent journals are never relevant to legal writing","Old works are always more accurate than new ones","Some works are classics in their field and remain relevant as guideposts to the development of the law","Only works over forty years old may be cited in legal writing"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"Some older works are classics that remain relevant despite later developments, so they can be cited for the impact they have had. Option B is wrong because currency is also vital, which is why the latest editions should be used. Option A contradicts that need for currency."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 622, $official_bank_source${"itemId":"24d78374-9753-5074-afd8-efa3edd9f76a","questionId":"c1d1dff4-cbf7-5abd-b838-195374a23ad9","sourceKey":"bank:PUL101:RES-035","payload":{"prompt":"While reading an article for her essay, Ngozi asks herself whether the writer's conclusions are justified by his evidence, whether his reasoning is faulty and whether the work will command respect when cited. She is:","options":["Organising her reading time","Reading responsibly","Reading selectively","Reading critically"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"Reading critically means analysing what you read: testing the writer's arguments and evidence, checking the reasoning and deciding whether the work will command respect. Option C means reading only what will be used. Option B means reading methodically and in context. Option A means scheduling your reading."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 623, $official_bank_source${"itemId":"07d39373-d179-50bf-b5c3-839a803596ce","questionId":"58ecd8ac-fe73-54ad-93d8-f6b68a8653ab","sourceKey":"bank:PUL101:RES-036","payload":{"prompt":"The advice 'Don't get it right, get it written' applies to which stage of essay writing?","options":["The first draft, where the whole paper is written without stopping to correct anything","The second draft, where omitted words and details are added","The outline, where major divisions are planned","The third draft, where repetition and verbosity are cut"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"At the first draft the writer should get the whole paper down without stopping to correct, because until it is written there is nothing to revise. Option B adds missing words and details. Option D trims deadwood and moves the text towards a reader-oriented work."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 624, $official_bank_source${"itemId":"fe9d3570-d21b-55fb-8eea-97aca1ba1c22","questionId":"a51f76c2-4d46-5be3-960c-2053ad1a0ba1","sourceKey":"bank:PUL101:RES-037","payload":{"prompt":"At which drafting stage does the writer cut off the 'dead wood' of repetition and verbosity and move from a writer-oriented draft towards a finished reader-oriented work?","options":["The second draft","The first draft","The preliminary reading stage","The third draft"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"The third draft trims repetition and verbosity and addresses content, organisation, logic and coherence, turning a writer-oriented draft into a reader-oriented work. Option B is for getting everything written without correction. Option A is for adding missing words and details."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 625, $official_bank_source${"itemId":"7cdfeac1-eb6d-5771-a516-6f53e7e5f844","questionId":"989dd464-2552-5d3d-8eb0-ff82dcdb8f82","sourceKey":"bank:PUL101:RES-038","payload":{"prompt":"For an essay introduction to be effective, it must:","options":["Be the longest part of the essay","Contain all the main arguments of the body","Always be written before anything else","Identify the subject, arouse interest and be brief"],"correctOption":3,"section":"Legal Research and Legal Writing","explanation":"An effective introduction identifies the subject, arouses interest and is brief; it may take the form of a question, a problem or an illustration. Option C is wrong because writing the introduction may be put off until the body is organised. Option B is a common mistake, since starting the body in the introduction loses the marks for the introduction."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 626, $official_bank_source${"itemId":"d2cdc004-1278-5ea5-be2c-9130ed232d91","questionId":"3bc55c31-52a1-5cdd-8b20-0a01418bc143","sourceKey":"bank:PUL101:RES-039","payload":{"prompt":"The use of the thoughts and ideas belonging to others without acknowledgement is called:","options":["Paraphrase","Plagiarism","Citation","Brevity"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"Plagiarism is using other people's thoughts and ideas without acknowledging them, and good legal writing must avoid it by giving credit and expressing independent views. Option C is the proper way of acknowledging another writer. Option D means saying much in few words."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_pul101', 'add', 627, $official_bank_source${"itemId":"0ec040ed-890f-53b0-8036-f35e50089a17","questionId":"f612fd72-3198-5057-b669-ef35211e0813","sourceKey":"bank:PUL101:RES-040","payload":{"prompt":"Bisi ends her essay on cybercrime by predicting what the problem may look like in Nigeria in ten years and warning of what could happen if nothing is done. Her conclusion is best described as:","options":["A looking-ahead conclusion","A reflective conclusion","An introduction in disguise","A straightforward conclusion"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"A looking-ahead conclusion makes a prediction or sounds a warning about what may happen to the subject in future. Option B highlights related issues and questions for further inquiry. Option D states that the work has ended and then makes suggestions and recommendations."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 628, $official_bank_source${"itemId":"e26d4d2f-719f-5180-a2f9-3873d2065854","questionId":"6d2f0e87-9dc5-57c4-8378-deb99a8864d0","sourceKey":"bank:PUL101:RES-041","payload":{"prompt":"Why should an essay proposing a legal solution to cultism in Nigerian universities also consider psychological, social, economic and political factors?","options":["Because a multidimensional approach, not a strictly legal solution, is needed to put such issues in perspective","Because brevity requires ignoring the law","Because only sociologists may write about cultism","Because legal writing must never mention the law"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"Legal writing should analyse issues in the light of social realities; a purely legal solution to cultism that ignores its psychological, social, economic and political causes would be like putting 'something on nothing'. Option D goes too far, since the legal analysis remains central."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 629, $official_bank_source${"itemId":"79fb4aa8-012f-50b3-9b6d-3ea209aa2840","questionId":"db493173-d988-502f-a697-ade81a74c979","sourceKey":"bank:PUL101:RES-042","payload":{"prompt":"The acronym IDBC, used for answering law essay questions, stands for:","options":["Introduction, Discussion, Bibliography, Citation","Issue, Definition, Basis, Case","Introduction, Definition, Body, Conclusion","Issue, Decision, Body, Conclusion"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"IDBC is a conventional structure for law essay questions: Introduction, Definition, Body and Conclusion. Option D mixes in elements of the problem-question method. Options A and B are invented expansions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 630, $official_bank_source${"itemId":"1359671c-4e87-5adf-bf4c-ac2aefb0c756","questionId":"bd75af6c-bef6-5dd4-ba82-c96589797e13","sourceKey":"bank:PUL101:RES-043","payload":{"prompt":"Law problem questions are commonly tackled using IRAC (or IPAC), which stands for:","options":["Introduction, Reasoning, Analysis, Comment","Issue, Ratio, Authority, Case","Issue(s), Rule (or Principle), Application (or Analysis), Conclusion","Introduction, Rule, Argument, Citation"],"correctOption":2,"section":"Legal Research and Legal Writing","explanation":"In IRAC or IPAC, the answer identifies the Issue(s), states the Rule or Principle, Applies it to the facts, and reaches a Conclusion. Option D begins with Introduction, which belongs to the essay structure IDBC. Options B and A are invented expansions."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 631, $official_bank_source${"itemId":"c96be9e9-c7a2-5e9b-8889-56a9df4843b5","questionId":"fef1ec8b-7d53-5241-8b4a-205c8598dbb7","sourceKey":"bank:PUL101:RES-044","payload":{"prompt":"An examination question sets out facts about a trader in Onitsha whose customary claim is challenged, and ends with 'Advise him.' Which method is most suitable for answering it?","options":["A descriptive essay on how the trader feels","IRAC: identify the issues, state the rules, apply them to the facts, and conclude","IDBC: introduction, definition, body, conclusion","A narrative essay retelling the facts in date order"],"correctOption":1,"section":"Legal Research and Legal Writing","explanation":"A question that gives facts and asks you to advise is a problem question, best answered with IRAC (or IPAC). Option C suits essay questions; using the essay format for a problem question is like putting old wine into a new wineskin. Options D and A do not apply the law to the facts at all."}}$official_bank_source$::jsonb),
  ('official_bank_pul101', 'add', 632, $official_bank_source${"itemId":"cf7106a2-90ed-54d0-a768-e76ebf4386fe","questionId":"f0f1f1d6-7697-5604-9bc1-cfc8d27e4c48","sourceKey":"bank:PUL101:RES-045","payload":{"prompt":"What is the common mistake many students make in the introduction to a law essay answer?","options":["Starting the body of the essay in the introduction, instead of giving background and a thesis statement","Writing a thesis statement that tells the examiner what will be discussed","Giving a brief background analysis of the question","Beginning with an apt quotation from a scholar or a court"],"correctOption":0,"section":"Legal Research and Legal Writing","explanation":"Many students start answering the question in the introduction, so the examiner treats it as the body and no marks go to the introduction. The introduction should instead give the background and end with a thesis statement. Options B, C and D are all recommended practices, not mistakes."}}$official_bank_source$::jsonb);
